INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('VjayRam/dspy-prompt-optimizer/dspy-expert', 'community', 'VjayRam', 'dspy-prompt-optimizer', 'VjayRam/dspy-prompt-optimizer', 'dspy-expert', 0, 0, 45, '2026-03-08T01:57:15.474Z', '2026-03-08T02:09:41.361Z', '0d162ce7b4649a714ecf068cdacc869dfbf8344a19bdadc4bc73f44b3c7b5fd2', '{"id":"VjayRam/dspy-prompt-optimizer/dspy-expert","name":"dspy-expert","description":{"en":"The dspy-expert skill enables developers to construct and optimize DSPy programs. It focuses on creating clear Signatures, leveraging local LM endpoints, and establishing a rigorous evaluation workflow for AI pipeline development.","zh":"DSPy Expert 是一个高效的 AI 工具开发框架，遵循简单的 DSPy 程序和可测量的迭代原则","ja":"DSPy Expert は効率的な AI エージェント開発フレームワークであり、シンプルな DSPy プログラムと可測的なイテレーション原則に従う","ko":"DSPy Expert는 효율적인 AI 에이전트 개발 프레임워크로 단순한 DSPy 프로그램과 측정 가능한 반복 원칙을 따름","es":"dspy-expert es una herramienta para desarrollar programas de DSPy simples y eficientes con endpoints de OpenAI. Ofrece una iteración medible y una evaluación de fallos","fr":"dspy-expert est un outil pour développer des programmes DSPy simples et efficaces avec des points de terminaison OpenAI. Il propose une itération mesurable et une évaluation des défaillances","de":"dspy-expert ist ein Tool für die Entwicklung einfacher und effizienter DSPy-Programme mit OpenAI-Endpunkten. Es bietet eine messbare Iteration und eine Auswertung von Fehlern","pt":"O dspy-expert é uma ferramenta de desenvolvimento para AI Agents que utiliza programas DSPy simples e iterativos para melhorar a eficiência","ru":"dspy-expert - это инструмент для разработки ИИ Агентов, использующий простые и итеративные программы DSPy для повышения эффективности","ar":"dspy-expert هو أداة تطوير للوكلاء الذكية التي تستخدم برامج DSPy البسيطة والمتكررة لتحسين الكفاءة"},"seo":{"title":{"en":"dspy-expert: Build & Optimize AI Pipelines | AI Agent Skill","zh":"DSPy Expert 设置指南 - AI 工具开发最佳实践","ja":"DSPy Expert セットアップガイド - AI エージェント開発のベストプラクティス","ko":"DSPy Expert 설정 가이드 - AI 에이전트 개발 모범 사례","es":"Guía de configuración de dspy-expert para agentes de AI","fr":"Guide de mise en place de dspy-expert pour outils d''IA","de":"Einrichtungsleitfaden für dspy-expert in der KI-Entwicklung","pt":"Guia de Configuração do dspy-expert: Melhores Práticas pa...","ru":"Настройка dspy-expert: Лучшие Практики для Разработчиков ...","ar":"دليل إعداد dspy-expert: أفضل الممارسات لمراقبي الوكلاء ال..."},"description":{"en":"Master DSPy with this AI Agent skill. Learn to create simple DSPy programs, set up local OpenAI endpoints with Ollama/vLLM, and implement a tight eval loop f...","zh":"了解 DSPy Expert 的操作原则和快速工作流程，实现高效的 AI 工具开发","ja":"DSPy Expert の操作原則とクイックワークフローを学び、効率的な AI エージェント開発を実現","ko":"DSPy Expert의 운영 원칙과 빠른 워크플로우를 배우고 효율적인 AI 에이전트 개발을 실현","es":"Aprende a configurar y utilizar dspy-expert para desarrollar programas de DSPy simples y eficientes con endpoints de OpenAI","fr":"Découvrez comment configurer et utiliser dspy-expert pour développer des programmes DSPy simples et efficaces avec des points de terminaison OpenAI","de":"Erfahren Sie, wie Sie dspy-expert konfigurieren und verwenden, um einfache und effiziente DSPy-Programme mit OpenAI-Endpunkten zu entwickeln","pt":"Aprenda a configurar e utilizar o dspy-expert com nossas melhores práticas e dicas para desenvolvedores de AI Agents","ru":"Узнайте, как настроить и использовать dspy-expert с нашими лучшими практиками и советами для разработчиков ИИ Агентов","ar":"تعلم كيفية 설정 واستخدام dspy-expert مع أفضل الممارسات والنصائح لمراقبي الوكلاء الذكية"},"definition":{"en":"dspy-expert is an AI Agent skill designed to help developers build and optimize programs using the DSPy framework. It emphasizes simple program structure, measurable iteration through a dataset→metric→compile loop, and compatibility with local OpenAI endpoints like Ollama, vLLM, and LM Studio.","zh":"DSPy Expert 是一个 AI 工具开发框架，用于构建高效的 AI 应用","ja":"DSPy Expert は AI エージェント開発フレームワークであり、高効率の AI アプリケーションを構築するために使用される","ko":"DSPy Expert는 AI 에이전트 개발 프레임워크로서 높은 효율의 AI 애플리케이션을 구축하기 위해 사용됨","es":"dspy-expert es un experto en DSPy que utiliza principios de operación para desarrollar programas simples y eficientes","fr":"dspy-expert est un expert en DSPy qui utilise des principes d''opération pour développer des programmes simples et efficaces","de":"dspy-expert ist ein DSPy-Experte, der Betriebsprinzipien verwendet, um einfache und effiziente Programme zu entwickeln","pt":"O dspy-expert é uma ferramenta de desenvolvimento para AI Agents que utiliza programas DSPy para melhorar a eficiência","ru":"dspy-expert - это инструмент для разработки ИИ Агентов, использующий программы DSPy","ar":"dspy-expert هو أداة تطوير للوكلاء الذكية التي تستخدم برامج DSPy"},"features":{"en":["Creates simple DSPy programs with one clear Signature and few modules","Implements a tight evaluation loop (dataset → metric → compile/optimize → evaluate)","Defaults to local OpenAI-compatible endpoints (Ollama, vLLM, LM Studio)","Recommends checking the installed DSPy version for API confirmation","Focuses on measurable iteration by inspecting failures to repeat the process"],"zh":["默认使用简单的 DSPy 程序","支持可测量的迭代","假设本地 OpenAI 兼容端点","支持快速工作流程"],"ja":["デフォルトでシンプルな DSPy プログラムを使用","可測的なイテレーションをサポート","ローカル OpenAI 互換エンドポイントを仮定","クイックワークフローをサポート"],"ko":["기본적으로 단순한 DSPy 프로그램 사용","측정 가능한 반복 지원","로컬 OpenAI 호환 엔드포인트 가정","빠른 워크플로우 지원"],"es":["Programas de DSPy simples con una sola firma y pocos módulos","Iteración medible con evaluación de fallos","Compatibilidad con endpoints de OpenAI locales","Verificación de la versión de DSPy instalada para detalles de API","Flujo de trabajo rápido con copia y pegado"],"fr":["Programmes DSPy simples avec une seule signature et quelques modules","Itération mesurable avec évaluation des défaillances","Compatibilité avec des points de terminaison OpenAI locaux","Vérification de la version de DSPy installée pour les détails de l''API","Flux de travail rapide avec copie et collage"],"de":["Einfache DSPy-Programme mit einer einzigen Signatur und wenigen Modulen","Messbare Iteration mit Auswertung von Fehlern","Kompatibilität mit lokalen OpenAI-Endpunkten","Überprüfung der installierten DSPy-Version für API-Details","Schneller Arbeitsablauf mit Kopieren und Einfügen"],"pt":["Programas DSPy simples e iterativos","Integração com endpoints OpenAI compatíveis","Método de desenvolvimento baseado em métricas e avaliação","Suporte a múltiplos módulos e assinaturas","Verificação de detalhes de API via docs e exemplos"],"ru":["Простые и итеративные программы DSPy","Интеграция с совместимыми конечными точками OpenAI","Метод разработки, основанный на метриках и оценке","Поддержка нескольких модулей и подписей","Проверка деталей API через документацию и примеры"],"ar":["برامج DSPy البسيطة والمتكررة","التكامل مع نقاط النهاية OpenAI المتوافقة","طريقة التطوير القائمة على المقاييس والتقييم","دعم متعدد الوحدات والتواقيع","التحقق من تفاصيل واجهة برمجة التطبيقات عبر الوثائق والأمثلة"]},"keywords":{"en":["how to use dspy-expert","what is dspy-expert","dspy-expert vs haystack","dspy-expert setup guide","dspy-expert install Ollama","dspy-expert local LM endpoints","dspy-expert compile optimize","dspy-expert signature module","dspy-expert evaluation loop"],"zh":["AI 工具开发","DSPy Expert","AI 应用构建","高效开发框架","简单 DSPy 程序","可测量的迭代"],"ja":["AI エージェント開発","DSPy Expert","AI アプリケーション構築","効率的な開発フレームワーク","シンプルな DSPy プログラム","可測的なイテレーション"],"ko":["AI 에이전트 개발","DSPy Expert","AI 애플리케이션 구축","효율적인 개발 프레임워크","단순한 DSPy 프로그램","측정 가능한 반복"],"es":["dspy-expert","agentes de AI","desarrollo de programas de DSPy","endpoints de OpenAI","iteración medible","evaluación de fallos","configuración de dspy-expert","herramientas de AI","desarrollo de software de AI"],"fr":["dspy-expert","outils d''IA","développement de programmes DSPy","points de terminaison OpenAI","itération mesurable","évaluation des défaillances","configuration de dspy-expert","développement de logiciels d''IA","agents d''IA"],"de":["dspy-expert","KI-Entwicklung","KI-Tools","Entwicklung von DSPy-Programmen","OpenAI-Endpunkte","messbare Iteration","Auswertung von Fehlern","Konfiguration von dspy-expert","KI-Software-Entwicklung","KI-Agenten"],"pt":["dspy-expert","AI Agents","Desenvolvimento de AI","Programas DSPy","OpenAI","Desenvolvimento de software","Ferramentas de desenvolvimento","Melhores práticas de desenvolvimento"],"ru":["dspy-expert","ИИ Агенты","Разработка ИИ","Программы DSPy","OpenAI","Разработка программного обеспечения","Инструменты разработки","Лучшие практики разработки"],"ar":["dspy-expert","الوكلاء الذكية","تطوير الوكلاء الذكية","برامج DSPy","OpenAI","تطوير البرمجيات","أدوات التطوير","أفضل الممارسات للتطوير"]}},"owner":"VjayRam","repo":"dspy-prompt-optimizer","repoPath":"VjayRam/dspy-prompt-optimizer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.474Z","topics":[],"category":"community","skillMd":{"name":"dspy-expert","description":"Builds and optimizes DSPy (dspy) programs end-to-end: signatures, modules, compilation/optimization, evaluation, and debugging. Use when the user mentions dspy/DSPy, Signature, Module, teleprompter/optimizer, compile, evaluate, few-shot, RAG, tool use, or local LLM endpoints (Ollama/vLLM/LM Studio).","bodyPreview":"# DSPy Expert\n\n## Operating principles\n\n- Default to **simple DSPy programs**: one clear `Signature`, one/few modules, tight eval loop.\n- Prefer **measurable iteration**: dataset → metric → compile/optimize → evaluate → inspect failures → repeat.\n- Assume **local OpenAI-compatible endpoints** by default (Ollama/vLLM/LM Studio). If not available, adapt.\n- If an API detail is uncertain, **check the installed DSPy version** and confirm via docs/examples before coding.\n\n## Quick workflow (copy/paste","body":"# DSPy Expert\n\n## Operating principles\n\n- Default to **simple DSPy programs**: one clear `Signature`, one/few modules, tight eval loop.\n- Prefer **measurable iteration**: dataset → metric → compile/optimize → evaluate → inspect failures → repeat.\n- Assume **local OpenAI-compatible endpoints** by default (Ollama/vLLM/LM Studio). If not available, adapt.\n- If an API detail is uncertain, **check the installed DSPy version** and confirm via docs/examples before coding.\n\n## Quick workflow (copy/paste checklist)\n\n### 1) Frame the task\n- What is the **input**? What is the **output**?\n- What are 10–200 **representative examples** (or how do we generate them)?\n- What metric defines “good”? (exact match, F1, rubric judge, retrieval hit-rate, latency, cost)\n\n### 2) Create a minimal baseline\n- Define a `Signature` with the smallest useful fields.\n- Implement the simplest module that can work (often `Predict`, `ChainOfThought`, or a tiny custom `Module`).\n- Add deterministic pre/post-processing outside DSPy when helpful (parsing, normalization, schema validation).\n\n### 3) Build an evaluation harness\n- Create `train` / `dev` / `test` splits (even if small).\n- Implement `metric(example, pred) -> float/bool`.\n- Run baseline; save failure cases (inputs + model outputs + expected).\n\n### 4) Compile/optimize\n- Choose one optimizer/teleprompter and a small search budget first.\n- Compile on `train`, select by `dev`, report final on `test`.\n- Keep prompts/program changes attributable (one change at a time; log configs and seeds when possible).\n\n### 5) Debug systematically\n- Classify errors: schema/formatting, missing context, wrong reasoning, hallucination, retrieval, tool failures.\n- Add constraints: structured outputs, validation + retry, better instructions, or tighter signatures.\n- Only scale complexity (multi-stage, RAG, tools) after the baseline is measurable.\n\n## Local LLM defaults (OpenAI-compatible)\n\nUse a local OpenAI-compatible base URL when available. Prefer configuring via **environment variables** or a single “LM factory” in code.\n\nMinimal pattern (adjust to your DSPy version):\n\n```python\nimport os\nimport dspy\n\n# Example OpenAI-compatible local endpoint (adjust as needed)\nos.environ.setdefault(\"OPENAI_API_BASE\", \"http://localhost:11434/v1\")\nos.environ.setdefault(\"OPENAI_API_KEY\", \"ollama\")  # placeholder for local gateways\n\n# Model name depends on your gateway (e.g., \"llama3.1\", \"qwen2.5\", etc.)\nlm = dspy.LM(model=os.environ.get(\"DSPY_MODEL\", \"qwen3:latest\"))\ndspy.settings.configure(lm=lm)\n```\n\nIf the repo already has a working local-LLM helper, **reuse it** instead of re-inventing configuration.\n\n## DSPy patterns (keep it simple)\n\n### Classification / extraction\n- Use a `Signature` with explicit output fields (and constraints like allowed labels).\n- Add lightweight normalization (strip, lowercase, JSON parsing) and validate outputs.\n\n### RAG (retrieval-augmented generation)\n- Start with: retrieve top-k → single generate step referencing retrieved passages.\n- Evaluate retrieval separately (recall@k) vs generation quality.\n\n### Tool use\n- Keep tool schema strict (inputs/outputs), validate tool results, and handle retries/timeouts.\n- Prefer separating: “decide tool call” → “execute” → “final answer”.\n\n## When asked to “learn DSPy and build X”\n\nFollow this order:\n1. Inspect the repo’s current DSPy usage (existing modules, eval scripts, LM config).\n2. Identify the installed DSPy version (from `pyproject.toml`, lockfile, or import behavior).\n3. Build the smallest working baseline and an eval harness.\n4. Only then introduce compilation/optimization and extra components (retrieval, tools, multi-step).\n\n"},"lastSynced":"2026-03-08T02:09:41.361Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Pipeline Development Agents needing to construct and optimize DSPy programs with clear Signatures and local LM endpoints.","zh":"非常适合需要构建和优化DSPy程序的AI Pipeline开发代理，具有明确的Signatures和本地LM端点。","ja":"AIパイプライン開発エージェントがDSPyプログラムを構築して最適化するのに最適で、明確なSignaturesとローカルのLMエンドポイントがあります。","ko":"AI 파이프라인 개발 에이전트가 DSPy 프로그램을 구축하고 최적화하는 데完璧한 선택지로, 명확한 Signatures와 로컬 LM 엔드포인트를 제공합니다.","es":"Perfecto para agentes de desarrollo de tuberías de IA que necesitan construir y optimizar programas DSPy con firmas claras y puntos de conexión de LM locales.","fr":"Parfait pour les agents de développement de pipeline d''IA ayant besoin de construire et d''optimiser des programmes DSPy avec des signatures claires et des points de terminaison de LM locaux.","de":"Perfekt für AI-Pipeline-Entwicklungsagenten, die DSPy-Programme mit klaren Signaturen und lokalen LM-Endpunkten erstellen und optimieren müssen.","pt":"Perfeito para Agentes de Desenvolvimento de Pipeline de IA que precisam construir e otimizar programas DSPy com Signatures claras e endpoints de LM locais.","ru":"Идеально подходит для агентов разработки конвейера ИИ, которым необходимо создавать и оптимизировать программы DSPy с ясными Signature и локальными конечными точками LM.","ar":"مثالي لتعيين وكلاء تطوير خط أنابيب الذكاء الاصطناعي الذين يحتاجون إلى بناء وضبط برامج DSPy مع التوقيعات الواضحة والنقاط النهائية المحلية LM."},"recommendation":{"en":"Empowers agents to create rigorous evaluation workflows, leverage measurable iteration, and utilize OpenAI-compatible endpoints like Ollama, vLLM, or LM Studio for optimized AI pipeline development, all while ensuring compatibility with the installed DSPy version.","zh":"赋予代理创建严格的评估工作流、利用可衡量的迭代和OpenAI兼容端点（如Ollama、vLLM或LM Studio）进行优化的AI管道开发，同时确保与安装的DSPy版本的兼容性。","ja":"エージェントが厳密な評価ワークフローを作成し、測定可能なイテレーションを利用し、OpenAIと互換性のあるエンドポイント（Ollama、vLLM、またはLM Studioなど）を使用してAIパイプラインの開発を最適化し、同時にインストールされたDSPyバージョンとの互換性を確保する。","ko":"에이전트가 엄격한 평가 워크플ロー를 생성하고, 측정 가능한 반복을 활용하며, OpenAI와 호환되는 엔드포인트(Ollama, vLLM, LM Studio 등)를 사용하여 AI 파이프라인 개발을 최적화하고,同時に 설치된 DSPy 버전과의 호환성을 보장합니다.","es":"Habilita a los agentes a crear flujos de trabajo de evaluación rigurosos, aprovechar la iteración medible y utilizar puntos de conexión compatibles con OpenAI como Ollama, vLLM o LM Studio para el desarrollo óptimo de la tubería de IA, todo ello garantizando la compatibilidad con la versión de DSPy instalada.","fr":"Permet aux agents de créer des flux de travail d''évaluation rigoureux, d''exploiter l''itération mesurable et d''utiliser des points de terminaison compatibles OpenAI tels que Ollama, vLLM ou LM Studio pour le développement optimal du pipeline d''IA, tout en garantissant la compatibilité avec la version de DSPy installée.","de":"Ermöglicht es Agenten, strenge Evaluierungs-Workflows zu erstellen, messbare Iterationen zu nutzen und OpenAI-kompatible Endpunkte wie Ollama, vLLM oder LM Studio für die optimale Entwicklung der AI-Pipeline zu verwenden, während die Kompatibilität mit der installierten DSPy-Version gewährleistet wird.","pt":"Habilita os agentes a criar fluxos de trabalho de avaliação rigorosos, aproveitar iterações mensuráveis e utilizar pontos finais compatíveis com a OpenAI, como Ollama, vLLM ou LM Studio, para o desenvolvimento otimizado do pipeline de IA, garantindo a compatibilidade com a versão do DSPy instalada.","ru":"Наделяет агентов возможностью создавать строгие рабочие процессы оценки, использовать измеримые итерации и задействовать конечные точки, совместимые с OpenAI, такие как Ollama, vLLM или LM Studio, для оптимизированного развития конвейера ИИ, обеспечивая при этом совместимость с установленной версией DSPy.","ar":"يمنح الوكلاء khảية إنشاء تدفقات عمل تقييم صارمة، واستخدام التكرارات القابلة للقياس، وتشغيل نقاط النهاية المتوافقة مع OpenAI، مثل Ollama، vLLM أو LM Studio، من أجل تطوير خط أنابيب الذكاء الاصطناعي المُحسّن، مع ضمان التوافق مع إصدار DSPy المثبت."},"useCases":{"en":["Constructing clear Signatures for DSPy programs","Optimizing DSPy programs using local LM endpoints and measurable iteration","Establishing rigorous evaluation workflows for AI pipeline development","Adapting to different API details by checking the installed DSPy version and confirming via docs/examples"],"zh":["为DSPy程序构建明确的Signatures","使用本地LM端点和可衡量的迭代来优化DSPy程序","为AI管道开发建立严格的评估工作流","通过检查安装的DSPy版本和确认文档/示例来适应不同的API细节"],"ja":["DSPyプログラムの明確なSignaturesを構築する","ローカルのLMエンドポイントと測定可能なイテレーションを使用してDSPyプログラムを最適化する","AIパイプライン開発のための厳密な評価ワークフローを確立する","インストールされたDSPyバージョンを確認し、ドキュメント/サンプルを確認することで、異なるAPIの詳細に適応する"],"ko":["DSPy 프로그램의 명확한 Signatures를 구축하는 것","로컬 LM 엔드포인트와 측정 가능한 반복을 사용하여 DSPy 프로그램을 최적화하는 것","AI 파이프라인 개발을 위한 엄격한 평가 워크플ロー를 설정하는 것","설치된 DSPy 버전을 확인하고 문서/예제를 확인하여 다른 API 세부 정보에 적응하는 것"],"es":["Construir firmas claras para programas DSPy","Optimizar programas DSPy utilizando puntos de conexión de LM locales y iteración medible","Establecer flujos de trabajo de evaluación rigurosos para el desarrollo de tuberías de IA","Adaptarse a diferentes detalles de API comprobando la versión de DSPy instalada y confirmando mediante la documentación"],"fr":["Construire des signatures claires pour des programmes DSPy","Optimiser des programmes DSPy en utilisant des points de terminaison de LM locaux et l''itération mesurable","Établir des flux de travail d''évaluation rigoureux pour le développement de pipeline d''IA","S''adapter à différents détails d''API en vérifiant la version de DSPy installée et en confirmant via la documentation"],"de":["Erstellen von klaren Signaturen für DSPy-Programme","Optimieren von DSPy-Programmen unter Verwendung lokaler LM-Endpunkte und messbarer Iteration","Einrichten strenger Evaluierungs-Workflows für die Entwicklung der AI-Pipeline","Anpassen an verschiedene API-Details durch Überprüfen der installierten DSPy-Version und Bestätigung über die Dokumentation"],"pt":["Construir Signatures claras para programas DSPy","Otimizar programas DSPy utilizando endpoints de LM locais e iteração mensurável","Estabelecer fluxos de trabalho de avaliação rigorosos para desenvolvimento de pipeline de IA","Adaptar-se a diferentes detalhes de API, verificando a versão do DSPy instalada e confirmado via docs/exemplos"],"ru":["Создание ясных Signature для программ DSPy","Оптимизация программ DSPy с использованием локальных конечных точек LM и измеримой итерации","Установление строгих рабочих процессов оценки для разработки конвейера ИИ","Адаптация к различным деталям API путем проверки установленной версии DSPy и подтверждения через документацию/примеры"],"ar":["بناء التوقيعات الواضحة لبرامج DSPy","تحسين برامج DSPy باستخدام نقاط النهاية المحلية LM والتكرار القابل للقياس","إنشاء تدفقات عمل تقييم صارمة لتطوير خط أنابيب الذكاء الاصطناعي","التكيف مع تفاصيل واجهة برمجة التطبيقات المختلفة عن طريق التحقق من إصدار DSPy المثبت والمؤكد من خلال الوثائق/الأمثلة"]},"limitations":{"en":["Requires local OpenAI-compatible endpoints","Assumes default to simple DSPy programs","Needs confirmation of API details via DSPy version and documentation"],"zh":["需要本地OpenAI兼容端点","假设默认为简单的DSPy程序","需要通过DSPy版本和文档确认API细节"],"ja":["ローカルのOpenAIと互換性のあるエンドポイントが必要","デフォルトではシンプルなDSPyプログラムであると仮定","APIの詳細をDSPyバージョンとドキュメントを通じて確認する必要がある"],"ko":["로컬 OpenAI와 호환되는 엔드포인트가 필요","기본적으로 단순한 DSPy 프로그램이라고 가정","API 세부 정보를 DSPy 버전과 문서를 통해 확인해야 함"],"es":["Requiere puntos de conexión de OpenAI compatibles locales","Supone la configuración predeterminada a programas DSPy simples","Necesita confirmación de detalles de API a través de la versión de DSPy y la documentación"],"fr":["Nécessite des points de terminaison OpenAI compatibles locaux","Suppose la configuration par défaut à des programmes DSPy simples","A besoin d''une confirmation des détails d''API via la version de DSPy et la documentation"],"de":["Erfordert lokale OpenAI-kompatible Endpunkte","Geht von der Standardkonfiguration für einfache DSPy-Programme aus","Benötigt eine Bestätigung der API-Details über die DSPy-Version und die Dokumentation"],"pt":["Exige endpoints de OpenAI compatíveis locais","Pressupõe programas DSPy simples por padrão","Necessita de confirmação de detalhes de API via versão do DSPy e documentação"],"ru":["Требует локальных конечных точек, совместимых с OpenAI","Предполагает простые программы DSPy по умолчанию","Требует подтверждения деталей API через версию DSPy и документацию"],"ar":["يتطلب نقاط نهاية متوافقة مع OpenAI محليًا","يفترض برامج DSPy البسيطة افتراضيًا","يحتاج إلى تأكيد تفاصيل واجهة برمجة التطبيقات من خلال إصدار DSPy والتوثيق"]},"version":4},"contentHash":"0d162ce7b4649a714ecf068cdacc869dfbf8344a19bdadc4bc73f44b3c7b5fd2","qualityScore":45}');
DELETE FROM skills_fts WHERE id = 'VjayRam/dspy-prompt-optimizer/dspy-expert';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('VjayRam/dspy-prompt-optimizer/dspy-expert', 'dspy-expert', 'VjayRam', 'dspy-prompt-optimizer', 'community', 'dspy-expert VjayRam dspy-prompt-optimizer community The dspy-expert skill enables developers to construct and optimize DSPy programs. It focuses on creating clear Signatures, leveraging local LM endpoints, and establishing a rigorous evaluation workflow for AI pipeline development. DSPy Expert 是一个高效的 AI 工具开发框架，遵循简单的 DSPy 程序和可测量的迭代原则 DSPy Expert は効率的な AI エージェント開発フレームワークであり、シンプルな DSPy プログラムと可測的なイテレーション原則に従う DSPy Expert는 효율적인 AI 에이전트 개발 프레임워크로 단순한 DSPy 프로그램과 측정 가능한 반복 원칙을 따름 dspy-expert es una herramienta para desarrollar programas de DSPy simples y eficientes con endpoints de OpenAI. Ofrece una iteración medible y una evaluación de fallos dspy-expert est un outil pour développer des programmes DSPy simples et efficaces avec des points de terminaison OpenAI. Il propose une itération mesurable et une évaluation des défaillances dspy-expert ist ein Tool für die Entwicklung einfacher und effizienter DSPy-Programme mit OpenAI-Endpunkten. Es bietet eine messbare Iteration und eine Auswertung von Fehlern O dspy-expert é uma ferramenta de desenvolvimento para AI Agents que utiliza programas DSPy simples e iterativos para melhorar a eficiência dspy-expert - это инструмент для разработки ИИ Агентов, использующий простые и итеративные программы DSPy для повышения эффективности dspy-expert هو أداة تطوير للوكلاء الذكية التي تستخدم برامج DSPy البسيطة والمتكررة لتحسين الكفاءة how to use dspy-expert what is dspy-expert dspy-expert vs haystack dspy-expert setup guide dspy-expert install Ollama dspy-expert local LM endpoints dspy-expert compile optimize dspy-expert signature module dspy-expert evaluation loop AI 工具开发 DSPy Expert AI 应用构建 高效开发框架 简单 DSPy 程序 可测量的迭代 Creates simple DSPy programs with one clear Signature and few modules Implements a tight evaluation loop (dataset → metric → compile/optimize → evaluate) Defaults to local OpenAI-compatible endpoints (Ollama, vLLM, LM Studio) Recommends checking the installed DSPy version for API confirmation Focuses on measurable iteration by inspecting failures to repeat the process dspy-expert is an AI Agent skill designed to help developers build and optimize programs using the DSPy framework. It emphasizes simple program structure, measurable iteration through a dataset→metric→compile loop, and compatibility with local OpenAI endpoints like Ollama, vLLM, and LM Studio.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zile0207/enigma-engine/orchestrator-cli', 'community', 'zile0207', 'enigma-engine', 'zile0207/enigma-engine', 'orchestrator-cli', 0, 0, 45, '2026-03-08T01:57:15.474Z', '2026-03-08T02:09:43.332Z', '45aab940518f77c6594b046aba29cc26ce16de5e801120a0edea1a5b758b0780', '{"id":"zile0207/enigma-engine/orchestrator-cli","name":"orchestrator-cli","description":{"en":"The orchestrator-cli skill empowers Systems Engineers to build reliable, fast, and UX-oriented CLIs, bridging designer workspaces and developer workflows. It enables branded CLIs like `npx company-ui add button`.","zh":"orchestrator-cli 是一种强大的 CLI 工具，用于构建设计系统的交付机制，实现设计师和开发者的无缝协作","ja":"orchestrator-cli はデザインシステムの配信を実現する強力な CLI ツールで、デザイナーと開発者の協業を強化します","ko":"orchestrator-cli는 디자인 시스템 배포 메커니즘을 구축하는 강력한 CLI 도구로 디자인 및 개발 협업을 강화합니다","es":"Orchestrator CLI es una herramienta de línea de comandos que conecta los espacios de trabajo de diseño con los flujos de trabajo de desarrollo, permitiendo la creación de herramientas de línea de comandos personalizadas","fr":"L''Orchestrator CLI est un outil de ligne de commande qui relie les espaces de travail de conception aux flux de travail de développement, permettant la création d''outils de ligne de commande personnalisés","de":"Orchestrator CLI ist ein Befehlszeilentool, das die Designarbeitsbereiche mit den Entwicklungswerkzeugen verbindet und die Erstellung benutzerdefinierter Befehlszeilentools ermöglicht","pt":"O Orchestrator-CLI é uma ferramenta de distribuição de design systems que permite aos designers entregar suas criações aos desenvolvedores via CLIs personalizadas","ru":"Orchestrator-CLI - это инструмент доставки дизайн-систем, который позволяет дизайнерам доставлять свои творения разработчикам через настраиваемые CLI","ar":"Orchestrator-CLI هو أداة توصيل أنظمة التصميم التي تمكن المصممين من توصيل تصميماتهم للمطورين عبر واجهات سطر الأوامر المخصصة"},"seo":{"title":{"en":"orchestrator-cli: Expert CLI Setup Guide | AI Agent Skill","zh":"orchestrator-cli 安装指南：构建可靠的设计系统交付机制","ja":"orchestrator-cli セットアップガイド：デザインシステムの迅速な配信を実現","ko":"orchestrator-cli 설정 가이드: 신뢰할 수 있는 디자인 시스템 배포 메커니즘 구축","es":"Guía de configuración de Orchestrator CLI para desarrolla...","fr":"Guide de mise en place de l''Orchestrator CLI pour les dév...","de":"Einrichtungsleitfaden für Orchestrator CLI-Entwickler","pt":"Guia de Configuração do Orchestrator-CLI: Ferramenta de D...","ru":"ИИ Агенты: Orchestrator-CLI - Руководство по Настройке и ...","ar":"دليل إعداد Orchestrator-CLI: أداة توصيل أنظمة التصميم"},"description":{"en":"Unlock seamless designer-developer collaboration with orchestrator-cli. Learn how to set up and master this critical bridge between workspaces.","zh":"了解如何使用 orchestrator-cli 构建快速、可靠的设计系统交付机制，实现设计师和开发者的无缝协作","ja":"orchestrator-cli を使用してデザインシステムの配信を迅速化し、デザイナーと開発者の協業を強化する方法を学びます","ko":"orchestrator-cli를 사용하여 신뢰할 수 있는 디자인 시스템 배포 메커니즘을 구축하고 디자인 및 개발 협업을 강화하는 방법에 대해 알아보세요","es":"Descubre cómo configurar y utilizar Orchestrator CLI para mejorar tus flujos de trabajo de diseño y desarrollo con herramientas de línea de comandos personal...","fr":"Découvrez comment configurer et utiliser l''Orchestrator CLI pour améliorer vos flux de travail de conception et de développement avec des outils de ligne de ...","de":"Erfahren Sie, wie Sie Orchestrator CLI konfigurieren und verwenden können, um Ihre Design- und Entwicklungswerkzeuge mit benutzerdefinierten Befehlszeilentoo...","pt":"Aprenda a configurar e usar o Orchestrator-CLI, uma ferramenta de distribuição de design systems para designers e desenvolvedores","ru":"Узнайте, как настроить и использовать Orchestrator-CLI, инструмент доставки дизайн-систем для дизайнеров и разработчиков","ar":"تعرف على كيفية إعداد واستخدام Orchestrator-CLI، أداة توصيل أنظمة التصميم للمصممين والمطوّرين"},"definition":{"en":"orchestrator-cli is a standalone Enigma CLI distribution tool that delivers design systems to developers via branded CLIs, respecting designer brand identity.","zh":"orchestrator-cli 是一种命令行界面工具，用于构建和交付设计系统","ja":"orchestrator-cli はデザインシステムを構築および配信するためのコマンドラインインターフェースツールです","ko":"orchestrator-cli는 디자인 시스템을 구축 및 배포하는 위한 명령줄 인터페이스 도구입니다","es":"Orchestrator CLI es una herramienta de línea de comandos que permite la creación de herramientas de línea de comandos personalizadas para conectar diseño y desarrollo","fr":"L''Orchestrator CLI est un outil de ligne de commande qui permet la création d''outils de ligne de commande personnalisés pour relier la conception et le développement","de":"Orchestrator CLI ist ein Befehlszeilentool, das die Erstellung benutzerdefinierter Befehlszeilentools für die Verbindung von Design und Entwicklung ermöglicht","pt":"O que é Orchestrator-CLI? É uma ferramenta de linha de comando que facilita a entrega de design systems aos desenvolvedores","ru":"Что такое Orchestrator-CLI? Это командная строка, которая облегчает доставку дизайн-систем разработчикам","ar":"ما هو Orchestrator-CLI؟ هو أداة سطر الأوامر التي تسهل توصيل أنظمة التصميم للمطورين"},"features":{"en":["Empowers designers to ship design systems to developers via branded CLIs","Supports commands like `npx company-ui add button` for seamless integration","Provides reliable, fast, and excellent UX while respecting designer brand identity","Acts as a critical bridge between designer workspaces and developer workflows","Enables white-labeling for branded CLIs"],"zh":["支持快速可靠的设计系统交付","提供优秀的用户体验和白标签品牌身份","实现设计师和开发者的无缝协作","支持 npmx company-ui add button 等命令","构建独立的 Enigma CLI 分布工具"],"ja":["迅速なデザインシステムの配信をサポート","優れたユーザーエクスペリエンスとホワイトラベルブランドアイデンティティを提供","デザイナーと開発者の無縁協業を実現","npmx company-ui add button などのコマンドをサポート","独立した Enigma CLI 配布ツールを構築"],"ko":["신뢰할 수 있는 디자인 시스템 배포를 지원","우수한 사용자 경험과 하얀 라벨 브랜드 아이덴티티를 제공","디자이너와 개발자의 무결점 협업을 구현","npmx company-ui add button 등의 명령어 지원","독립적인 Enigma CLI 배포 도구 구축"],"es":["Creación de herramientas de línea de comandos personalizadas","Conexión de espacios de trabajo de diseño con flujos de trabajo de desarrollo","Compatibilidad con la entrega de sistemas de diseño a través de la línea de comandos","Respeto a la identidad de marca del diseñador","UX excelente y rendimiento rápido"],"fr":["Création d''outils de ligne de commande personnalisés","Connexion des espaces de travail de conception aux flux de travail de développement","Compatibilité avec la livraison de systèmes de conception via la ligne de commande","Respect de l''identité de marque du concepteur","UX excellente et performances rapides"],"de":["Erstellung benutzerdefinierter Befehlszeilentools","Verbindung von Designarbeitsbereichen mit Entwicklungswerkzeugen","Unterstützung der Auslieferung von Designsystemen über die Befehlszeile","Respektierung der Markenidentität des Designers","Exzellente Benutzererfahrung und schnelle Leistung"],"pt":["Suporte a CLIs personalizadas","Entrega de design systems via npm","Integração com workflows de designers e desenvolvedores","Suporte a marca branca para designers","Comandos rápidos e confiáveis"],"ru":["Поддержка настраиваемых CLI","Доставка дизайн-систем через npm","Интеграция с рабочими процессами дизайнеров и разработчиков","Поддержка белой марки для дизайнеров","Быстрые и надежные команды"],"ar":["دعم واجهات سطر الأوامر المخصصة","توصيل أنظمة التصميم عبر npm","التكامل مع سير العمل للمصممين والمطورين","دعم العلامة التجارية البيضاء للمصممين","أوامر سريعة وموثوقة"]},"keywords":{"en":["how to use orchestrator-cli","orchestrator-cli setup guide","what is orchestrator-cli","orchestrator-cli alternative","orchestrator-cli vs Enigma CLI","orchestrator-cli install","orchestrator-cli for designers","orchestrator-cli for developers","orchestrator-cli white-labeling"],"zh":["orchestrator-cli","设计系统","CLI 工具","设计师协作","开发者协作","白标签品牌","Enigma CLI","npmx company-ui"],"ja":["orchestrator-cli","デザインシステム","CLI ツール","デザイナー協業","開発者協業","ホワイトラベルブランド","Enigma CLI","npmx company-ui"],"ko":["orchestrator-cli","디자인 시스템","CLI 도구","디자이너 협업","개발자 협업","하얀 라벨 브랜드","Enigma CLI","npmx company-ui"],"es":["Orchestrator CLI","herramientas de línea de comandos","diseño y desarrollo","sistemas de diseño","entrega de sistemas de diseño","identidad de marca","UX","rendimiento rápido","desarrollo de software","Herramientas de línea de comandos personalizadas"],"fr":["Orchestrator CLI","outils de ligne de commande","conception et développement","systèmes de conception","livraison de systèmes de conception","identité de marque","UX","performances rapides","développement de logiciels","Outils de ligne de commande personnalisés"],"de":["Orchestrator CLI","Befehlszeilentools","Design und Entwicklung","Designsysteme","Auslieferung von Designsystemen","Markenidentität","UX","schnelle Leistung","Softwareentwicklung","Benutzerdefinierte Befehlszeilentools"],"pt":["Orchestrator-CLI","design systems","CLI personalizada","entrega de design systems","npm","workflows de designers","marca branca"],"ru":["ИИ Агенты","Orchestrator-CLI","дизайн-системы","настраиваемая CLI","доставка дизайн-систем","npm","рабочие процессы дизайнеров"],"ar":["أدوات الذكاء الاصطناعي","Orchestrator-CLI","أنظمة التصميم","واجهة سطر الأوامر المخصصة","توصيل أنظمة التصميم","npm","سير العمل للمصممين"]}},"owner":"zile0207","repo":"enigma-engine","repoPath":"zile0207/enigma-engine","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.474Z","topics":[],"category":"community","skillMd":{"name":"orchestrator-cli","description":"Orchestrator CLI Expert","bodyPreview":"# Specialty: Orchestrator CLI Expert\n\n## Persona\n\nYou are a Systems Engineer building the standalone Enigma CLI distribution tool—the RaaS delivery mechanism that empowers designers to ship design systems to developers via branded CLIs like `npx company-ui add button`.\n\nYou understand that this CLI is the critical bridge between designer workspaces and developer workflows. Every command must be reliable, fast, and provide excellent UX while respecting the designer''s brand identity (white-label e","body":"# Specialty: Orchestrator CLI Expert\n\n## Persona\n\nYou are a Systems Engineer building the standalone Enigma CLI distribution tool—the RaaS delivery mechanism that empowers designers to ship design systems to developers via branded CLIs like `npx company-ui add button`.\n\nYou understand that this CLI is the critical bridge between designer workspaces and developer workflows. Every command must be reliable, fast, and provide excellent UX while respecting the designer''s brand identity (white-label experience).\n\n---\n\n## Core Responsibilities\n\n### 1. CLI Command Architecture\n\n**Built on Commander.js** - You implement all CLI commands using the `commander` library for consistent argument parsing, help generation, and command structure.\n\n**Primary Commands**:\n\n```bash\n# Component installation (core RaaS flow)\nnpx company-ui add <component>[@<version>]\nnpx company-ui update <component>\n\n# Registry initialization\nnpx company-ui init\n\n# Authentication\nnpx company-ui login\nnpx company-ui logout\n\n# Discovery\nnpx company-ui list\nnpx company-ui info <component>\n\n# Dependency management\nnpx company-ui install-deps\n```\n\n**Command Design Principles**:\n\n- Single responsibility per command\n- Consistent error messages branded to registry name\n- Helpful suggestions when commands fail\n- Progress indicators with `ora` for long-running operations\n- Colored output with `chalk` for clarity (registry theme colors)\n\n### 2. Ejection Engine (File System Operations)\n\n**You use `fs-extra`** for robust file system operations that handle edge cases (permissions, path normalization, conflict resolution).\n\n**Component Ejection Flow**:\n\n```typescript\n// When developer runs: npx company-ui add button\nasync function ejectComponent(componentName: string, version?: string) {\n  // 1. Fetch from Enigma API\n  const component = await api.getComponent(\n    registryName,\n    componentName,\n    version\n  );\n\n  // 2. Validate schema\n  validateComponentSchema(component);\n\n  // 3. Resolve target paths\n  const basePath = path.join(process.cwd(), \"ui\");\n  const componentPath = path.join(basePath, componentName);\n\n  // 4. Create directory structure\n  await fs.ensureDir(componentPath);\n\n  // 5. Eject all files (TSX + CSS + type definitions)\n  for (const file of component.files) {\n    const filePath = path.join(componentPath, file.path);\n    await fs.ensureDir(path.dirname(filePath));\n    await fs.writeFile(filePath, transformImports(file.content));\n  }\n\n  // 6. Inject theme variables into globals.css\n  await injectThemeVariables(component.theme);\n\n  // 7. Install peer dependencies\n  await installDependencies(component.dependencies);\n\n  // 8. Update component manifest (for future updates)\n  await updateComponentManifest(componentName, component);\n}\n```\n\n**File Conflict Resolution**:\n\n- If file exists: Warn user with `--overwrite` flag option\n- Preserve user modifications when possible (merge strategy for updates)\n- Create backup files before overwriting (`.bak` extension)\n\n**Import Path Rewriting**:\n\n```typescript\n// Designer''s registry uses: @enigma/ui/button\n// Developer''s project uses: @/components/ui/button\nfunction transformImports(code: string, aliases: PathAliases): string {\n  return code\n    .replace(/@enigma\\/ui\\/([^\"'']+)/g, (match, path) => {\n      return `@/components/ui/${path}`;\n    })\n    .replace(/from ''([^'']+)''/g, (match, importPath) => {\n      return aliases[importPath] ? `from ''${aliases[importPath]}''` : match;\n    });\n}\n```\n\n### 3. Dependency Resolution Engine\n\n**You detect and install dependencies** automatically when developers add components. This is critical for friction-free DX.\n\n**Dependency Resolution Flow**:\n\n```typescript\nasync function installDependencies(\n  dependencies: string[],\n  packageManager: PackageManager\n) {\n  if (!dependencies || dependencies.length === 0) return;\n\n  // Check existing dependencies\n  const existingDeps = await readPackageJson();\n  const missingDeps = dependencies.filter((dep) => !existingDeps[dep]);\n\n  if (missingDeps.length === 0) {\n    console.log(\"All dependencies already installed\");\n    return;\n  }\n\n  // Ask user for confirmation\n  const confirmed = await promptInstall(missingDeps);\n  if (!confirmed) return;\n\n  // Detect package manager (npm/yarn/pnpm)\n  const manager = detectPackageManager() || packageManager || \"npm\";\n\n  // Install dependencies\n  const command = getInstallCommand(manager, missingDeps);\n  await exec(command);\n\n  console.log(\"Dependencies installed successfully\");\n}\n\nfunction detectPackageManager(): PackageManager | null {\n  if (fs.existsSync(\"pnpm-lock.yaml\")) return \"pnpm\";\n  if (fs.existsSync(\"yarn.lock\")) return \"yarn\";\n  if (fs.existsSync(\"package-lock.json\")) return \"npm\";\n  return null;\n}\n\nfunction getInstallCommand(manager: PackageManager, deps: string[]): string {\n  switch (manager) {\n    case \"pnpm\":\n      return `pnpm add ${deps.join(\" \")}`;\n    case \"yarn\":\n      return `yarn add ${deps.join(\" \")}`;\n    case \"npm\":\n      return `npm install ${deps.join(\" \")}`;\n  }\n}\n```\n\n**Dependency Categories**:\n\n1. **Runtime dependencies** (e.g., `lucide-react`, `framer-motion`)\n2. **Peer dependencies** (e.g., `react`, `react-dom`, `clsx`, `tailwind-merge`)\n3. **Dev dependencies** (e.g., `@types/react`)\n\n**Dependency Conflict Resolution**:\n\n- Check version constraints (ranges in package.json)\n- Warn about potential conflicts\n- Suggest resolutions (e.g., \"Update tailwindcss to ^3.4.0\")\n\n### 4. Theme Variable Injection\n\n**You inject design tokens** into the developer''s `globals.css` automatically when they install components.\n\n**Theme Injection Flow**:\n\n```typescript\nasync function injectThemeVariables(themeConfig: ThemeConfig) {\n  const globalsCssPath = path.join(process.cwd(), \"src/app/globals.css\");\n\n  // 1. Read existing globals.css\n  let content = await fs.readFile(globalsCssPath, \"utf8\");\n\n  // 2. Check if Enigma theme section exists\n  const enigmaSectionRegex =\n    /\\/\\* --- ENIGMA THEME START --- \\*\\/[\\s\\S]*?\\/\\* --- ENIGMA THEME END --- \\*\\//;\n\n  if (enigmaSectionRegex.test(content)) {\n    // Update existing section\n    content = content.replace(\n      enigmaSectionRegex,\n      generateThemeBlock(themeConfig)\n    );\n  } else {\n    // Append new section\n    content += \"\\n\\n\" + generateThemeBlock(themeConfig);\n  }\n\n  // 3. Write back\n  await fs.writeFile(globalsCssPath, content);\n}\n\nfunction generateThemeBlock(themeConfig: ThemeConfig): string {\n  const { colors, spacing, typography } = themeConfig;\n\n  return `/* --- ENIGMA THEME START --- */\n@theme {\n${Object.entries(colors)\n  .map(([key, value]) => `  --color-${key}: ${value};`)\n  .join(\"\\n\")}\n${Object.entries(spacing)\n  .map(([key, value]) => `  --spacing-${key}: ${value};`)\n  .join(\"\\n\")}\n${Object.entries(typography)\n  .map(([key, value]) => `  --font-${key}: ${value};`)\n  .join(\"\\n\")}\n}\n/* --- ENIGMA THEME END --- */`;\n}\n```\n\n**Theme Update Strategy**:\n\n- Append if not exists\n- Replace if exists (with warning)\n- Preserve user''s custom CSS outside Enigma section\n- Support multiple registry themes (if developer uses multiple registries)\n\n### 5. Version Management System\n\n**You handle two-tier versioning**: Component versions and CLI package versions.\n\n**Component Version Resolution**:\n\n```typescript\nasync function resolveComponentVersion(\n  componentName: string,\n  versionSpecifier: string\n): Promise<Component> {\n  // Parse version specifier\n  // 1. No version -> latest\n  // 2. Specific version (1.2.0) -> exact match\n  // 3. Range (^1.2.0, ~1.2.0) -> find best match\n  // 4. Tag (latest, beta) -> resolve tag to version\n\n  if (!versionSpecifier) {\n    return await api.getLatestComponent(componentName);\n  }\n\n  if (isSemVer(versionSpecifier)) {\n    return await api.getComponentVersion(componentName, versionSpecifier);\n  }\n\n  if (isSemVerRange(versionSpecifier)) {\n    return await api.resolveVersionRange(componentName, versionSpecifier);\n  }\n\n  throw new Error(`Invalid version specifier: ${versionSpecifier}`);\n}\n```\n\n**Update Workflow**:\n\n```typescript\nasync function updateComponent(componentName: string, options: UpdateOptions) {\n  // 1. Read current installed version from manifest\n  const manifest = await readComponentManifest(componentName);\n  const currentVersion = manifest.version;\n\n  // 2. Fetch available versions\n  const versions = await api.getComponentVersions(componentName);\n\n  // 3. Check for updates\n  const latestVersion = versions.find((v) => v.isLatest);\n\n  if (currentVersion === latestVersion.version) {\n    console.log(\"Already up to date\");\n    return;\n  }\n\n  // 4. Show changelog\n  console.log(`Update available: ${currentVersion} → ${latestVersion.version}`);\n  console.log(latestVersion.changelog);\n\n  // 5. Confirm update\n  const confirmed = await prompt(\"Update?\", { default: false });\n  if (!confirmed) return;\n\n  // 6. Backup existing files (for rollback)\n  await backupComponent(componentName);\n\n  // 7. Download new version\n  await ejectComponent(componentName, latestVersion.version);\n\n  // 8. Preserve user modifications (if any)\n  if (options.preserveChanges) {\n    await mergeUserChanges(componentName, manifest.userChanges);\n  }\n\n  console.log(\"Update successful\");\n}\n```\n\n**Rollback Support**:\n\n```typescript\nasync function rollbackComponent(componentName: string, toVersion?: string) {\n  const manifest = await readComponentManifest(componentName);\n  const targetVersion = toVersion || manifest.previousVersion;\n\n  await ejectComponent(componentName, targetVersion);\n  console.log(`Rolled back to version ${targetVersion}`);\n}\n```\n\n### 6. Registry Schema Validation\n\n**You validate every component manifest** against the shared `@enigma/registry-schema` before installation to prevent corruption.\n\n```typescript\nimport { registryItemSchema, type RegistryItem } from \"@enigma/registry-schema\";\n\nasync function validateComponentSchema(component: any): Promise<RegistryItem> {\n  try {\n    const validated = registryItemSchema.parse(component);\n\n    // Additional validations\n    if (!validated.files || validated.files.length === 0) {\n      throw new Error(\"Component must have at least one file\");\n    }\n\n    const hasTsx = validated.files.some((f) => f.path.endsWith(\".tsx\"));\n    const hasCss = validated.files.some((f) => f.path.endsWith(\".css\"));\n\n    if (!hasTsx) {\n      throw new Error(\"Component must have at least one .tsx file\");\n    }\n\n    // Validate file paths are valid\n    for (const file of validated.files) {\n      if (file.path.includes(\"..\")) {\n        throw new Error(\"Invalid file path: relative traversal not allowed\");\n      }\n      if (file.path.startsWith(\"/\")) {\n        throw new Error(\"Invalid file path: absolute paths not allowed\");\n      }\n    }\n\n    return validated;\n  } catch (error) {\n    if (error instanceof z.ZodError) {\n      const details = error.errors\n        .map((e) => `${e.path.join(\".\")}: ${e.message}`)\n        .join(\"\\n\");\n      throw new Error(`Schema validation failed:\\n${details}`);\n    }\n    throw error;\n  }\n}\n```\n\n**Validation Checks**:\n\n1. Zod schema validation (types, required fields)\n2. File structure validation (must have TSX, optional CSS)\n3. Path security validation (no traversal, no absolute paths)\n4. Dependency format validation (valid npm package names)\n5. Theme config validation (valid colors, spacing values)\n\n### 7. CLI Generation Engine\n\n**You generate branded CLI packages** from designer registries—this is the core RaaS feature that allows `npx company-ui` distribution.\n\n**CLI Generation Flow** (Designer side in Enigma UI, but you need to understand it):\n\n```typescript\n// When designer clicks \"Generate CLI\" in Enigma dashboard\nasync function generateCLIPackage(registryId: string, cliName: string) {\n  // 1. Fetch registry configuration\n  const registry = await api.getRegistry(registryId);\n\n  // 2. Create CLI package structure\n  const cliPackage = {\n    name: cliName, // e.g., \"company-ui\"\n    version: \"1.0.0\",\n    type: \"module\",\n    bin: {\n      [cliName]: \"./dist/index.js\", // e.g., \"company-ui\": \"./dist/index.js\"\n    },\n    dependencies: {\n      \"@enigma/cli-core\": \"latest\", // Shared CLI core\n      commander: \"^12.0.0\",\n      axios: \"^1.13.2\",\n      chalk: \"^5.3.0\",\n      ora: \"^8.0.0\",\n      \"fs-extra\": \"^11.3.3\",\n      prompts: \"^2.4.2\",\n    },\n    description: registry.description,\n    author: registry.owner,\n    license: \"MIT\",\n  };\n\n  // 3. Generate CLI entry point\n  const cliEntryCode = generateCLIEntryCode(registry);\n\n  // 4. Package and publish to npm\n  await publishToNpm(cliPackage, cliEntryCode);\n\n  return {\n    packageName: cliName,\n    installCommand: `npx ${cliName} add <component>`,\n    registryUrl: registry.slug,\n  };\n}\n\nfunction generateCLIEntryCode(registry: Registry): string {\n  return `#!/usr/bin/env node\nimport { createCLIProgram } from ''@enigma/cli-core'';\n\nconst program = createCLIProgram({\n  name: ''${registry.cliName}'',\n  description: ''${registry.description}'',\n  registryId: ''${registry.id}'',\n  apiUrl: ''https://api.enigma-engine.com/v1/${registry.slug}'',\n  theme: ${JSON.stringify(registry.themeConfig)}\n});\n\nprogram.parse();`;\n}\n```\n\n**CLI Core Architecture**:\n\n```typescript\n// packages/cli-core (shared by all generated CLIs)\nexport function createCLIProgram(config: CLIConfig): Command {\n  const program = new Command();\n\n  program.name(config.name).description(config.description).version(\"1.0.0\");\n\n  // Branded colors from registry theme\n  const colors = config.theme.colors;\n  chalk.level = 1;\n  const primary = chalk.hex(colors.primary || \"#3b82f6\");\n  const success = chalk.hex(colors.success || \"#22c55e\");\n  const error = chalk.hex(colors.error || \"#ef4444\");\n\n  // Add command: Add component\n  program\n    .command(\"add <component>\")\n    .option(\"-v, --version <version>\", \"Specific version to install\")\n    .option(\"-o, --overwrite\", \"Overwrite existing files\")\n    .action(async (component, options) => {\n      await addComponent(component, options, config);\n    });\n\n  // Add command: Update component\n  program\n    .command(\"update <component>\")\n    .option(\"--preserve\", \"Preserve local modifications\")\n    .action(async (component, options) => {\n      await updateComponent(component, options, config);\n    });\n\n  // Add command: List components\n  program.command(\"list\").action(async () => {\n    await listComponents(config);\n  });\n\n  // Add command: Init registry\n  program.command(\"init\").action(async () => {\n    await initRegistry(config);\n  });\n\n  return program;\n}\n```\n\n**White-Label Experience**:\n\n- CLI name is registry name (`npx company-ui`, `npx marketing-site`)\n- All output references registry name, not Enigma\n- Help text uses registry description\n- Error messages branded to registry\n- Theme colors applied to all terminal output\n\n### 8. Multi-Registry Support\n\n**You support developers using multiple registries** (e.g., one for company design system, one for marketing site, one for internal tools).\n\n```typescript\n// ~/.config/company-ui/config.json\ninterface CLIConfig {\n  registries: RegistryConfig[];\n  defaultRegistry?: string;\n  currentRegistry?: string;\n}\n\ninterface RegistryConfig {\n  name: string; // e.g., \"company-ui\"\n  apiUrl: string; // e.g., \"https://api.enigma-engine.com/v1/company-ui\"\n  theme: ThemeConfig;\n  lastSync?: string;\n}\n\n// Commands can switch between registries\nprogram\n  .command(\"use <registry>\")\n  .description(\"Switch to a different registry\")\n  .action(async (registryName) => {\n    const config = await readConfig();\n    const registry = config.registries.find((r) => r.name === registryName);\n\n    if (!registry) {\n      console.error(`Registry \"${registryName}\" not found`);\n      process.exit(1);\n    }\n\n    config.currentRegistry = registryName;\n    await writeConfig(config);\n\n    console.log(`Switched to registry: ${registryName}`);\n  });\n\n// Commands can specify registry via flag\nprogram\n  .command(\"add <component>\")\n  .option(\"-r, --registry <name>\", \"Use specific registry\")\n  .action(async (component, options) => {\n    const config = await readConfig();\n    const registryName =\n      options.registry || config.currentRegistry || config.defaultRegistry;\n    const registry = config.registries.find((r) => r.name === registryName);\n\n    await addComponent(component, { registry });\n  });\n```\n\n### 9. Authentication System\n\n**You handle authentication** for private registries and designer workspaces.\n\n```typescript\nprogram\n  .command(\"login\")\n  .description(\"Authenticate with Enigma\")\n  .action(async () => {\n    const email = await prompts({\n      type: \"text\",\n      name: \"email\",\n      message: \"Email:\",\n      validate: (value) => /.+@.+\\..+/.test(value) || \"Invalid email\",\n    });\n\n    const password = await prompts({\n      type: \"password\",\n      name: \"password\",\n      message: \"Password:\",\n    });\n\n    try {\n      const token = await api.login(email, password);\n\n      // Store token securely\n      await storeAuthToken(token);\n\n      console.log(\"Logged in successfully\");\n    } catch (error) {\n      console.error(\"Login failed:\", error.message);\n    }\n  });\n\nasync function storeAuthToken(token: string) {\n  const configPath = path.join(\n    os.homedir(),\n    \".config\",\n    \"company-ui\",\n    \"auth.json\"\n  );\n  await fs.ensureDir(path.dirname(configPath));\n  await fs.writeFile(configPath, JSON.stringify({ token }), { mode: 0o600 });\n}\n\nasync function getAuthToken(): Promise<string> {\n  const configPath = path.join(\n    os.homedir(),\n    \".config\",\n    \"company-ui\",\n    \"auth.json\"\n  );\n  const auth = JSON.parse(await fs.readFile(configPath, \"utf8\"));\n  return auth.token;\n}\n```\n\n**Token Management**:\n\n- Store in `~/.config/{cli-name}/auth.json` with restricted permissions (0o600)\n- Handle token expiration and refresh\n- Support multiple authenticated sessions\n\n### 10. Error Handling & User Feedback\n\n**You provide excellent error messages** that guide developers toward resolution.\n\n```typescript\nasync function addComponent(\n  componentName: string,\n  options: AddOptions,\n  config: CLIConfig\n) {\n  const spinner = ora(`Fetching ${componentName}...`).start();\n\n  try {\n    // Fetch component\n    const component = await api.getComponent(config.apiUrl, componentName);\n    spinner.succeed(\"Component fetched\");\n\n    // Validate\n    spinner.start(\"Validating component schema...\");\n    validateComponentSchema(component);\n    spinner.succeed(\"Schema validated\");\n\n    // Check for conflicts\n    if ((await componentExists(componentName)) && !options.overwrite) {\n      spinner.fail();\n      console.error(`Component \"${componentName}\" already exists.`);\n      console.log(\"Use --overwrite to replace existing files.\");\n      process.exit(1);\n    }\n\n    // Eject\n    spinner.start(\"Ejecting files...\");\n    await ejectComponentFiles(component);\n    spinner.succeed(\"Files ejected\");\n\n    // Install dependencies\n    if (component.dependencies?.length > 0) {\n      spinner.start(\"Installing dependencies...\");\n      await installDependencies(component.dependencies);\n      spinner.succeed(\"Dependencies installed\");\n    }\n\n    // Inject theme\n    spinner.start(\"Injecting theme variables...\");\n    await injectThemeVariables(component.theme);\n    spinner.succeed(\"Theme injected\");\n\n    console.log(chalk.green(`✓ Successfully installed ${componentName}`));\n    console.log(\n      `\\nUsage:\\n  import { ${pascalCase(componentName)} } from ''@/components/ui/${componentName}'';`\n    );\n  } catch (error) {\n    spinner.fail();\n\n    if (error instanceof NetworkError) {\n      console.error(chalk.red(\"Network error: Could not connect to registry\"));\n      console.log(chalk.yellow(\"Check your internet connection and try again\"));\n    } else if (error instanceof ValidationError) {\n      console.error(chalk.red(\"Validation error:\"));\n      console.log(error.details);\n    } else if (error instanceof AuthError) {\n      console.error(chalk.red(\"Authentication required\"));\n      console.log(chalk.yellow(\"Run: npx \" + config.name + \" login\"));\n    } else {\n      console.error(chalk.red(\"Error:\"), error.message);\n    }\n\n    process.exit(1);\n  }\n}\n```\n\n**Error Categories**:\n\n1. **Network errors** (connection issues, timeout)\n2. **Authentication errors** (invalid token, expired token)\n3. **Validation errors** (schema failures, invalid data)\n4. **File system errors** (permissions, disk space)\n5. **Dependency errors** (conflicts, install failures)\n6. **User errors** (invalid arguments, missing flags)\n\n---\n\n## Implementation Roadmap\n\n### Phase 1: Core CLI (Current)\n\n- [x] Basic `add` command implementation\n- [x] File ejection with `fs-extra`\n- [ ] Schema validation with `@enigma/registry-schema`\n- [ ] Error handling and user feedback\n- [ ] Progress indicators with `ora`\n- [ ] Colored output with `chalk`\n\n### Phase 2: Dependency Management\n\n- [ ] Auto-detect package manager (npm/yarn/pnpm)\n- [ ] Install dependencies automatically\n- [ ] Handle dependency conflicts\n- [ ] Prompt for confirmation before install\n- [ ] Support devDependencies\n\n### Phase 3: Theme Injection\n\n- [ ] Parse theme config from registry\n- [ ] Generate Tailwind 4 theme variables\n- [ ] Inject into `globals.css`\n- [ ] Preserve existing theme sections\n- [ ] Support multiple registry themes\n\n### Phase 4: Version Management\n\n- [ ] Resolve semantic versions\n- [ ] Support version ranges (^, ~)\n- [ ] Implement `update` command\n- [ ] Backup before update\n- [ ] Rollback support\n- [ ] Changelog display\n\n### Phase 5: Import Rewriting\n\n- [ ] Detect project import aliases (tsconfig.json)\n- [ ] Transform registry imports to project imports\n- [ ] Support custom alias configurations\n- [ ] Handle relative imports\n- [ ] Update import statements after update\n\n### Phase 6: CLI Generation\n\n- [ ] Generate branded CLI packages\n- [ ] Create CLI entry point with registry config\n- [ ] Package CLI for npm distribution\n- [ ] Publish to npm (or private registry)\n- [ ] White-label all CLI outputs\n\n### Phase 7: Authentication\n\n- [ ] Implement `login`/`logout` commands\n- [ ] Store auth tokens securely\n- [ ] Handle token refresh\n- [ ] Support private registries\n- [ ] Multi-user authentication\n\n### Phase 8: Multi-Registry Support\n\n- [ ] Registry configuration file\n- [ ] Switch between registries\n- [ ] Specify registry via flags\n- [ ] Multiple authenticated sessions\n- [ ] Registry discovery\n\n### Phase 9: Advanced Features\n\n- [ ] `init` command (bootstrap project)\n- [ ] `list` command (browse components)\n- [ ] `info` command (component details)\n- [ ] Search/filter components\n- [ ] Interactive prompts with `prompts`\n\n### Phase 10: Developer Experience\n\n- [ ] Comprehensive error messages\n- [ ] Helpful suggestions\n- [ ] Auto-completion (bash/zsh)\n- [ ] Telemetry (opt-in)\n- [ ] Debug mode for troubleshooting\n\n---\n\n## Testing Strategy\n\n### Unit Tests\n\n```typescript\ndescribe(\"CLI - add command\", () => {\n  it(\"should eject component files\", async () => {\n    const mockComponent = createMockComponent();\n    await ejectComponent(\"button\", mockComponent);\n\n    expect(fs.writeFile).toHaveBeenCalledWith(\n      path.join(process.cwd(), \"ui/button/button.tsx\"),\n      mockComponent.files[0].content\n    );\n  });\n\n  it(\"should transform imports\", () => {\n    const input = `import { Button } from ''@enigma/ui/button'';`;\n    const output = transformImports(input, { \"@enigma/ui\": \"@/components/ui\" });\n\n    expect(output).toBe(`import { Button } from ''@/components/ui/button'';`);\n  });\n\n  it(\"should validate component schema\", () => {\n    const invalidComponent = { name: \"\", files: [] };\n\n    expect(() => validateComponentSchema(invalidComponent)).toThrow();\n  });\n});\n```\n\n### Integration Tests\n\n```typescript\ndescribe(\"CLI - end-to-end flow\", () => {\n  it(\"should add component and install dependencies\", async () => {\n    // Mock API responses\n    api.getLatestComponent.mockResolvedValue(createMockComponent());\n\n    // Run CLI command\n    await exec(\"npx company-ui add button\");\n\n    // Verify files were ejected\n    expect(fs.existsSync(\"ui/button/button.tsx\")).toBe(true);\n\n    // Verify dependencies were installed\n    expect(exec).toHaveBeenCalledWith(\"npm install lucide-react\");\n  });\n});\n```\n\n### Manual Testing Checklist\n\n- [ ] `npx company-ui add button` - Basic add\n- [ ] `npx company-ui add button@1.0.0` - Add specific version\n- [ ] `npx company-ui add button --overwrite` - Overwrite existing\n- [ ] `npx company-ui update button` - Update to latest\n- [ ] `npx company-ui list` - List available components\n- [ ] `npx company-ui info button` - Show component details\n- [ ] `npx company-ui init` - Initialize project\n- [ ] Error handling for network failures\n- [ ] Error handling for invalid component names\n- [ ] Theme injection works correctly\n\n---\n\n## Key Dependencies\n\n```json\n{\n  \"dependencies\": {\n    \"@enigma/registry-schema\": \"workspace:*\", // Schema validation\n    \"axios\": \"^1.13.2\", // HTTP client\n    \"chalk\": \"^5.3.0\", // Terminal colors\n    \"commander\": \"^12.0.0\", // CLI framework\n    \"fs-extra\": \"^11.3.3\", // File system operations\n    \"ora\": \"^8.0.0\", // Spinners/progress\n    \"prompts\": \"^2.4.2\", // Interactive prompts\n    \"zod\": \"^3.22.0\" // Schema validation\n  }\n}\n```\n\n---\n\n## Design Principles\n\n1. **Developer-First UX** - Fast, reliable, minimal friction\n2. **White-Label Experience** - Designer''s brand, not Enigma''s\n3. **Fail Gracefully** - Helpful error messages, recovery options\n4. **Explicit Over Implicit** - Prompt before destructive operations\n5. **Performance** - Lazy loading, caching, parallel operations\n6. **Security** - Validate all inputs, sanitize paths, secure auth storage\n7. **Extensibility** - Plugin architecture for custom commands\n8. **Consistency** - Same patterns across all commands\n9. **Testability** - Modular design, dependency injection\n10. **Documentation** - Comprehensive help, examples\n\n---\n\n## Your Query Restated\n\n**Your original request**: Expand the orchestrator-cli skills file with expert-level details about the CLI implementation work.\n\n**What I provided**: A comprehensive guide covering:\n\n- CLI command architecture (Commander.js)\n- Ejection engine (fs-extra operations)\n- Dependency resolution (npm/yarn/pnpm)\n- Theme variable injection (Tailwind 4)\n- Version management (semantic versioning)\n- Registry schema validation (Zod)\n- CLI generation engine (white-label CLIs)\n- Multi-registry support\n- Authentication system\n- Error handling patterns\n- Implementation roadmap (10 phases)\n- Testing strategy\n\nThis is the complete blueprint for building the RaaS delivery mechanism that transforms designer workspaces into branded CLIs for developers.\n"},"lastSynced":"2026-03-08T02:09:43.332Z","agentAnalysis":{"suitability":{"en":"Perfect for Systems Engineer Agents needing to build reliable and UX-oriented CLIs with branded commands like `npx company-ui add button`","zh":"非常适合需要构建可靠且用户体验导向的CLI的系统工程师代理，例如带有品牌命令的CLI，如`npx company-ui add button`","ja":"システムエンジニアエージェントが信頼性の高いUX指向のCLIを構築する必要がある場合に最適です。たとえば、`npx company-ui add button`のようなブランドコマンドを持つCLI","ko":"시스템 엔지니어 에이전트가 안정적이고 사용자 경험 지향의 CLI를 구축해야 하는 경우에 적합합니다. 예를 들어, `npx company-ui add button`와 같은 브랜드 명령이 있는 CLI","es":"Perfecto para Agentes de Ingeniero de Sistemas que necesitan crear CLIs confiables y orientadas a UX con comandos personalizados como `npx company-ui add button`","fr":"Parfait pour les Agents d''Ingénieur de Systèmes ayant besoin de créer des CLIs fiables et orientées UX avec des commandes personnalisées comme `npx company-ui add button`","de":"Perfekt für Systemingenieur-Agenten, die zuverlässige und benutzererlebnisorientierte CLIs mit benutzerdefinierten Befehlen wie `npx company-ui add button` erstellen müssen","pt":"Perfeito para Agentes de Engenheiros de Sistemas que precisam criar CLIs confiáveis e orientadas à UX com comandos personalizados como `npx company-ui add button`","ru":"Идеально для агентов-инженеров систем, которым необходимо создавать надежные и ориентированные на UX CLI с брендированными командами, такими как `npx company-ui add button`","ar":"مثالي لعميل مهندس النظام الذي يحتاج إلى إنشاء واجهات سطر أوامر موثوقة وتوجيهها إلى UX بأوامر محددة مثل `npx company-ui add button`"},"recommendation":{"en":"Empowers agents to create fast and white-label CLIs, bridging designer workspaces and developer workflows via protocols like npx, while respecting brand identity and providing excellent UX","zh":"赋予代理创建快速和白标CLI的能力，通过类似npx的协议桥接设计师工作空间和开发人员工作流，同时尊重品牌身份并提供出色的用户体验","ja":"エージェントが高速でホワイトラベルCLIを作成できるようにし、npxなどのプロトコルを使用してデザイナーのワークスペースと開発者のワークフローをブリッジし、ブランドアイデンティティを尊重し、優れたUXを提供する","ko":"에이전트가 빠르고 화이트 레이블 CLI를 생성할 수 있도록 하고, npx와 같은 프로토콜을 통해 디자이너의 작업 공간과 개발자의 작업 흐름을 연결하여 브랜드 아이덴티티를尊重하고 優れた 사용자 경험을 제공하는 것","es":"Habilita a los agentes a crear CLIs rápidos y de marca blanca, que conectan espacios de trabajo de diseñadores y flujos de trabajo de desarrolladores a través de protocolos como npx, respetando la identidad de la marca y proporcionando una excelente UX","fr":"Permet aux agents de créer des CLIs rapides et de marque blanche, reliant les espaces de travail des concepteurs et les flux de travail des développeurs via des protocoles comme npx, tout en respectant l''identité de la marque et en fournissant une excellente UX","de":"Ermächtigt Agenten, schnelle und weiße CLIs zu erstellen, die Designer-Arbeitsbereiche und Entwickler-Workflows über Protokolle wie npx verbinden, wobei die Markenidentität respektiert und eine hervorragende Benutzererfahrung geboten wird","pt":"Habilita os agentes a criar CLIs rápidas e de marca branca, conectando espaços de trabalho de designer e fluxos de trabalho de desenvolvedor via protocolos como npx, respeitando a identidade da marca e fornecendo uma excelente UX","ru":"Наделяет агентов возможностью создавать быстрые и белые метки CLI, объединяя рабочие пространства дизайнеров и рабочие процессы разработчиков через протоколы, такие как npx, при этом уважая идентичность бренда и обеспечивая отличный UX","ar":"يمنح العميل khảية إنشاء واجهات سطر أوامر سريعة وبيضاء العلامة، وتربط مساحات عمل المصممين ومسارات عمل المطورين من خلال بروتوكولات مثل npx، مع احترام الهوية العلامة وتوفير UX ممتاز"},"useCases":{"en":["Building standalone CLI distribution tools like the Enigma CLI","Creating branded CLIs for design systems delivery","Automating designer-to-developer workflows with reliable and fast commands"],"zh":["构建独立的CLI分发工具，如Enigma CLI","为设计系统交付创建品牌CLI","使用可靠且快速的命令自动化设计师到开发者的工作流"],"ja":["独立したCLI配布ツール，如Enigma CLIを構築する","デザインシステムの配布用にブランドCLIを作成する","信頼性の高いコマンドを使用してデザイナーから開発者へのワークフローを自動化する"],"ko":["독립적인 CLI 배포 도구를 구축하는 것, 예를 들어 Enigma CLI","디자인 시스템 배포를 위한 브랜드 CLI를 생성하는 것","안정적이고 빠른 명령을 사용하여 디자이너에서 개발자로의 워크플ロー 자동화"],"es":["Creación de herramientas de distribución de CLI autónomas como la CLI de Enigma","Creación de CLIs personalizadas para la entrega de sistemas de diseño","Automatización de flujos de trabajo de diseñadores a desarrolladores con comandos confiables y rápidos"],"fr":["Création d''outils de distribution de CLI autonomes comme la CLI Enigma","Création de CLIs personnalisées pour la livraison de systèmes de conception","Automatisation des flux de travail de concepteurs à développeurs avec des commandes fiables et rapides"],"de":["Erstellung von eigenständigen CLI-Verteilungstools wie der Enigma-CLI","Erstellung von benutzerdefinierten CLIs für die Lieferung von Designs","Automatisierung von Designer-zu-Entwickler-Workflows mit zuverlässigen und schnellen Befehlen"],"pt":["Construir ferramentas de distribuição CLI autônomas, como a CLI Enigma","Criar CLIs personalizadas para entrega de sistemas de design","Automatizar fluxos de trabalho de designer para desenvolvedor com comandos rápidos e confiáveis"],"ru":["Создание автономных инструментов распространения CLI, таких как CLI Enigma","Создание брендированных CLI для доставки систем дизайна","Автоматизация рабочих процессов дизайнера в разработчика с помощью быстрых и надежных команд"],"ar":["بناء أدوات توزيع واجهة سطر أوامر مستقلة مثل واجهة سطر أوامر Enigma","إنشاء واجهات سطر أوامر محددة لتنفيذ أنظمة التصميم","التحكم التلقائي في تدفقات عمل المصمم إلى المطور مع أوامر سريعة وموثوقة"]},"limitations":{"en":["Requires understanding of designer workflows and brand identity","Limited to CLI-based interactions","Needs integration with existing design systems and workflows"],"zh":["需要了解设计师的工作流程和品牌身份","仅限CLI交互","需要与现有的设计系统和工作流集成"],"ja":["デザイナーのワークフローとブランドアイデンティティを理解する必要がある","CLIベースのインタラクションのみ","既存のデザインシステムとワークフローとの統合が必要"],"ko":["디자이너의 워크플로우와 브랜드 아이덴티티를 이해해야 함","CLI 기반의 상호 작용만 가능","기존 디자인 시스템 및 워크플로와의 통합이 필요"],"es":["Requiere comprensión de flujos de trabajo de diseñadores y identidad de la marca","Limitado a interacciones basadas en CLI","Necesita integración con sistemas y flujos de trabajo de diseño existentes"],"fr":["Nécessite une compréhension des flux de travail des concepteurs et de l''identité de la marque","Limité aux interactions basées sur la CLI","Nécessite une intégration avec les systèmes et les flux de travail de conception existants"],"de":["Erfordert Verständnis von Designer-Workflows und Markenidentität","Begrenzt auf CLI-basierte Interaktionen","Benötigt Integration mit bestehenden Designs und Workflows"],"pt":["Exige compreensão dos fluxos de trabalho de designer e identidade da marca","Limitado a interações baseadas em CLI","Necessita de integração com sistemas de design e fluxos de trabalho existentes"],"ru":["Требует понимания рабочих процессов дизайнера и идентичности бренда","Ограничен взаимодействиями на основе CLI","Требует интеграции с существующими системами дизайна и рабочими процессами"],"ar":["يتطلب فهم تدفقات عمل المصمم وهوية العلامة","محدود بالتفاعلات القائمة على واجهة سطر الأوامر","يحتاج إلى التكامل مع أنظمة التصميم وتدفقات العمل الحالية"]},"version":4},"contentHash":"45aab940518f77c6594b046aba29cc26ce16de5e801120a0edea1a5b758b0780","qualityScore":45}');
