INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tetherto/wdk-docs/wdk', 'wdk', 'tetherto', 'wdk-docs', 'community', 'wdk tetherto wdk-docs community The wdk skill provides a multi-chain wallet SDK for developers, offering a common interface from @tetherto/wdk-wallet. It facilitates URL fetching workflows and documentation access. wdk是Tether的多链钱包SDK，提供了统一的接口和配置 wdkはTetherのマルチチェーンウォレットSDKで、共通のインターフェースと設定を提供する wdk는 Tether의 멀티체인 월렛 SDK로 공통 인터페이스와 설정을 제공합니다 WDK es un SDK de wallet multi-chain que proporciona interfaces comunes a través de @tetherto/wdk-wallet. La documentación oficial se encuentra en docs.wallet.tether.io WDK est un SDK de wallet multi-chain qui fournit des interfaces communes via @tetherto/wdk-wallet. La documentation officielle est disponible sur docs.wallet.tether.io WDK ist ein Multi-Chain-Wallet-SDK, das über @tetherto/wdk-wallet gemeinsame Schnittstellen bietet. Die offizielle Dokumentation finden Sie unter docs.wallet.tether.io O WDK é uma ferramenta de wallet multi-chain para desenvolvedores, com documentação oficial e GitHub. Ele fornece uma interface comum para todos os módulos. WDK - это многоцепочечный кошелек SDK для разработчиков, с официальной документацией и GitHub. Он предоставляет общий интерфейс для всех модулей для ИИ Агентов WDK هو SDK محفظة متعددة السلاسل لل مطورين، مع توثيق رسمي و GitHub. ي 提供 واجهة مشتركة لجميع الوحدات للأدوات الذكية how to use wdk wdk multi-chain wallet SDK wdk alternative wdk setup guide wdk vs wallet SDKs wdk install what is wdk wdk documentation wdk GitHub repository wdk 多链钱包SDK Tether AI工具 跨链钱包 web_fetch web_search GitHub Utilizes @tetherto/wdk-wallet for common interfaces Supports URL fetching workflow with web_fetch and web_search Provides documentation access through https://docs.wallet.tether.io Includes GitHub repository at https://github.com/tetherto/wdk-core Offers module doc pages with subpages for usage and configuration wdk is a multi-chain wallet SDK providing a common interface for various modules, enabling seamless wallet integration and management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Git-Fg/meta-plugin-manager/command-authoring', 'community', 'Git-Fg', 'meta-plugin-manager', 'Git-Fg/meta-plugin-manager', 'command-authoring', 0, 0, 45, '2026-03-08T01:57:15.552Z', '2026-03-08T02:11:31.829Z', 'f921ddf243595c687f2577d25b1c123c6c1e75d094201f3820f0ca437e47e531', '{"id":"Git-Fg/meta-plugin-manager/command-authoring","name":"command-authoring","description":{"en":"Command-authoring enables developers to create single-file commands with dynamic content and runtime state using @path and !command injection. This skill benefits developers working with dynamic file content and shell commands.","zh":"命令创建技能允许开发者使用@path和!command注入创建单文件命令，实现动态内容和运行时状态","ja":"コマンド作成スキルは、開発者が@pathと!commandの注入を使用して単一ファイルコマンドを作成できるようにし、動的なコンテンツと実行時状態を実現する","ko":"명령어 작성 스킬을 사용하면 개발자가 @path와 !command 삽입을 사용하여 단일 파일 명령어를 생성하여 동적 콘텐츠와 런타임 상태를 구현할 수 있습니다","es":"El command-authoring permite crear comandos de un solo archivo con inyección de contenido dinámico y estado de ejecución","fr":"Le command-authoring permet de créer des commandes de fichiers uniques avec injection de contenu dynamique et état d''exécution","de":"Das command-authoring ermöglicht die Erstellung einzelner Dateikommandos mit dynamischem Inhalt und Laufzeitstatus","pt":"Crie comandos personalizados com injeção de conteúdo dinâmico e estado de tempo de execução","ru":"Создайте пользовательские команды с динамическим контентом и состоянием выполнения","ar":"انشئ أوامر مخصصة مع محتوى ديناميكي وحالة وقت التشغيل"},"seo":{"title":{"en":"Command-Authoring: Dynamic Content Setup Guide | AI Agent...","zh":"命令创建指南：使用@path和!command注入","ja":"コマンド作成ベストプラクティス：@pathと!commandの注入","ko":"명령어 작성 가이드: @path와 !command 삽입","es":"Guía de configuración de command-authoring para agentes d...","fr":"Guide de mise en place de command-authoring pour les outi...","de":"Einrichtungsleitfaden für command-authoring in KI-Agents","pt":"Guia de Configuração de Autenticação de Comando","ru":"Настройка Авторства Команд: Лучшие Практики","ar":"دليل إعداد أمر الإصدار"},"description":{"en":"Learn how to create single-file commands with @path and !command injection for dynamic content and runtime state. Get started with command-authoring today!","zh":"学习如何使用@path和!command注入创建动态命令，实现运行时状态和错误处理","ja":"動的なコマンドを作成する方法を学び、@pathと!commandの注入を使用して実行時状態とエラーハンドリングを実現する","ko":"동적 명령어를 생성하고 @path와 !command 삽입을 사용하여 런타임 상태 및 오류 처리를 구현하는 방법을 배우세요","es":"Aprende a crear comandos de un solo archivo con inyección de contenido dinámico y estado de ejecución con @path y !command","fr":"Découvrez comment créer des commandes de fichiers uniques avec injection de contenu dynamique et état d''exécution avec @path et !command","de":"Erfahren Sie, wie Sie einzelne Dateikommandos mit @path und !command erstellen und dynamischen Inhalt sowie Laufzeitstatus einfügen","pt":"Aprenda a criar comandos em um único arquivo com injeção de conteúdo dinâmico e estado de tempo de execução usando @path e !command","ru":"Изучите создание команд в одном файле с помощью @path и !command для динамического контента и состояния выполнения","ar":"تعلم كيفية إنشاء أوامر في ملف واحد مع حقن المحتوى الديناميكي وحالة وقت التشغيل باستخدام @path و !command"},"definition":{"en":"Command-authoring is a technique for creating single-file commands with dynamic content and runtime state using @path and !command injection patterns.","zh":"命令创建是使用@path和!command注入创建单文件命令的过程","ja":"コマンド作成は、@pathと!commandの注入を使用して単一ファイルコマンドを作成するプロセスです","ko":"명령어 작성은 @path와 !command 삽입을 사용하여 단일 파일 명령어를 생성하는 프로세스입니다","es":"Command-authoring es una técnica para crear comandos de un solo archivo con inyección de contenido dinámico","fr":"Le command-authoring est une technique pour créer des commandes de fichiers uniques avec injection de contenu dynamique","de":"Command-authoring ist eine Technik zur Erstellung einzelner Dateikommandos mit dynamischem Inhalt","pt":"Autenticação de comando é uma técnica para criar comandos em um único arquivo","ru":"Авторство команд - это техника создания команд в одном файле","ar":"أمر الإصدار هو تقنية لإنشاء أوامر في ملف واحد"},"features":{"en":["Supports @path pattern for injecting file content at invocation time","Enables execution of shell commands using !`command` syntax for dynamic state","Provides graceful error handling for robust command execution","Allows for creation of single-file commands with valid frontmatter","Supports proper @/! injection patterns for dynamic content"],"zh":["使用@path注入文件内容","使用!command执行shell命令","实现运行时状态和错误处理","支持单文件命令创建","动态内容生成"],"ja":["ファイル内容を@pathで注入する","シェルコマンドを!commandで実行する","実行時状態とエラーハンドリングを実現する","単一ファイルコマンドの作成をサポートする","動的なコンテンツ生成"],"ko":["파일 내용을 @path로 삽입","쉘 명령어를 !command로 실행","런타임 상태 및 오류 처리를 구현","단일 파일 명령어 생성 지원","동적 콘텐츠 생성"],"es":["Inyección de contenido dinámico con @path","Ejecución de comandos de shell con !command","Manejo de errores elegante","Compatibilidad con frontmatter","Patrones de inyección @/! para contenido dinámico"],"fr":["Injection de contenu dynamique avec @path","Exécution de commandes de shell avec !command","Gestion d''erreurs élégante","Compatibilité avec frontmatter","Modèles d''injection @/! pour contenu dynamique"],"de":["Dynamischer Inhalt mit @path","Ausführung von Shell-Befehlen mit !command","Elegantes Fehlerhandling","Kompatibilität mit frontmatter","Muster für @/!-Injektion für dynamischen Inhalt"],"pt":["Injeção de conteúdo dinâmico usando @path","Execução de comandos shell com !command","Tratamento de erros gracioso","Criação de comandos em um único arquivo","Suporte a estado de tempo de execução"],"ru":["Внедрение динамического контента с помощью @path","Выполнение команд shell с помощью !command","Благоприятное обработка ошибок","Создание команд в одном файле","Поддержка состояния выполнения"],"ar":["حقن المحتوى الديناميكي باستخدام @path","تشغيل أوامر Shell باستخدام !command","معالجة الأخطاء بسلاسة","إنشاء أوامر في ملف واحد","دعم حالة وقت التشغيل"]},"keywords":{"en":["how to use command-authoring","command-authoring setup guide","command-authoring vs alternative tools","command-authoring install","what is command-authoring","command-authoring tutorial","command-authoring dynamic content","command-authoring runtime state","command-authoring error handling"],"zh":["命令创建","AIエージェント","动态命令","运行时状态","错误处理","单文件命令","命令注入","shell命令"],"ja":["コマンド作成","AIエージェント","動的なコマンド","実行時状態","エラーハンドリング","単一ファイルコマンド","コマンド注入","シェルコマンド"],"ko":["명령어 작성","AI 에이전트","동적 명령어","런타임 상태","오류 처리","단일 파일 명령어","명령어 삽입","쉘 명령어"],"es":["command-authoring","agentes de inteligencia artificial","inyección de contenido dinámico","estado de ejecución","comandos de un solo archivo","frontmatter","patrones de inyección @/!"],"fr":["command-authoring","outils d''intelligence artificielle","injection de contenu dynamique","état d''exécution","commandes de fichiers uniques","frontmatter","modèles d''injection @/!"],"de":["command-authoring","KI-Agents","dynamischer Inhalt","Laufzeitstatus","einzelne Dateikommandos","frontmatter","Muster für @/!-Injektion"],"pt":["autenticação de comando","injeção de conteúdo dinâmico","execução de comandos shell","tratamento de erros","criação de comandos","estado de tempo de execução","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["авторство команд","внедрение динамического контента","выполнение команд shell","обработка ошибок","создание команд","состояние выполнения","разработка программного обеспечения","инструменты разработки"],"ar":["أمر الإصدار","حقن المحتوى الديناميكي","تشغيل أوامر Shell","معالجة الأخطاء","إنشاء أوامر","حالة وقت التشغيل","تطوير البرمجيات","أدوات التطوير"]}},"owner":"Git-Fg","repo":"meta-plugin-manager","repoPath":"Git-Fg/meta-plugin-manager","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.552Z","topics":[],"category":"community","skillMd":{"name":"command-authoring","description":"Create single-file commands with dynamic content injection (@path and !command). Use when building commands that need filesystem access, git state, runtime context, or argument handling with $1 placeholders. Includes @file injection, !shell execution, <injected_content> wrappers, and single-file structure patterns. Not for skills (use skill-development) or audit workflows.","bodyPreview":"<mission_control>\n<objective>Create single-file commands with @path and !command injection for dynamic content and runtime state</objective>\n<success_criteria>Command has valid frontmatter, proper @/! injection patterns, and graceful error handling</success_criteria>\n</mission_control>\n\n## Quick Start\n\n**If you need to inject file content:** Use `@path` pattern at invocation time.\n\n**If you need to execute shell commands:** Use `` !`command` `` for dynamic state.\n\n**If you need graceful file han","body":"<mission_control>\n<objective>Create single-file commands with @path and !command injection for dynamic content and runtime state</objective>\n<success_criteria>Command has valid frontmatter, proper @/! injection patterns, and graceful error handling</success_criteria>\n</mission_control>\n\n## Quick Start\n\n**If you need to inject file content:** Use `@path` pattern at invocation time.\n\n**If you need to execute shell commands:** Use `` !`command` `` for dynamic state.\n\n**If you need graceful file handling:** Wrap `@path` in `<injected_content>` with fallback text.\n\n**If you need argument handling:** Use `$1` for unique identifiers (IDs, hashes, slugs) only.\n\n## Navigation\n\n| If you need...    | Read this section...             |\n| :---------------- | :------------------------------- |\n| File injection    | ## PATTERN: @ Path Injection     |\n| Command execution | ## PATTERN: ! Command Injection  |\n| Structure         | ## PATTERN: Command Structure    |\n| Namespacing       | ## PATTERN: Namespacing          |\n| Thin interface    | ## PATTERN: Thin Interface       |\n| Engine separation | ## PATTERN: Engine Separation    |\n| Argument handling | ## PATTERN: Argument Patterns    |\n| Anti-patterns     | ## ANTI-PATTERN: Common Mistakes |\n\n## PATTERN: @ Path Injection\n\n### Basic @ Syntax\n\n```markdown\n<injected_content>\n@.claude/workspace/handoffs/diagnostic.yaml\n</injected_content>\n```\n\nOr inline:\n\n```markdown\nCurrent handoff: @.claude/workspace/handoffs/latest.yaml\n```\n\n### What @ Does\n\nAt invocation time, the file content replaces the `@path` pattern. This captures the **current state** of files that change between sessions.\n\n### @ Rules\n\n| Rule                           | Example                            |\n| :----------------------------- | :--------------------------------- |\n| Wrap in `<injected_content>`   | Semantic grouping                  |\n| Use absolute or relative paths | `@/path/file` or `@./path/file`    |\n| Content replaces pattern       | File content inlines at invocation |\n\n### @ Use Cases\n\n| Use Case         | Example                              |\n| :--------------- | :----------------------------------- |\n| Handoff files    | `@.claude/workspace/handoffs/*.yaml` |\n| Configuration    | `@.claude/settings.json`             |\n| Diagnostic files | `@.claude/workspace/diagnostic.yaml` |\n\n### Error Handling\n\n| Scenario     | Behavior                                  |\n| :----------- | :---------------------------------------- |\n| File exists  | Injects content                           |\n| File missing | Empty result (command handles gracefully) |\n\n### Graceful File Handling\n\n```markdown\n<injected_content>\n@.claude/workspace/handoffs/diagnostic.yaml\n</injected_content>\n\nIf file doesn''t exist: Create new diagnostic\n```\n\n### Multiple File Injection\n\n```markdown\n<injected_content>\n@.claude/workspace/handoffs/diagnostic.yaml\n@.claude/workspace/handoffs/handoff.yaml\n</injected_content>\n```\n\n---\n\n## PATTERN: ! Command Injection\n\n### Basic ! Syntax\n\n```markdown\nCurrent branch: !`git branch --show-current`\nGit status: !`git status --short`\n```\n\n### What ! Does\n\nAt invocation time, the bash command executes and its output replaces the `` !`command` `` pattern. This captures **runtime state** that changes between invocations.\n\n### ! Rules\n\n| Rule                         | Example                 |\n| :--------------------------- | :---------------------- |\n| Use backticks                | `` !`command` ``        |\n| Standard bash syntax         | `git`, `gh`, `ls`, etc. |\n| Output inlines at invocation | stdout replaces pattern |\n\n### ! Use Cases\n\n| Use Case   | Example                                        |\n| :--------- | :--------------------------------------------- |\n| Git state  | `` !`git branch --show-current``               |\n| CI status  | `` !`gh run list --limit 1 --json conclusion`` |\n| File stats | `` !`wc -l file.ts``                           |\n\n### Error Handling\n\n| Scenario         | Behavior                                  |\n| :--------------- | :---------------------------------------- |\n| Command succeeds | Injects stdout                            |\n| Command fails    | Empty result (command handles gracefully) |\n\n### Safe Commands\n\n```markdown\n✅ Safe:\n!`git branch --show-current`\n!`gh run list --limit 1 --json conclusion`\n!`pwd`\n!`ls *.md`\n\n❌ Unsafe:\n!`rm file.ts`\n!`git push --force`\n!`chmod -R 777 .`\n```\n\n### Graceful Patterns\n\n```markdown\n<injected_content>\n@.claude/workspace/handoff.yaml\n</injected_content>\n\nIf no handoff exists: Create new session\n\nCurrent branch: !`git branch --show-current 2>/dev/null || echo \"detached\"`\n```\n\n---\n\n## PATTERN: Command Structure\n\n### Single-File Structure\n\nCommands are single markdown files:\n\n```\n.claude/commands/folder-name.md\n```\n\nOr flat structure:\n\n```\n.claude/commands/command-name.md\n```\n\n### Flat Structure\n\n```\n.claude/commands/analyze.md\n.claude/commands/create.md\n.claude/commands/verify.md\n```\n\n### Nested Structure\n\n```\n.claude/commands/analysis/\n├── diagnose.md\n├── explore.md\n└── reason.md\n```\n\n### Command Scope\n\n| Scope | Location | Description |\n| :---- | :------- | :---------- |\n| Project | `.claude/commands/` | Command available in this project only |\n| Personal | `~/.claude/commands/` | Command available in all projects |\n\n### Command Components\n\n| Component             | Required? | Notes                       |\n| :-------------------- | :-------- | :-------------------------- |\n| Frontmatter           | Yes       | YAML with description       |\n| ## Quick Start        | Yes       | Scenario-based              |\n| Content               | Yes       | With @/! injection          |\n| <critical_constraint> | Yes       | At bottom                   |\n\n### What Commands Contain\n\n| Content               | Type     | Notes                  |\n| :-------------------- | :------- | :--------------------- |\n| Frontmatter           | Required | First content          |\n| Quick Start           | Required | Scenario-based         |\n| @ injection           | Optional | Dynamic file content   |\n| ! injection           | Optional | Dynamic command output |\n| <critical_constraint> | Required | At file bottom         |\n\n### What Commands Don''t Contain\n\n| Excluded               | Reason                     |\n| :--------------------- | :------------------------- |\n| references/ folder     | Commands are single-file   |\n| SKILL.md               | Skills use this format     |\n| Progressive disclosure | Commands load full content |\n\n### Frontmatter Fields\n\nCommands use minimal frontmatter - no `name` field (auto-derived from path):\n\n```yaml\n---\ndescription: \"Brief description, non spoiling of the content. Use when {trigger condition + keywords + key sentences user might say that should lead the command to be triggered}. Not for {exclusions}.\"\nargument-hint: \"<identifier>\"  # Optional: hint for positional args\ncontext: fork  # Optional: for orchestration, see ## PATTERN: Thin Interface\n---\n```\n\n### All Frontmatter Fields\n\n| Field | Required? | Purpose |\n| :---- | :-------- | :------- |\n| `description` | Yes | Auto-discovery, shown in slash menu |\n| `argument-hint` | No | Placeholder for `$1` arguments |\n| `context` | No | `fork` for orchestration with result return |\n| `hooks` | No | Event hooks configuration |\n| `disable-model-invocation` | No | `true` for liaison commands (requires AskUserQuestion) |\n\n### Example Frontmatter\n\n```yaml\n---\ndescription: \"Refine skill content for quality and portability. Use when improving existing skills, fixing quality issues, or updating documentation. Includes pattern validation and anti-pattern detection. Not for creating new skills from scratch.\"\nargument-hint: \"<skill-name>\"\nhooks:\n  PreToolUse:\n    - matcher: \"tool == \\\"Bash\\\" && tool_input.command matches \\\"rm\\\"\"\n      type: prompt\n      prompt: \"About to run rm - confirm this is intentional.\"\n---\n```\n\n### Argument Handling\n\n| Syntax | Description | Example |\n| :----- | :---------- | :------ |\n| `$ARGUMENTS` | Everything after command | `/test auth` → `Run tests matching: auth` |\n| `$1`, `$2` | Positional arguments | `/fix 123 high` → Issue #123, priority high |\n\n### String Substitutions\n\n| Variable | Replaces With |\n| :------- | :------------ |\n| `$ARGUMENTS` | All passed args (appended if missing) |\n| `$ARGUMENTS[N]` | Nth arg (0-based) |\n| `$N` | Shorthand for `$ARGUMENTS[N]` |\n| `${CLAUDE_SESSION_ID}` | Current session ID |\n\n### Best Practices\n\n1. **Discovery**: Commands available via slash command menu\n2. **Security**: Limit `allowed-tools` to essentials when needed\n3. **Organization**: Use subdirectories for namespacing complex projects\n\n### Command Frontmatter\n\n```yaml\n---\ndescription: \"Verb + object. Use when [condition]. Includes [features]. Not for [exclusions].\"\n---\n```\n\n### Command Body\n\n```markdown\n## Quick Start\n\n**If you need X:** Do Y\n\n## Core Content\n\n[Content with @ and ! injection patterns]\n\n<injected_content>\n@path/to/file.yaml\n</injected_content>\n```\n\n### Commands vs Skills\n\n| Aspect      | Commands             | Skills                 |\n| :---------- | :------------------- | :--------------------- |\n| Structure   | Single file          | SKILL.md + references/ |\n| Injection   | @, ! supported       | Not supported          |\n| Frontmatter | Required             | Required               |\n| References  | Optional references/ | Extensive references/  |\n\n## PATTERN: Engine Separation\n\nCommands **SHOULD NOT contain complex logic**. They should:\n\n1. **Gather context** (via @/!)\n2. **Ask clarifying questions** (if Liaison)\n3. **Invoke the appropriate Skill**\n\n### Anti-Pattern: Command with Logic\n\n```markdown\n❌ Wrong: A 200-line \"how-to\" guide in a command\n✅ Correct: 5-line context gatherer → invoke Skill\n```\n\n### Command Responsibilities\n\n| Responsibility | Description |\n| :------------- | :---------- |\n| Context Injection | Use @/! to capture current state |\n| Human Negotiation | Use AskUserQuestion to clarify intent |\n| Skill Invocation | Delegate to Engine with compiled context |\n\n### When to Move to Skill\n\nUse a Skill instead of a Command when:\n- You need `references/` for documentation\n- Logic exceeds 50 lines of content\n- Multiple patterns and anti-patterns needed\n- Complex decision trees required\n\n**Rule: If you need references/, you are building a Skill, not a Command.**\n\n---\n\n## PATTERN: Namespacing\n\nCommands use folder hierarchy for namespacing. Path maps to colon syntax:\n\n| Folder Path | Command Invocation |\n|-------------|-------------------|\n| `.claude/commands/meta/refine/rules.md` | `/meta:refine:rules` |\n| `.claude/commands/strategy/architect.md` | `/strategy:architect` |\n| `.claude/commands/meta/audit/all.md` | `/meta:audit:all` |\n\n### Namespacing Rules\n\n| Rule | Example |\n| :--- | :------- |\n| No `name` field in frontmatter | Auto-derived from path |\n| Only `description` is mandatory | Frontmatter is minimal |\n| `argument-hint` optional | `\"<skill-name>\"` |\n| Folders create namespace hierarchy | `meta/refine/` → `/meta:refine:` |\n\n### Flat vs Namespaced\n\n| Type | Use When | Example |\n| :--- | :-------- | :------- |\n| Flat | Core, high-frequency commands | `/continue`, `/handoff` |\n| Namespaced | Related commands, complex domains | `/meta:refine:rules` |\n\n### Namespace Categories\n\n| Namespace | Purpose | Example Commands |\n| :--------- | :------ | :---------------- |\n| `meta/*` | Toolkit self-improvement | refine, audit, reflect, capture |\n| `strategy/*` | Planning and execution | architect, execute |\n| `handoff/*` | Session continuity | resume, diagnostic |\n| `learning/*` | Knowledge capture | archive, refine-rules |\n\n---\n\n## PATTERN: Thin Interface\n\nCommands are \"Skin\" - thin interfaces that bind Reality to Knowledge Skills (\"Brain\").\n\n### Three Command Use-Cases\n\n| Use-Case | Pattern | Example |\n| :-------- | :------- | :------- |\n| Context Gathering | `@` and `!` injection | Gather git state, file content |\n| Liaison Work | `AskUserQuestion` | Clarify ambiguous intent |\n| Delegation | `Skill(tool)` invocation | Call Knowledge Skill for logic |\n\n### Thin Interface Rules\n\n1. Commands MUST provide at least one \"Reality\" source (`@` or `!`)\n2. Commands SHOULD NOT contain complex logic - delegate to Skills\n3. Commands MUST NOT delegate to other commands (only to Skills)\n4. Skill chaining IS allowed when using `context:forked` in frontmatter\n\n### Context Forking (Orchestration)\n\nWhen a command/skill must orchestrate subprocesses and receive their results:\n\n**Without `context:forked`:**\n```markdown\n---\ndescription: \"Call skill B.\"\n---\n1. Invoke `skill-b` skill.\n2. [Skill A ends here - unreliable return]\n```\n\nSkill B runs but results don''t reliably return to Skill A.\n\n**With `context:forked`:**\n```yaml\n---\ndescription: \"Call skill B with result return.\"\ncontext: forked\n---\n```\n\n```markdown\n1. Invoke `skill-b` skill.\n2. [Skill B completes, result returns to Skill A]\n3. Process skill B results...\n```\n\n**How it works:**\n- `context: forked` in frontmatter makes the component behave like a subagent\n- Results reliably return to the parent for analysis\n- Essential for: multi-step workflows, result aggregation, orchestration\n\n### Delegation Pattern\n\n```markdown\n## Execution\n1. Read the provided skill content.\n2. Invoke `skill-development` skill.\n3. Compare content against standards.\n4. Apply refinements autonomously.\n```\n\n### Reality Source Requirement\n\n| Do | Don''t |\n| :-- | :----- |\n| Use `@` for current file state | Assume static content |\n| Use `!` for runtime state | Hardcode git status, etc. |\n| Provide at least one injection | Create pure logic commands |\n\n---\n\n\n\n## PATTERN: Argument Patterns\n\n### Dual-Mode Pattern\n\nCommands can operate in two modes:\n\n| Mode         | Behavior              | Example                                      |\n| :----------- | :-------------------- | :------------------------------------------- |\n| **Implicit** | Infer from context    | `/handoff:resume` → scans handoffs           |\n| **Explicit** | Use provided argument | `/handoff:resume session-x` → loads specific |\n\n### Argument Rules\n\n| Rule                             | Example                    |\n| :------------------------------- | :------------------------- |\n| `$1` for unique identifiers only | `session-x`, `abc123`      |\n| Not for flags/options            | `$1` cannot be `--verbose` |\n| Positional only                  | No `--flag value` syntax   |\n\n### Example\n\n```markdown\n$IF($1, Use the provided argument, Scan conversation for context and infer intent)\n```\n\n### Argument Use Cases\n\n| Use Case     | Example                       |\n| :----------- | :---------------------------- |\n| Session ID   | `/handoff:resume session-x`   |\n| File hash    | `/ops:extract abc123`         |\n| Project slug | `/strategy:create my-project` |\n\n### Valid Arguments\n\n```markdown\n✅ Valid (identifiers only):\nsession-abc123  # session ID\nhash-xyz789     # file hash\nmy-project      # project slug\n```\n\n### Invalid Arguments\n\n```markdown\n❌ Invalid (flags not allowed):\n--verbose               # flag\noutput-format json      # flag with value\n--max-results 10        # flag with value\n```\n\n---\n\n## PATTERN: Error Handling\n\n### @ Error Behavior\n\n| Scenario     | Result           |\n| :----------- | :--------------- |\n| File exists  | Content injected |\n| File missing | Empty string     |\n\n### ! Error Behavior\n\n| Scenario         | Result          |\n| :--------------- | :-------------- |\n| Command succeeds | stdout injected |\n| Command fails    | Empty string    |\n\n---\n\n## ANTI-PATTERN: Common Mistakes\n\n### Anti-Pattern: Using @ in Skills\n\n```markdown\n❌ Wrong (skill):\n@injected_content>\n@.claude/workspace/file.yaml\n</injected_content>\n\n✅ Correct (skill):\nRead `references/configuration.md` to understand the schema.\n```\n\n**Fix:** Skills use semantic instructions, not @ injection.\n\n### Anti-Pattern: @ for Static Content\n\n```markdown\n❌ Wrong:\n@.claude/commands/static-template.md\n\n✅ Correct:\n[inline the template directly]\n```\n\n**Fix:** Use @ for dynamic content (changes between invocations), not static templates.\n\n### Anti-Pattern: No Error Handling\n\n```markdown\n❌ Wrong:\nCurrent branch: !`git branch --show-current`\n[no fallback]\n\n✅ Correct:\nCurrent branch: !`git branch --show-current` (or detached HEAD)\n```\n\n**Fix:** Consider edge cases and provide context.\n\n### Anti-Pattern: $1 for Options\n\n```markdown\n❌ Wrong:\n--verbose               # using flags\noutput-format           # option names\n\n✅ Correct:\nsession-abc123          # identifier only\n```\n\n**Fix:** `$1` is for IDs, slugs, hashes only—not flags or options.\n\n### Anti-Pattern: Command with References/\n\n```\n❌ Wrong:\n.claude/commands/example/\n├── command.md\n└── references/\n    └── detail.md\n\n✅ Correct:\n.claude/commands/example.md  # Single file\n\nOr if needed:\n.claude/skills/example/\n├── SKILL.md\n└── references/\n```\n\n### Anti-Pattern: Wrong Extension\n\n```\n❌ Wrong:\n.claude/commands/command.txt\n.claude/commands/command\n\n✅ Correct:\n.claude/commands/command.md\n```\n\n### Anti-Pattern: Inconsistent Naming\n\n```\n❌ Wrong:\n.claude/commands/create-prompt.md\n.claude/commands/run_prompt.md\n.claude/commands/runprompt.md\n\n✅ Correct:\n.claude/commands/create-prompt.md\n.claude/commands/run-prompt.md\n.claude/commands/run-prompt.md  # Consistent kebab-case\n```\n\n### Anti-Pattern: Complex Logic in !\n\n```\n❌ Wrong:\n!`for f in *.ts; do echo $f; done`\n\n✅ Correct:\nUse bash with proper escaping or inline differently\n```\n\n---\n\n## EDGE: Special Cases\n\n### Edge Case: No @ or !\n\nCommands that don''t need dynamic content:\n\n```\n✅ Valid:\n.claude/commands/simple.md\n[no @ or ! injection]\n\nContent is static, no dynamic state needed.\n```\n\n### Edge Case: Multiple Injections\n\nCommands with complex injection:\n\n```markdown\n<injected_content>\n@.claude/workspace/handoff.yaml\n</injected_content>\n\nCurrent branch: !`git branch --show-current`\nModified files: !`git status --porcelain`\n```\n\n### Edge Case: Nested Wrappers\n\n```markdown\n<injected_content>\n@main-file.yaml\n\n<details>\n\n<injected_content>\n@supporting.yaml\n</injected_content>\n\n</details>\n</injected_content>\n```\n\n### Edge Case: Conditional Injection\n\n```markdown\n$IF($1, Use explicit: $1, Infer from context)\n```\n\n### Edge Case: Command Grouping\n\nRelated commands in folder:\n\n```\n.claude/commands/handoff/\n├── create.md\n├── diagnostic.md\n├── resume.md\n└── create-full.md\n```\n\n### Edge Case: Single Command\n\nNo folder needed for single command:\n\n```\n.claude/commands/simple.md\n```\n\n### Edge Case: Many Commands\n\nUse folders for organization:\n\n```\n.claude/commands/\n├── analysis/\n├── build/\n├── handoff/\n├── learning/\n├── ops/\n├── planning/\n├── qa/\n├── strategy/\n└── sync/\n```\n\n### Edge Case: Optional Injection\n\nCommands with optional @/!:\n\n```\n✅ Valid:\n!`git branch --show-current` (or detached)\n\n<injected_content>\n@optional-file.yaml\n</injected_content>\n(if exists)\n```\n\n### Edge Case: Multiple Commands\n\nCommands with multiple ! patterns:\n\n```markdown\nBranch: !`git branch --show-current`\nStatus: !`git status --short`\nLast commit: !`git log -1 --oneline`\n```\n\n### Edge Case: Conditional Arguments\n\n```markdown\n$IF($1, Use: $1, Infer from context)\n```\n\n---\n\n## Validation Checklist\n\nBefore claiming command authoring complete:\n\n**Structure:**\n- [ ] Single markdown file in `.claude/commands/`\n- [ ] File has `.md` extension\n- [ ] Valid YAML frontmatter with description\n\n**Injection Patterns:**\n- [ ] @path for dynamic file content (not in skills)\n- [ ] !command for runtime state capture\n- [ ] Wrapped in `<injected_content>` for semantic grouping\n- [ ] Paths are absolute or relative to workspace root\n\n**Error Handling:**\n- [ ] Missing files handled gracefully (empty result)\n- [ ] Command failures handled gracefully\n\n**Argument Handling:**\n- [ ] $1 used only for identifiers (IDs, slugs, hashes)\n- [ ] No flags or modes as $1 arguments\n\n**Content:**\n- [ ] Follows What-When-Not-Includes format in description\n- [ ] Imperative/infinitive voice throughout\n- [ ] No references/ folder (commands are single-file)\n\n---\n\n## Common Mistakes to Avoid\n\n### Mistake 1: Using @ or ! in Skills\n\n❌ **Wrong:**\n```markdown\n# My Skill\nCurrent branch: !`git branch --show-current`\n```\n\n✅ **Correct:**\nSkills use semantic instructions:\n```markdown\n# My Skill\nDetermine the current Git branch using standard git commands.\n```\n\n### Mistake 2: Using $1 for Flags\n\n❌ **Wrong:**\n```yaml\n$1: --verbose\n```\n\n✅ **Correct:**\n```yaml\n$1: session-id  # Only for identifiers\n```\n\n### Mistake 3: Missing Frontmatter\n\n❌ **Wrong:**\n```markdown\n# My Command\ndescription: Does something useful\n```\n\n✅ **Correct:**\n```yaml\n---\nname: my-command\ndescription: \"Verb + object. Use when [condition]. Includes [features]. Not for [exclusions].\"\n---\n```\n\n### Mistake 4: Complex Bash in !\n\n❌ **Wrong:**\n```markdown\n!`for f in $(ls *.json); do cat $f | jq ''.name''; done`\n```\n\n✅ **Correct:**\n```markdown\n!`find . -name \"*.json\" -exec jq -r ''.name'' {} \\;`\n```\n\n### Mistake 5: Missing Error Handling\n\n❌ **Wrong:**\n```markdown\n@/path/to/mandatory/file.yaml\n```\n(If file doesn''t exist, command fails)\n\n✅ **Correct:**\n```markdown\n@/path/to/file.yaml\n```\n(gracefully handles missing files)\n```\n\n---\n\n## Best Practices Summary\n\n✅ **DO:**\n- Use @path for dynamic file content that changes between sessions\n- Use !command for runtime state (git status, CI results)\n- Wrap injections in `<injected_content>` for semantic grouping\n- Handle missing files gracefully\n- Use $1 only for unique identifiers (IDs, slugs)\n- Follow single-file structure (no references/ folder)\n- Provide at least one \"Reality\" source (@ or !)\n- Delegate complex logic to Skills\n\n❌ **DON''T:**\n- Use @ or ! in skills (skills use semantic instructions)\n- Use $1 for flags, modes, or non-identifier values\n- Create multi-file commands (use skills instead)\n- Skip .md extension\n- Skip frontmatter description\n- Use complex bash in ! without proper escaping\n- Delegate from command to another command (delegate to Skills only)\n\n---\n\n## Recognition Questions\n\n| Question                                | Recognition |\n| :-------------------------------------- | :---------- |\n| Does @ inject dynamic file content?     | Yes, content changes between sessions |\n| Does ! execute for runtime state?       | Yes, captures git status, CI, etc.    |\n| Does command use single-file structure? | Yes, no references/ folder            |\n| Does $1 use identifier-only pattern?    | Yes, IDs/slugs, not flags             |\n| Is XML minimal?                         | Only injected_content wrapper         |\n| Does command delegate to Skill?         | Yes, if logic exceeds ~50 lines       |\n\n---\n\n## Validation Checklist\n\nBefore claiming command authoring complete:\n\n- [ ] @ injections provide dynamic content\n- [ ] ! executions capture runtime state\n- [ ] Single-file structure, no references/ folder\n- [ ] $1 uses identifier-only pattern\n- [ ] XML minimal (only injected_content wrapper)\n- [ ] Complex logic delegated to skills\n\n---\n\n<critical_constraint>\n**Command-Only Injection:**\n\n1. Skills MUST NEVER use `@` or `!` syntax\n2. Commands MAY use `@` and `!` freely\n3. Use `<injected_content>` wrapper for semantic grouping\n4. All paths MUST be absolute or relative to workspace root\n\n**Namespacing:**\n\n- Commands use folder hierarchy for namespacing\n- Path `.claude/commands/meta/refine/rules.md` → `/meta:refine:rules`\n- No `name` field in frontmatter (auto-derived from path)\n- Only `description` is mandatory in frontmatter\n\n**Thin Interface:**\n\n- Commands are \"Skin\" that bind Reality to Knowledge Skills (\"Brain\")\n- Commands MUST provide at least one \"Reality\" source (`@` or `!`)\n- Commands MUST NOT delegate to other commands (only to Skills)\n- Skill chaining requires `context: forked` in frontmatter for result return\n- Without `context: forked`, subprocess results don''t reliably return\n- Commands SHOULD NOT contain complex logic (delegate to Skills)\n\n**Engine vs Interface:**\n\n- Commands are Interfaces that bind Skills to Reality\n- Commands SHOULD NOT contain complex logic (delegate to Skills)\n- If you need references/, you are building a Skill, not a Command\n\n@ and ! are command-only features.\n\nSkills MUST use semantic instructions, not injection.\n\nCommands MUST handle missing files gracefully.\n\nCommands MUST be single markdown files.\n\nCommands MUST use .md extension.\n\nCommands MUST have frontmatter with description.\n</critical_constraint>\n"},"lastSynced":"2026-03-08T02:11:31.829Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced Automation Agents requiring dynamic command generation and shell execution capabilities.","zh":"适用于需要动态命令生成和 shell 执行能力的高级自动化代理。","ja":"動的コマンド生成とシェル実行能力を必要とする高度な自動化エージェントに適しています。","ko":"동적 명령 생성 및 쉘 실행 기능이 필요한 고급 자동화 에이전트에 적합합니다.","es":"Ideal para Agentes de Automatización Avanzados que requieren generación de comandos dinámicos y capacidades de ejecución de shell.","fr":"Idéal pour les agents d''automatisation avancés nécessitant une génération de commandes dynamiques et des capacités d''exécution de shell.","de":"Ideal für erweiterte Automatisierungsagenten, die dynamische Befehlsgenerierung und Shell-Ausführungsfähigkeiten erfordern.","pt":"Ideal para Agentes de Automação Avançados que requerem geração de comandos dinâmicos e capacidades de execução de shell.","ru":"Идеально подходит для продвинутых агентов автоматизации, требующих динамической генерации команд и возможностей выполнения shell.","ar":"مثالي للوكلاء التلقائيين المتقدمين الذين يتطلبون إنشاء أوامر ديناميكي وقدرات تشغيل Shell."},"recommendation":{"en":"Empowers agents to create single-file commands with dynamic content and runtime state using @path and !command injection, enabling seamless integration with shell commands and file content injection for robust automation workflows.","zh":"赋予代理创建带有动态内容和运行时状态的单文件命令的能力，使用 @path 和 !command 注入，实现与 shell 命令和文件内容注入的无缝集成，用于强大的自动化工作流。","ja":"エージェントが動的コンテンツと実行時状態を含む単一ファイルのコマンドを作成する機能を提供し、@path と !command 注入を使用してシェルコマンドやファイルコンテンツの注入とのシームレスな統合を可能にし、強力な自動化ワークフローを実現します。","ko":"에이전트가 동적 콘텐츠 및 런타임 상태를 포함하는 단일 파일 명령을 생성할 수 있는 기능을 제공하여 @path 및 !command 주입을 사용하여 쉘 명령어와 파일 콘텐츠 주입과 무결한 통합을 가능하게 하여 강력한 자동화 워크플로우를 구현합니다.","es":"Habilita a los agentes a crear comandos de un solo archivo con contenido dinámico y estado de tiempo de ejecución utilizando @path y !command injection, lo que permite una integración perfecta con comandos de shell y la inyección de contenido de archivos para flujos de trabajo de automatización robustos.","fr":"Permet aux agents de créer des commandes de fichier unique avec un contenu dynamique et un état d''exécution à l''aide de @path et !command injection, permettant ainsi une intégration transparente avec les commandes shell et l''injection de contenu de fichier pour des flux de travail d''automatisation robustes.","de":"Ermächtigt Agenten, Single-File-Befehle mit dynamischem Inhalt und Laufzeitstatus unter Verwendung von @path und !command injection zu erstellen, ermöglicht eine nahtlose Integration mit Shell-Befehlen und die Injektion von Dateiinhalten für robuste Automatisierungsworkflows.","pt":"Habilita os agentes a criar comandos de arquivo único com conteúdo dinâmico e estado de tempo de execução usando @path e injeção de comando !, permitindo uma integração perfeita com comandos de shell e injeção de conteúdo de arquivo para fluxos de trabalho de automação robustos.","ru":"Наделяет агентов возможностью создавать одnofайловые команды с динамическим содержимым и состоянием выполнения, используя @path и внедрение команды !, обеспечивая бесшовную интеграцию с командами shell и внедрением содержимого файла для прочных рабочих процессов автоматизации.","ar":"تمكّن الوكلاء من إنشاء أوامر ملف واحدة ذات محتوى ديناميكي وحالة زمنية باستخدام @path و الحقن ! لتحقيق تكامل مثالي مع أوامر Shell و حقن محتوى الملف من أجل سير عمل تلقائي قوي."},"useCases":{"en":["Generating dynamic shell commands for automated workflows","Injecting file content into commands for customized execution","Debugging command execution with graceful error handling"],"zh":["为自动化工作流生成动态 shell 命令","将文件内容注入命令以实现自定义执行","使用优雅的错误处理进行命令执行调试"],"ja":["自動化ワークフロー用の動的シェルコマンドの生成","ファイルコンテンツをコマンドに注入してカスタマイズされた実行を実現","優雅なエラーハンドリングを使用したコマンド実行のデバッグ"],"ko":["자동화 워크플로우를 위한 동적 쉘 명령 생성","파일 콘텐츠를 명령어에 주입하여 사용자 정의 실행을 구현","우아한 오류 처리를 사용한 명령어 실행 디버깅"],"es":["Generación de comandos de shell dinámicos para flujos de trabajo automatizados","Inyección de contenido de archivos en comandos para una ejecución personalizada","Depuración de la ejecución de comandos con control de errores elegante"],"fr":["Génération de commandes shell dynamiques pour les flux de travail automatisés","Injection de contenu de fichiers dans les commandes pour une exécution personnalisée","Débogage de l''exécution de commandes avec une gestion d''erreurs élégante"],"de":["Generierung dynamischer Shell-Befehle für automatisierte Workflows","Injektion von Dateiinhalten in Befehle für eine benutzerdefinierte Ausführung","Fehlerbehandlung bei der Befehlsausführung mit eleganter Fehlerbehandlung"],"pt":["Geração de comandos de shell dinâmicos para fluxos de trabalho automatizados","Injeção de conteúdo de arquivo em comandos para execução personalizada","Depuração da execução de comandos com tratamento de erros elegante"],"ru":["Генерация динамических команд shell для автоматизированных рабочих процессов","Внедрение содержимого файла в команды для индивидуального выполнения","Отладка выполнения команд с элегантным обработкой ошибок"],"ar":["إنشاء أوامر Shell ديناميكي لتدفقات العمل التلقائية","حقن محتوى الملف في الأوامر για التنفيذ المخصص","تصحيح أخطاء تشغيل الأوامر مع معالجة الأخطاء أنيق"]},"limitations":{"en":["Requires proper @/! injection pattern implementation","Dependent on shell command availability and compatibility","Error handling implementation is crucial for robust command execution"],"zh":["需要正确的 @/! 注入模式实现","依赖于 shell 命令的可用性和兼容性","错误处理的实现对于强大的命令执行至关重要"],"ja":["@/! 注入パターンの正しい実装が必要","シェルコマンドの可用性と互換性に依存","エラーハンドリングの実装は強力なコマンド実行に不可欠"],"ko":["@/! 주입 패턴의 올바른 구현이 필요","쉘 명령어의 가용성 및 호환성에 의존","오류 처리 구현은 강력한 명령어 실행에 필수"],"es":["Requiere una implementación adecuada del patrón de inyección @/!","Depende de la disponibilidad y compatibilidad de los comandos de shell","La implementación de la gestión de errores es crucial para una ejecución de comandos robusta"],"fr":["Nécessite une mise en œuvre appropriée du modèle d''injection @/!","Dépend de la disponibilité et de la compatibilité des commandes shell","La mise en œuvre de la gestion des erreurs est cruciale pour une exécution de commandes robuste"],"de":["Erfordert eine ordnungsgemäße Implementierung des @/!-Injektionsmusters","Hängt von der Verfügbarkeit und Kompatibilität von Shell-Befehlen ab","Die Implementierung der Fehlerbehandlung ist für eine robuste Befehlsausführung von entscheidender Bedeutung"],"pt":["Requer implementação adequada do padrão de injeção @/!","Depende da disponibilidade e compatibilidade dos comandos de shell","A implementação do tratamento de erros é crucial para a execução de comandos robusta"],"ru":["Требует правильной реализации шаблона внедрения @/!","Зависит от наличия и совместимости команд shell","Реализация обработки ошибок имеет важное значение для прочного выполнения команд"],"ar":["يتطلب تنفيذاً صحيحاً لنمط الحقن @/!","يعتمد على توافر أوامر Shell ومتانتها","معالجة الأخطاء لها أهمية حاسمة لتنفيذ أوامر قوي"]},"version":4},"contentHash":"f921ddf243595c687f2577d25b1c123c6c1e75d094201f3820f0ca437e47e531","qualityScore":45}');
