INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Git-Fg/meta-plugin-manager/command-authoring', 'command-authoring', 'Git-Fg', 'meta-plugin-manager', 'community', 'command-authoring Git-Fg meta-plugin-manager community Command-authoring enables developers to create single-file commands with dynamic content and runtime state using @path and !command injection. This skill benefits developers working with dynamic file content and shell commands. 命令创建技能允许开发者使用@path和!command注入创建单文件命令，实现动态内容和运行时状态 コマンド作成スキルは、開発者が@pathと!commandの注入を使用して単一ファイルコマンドを作成できるようにし、動的なコンテンツと実行時状態を実現する 명령어 작성 스킬을 사용하면 개발자가 @path와 !command 삽입을 사용하여 단일 파일 명령어를 생성하여 동적 콘텐츠와 런타임 상태를 구현할 수 있습니다 El command-authoring permite crear comandos de un solo archivo con inyección de contenido dinámico y estado de ejecución Le command-authoring permet de créer des commandes de fichiers uniques avec injection de contenu dynamique et état d''exécution Das command-authoring ermöglicht die Erstellung einzelner Dateikommandos mit dynamischem Inhalt und Laufzeitstatus Crie comandos personalizados com injeção de conteúdo dinâmico e estado de tempo de execução Создайте пользовательские команды с динамическим контентом и состоянием выполнения انشئ أوامر مخصصة مع محتوى ديناميكي وحالة وقت التشغيل how to use command-authoring command-authoring setup guide command-authoring vs alternative tools command-authoring install what is command-authoring command-authoring tutorial command-authoring dynamic content command-authoring runtime state command-authoring error handling 命令创建 AIエージェント 动态命令 运行时状态 错误处理 单文件命令 命令注入 shell命令 Supports @path pattern for injecting file content at invocation time Enables execution of shell commands using !`command` syntax for dynamic state Provides graceful error handling for robust command execution Allows for creation of single-file commands with valid frontmatter Supports proper @/! injection patterns for dynamic content Command-authoring is a technique for creating single-file commands with dynamic content and runtime state using @path and !command injection patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nrwl/nx/ci-monitor', 'community', 'nrwl', 'nx', 'nrwl/nx', 'ci-monitor', 0, 0, 45, '2026-03-08T01:57:15.562Z', '2026-03-08T02:11:35.978Z', 'a124ec3b3bd0e12152c9729b1239df7f69da2321c3a4d8be2014943056d3f6b6', '{"id":"nrwl/nx/ci-monitor","name":"ci-monitor","description":{"en":"The ci-monitor skill amplifies developer and AI agent productivity by optimizing builds, scaling CI, and automatically fixing failed PRs. It benefits developers and AI agents by streamlining the development process.","zh":"CI Monitor 是一个用于监控 Nx Cloud CI 流水线执行和处理自愈修复的工具。它可以自动化 CI 流水线的执行和修复，提高开发效率","ja":"CI モニターは、Nx Cloud CI パイプラインの実行と自己修復を処理するツールです。CI パイプラインの実行と修復を自動化することで、開発の効率を向上させることができます","ko":"CI 모니터는 Nx Cloud CI 파이프라인 실행과 자가 수리를 처리하는 도구입니다. CI 파이프ライン의 실행과 修复를 자동화하여 개발 효율성을 향상시킵니다","es":"ci-monitor es una herramienta de monitoreo de CI que optimiza los flujos de trabajo de integración continua y automatiza la corrección de errores en las solicitudes de extracción","fr":"ci-monitor est un outil de surveillance de CI qui optimise les flux de travail d''intégration continue et automatise la correction des erreurs dans les demandes d''extraction","de":"ci-monitor ist ein CI-Überwachungstool, das die Arbeitsabläufe der kontinuierlichen Integration optimiert und die Korrektur von Fehlern in den Pull-Requests automatisiert","pt":"O ci-monitor é uma ferramenta que otimiza builds e escalona CI com a plataforma Nx, permitindo que os desenvolvedores entreguem resultados mais rápido","ru":"ci-monitor - это инструмент, который оптимизирует сборки и масштабирует CI с помощью платформы Nx, позволяя разработчикам доставлять результаты быстрее с помощью ИИ Агентов","ar":"ci-monitor هو أداة تحسين البناء وتوسيع نطاق CI مع منصة Nx، مما يسمح للمطورين بتسليم النتائج بشكل أسرع مع وكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"ci-monitor: Automated CI Pipeline Monitoring for AI Agent...","zh":"CI Monitor Setup Guide - Nx Cloud CI Pipeline 优化","ja":"CI モニター ベストプラクティス - Nx Cloud CI パイプライン最適化","ko":"CI 모니터 설정 가이드 - Nx Cloud CI 파이프라인 최적화","es":"Guía de Configuración de ci-monitor: Optimización de CI","fr":"Guide de Configuration de ci-monitor : Optimisation de l''...","de":"Einrichtungsleitfaden für ci-monitor: CI-Optimierung","pt":"Guia de Configuração do ci-monitor: Otimizando Builds e CI","ru":"Настройка ci-monitor: Ускорение сборок и CI с ИИ Агентами","ar":"دليل إعداد ci-monitor: تحسين البناء وال_ci مع وكلاء الذكا..."},"description":{"en":"Discover how ci-monitor simplifies CI pipeline executions and automates self-healing fixes. Learn more and optimize your workflow today!","zh":"使用 CI Monitor 自动化 Nx Cloud CI 流水线执行和自愈修复，提高开发效率","ja":"CI モニターを使用して Nx Cloud CI パイプラインの実行と自己修復を自動化し、開発の効率を向上させる","ko":"CI 모니터를 사용하여 Nx Cloud CI 파이프라인 실행과 자가 수리를 자동화하여 개발 효율성을 향상시키다","es":"Aprende a configurar ci-monitor para mejorar la eficiencia de tus flujos de trabajo de CI y maximizar la productividad de tu equipo de desarrollo","fr":"Découvrez comment configurer ci-monitor pour améliorer l''efficacité de vos flux de travail de CI et maximiser la productivité de votre équipe de développement","de":"Erfahren Sie, wie Sie ci-monitor konfigurieren, um die Effizienz Ihrer CI-Arbeitsabläufe zu verbessern und die Produktivität Ihres Entwicklungsteams zu maxim...","pt":"Aprenda a configurar o ci-monitor para otimizar builds, escalonar CI e reparar PRs falhados automaticamente com a plataforma Nx","ru":"Узнайте, как настроить ci-monitor для оптимизации сборок, масштабирования CI и автоматического исправления неудачных PR с помощью платформы Nx и ИИ Агентов","ar":"تعرف على كيفية إعداد ci-monitor لتحسين البناء وتوسيع نطاق CI وتصحيح PRs الفاشلة تلقائيًا مع منصة Nx ووكلاء الذكاء الاصطناعي"},"definition":{"en":"ci-monitor is a Monorepo Platform that orchestrates CI pipeline executions, handles self-healing fixes, and utilizes the ci-watcher subagent to poll CI status.","zh":"CI Monitor 是一个用于监控和自动化 Nx Cloud CI 流水线执行的 AI 工具","ja":"CI モニターは、Nx Cloud CI パイプラインの実行を監視し、自動化する AI エージェントです","ko":"CI 모니터는 Nx Cloud CI 파이프ライン 실행을 모니터링하고 자동화하는 AI 에이전트입니다","es":"ci-monitor es un agente de AI que monitorea y optimiza los flujos de trabajo de CI","fr":"ci-monitor est un agent IA qui surveille et optimise les flux de travail de CI","de":"ci-monitor ist ein KI-Agent, der die CI-Arbeitsabläufe überwacht und optimiert","pt":"O que é ci-monitor? É uma ferramenta de monitoramento de pipeline de CI que executa ações de autocorreção","ru":"Что такое ci-monitor? Это инструмент мониторинга CI-пайплайна, который выполняет действия по самоисправлению с помощью ИИ Агентов","ar":"ما هو ci-monitor؟ إنه أداة مراقبة трубة CI التي تقوم بactions الself-healing"},"features":{"en":["Utilizes the `ci-watcher` subagent to poll CI status","Executes `git branch --show-current` to determine the current branch","Runs `git rev-parse --short HEAD` to retrieve the current commit","Analyzes `git status -sb` output to assess remote status","Automatically fixes failed PRs using self-healing capabilities"],"zh":["自动化 Nx Cloud CI 流水线执行","处理自愈修复","使用 Git 命令行工具获取当前分支和提交信息","支持 CI 流水线状态监控","集成 ci-watcher 子代理进行 CI 状态轮询"],"ja":["Nx Cloud CI パイプラインの実行を自動化","自己修復を処理","Git コマンドラインツールを使用して現在のブランチとコミット情報を取得","CI パイプラインのステータス監視をサポート","ci-watcher サブエージェントを使用して CI ステータスをポーリング"],"ko":["Nx Cloud CI 파이프ライン 실행을 자동화","자가 수리를 처리","Git 명령줄 도구를 사용하여 현재 브랜치와 커밋 정보를 가져옴","CI 파이프라인 상태 모니터링을 지원","ci-watcher 서브 에이전트를 사용하여 CI 상태를 폴링"],"es":["Monitoreo de pipelines de CI","Corrección automática de errores en solicitudes de extracción","Integración con Nx Cloud","Optimización de flujos de trabajo de integración continua","Soporte para comandos de Git"],"fr":["Surveillance des pipelines de CI","Correction automatique des erreurs dans les demandes d''extraction","Intégration avec Nx Cloud","Optimisation des flux de travail d''intégration continue","Prise en charge des commandes Git"],"de":["Überwachung von CI-Pipelines","Automatische Korrektur von Fehlern in Pull-Requests","Integration mit Nx Cloud","Optimierung von CI-Arbeitsabläufen","Unterstützung von Git-Befehlen"],"pt":["Otimização de builds com a plataforma Nx","Escalonação de CI para melhorar a eficiência","Reparo automático de PRs falhados","Monitoramento de pipeline de CI com o subagente ci-watcher","Suporte à execução de comandos personalizados"],"ru":["Оптимизация сборок с помощью платформы Nx","Масштабирование CI для улучшения эффективности","Автоматическое исправление неудачных PR","Мониторинг CI-пайплайна с помощью субагента ci-watcher","Поддержка выполнения пользовательских команд"],"ar":["تحسين البناء مع منصة Nx","توسيع نطاق CI لتحسين الكفاءة","تصحيح PRs الفاشلة تلقائيًا","مراقبة трубة CI مع وكيل ci-watcher","دعم تنفيذ أوامر مخصصة"]},"keywords":{"en":["how to use ci-monitor","ci-monitor setup guide","what is ci-monitor","ci-monitor alternative","ci-monitor vs Jenkins","ci-monitor install","automated CI pipeline monitoring","ci-monitor for AI agents","Nx Cloud CI pipeline optimization"],"zh":["CI Monitor","Nx Cloud CI","自动化流水线","AI 工具","Git 命令行工具","CI 流水线状态监控","ci-watcher 子代理"],"ja":["CI モニター","Nx Cloud CI","自動化パイプライン","AI エージェント","Git コマンドラインツール","CI パイプラインのステータス監視","ci-watcher サブエージェント"],"ko":["CI 모니터","Nx Cloud CI","자동화 파이프라인","AI 에이전트","Git 명령줄 도구","CI 파이프라인 상태 모니터링","ci-watcher 서브 에이전트"],"es":["ci-monitor","herramientas de AI","optimización de CI","integración continua","automatización de errores","Nx Cloud","Git","desarrollo de software","productividad del equipo"],"fr":["ci-monitor","outils IA","optimisation de CI","intégration continue","automatisation des erreurs","Nx Cloud","Git","développement de logiciels","productivité de l''équipe"],"de":["ci-monitor","KI-Tools","CI-Optimierung","kontinuierliche Integration","Automatisierung von Fehlern","Nx Cloud","Git","Software-Entwicklung","Team-Produktivität"],"pt":["ci-monitor","otimização de builds","escalonação de CI","reparo automático de PRs","monitoramento de pipeline de CI","Nx","desenvolvimento de software","ferramentas de CI"],"ru":["ci-monitor","оптимизация сборок","масштабирование CI","автоматическое исправление неудачных PR","мониторинг CI-пайплайна","Nx","разработка программного обеспечения","инструменты CI","ИИ Агенты"],"ar":["ci-monitor","تحسين البناء","توسيع نطاق CI","تصحيح PRs الفاشلة","مراقبة трубة CI","Nx","تطوير البرمجيات","أدوات CI","وكلاء الذكاء الاصطناعي"]}},"owner":"nrwl","repo":"nx","repoPath":"nrwl/nx","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.562Z","topics":[],"category":"community","skillMd":{"name":"ci-monitor","description":"Monitor Nx Cloud CI pipeline and handle self-healing fixes automatically. Checks for Nx Cloud connection before starting.","bodyPreview":"# CI Monitor Command\n\nYou are the orchestrator for monitoring Nx Cloud CI pipeline executions and handling self-healing fixes. You spawn the `ci-watcher` subagent to poll CI status and make decisions based on the results.\n\n## Context\n\n- **Current Branch:** !`git branch --show-current`\n- **Current Commit:** !`git rev-parse --short HEAD`\n- **Remote Status:** !`git status -sb | head -1`\n\n## User Instructions\n\n$ARGUMENTS\n\n**Important:** If user provides specific instructions, respect them over defau","body":"# CI Monitor Command\n\nYou are the orchestrator for monitoring Nx Cloud CI pipeline executions and handling self-healing fixes. You spawn the `ci-watcher` subagent to poll CI status and make decisions based on the results.\n\n## Context\n\n- **Current Branch:** !`git branch --show-current`\n- **Current Commit:** !`git rev-parse --short HEAD`\n- **Remote Status:** !`git status -sb | head -1`\n\n## User Instructions\n\n$ARGUMENTS\n\n**Important:** If user provides specific instructions, respect them over default behaviors described below.\n\n## Configuration Defaults\n\n| Setting                   | Default       | Description                                                         |\n| ------------------------- | ------------- | ------------------------------------------------------------------- |\n| `--max-cycles`            | 10            | Maximum CIPE cycles before timeout                                  |\n| `--timeout`               | 120           | Maximum duration in minutes                                         |\n| `--verbosity`             | medium        | Output level: minimal, medium, verbose                              |\n| `--branch`                | (auto-detect) | Branch to monitor                                                   |\n| `--subagent-timeout`      | 60            | Subagent polling timeout in minutes                                 |\n| `--fresh`                 | false         | Ignore previous context, start fresh                                |\n| `--auto-fix-workflow`     | false         | Attempt common fixes for pre-CIPE failures (e.g., lockfile updates) |\n| `--new-cipe-timeout`      | 10            | Minutes to wait for new CIPE after action                           |\n| `--local-verify-attempts` | 3             | Max local verification + enhance cycles before pushing to CI        |\n\nParse any overrides from `$ARGUMENTS` and merge with defaults.\n\n## Nx Cloud Connection Check\n\n**CRITICAL**: Before starting the monitoring loop, verify the workspace is connected to Nx Cloud.\n\n### Step 0: Verify Nx Cloud Connection\n\n1. **Check `nx.json`** at workspace root for `nxCloudId` or `nxCloudAccessToken`\n2. **If `nx.json` missing OR neither property exists** → exit with:\n   ```\n   [ci-monitor] Nx Cloud not connected. Unlock 70% faster CI and auto-fix broken PRs with https://nx.dev/nx-cloud\n   ```\n3. **If connected** → continue to main loop\n\n## Session Context Behavior\n\n**Important:** Within a Claude Code session, conversation context persists. If you Ctrl+C to interrupt the monitor and re-run `/ci-monitor`, Claude remembers the previous state and may continue from where it left off.\n\n- **To continue monitoring:** Just re-run `/ci-monitor` (context is preserved)\n- **To start fresh:** Use `/ci-monitor --fresh` to ignore previous context\n- **For a completely clean slate:** Exit Claude Code and restart `claude`\n\n## Default Behaviors by Status\n\nThe subagent returns with one of the following statuses. This table defines the **default behavior** for each status. User instructions can override any of these.\n\n| Status              | Default Behavior                                                                                                                                                  |\n| ------------------- | ----------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| `ci_success`        | Exit with success. Log \"CI passed successfully!\"                                                                                                                  |\n| `fix_auto_applying` | Fix will be auto-applied by self-healing. Do NOT call MCP. Record `last_cipe_url`, spawn new subagent in wait mode to poll for new CIPE.                          |\n| `fix_available`     | Compare `failedTaskIds` vs `verifiedTaskIds` to determine verification state. See **Fix Available Decision Logic** section below.                                 |\n| `fix_failed`        | Self-healing failed to generate fix. Attempt local fix based on `taskOutputSummary`. If successful → commit, push, loop. If not → exit with failure.              |\n| `environment_issue` | Call MCP to request rerun: `update_self_healing_fix({ shortLink, action: \"RERUN_ENVIRONMENT_STATE\" })`. New CIPE spawns automatically. Loop to poll for new CIPE. |\n| `no_fix`            | CI failed, no fix available (self-healing disabled or not executable). Attempt local fix if possible. Otherwise exit with failure.                                |\n| `no_new_cipe`       | Expected CIPE never spawned (CI workflow likely failed before Nx tasks). Report to user, attempt common fixes if configured, or exit with guidance.               |\n| `polling_timeout`   | Subagent polling timeout reached. Exit with timeout.                                                                                                              |\n| `cipe_canceled`     | CIPE was canceled. Exit with canceled status.                                                                                                                     |\n| `cipe_timed_out`    | CIPE timed out. Exit with timeout status.                                                                                                                         |\n| `error`             | Increment `no_progress_count`. If >= 3 → exit with circuit breaker. Otherwise wait 60s and loop.                                                                  |\n\n### Fix Available Decision Logic\n\nWhen subagent returns `fix_available`, main agent compares `failedTaskIds` vs `verifiedTaskIds`:\n\n#### Step 1: Categorize Tasks\n\n1. **Verified tasks** = tasks in both `failedTaskIds` AND `verifiedTaskIds`\n2. **Unverified tasks** = tasks in `failedTaskIds` but NOT in `verifiedTaskIds`\n3. **E2E tasks** = unverified tasks where target contains \"e2e\" (task format: `<project>:<target>` or `<project>:<target>:<config>`)\n4. **Verifiable tasks** = unverified tasks that are NOT e2e\n\n#### Step 2: Determine Path\n\n| Condition                               | Path                                     |\n| --------------------------------------- | ---------------------------------------- |\n| No unverified tasks (all verified)      | Apply via MCP                            |\n| Unverified tasks exist, but ALL are e2e | Apply via MCP (treat as verified enough) |\n| Verifiable tasks exist                  | Local verification flow                  |\n\n#### Step 3a: Apply via MCP (fully/e2e-only verified)\n\n- Call `update_self_healing_fix({ shortLink, action: \"APPLY\" })`\n- Record `last_cipe_url`, spawn subagent in wait mode\n\n#### Step 3b: Local Verification Flow\n\nWhen verifiable (non-e2e) unverified tasks exist:\n\n1. **Detect package manager:**\n   - `pnpm-lock.yaml` exists → `pnpm nx`\n   - `yarn.lock` exists → `yarn nx`\n   - Otherwise → `npx nx`\n\n2. **Run verifiable tasks in parallel:**\n   - Spawn `general` subagents to run each task concurrently\n   - Each subagent runs: `<pm> nx run <taskId>`\n   - Collect pass/fail results from all subagents\n\n3. **Evaluate results:**\n\n| Result                    | Action                       |\n| ------------------------- | ---------------------------- |\n| ALL verifiable tasks pass | Apply via MCP                |\n| ANY verifiable task fails | Apply-locally + enhance flow |\n\n4. **Apply-locally + enhance flow:**\n   - Run `nx apply-locally <shortLink>`\n   - Enhance the code to fix failing tasks\n   - Run failing tasks again to verify fix\n   - If still failing → increment `local_verify_count`, loop back to enhance\n   - If passing → commit and push, record `expected_commit_sha`, spawn subagent in wait mode\n\n5. **Track attempts** (wraps step 4):\n   - Increment `local_verify_count` after each enhance cycle\n   - If `local_verify_count >= local_verify_attempts` (default: 3):\n     - Get code in commit-able state\n     - Commit and push with message indicating local verification failed\n     - Report to user:\n       ```\n       [ci-monitor] Local verification failed after <N> attempts. Pushed to CI for final validation. Failed: <taskIds>\n       ```\n     - Record `expected_commit_sha`, spawn subagent in wait mode (let CI be final judge)\n\n#### Commit Message Format\n\n```bash\ngit commit -m \"fix(<projects>): <brief description>\n\nFailed tasks: <taskId1>, <taskId2>\nLocal verification: passed|enhanced|failed-pushing-to-ci\"\n```\n\n### Unverified Fix Flow (No Verification Attempted)\n\nWhen `verificationStatus` is `FAILED`, `NOT_EXECUTABLE`, or fix has `couldAutoApplyTasks != true` with no verification:\n\n- Analyze fix content (`suggestedFix`, `suggestedFixReasoning`, `taskOutputSummary`)\n- If fix looks correct → apply via MCP\n- If fix needs enhancement → use Apply Locally + Enhance Flow above\n- If fix is wrong → reject via MCP, fix from scratch, commit, push\n\n### Auto-Apply Eligibility\n\nThe `couldAutoApplyTasks` field indicates whether the fix is eligible for automatic application:\n\n- **`true`**: Fix is eligible for auto-apply. Subagent keeps polling while verification is in progress. Returns `fix_auto_applying` when verified, or `fix_available` if verification fails.\n- **`false`** or **`null`**: Fix requires manual action (apply via MCP, apply locally, or reject)\n\n**Key point**: When subagent returns `fix_auto_applying`, do NOT call MCP to apply - self-healing handles it. Just spawn a new subagent in wait mode.\n\n### Apply vs Reject vs Apply Locally\n\n- **Apply via MCP**: Calls `update_self_healing_fix({ shortLink, action: \"APPLY\" })`. Self-healing agent applies the fix in CI and a new CIPE spawns automatically. No local git operations needed.\n- **Apply Locally**: Runs `nx apply-locally <shortLink>`. Applies the patch to your local working directory and sets state to `APPLIED_LOCALLY`. Use this when you want to enhance the fix before pushing.\n- **Reject via MCP**: Calls `update_self_healing_fix({ shortLink, action: \"REJECT\" })`. Marks fix as rejected. Use only when the fix is completely wrong and you''ll fix from scratch.\n\n### Apply Locally + Enhance Flow\n\nWhen the fix needs enhancement (use `nx apply-locally`, NOT reject):\n\n1. Apply the patch locally: `nx apply-locally <shortLink>` (this also updates state to `APPLIED_LOCALLY`)\n2. Make additional changes as needed\n3. Commit and push:\n   ```bash\n   git add -A\n   git commit -m \"fix: resolve <failedTaskIds>\"\n   git push origin $(git branch --show-current)\n   ```\n4. Loop to poll for new CIPE\n\n### Reject + Fix From Scratch Flow\n\nWhen the fix is completely wrong:\n\n1. Call MCP to reject: `update_self_healing_fix({ shortLink, action: \"REJECT\" })`\n2. Fix the issue from scratch locally\n3. Commit and push:\n   ```bash\n   git add -A\n   git commit -m \"fix: resolve <failedTaskIds>\"\n   git push origin $(git branch --show-current)\n   ```\n4. Loop to poll for new CIPE\n\n### Environment Issue Handling\n\nWhen `failureClassification == ''ENVIRONMENT_STATE''`:\n\n1. Call MCP to request rerun: `update_self_healing_fix({ shortLink, action: \"RERUN_ENVIRONMENT_STATE\" })`\n2. New CIPE spawns automatically (no local git operations needed)\n3. Loop to poll for new CIPE with `previousCipeUrl` set\n\n### No-New-CIPE Handling\n\nWhen `status == ''no_new_cipe''`:\n\nThis means the expected CIPE was never created - CI likely failed before Nx tasks could run.\n\n1. **Report to user:**\n\n   ```\n   [ci-monitor] No CI attempt for <sha> after 10 min. Check CI provider for pre-Nx failures (install, checkout, auth). Last CI attempt: <previousCipeUrl>\n   ```\n\n2. **If user configured auto-fix attempts** (e.g., `--auto-fix-workflow`):\n   - Detect package manager: check for `pnpm-lock.yaml`, `yarn.lock`, `package-lock.json`\n   - Run install to update lockfile:\n     ```bash\n     pnpm install   # or npm install / yarn install\n     ```\n   - If lockfile changed:\n     ```bash\n     git add pnpm-lock.yaml  # or appropriate lockfile\n     git commit -m \"chore: update lockfile\"\n     git push origin $(git branch --show-current)\n     ```\n   - Record new commit SHA, loop to poll with `expectedCommitSha`\n\n3. **Otherwise:** Exit with `no_new_cipe` status, providing guidance for user to investigate\n\n## Exit Conditions\n\nExit the monitoring loop when ANY of these conditions are met:\n\n| Condition                                   | Exit Type        |\n| ------------------------------------------- | ---------------- |\n| CI passes (`cipeStatus == ''SUCCEEDED''`)     | Success          |\n| Max CIPE cycles reached                     | Timeout          |\n| Max duration reached                        | Timeout          |\n| 3 consecutive no-progress iterations        | Circuit breaker  |\n| No fix available and local fix not possible | Failure          |\n| No new CIPE and auto-fix not configured     | Pre-CIPE failure |\n| User cancels                                | Cancelled        |\n\n## Main Loop\n\n### Step 1: Initialize Tracking\n\n```\ncycle_count = 0\nstart_time = now()\nno_progress_count = 0\nlocal_verify_count = 0\nlast_state = null\nlast_cipe_url = null\nexpected_commit_sha = null\n```\n\n### Step 2: Spawn Subagent\n\nSpawn the `ci-watcher` subagent to poll CI status:\n\n**Fresh start (first spawn, no expected CIPE):**\n\n```\nTask(\n  agent: \"ci-watcher\",\n  prompt: \"Monitor CI for branch ''<branch>''.\n           Subagent timeout: <subagent-timeout> minutes.\n           New-CIPE timeout: <new-cipe-timeout> minutes.\n           Verbosity: <verbosity>.\"\n)\n```\n\n**After action that triggers new CIPE (wait mode):**\n\n```\nTask(\n  agent: \"ci-watcher\",\n  prompt: \"Monitor CI for branch ''<branch>''.\n           Subagent timeout: <subagent-timeout> minutes.\n           New-CIPE timeout: <new-cipe-timeout> minutes.\n           Verbosity: <verbosity>.\n\n           WAIT MODE: A new CIPE should spawn. Ignore old CIPE until new one appears.\n           Expected commit SHA: <expected_commit_sha>\n           Previous CIPE URL: <last_cipe_url>\"\n)\n```\n\n### Step 3: Handle Subagent Response\n\nWhen subagent returns:\n\n1. Check the returned status\n2. Look up default behavior in the table above\n3. Check if user instructions override the default\n4. Execute the appropriate action\n5. **If action expects new CIPE**, update tracking (see Step 3a)\n6. If action results in looping, go to Step 2\n\n### Step 3a: Track State for New-CIPE Detection\n\nAfter actions that should trigger a new CIPE, record state before looping:\n\n| Action                        | What to Track                                 | Subagent Mode |\n| ----------------------------- | --------------------------------------------- | ------------- |\n| Fix auto-applying             | `last_cipe_url = current cipeUrl`             | Wait mode     |\n| Apply via MCP                 | `last_cipe_url = current cipeUrl`             | Wait mode     |\n| Apply locally + push          | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n| Reject + fix + push           | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n| Fix failed + local fix + push | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n| No fix + local fix + push     | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n| Environment rerun             | `last_cipe_url = current cipeUrl`             | Wait mode     |\n| No-new-CIPE + auto-fix + push | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n\n**CRITICAL**: When passing `expectedCommitSha` or `last_cipe_url` to the subagent, it enters **wait mode**:\n\n- Subagent will **completely ignore** the old/stale CIPE\n- Subagent will only wait for new CIPE to appear\n- Subagent will NOT return to main agent with stale CIPE data\n- Once new CIPE detected, subagent switches to normal polling\n\n**Why wait mode matters for context preservation**: Stale CIPE data can be very large (task output summaries, suggested fix patches, reasoning). If subagent returns this to main agent, it pollutes main agent''s context with useless data since we already processed that CIPE. Wait mode keeps stale data in the subagent, never sending it to main agent.\n\n### Step 4: Progress Tracking\n\nAfter each action:\n\n- If state changed significantly → reset `no_progress_count = 0`\n- If state unchanged → `no_progress_count++`\n- On new CI attempt detected → reset `local_verify_count = 0`\n\n## Status Reporting\n\nBased on verbosity level:\n\n| Level     | What to Report                                                             |\n| --------- | -------------------------------------------------------------------------- |\n| `minimal` | Only final result (success/failure/timeout)                                |\n| `medium`  | State changes + periodic updates (\"Cycle N \\| Elapsed: Xm \\| Status: ...\") |\n| `verbose` | All of medium + full subagent responses, git outputs, MCP responses        |\n\n## User Instruction Examples\n\nUsers can override default behaviors:\n\n| Instruction                                      | Effect                                        |\n| ------------------------------------------------ | --------------------------------------------- |\n| \"never auto-apply\"                               | Always prompt before applying any fix         |\n| \"always ask before git push\"                     | Prompt before each push                       |\n| \"reject any fix for e2e tasks\"                   | Auto-reject if `failedTaskIds` contains e2e   |\n| \"apply all fixes regardless of verification\"     | Skip verification check, apply everything     |\n| \"if confidence < 70, reject\"                     | Check confidence field before applying        |\n| \"run ''nx affected -t typecheck'' before applying\" | Add local verification step                   |\n| \"auto-fix workflow failures\"                     | Attempt lockfile updates on pre-CIPE failures |\n| \"wait 45 min for new CIPE\"                       | Override new-CIPE timeout (default: 10 min)   |\n\n## Error Handling\n\n| Error                    | Action                                                                                |\n| ------------------------ | ------------------------------------------------------------------------------------- |\n| Git rebase conflict      | Report to user, exit                                                                  |\n| `nx apply-locally` fails | Report to user, attempt manual patch or exit                                          |\n| MCP tool error           | Retry once, if fails report to user                                                   |\n| Subagent spawn failure   | Retry once, if fails exit with error                                                  |\n| No new CIPE detected     | If `--auto-fix-workflow`, try lockfile update; otherwise report to user with guidance |\n| Lockfile auto-fix fails  | Report to user, exit with guidance to check CI logs                                   |\n\n## Example Session\n\n### Example 1: Normal Flow with Self-Healing (medium verbosity)\n\n```\n[ci-monitor] Starting CI monitor for branch ''feature/add-auth''\n[ci-monitor] Config: max-cycles=5, timeout=120m, verbosity=medium\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] CI attempt: IN_PROGRESS | Self-Healing: NOT_STARTED | Elapsed: 1m\n[CI Monitor] CI attempt: FAILED | Self-Healing: IN_PROGRESS | Elapsed: 3m\n[CI Monitor] CI attempt: FAILED | Self-Healing: COMPLETED | Elapsed: 5m\n\n[ci-monitor] Fix available! Verification: COMPLETED\n[ci-monitor] Applying fix via MCP...\n[ci-monitor] Fix applied in CI. Waiting for new CI attempt...\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] New CI attempt detected!\n[CI Monitor] CI attempt: SUCCEEDED | Elapsed: 8m\n\n[ci-monitor] CI passed successfully!\n\n[ci-monitor] Summary:\n  - Total cycles: 2\n  - Total time: 12m 34s\n  - Fixes applied: 1\n  - Result: SUCCESS\n```\n\n### Example 2: Pre-CI Failure (medium verbosity)\n\n```\n[ci-monitor] Starting CI monitor for branch ''feature/add-products''\n[ci-monitor] Config: max-cycles=5, timeout=120m, auto-fix-workflow=true\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] CI attempt: FAILED | Self-Healing: COMPLETED | Elapsed: 2m\n\n[ci-monitor] Applying fix locally, enhancing, and pushing...\n[ci-monitor] Committed: abc1234\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] Waiting for new CI attempt... (expected SHA: abc1234)\n[CI Monitor] ⚠️  CI attempt timeout (10 min). Returning no_new_cipe.\n\n[ci-monitor] Status: no_new_cipe\n[ci-monitor] --auto-fix-workflow enabled. Attempting lockfile update...\n[ci-monitor] Lockfile updated. Committed: def5678\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] New CI attempt detected!\n[CI Monitor] CI attempt: SUCCEEDED | Elapsed: 18m\n\n[ci-monitor] CI passed successfully!\n\n[ci-monitor] Summary:\n  - Total cycles: 3\n  - Total time: 22m 15s\n  - Fixes applied: 1 (self-healing) + 1 (lockfile)\n  - Result: SUCCESS\n```\n"},"lastSynced":"2026-03-08T02:11:35.978Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated CI pipeline monitoring and self-healing capabilities.","zh":"适用于需要自动化 CI 流水线监控和自愈能力的 DevOps 代理。","ja":"DevOps エージェントが自動化された CI パイプラインの監視と自己回復機能を必要とする場合に適しています。","ko":"자동화된 CI 파이프라인 모니터링 및 셀프 힐링 기능이 필요한 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren monitoreo automatizado de tuberías de CI y capacidades de auto-sanación.","fr":"Idéal pour les agents DevOps nécessitant un monitoring automatique de pipeline CI et des capacités d''auto-réparation.","de":"Ideal für DevOps-Agents, die ein automatisiertes Monitoring von CI-Pipelines und Selbstheilungsfähigkeiten erfordern.","pt":"Ideal para agentes DevOps que exigem monitoramento automatizado de pipeline CI e capacidades de auto-cura.","ru":"Идеально для агентов DevOps, требующих автоматического мониторинга конвейера CI и возможностей самоисцеления.","ar":"مثالي لعميل DevOps الذين يتطلبون مراقبة خط أنابيب CI آلي وقدرات الشفاء الذاتي."},"recommendation":{"en":"Empowers agents to optimize builds, scale CI, and automatically fix failed PRs using Nx Cloud CI pipeline executions and git commands, streamlining the development process with features like polling CI status and making decisions based on the results.","zh":"赋予代理优化构建、扩展 CI 和使用 Nx Cloud CI 流水线执行和 git 命令自动修复失败的 PR 的能力，通过功能如轮询 CI 状态并根据结果做出决定来简化开发流程。","ja":"エージェントにビルドを最適化し、CI を拡張し、Nx Cloud CI パイプラインの実行と git コマンドを使用して失敗した PR を自動的に修復する能力を与え、CI 状態のポーリングなどの機能によって開発プロセスを簡素化し、結果に基づいて決定を下します。","ko":"에이전트에 빌드를 최적화하고 CI를 확장하며 Nx Cloud CI 파이프라인 실행과 git 명령을 사용하여 실패한 PR을 자동으로 수정하는 능력을 부여하여 CI 상태를 폴링하고 결과에 따라 결정 등을 통해 개발 프로세스를 간소화합니다.","es":"Habilita a los agentes a optimizar las compilaciones, escalar CI y reparar automáticamente PR fallidas utilizando ejecuciones de tuberías de CI de Nx Cloud y comandos de git, simplificando el proceso de desarrollo con características como la verificación del estado de CI y la toma de decisiones en función de los resultados.","fr":"Permet aux agents d''optimiser les builds, de mettre à l''échelle le CI et de réparer automatiquement les PR échouées en utilisant les exécutions de pipeline CI de Nx Cloud et les commandes git, en rationalisant le processus de développement avec des fonctionnalités comme la vérification de l''état de CI et la prise de décision en fonction des résultats.","de":"Ermächtigt Agenten, Builds zu optimieren, CI zu skalieren und fehlgeschlagene PRs mithilfe von Nx Cloud CI-Pipeline-Executions und Git-Befehlen automatisch zu beheben, wodurch der Entwicklungsprozess mit Funktionen wie der Überwachung des CI-Status und der Entscheidungsfindung auf der Grundlage der Ergebnisse rationalisiert wird.","pt":"Concede poderes aos agentes para otimizar compilações, dimensionar CI e consertar automaticamente PRs com falhas usando execuções de pipeline CI Nx Cloud e comandos git, otimizando o processo de desenvolvimento com recursos como sondagem do status CI e tomar decisões com base nos resultados.","ru":"Наделяет агентов возможностью оптимизировать сборки, масштабировать CI и автоматически исправлять неудачные PR с помощью выполнения конвейера CI Nx Cloud и команд git, оптимизируя процесс разработки функциями, такими как опрос состояния CI и принятие решений на основе результатов.","ar":"تمنح الوكيل صلاحيات لتحسين التجميع وتوسيع نطاق CI وإصلاح requestsPull الفاشلة تلقائيًا باستخدام تنفيذ خط أنابيب CI Nx Cloud وأوامر Git ، وبهذه الطريقة تحسين عملية التطوير باستخدام ميزات مثل استطلاع حالة CI واتخاذ قرارات بناءً على النتائج."},"useCases":{"en":["Automating failed PR fixes","Monitoring CI pipeline executions","Scaling CI for optimized builds"],"zh":["自动修复失败的 PR","监控 CI 流水线执行","优化构建以扩展 CI"],"ja":["失敗した PR の自動修復","CI パイプラインの実行の監視","ビルドの最適化による CI の拡張"],"ko":["실패한 PR 자동 수정","CI 파이프라인 실행 모니터링","빌드 최적화를 통한 CI 확장"],"es":["Automatización de correcciones de PR fallidas","Monitoreo de ejecuciones de tuberías de CI","Escalado de CI para compilaciones optimizadas"],"fr":["Automatisation de la correction des PR échouées","Surveillance des exécutions de pipeline CI","Mise à l''échelle du CI pour des builds optimisés"],"de":["Automatisierung von Korrekturen fehlgeschlagener PRs","Überwachung von CI-Pipeline-Executions","Skalierung von CI für optimierte Builds"],"pt":["Automatizar reparos de PR com falha","Monitorar execuções de pipeline CI","Dimensionar CI para compilações otimizadas"],"ru":["Автоматизировать исправление неудачных PR","Мониторить выполнение конвейера CI","Масштабировать CI для оптимизированных сборок"],"ar":["الاستفادة من إصلاح requestsPull الفاشلة تلقائيًا","مراقبة تنفيذ خط أنابيب CI","توسيع نطاق CI من أجل تجميع محسّن"]},"limitations":{"en":["Requires git access","Nx Cloud CI pipeline setup needed","Limited to handling self-healing fixes for CI pipeline executions"],"zh":["需要 git 访问","需要 Nx Cloud CI 流水线设置","仅限处理 CI 流水线执行的自愈修复"],"ja":["git アクセスが必要","Nx Cloud CI パイプラインの設定が必要","CI パイプラインの実行の自己回復修復のみを処理"],"ko":["git 접근이 필요","Nx Cloud CI 파이프라인 설정이 필요","CI 파이프라인 실행의 셀프 힐링 수정만 처리"],"es":["Requiere acceso a git","Configuración de tubería de CI de Nx Cloud necesaria","Limitado a la gestión de correcciones de auto-sanación para ejecuciones de tuberías de CI"],"fr":["Nécessite un accès à git","Configuration de pipeline CI de Nx Cloud nécessaire","Limité à la gestion des corrections d''auto-réparation pour les exécutions de pipeline CI"],"de":["Erfordert Git-Zugriff","Einrichtung von Nx Cloud CI-Pipeline erforderlich","Begrenzt auf die Verwaltung von Selbstheilungskorrekturen für CI-Pipeline-Executions"],"pt":["Exige acesso ao git","Configuração do pipeline CI Nx Cloud necessária","Limitado ao tratamento de reparos de auto-cura para execuções de pipeline CI"],"ru":["Требует доступа к git","Необходима настройка конвейера CI Nx Cloud","Ограничен обработкой исправлений самоисцеления для выполнения конвейера CI"],"ar":["يتطلب الوصول إلى Git","يحتاج إلى إعداد خط أنابيب CI Nx Cloud","محدود بمعالجة إصلاحات الشفاء الذاتي لتنفيذ خط أنابيب CI"]},"version":4},"contentHash":"a124ec3b3bd0e12152c9729b1239df7f69da2321c3a4d8be2014943056d3f6b6","qualityScore":45}');
