INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('saeed-vayghan/mitra/workflow-loader', 'workflow-loader', 'saeed-vayghan', 'mitra', 'community', 'workflow-loader saeed-vayghan mitra community The workflow-loader skill enables Gemini Agents to load, read, and execute external workflow files from the mitra/agents/{agent}/workflows/ directory, ensuring accurate and efficient collaborative problem-solving. Workflow Loader 技术允许 Gemini Agent 加载和执行外部工作流文件，实现 Mitra AI Agents 的集成 Workflow Loader 技術により、Gemini Agent が外部ワークフロー文件を読み込み実行できます 워크플로우 로더 기술을 통해 Gemini 에이전트는 외부 워크플로우 파일을 로드하고 실행할 수 있습니다 El skill workflow-loader permite a los agentes de IA cargar y ejecutar flujos de trabajo externos de manera robusta, mejorando la colaboración y la eficiencia Le skill workflow-loader permet aux agents d''IA de charger et d''exécuter des flux de travail externes de manière robuste, améliorant la collaboration et l''efficacité Das workflow-loader-Skill ermöglicht es AI-Agents, externe Workflows robust zu laden und auszuführen, wodurch die Zusammenarbeit und Effizienz verbessert werden O Workflow Loader é uma habilidade que permite carregar e executar arquivos de fluxo de trabalho externos em diretórios específicos Workflow Loader - это навык, позволяющий загружать и выполнять внешние файлы рабочих процессов в определенных директориях Workflow Loader هي مهارة تسمح بتحميل وتشغيل ملفات سير العمل الخارجية في مجلدات محددة how to use workflow-loader workflow-loader setup guide what is workflow-loader workflow-loader alternative workflow-loader vs mitra install workflow-loader workflow-loader for Gemini Agents loading external workflow files executing markdown workflows Mitra AI Agents Workflow Loader Gemini Agent 外部工作流文件 AI 集成 工作流执行 Hallucinate Fail 工作流精度 Loads external workflow files from the mitra/agents/{agent}/workflows/ directory Executes workflow files defined in markdown format Resolves ambiguity in instructions like ''Action: Load backend.md'' Prevents hallucination, failure, and guessing by the LLM Enables seamless collaboration through specialized AI personas workflow-loader is a skill designed for Gemini Agents to robustly load and execute external workflow files, facilitating collaborative problem-solving through specialized AI personas');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('natalialewis/CS4610-Supabase-NextJS-Starter-App/nextjs-supabase-starter', 'community', 'natalialewis', 'CS4610-Supabase-NextJS-Starter-App', 'natalialewis/CS4610-Supabase-NextJS-Starter-App', 'nextjs-supabase-starter', 0, 0, 45, '2026-03-08T01:57:15.587Z', '2026-03-08T02:11:58.159Z', '186bd8d7f200369aad117c71fe99434dd4e2eead43efe73ac808947cd7c9335a', '{"id":"natalialewis/CS4610-Supabase-NextJS-Starter-App/nextjs-supabase-starter","name":"nextjs-supabase-starter","description":{"en":"The nextjs-supabase-starter skill provides a foundation for building modern web apps with authentication using Next.js and Supabase. It benefits developers looking for a well-documented and easy-to-set-up starter app.","zh":"Next.js + Supabase Starter 应用是一个现代化的 Web 应用模板，包含身份验证和最新的 Next.js 13+ App Router 约定","ja":"Next.js + Supabase スターター アプリは、認証と最新の Next.js 13+ App Router 規約を含むモダンな Web アプリ テンプレートです","ko":"Next.js + Supabase 스타터 앱은 인증과 최신 Next.js 13+ App Router 규칙을 포함하는 현대적인 웹 애플리케이션 템플릿입니다","es":"La aplicación de inicio de Next.js y Supabase ofrece una base sólida para aplicaciones web modernas con autenticación","fr":"L''application de démarrage Next.js et Supabase fournit une base solide pour les applications web modernes avec authentification","de":"Die Next.js- und Supabase-Starter-App bietet eine solide Basis für moderne Webanwendungen mit Authentifizierung","pt":"O nextjs-supabase-starter é uma ferramenta para criar aplicações web modernas com autenticação","ru":"nextjs-supabase-starter - это инструмент для создания современных веб-приложений с аутентификацией","ar":"nextjs-supabase-starter هي أداة لإنشاء تطبيقات ويب حديثة مع مصادقة"},"seo":{"title":{"en":"nextjs-supabase-starter: Setup Guide for AI Agents","zh":"Next.js + Supabase Starter 应用设置指南","ja":"Next.js + Supabase スターター アプリ設定ガイド","ko":"Next.js + Supabase 스타터 앱 설정 가이드","es":"Guía de configuración para Next.js y Supabase Starter","fr":"Guide de démarrage pour Next.js et Supabase Starter","de":"Einrichtungsleitfaden für Next.js und Supabase Starter","pt":"Guia de Configuração do nextjs-supabase-starter","ru":"ИИ Агенты: Руководство по настройке nextjs-supabase-starter","ar":"دليل إعداد nextjs-supabase-starter مع أدوات الإي آي"},"description":{"en":"Discover how to implement Next.js 13+ App Router conventions with Supabase for a well-documented and easy-to-set-up modern web app. Learn more and get starte...","zh":"了解 Next.js 和 Supabase 的 starter 应用，包含最新的 Next.js 13+ App Router 约定","ja":"Next.js と Supabase のスターター アプリを学ぶ、最新の Next.js 13+ App Router 規約を含む","ko":"Next.js와 Supabase의 스타터 앱에 대해 알아보세요, 최신 Next.js 13+ App Router 규칙 포함","es":"Aprende a configurar la aplicación de inicio de Next.js y Supabase con autenticación y características esenciales","fr":"Découvrez comment configurer l''application de démarrage Next.js et Supabase avec authentification et fonctionnalités essentielles","de":"Erfahren Sie, wie Sie die Next.js- und Supabase-Starter-App mit Authentifizierung und wichtigen Funktionen einrichten","pt":"Aprenda a configurar o nextjs-supabase-starter com as melhores práticas e dicas para desenvolvedores","ru":"Узнайте, как настроить nextjs-supabase-starter с помощью последних рекомендаций и советов для разработчиков","ar":"تعلم كيفية إعداد nextjs-supabase-starter مع أفضل الممارسات وأدوات الإي آي"},"definition":{"en":"nextjs-supabase-starter is a starter app that combines Next.js with Supabase for building modern web applications with authentication, following Next.js 13+ App Router conventions.","zh":"Next.js + Supabase Starter 应用是一个预配置的模板，用于快速构建现代化的 Web 应用","ja":"Next.js + Supabase スターター アプリは、モダンな Web アプリを迅速に構築するための事前設定済みテンプレートです","ko":"Next.js + Supabase 스타터 앱은 현대적인 웹 애플리케이션을 빠르게 구축하기 위한 사전 구성된 템플릿입니다","es":"El kit de inicio de Next.js y Supabase es un conjunto de herramientas para crear aplicaciones web modernas","fr":"Le kit de démarrage Next.js et Supabase est un ensemble d''outils pour créer des applications web modernes","de":"Das Next.js- und Supabase-Starter-Kit ist ein Satz von Tools zur Erstellung moderner Webanwendungen","pt":"O nextjs-supabase-starter é um kit de início para aplicações web com Next.js e Supabase","ru":"nextjs-supabase-starter - это стартовый комплект для веб-приложений с Next.js и Supabase","ar":"nextjs-supabase-starter هو حزمة بداية لإنشاء تطبيقات ويب مع Next.js و Supabase"},"features":{"en":["Uses the latest Next.js version with App Router conventions","Follows Next.js 13+ App Router conventions for routing","Utilizes the `app/` directory for App Router implementation","Includes essential features for modern web apps with authentication","Requires clear and consistent naming for routes, components, and hooks","Must be well-documented and easy to set up"],"zh":["最新的 Next.js 13+ App Router 约定","包含身份验证功能","使用 app/ 目录","支持 Supabase 数据库","易于设置和使用"],"ja":["最新の Next.js 13+ App Router 規約","認証機能を含む","app/ ディレクトリを使用","Supabase データベースをサポート","簡単に設定と使用"],"ko":["최신 Next.js 13+ App Router 규칙","인증 기능 포함","app/ 디렉토리 사용","Supabase 데이터베이스 지원","쉽게 설정 및 사용"],"es":["Utiliza la última versión de Next.js","Seguimiento de las convenciones de App Router de Next.js 13+","Autenticación integrada","Documentación clara y consistente","Uso del directorio ''app/''"],"fr":["Utilise la dernière version de Next.js","Suivi des conventions de l''App Router de Next.js 13+","Authentification intégrée","Documentation claire et cohérente","Utilisation du répertoire ''app/''"],"de":["Verwenden der neuesten Version von Next.js","Befolgen der App-Router-Konventionen von Next.js 13+","Integrierte Authentifizierung","Klare und konsistente Dokumentation","Verwendung des ''app/''-Verzeichnisses"],"pt":["Uso da versão mais recente do Next.js","Implementação do App Router","Autenticação com Supabase","Documentação clara e consistente","Configuração fácil"],"ru":["Использование последней версии Next.js","Реализация App Router","Аутентификация с помощью Supabase","Ясная и последовательная документация","Легкая настройка"],"ar":["استخدام أحدث إصدار من Next.js","تنفيذ App Router","مصادقة مع Supabase","توثيق واضح ومستمر","إعداد سهل"]},"keywords":{"en":["how to use nextjs-supabase-starter","nextjs-supabase-starter setup guide","nextjs-supabase-starter vs nextjs-prisma-starter","nextjs-supabase-starter install","what is nextjs-supabase-starter","nextjs-supabase-starter alternative","nextjs-supabase-starter tutorial","nextjs-supabase-starter documentation","nextjs-supabase-starter example"],"zh":["Next.js","Supabase","starter 应用","现代化 Web 应用","身份验证","App Router","AIエージェント","设置指南"],"ja":["Next.js","Supabase","スターター アプリ","モダンな Web アプリ","認証","App Router","AIエージェント","設定ガイド"],"ko":["Next.js","Supabase","스타터 앱","현대적인 웹 애플리케이션","인증","App Router","AI 에이전트","설정 가이드"],"es":["Next.js Supabase","aplicaciones web modernas","autenticación en Next.js","App Router de Next.js","herramientas de desarrollo web","starter kit de Next.js"],"fr":["Next.js Supabase","applications web modernes","authentification dans Next.js","App Router de Next.js","outils de développement web","kit de démarrage Next.js"],"de":["Next.js Supabase","moderne Webanwendungen","Authentifizierung in Next.js","App-Router von Next.js","Webentwicklungstools","Next.js-Starter-Kit"],"pt":["nextjs-supabase-starter","Next.js","Supabase","autenticação","aplicações web modernas","desenvolvimento web","kit de início"],"ru":["nextjs-supabase-starter","Next.js","Supabase","аутентификация","современные веб-приложения","веб-разработка","стартовый комплект"],"ar":["nextjs-supabase-starter","Next.js","Supabase","مصادقة","تطبيقات ويب حديثة","تطوير ويب","حزمة بداية"]}},"owner":"natalialewis","repo":"CS4610-Supabase-NextJS-Starter-App","repoPath":"natalialewis/CS4610-Supabase-NextJS-Starter-App","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.587Z","topics":[],"category":"community","skillMd":{"name":"nextjs-supabase-starter","description":"Rules and best practices for building a Next.js starter app with Supabase (auth, profiles, RLS, declarative schemas, setup script). Use when working on Next.js + Supabase integration, authentication, migrations, or this starter app codebase.","bodyPreview":"# Next.js + Supabase Starter App Rules\n\nApply these rules when implementing or modifying the starter app. Names for routes, components, and hooks are flexible—use clear, consistent names and document choices. The starter should be **well-documented**, **easy to set up**, and include essential features for a modern web app with authentication.\n\n---\n\n## 1. Next.js\n\n- **Version**: Use the latest Next.js; follow Next.js 13+ App Router conventions.\n- **App Router only**: Use the `app/` directory; do","body":"# Next.js + Supabase Starter App Rules\n\nApply these rules when implementing or modifying the starter app. Names for routes, components, and hooks are flexible—use clear, consistent names and document choices. The starter should be **well-documented**, **easy to set up**, and include essential features for a modern web app with authentication.\n\n---\n\n## 1. Next.js\n\n- **Version**: Use the latest Next.js; follow Next.js 13+ App Router conventions.\n- **App Router only**: Use the `app/` directory; do not use `pages/`.\n- **TypeScript**: Use TypeScript throughout; no `any` without justification. Use explicit semicolons at the end of statements in `.ts` and `.tsx` files.\n- **Project structure**: Organize with `app/`, `components/`, `lib/`, etc. Document structure and conventions in README.\n- **Styling**: Use Tailwind CSS primarily, and plain CSS if needed.\n- **Mobile-first**: All layout and typography must be **mobile-first**. In Tailwind, base (unprefixed) classes define styles for the smallest viewport (mobile). Use `sm:`, `md:`, `lg:` only to add or override for larger screens. Do not use base classes for desktop and then scale down with breakpoints—design for mobile first, then enhance upward (e.g. base `text-sm` / `p-4`, then `md:text-base` / `md:p-6`). Use touch-friendly minimum sizes on mobile (e.g. `min-h-[2.75rem]` for buttons/links) and relax with `sm:min-h-0` or `md:` when appropriate. Page content should use `min-h-[calc(100vh-3.5rem)]` (or similar) to account for the header so vertical centering and scroll behavior are correct.\n- **Middleware**: Use Next.js middleware for Supabase token refresh; implement the refresh logic in `proxy.ts` and use it from `middleware.ts` (see Supabase section).\n- **Server vs client**: Prefer Server Components by default; add `''use client''` only where needed (e.g. forms, auth state in UI). Colocate route-specific components in route folders when it makes sense.\n- **UX**: Use `loading.tsx` and `error.tsx` in route segments for loading and error states where appropriate.\n\n---\n\n## 2. Supabase Integration\n\n- **CLI and client**: Install and configure Supabase CLI and client libraries; use `@supabase/ssr` for SSR-safe usage.\n- **Local dev**: Set up Supabase for local development; run via `npx supabase start`; setup script configures and documents this.\n- **Two client utilities**: Provide separate helpers for **server** and **client** components (e.g. `createServerClient`, `createBrowserClient` in `lib/supabase/`) using `@supabase/ssr`.\n- **Middleware**: Configure Next.js middleware for token refresh using `proxy.ts`: put the session refresh / proxy logic in `proxy.ts` and invoke it from `middleware.ts` so the session is updated on each request.\n- **Environment**: Require `NEXT_PUBLIC_SUPABASE_URL` and `NEXT_PUBLIC_SUPABASE_ANON_KEY` in `.env.local`; document in README. Never expose the service_role key in client or frontend code; use only the anon key in the app.\n- **Storage** (e.g. avatars): If using Supabase Storage, create a bucket and set RLS so users can read/update only their own objects (e.g. by path or user id).\n\n---\n\n## 3. Database and Migrations\n\n- **No manual SQL**: All schema changes go through **migration files** only.\n- **Declarative schemas**: Define tables in `supabase/schemas/` (e.g. `supabase/schemas/profiles.sql`). Generate migrations with:\n  ```bash\n  npx supabase db diff -f <migration_name>\n  ```\n- **Profiles table**:\n  - Primary key: `id` referencing `auth.users(id)`.\n  - Include `updated_at` with a trigger that sets it on row update.\n  - Define in declarative schema; add trigger and RLS in migrations.\n- **Automatic profile creation**: Use a PostgreSQL trigger that:\n  - Fires **AFTER INSERT** on `auth.users`.\n  - Reads the new user’s email (and id) from the inserted row.\n  - Inserts one row into `profiles` with that `id` and email. Trigger and function live in a migration file.\n\n---\n\n## 4. Row Level Security (RLS)\n\n- **Enable RLS** on `profiles`.\n- **Policies** (use `auth.uid()`):\n  - **SELECT**: User can read only their own profile.\n  - **UPDATE**: User can update only their own profile.\n  - **INSERT**: User can insert only their own profile (backup to trigger).\n- Ensure users cannot read or modify other users’ profiles.\n\n---\n\n## 5. Authentication\n\n- **Implement**: Sign up, sign in, sign out.\n- **Protected routes**: Redirect unauthenticated users to login (e.g. from dashboard/profile).\n- **State**: Handle auth state correctly in both server and client components.\n- **Patterns**: Use consistent patterns—e.g. a `useAuth()` (or similar) hook for client components and server-side helpers (e.g. `getUser()`) for server components. Document these in README.\n- **Errors**: Handle auth errors (invalid credentials, network, etc.) and show clear messages.\n\n---\n\n## 6. Example Pages and Routes\n\nRoute names are flexible (e.g. `/auth/login`, `/account`); keep them logical and consistent.\n\n- **Home (`/`)**: Welcome, auth status, link to login/signup when logged out, link to dashboard when logged in.\n- **Login**: Email/password form, error handling, redirect to dashboard on success.\n- **Signup**: Email/password form, error handling, redirect to dashboard on success.\n- **Dashboard (protected)**: Require auth; show profile summary and link to profile; sign out.\n- **Profile (protected)**: Require auth; show profile; form to update (e.g. `full_name` and any other profile fields); **avatar upload** that allows selecting/uploading an image, stores it (e.g. Supabase Storage), updates `avatar_url` in `profiles`, displays the avatar, and includes a save/update button; handle upload and validation errors.\n\n---\n\n## 7. Setup Script\n\n- **Purpose**: One command to install deps, start Supabase, write env, run migrations. Implement as `setup.sh`, `setup.js`, or use a tool like **zx** for cross-platform support; ensure it works reliably and handles edge cases.\n- **Assumptions**: Supabase is already initialized (`supabase/` with migrations and schemas exists). Do not assume a clean machine beyond that.\n- **Idempotent**: Safe to run multiple times. If `.env.local` exists, either skip or update it. If Supabase is already running, handle gracefully (e.g. skip start or detect and continue).\n- **Steps** (in order):\n  1. `npm install`\n  2. `npx supabase start` (or detect already running)\n  3. Extract Supabase URL and anon key from `supabase start` output\n  4. Create or update `.env.local` with `NEXT_PUBLIC_SUPABASE_URL` and `NEXT_PUBLIC_SUPABASE_ANON_KEY`\n  5. Run migrations: `npx supabase db reset` or `npx supabase migration up`\n  6. Print clear output showing what was done and next steps\n- **Errors**: Provide helpful error messages if something goes wrong. In README, include instructions on how to run the script and troubleshoot.\n\n---\n\n## 8. Code Organization and Documentation\n\n- **Explicit structure**: Decide where things live (e.g. `components/`, `components/ui/`, `lib/hooks/`, `lib/utils/`) and document in README so anyone using the starter understands structure and conventions.\n- **Reusable components**: Store shared UI (buttons, forms, etc.) in a documented location.\n- **Hooks and utils**: Keep custom hooks (e.g. auth) and utility functions in consistent locations; document naming and usage.\n- **README must include**: Project description and purpose; prerequisites (Node.js version, Docker for Supabase, etc.); quick start (how to run the setup script); manual setup (step-by-step if someone prefers); project structure; how to use this starter for new projects; environment variables; database schema overview; authentication flow; deployment instructions; GitHub Actions setup and configuration; troubleshooting section.\n\n---\n\n## 9. Testing\n\n- **Framework**: Use a unit test framework (e.g. Jest, Vitest).\n- **Coverage**: Include at least a few examples for:\n  - React components\n  - Utility functions\n  - Auth-related code\n- **README**: How to run tests and how to add new tests.\n\n---\n\n## 10. Deployment and CI/CD\n\n- **Deployment docs**: Document how to deploy to production (e.g. Vercel, Netlify): steps to set up the production Supabase project; how to configure environment variables in the deployment platform; how to link the production database; any platform-specific considerations (e.g. on Vercel: set env vars in project settings, use production Supabase URL/anon key, do not commit `.env.local`).\n- **Vercel**: If deploying on Vercel, use the dashboard for env vars, connect the repo, and ensure `NEXT_PUBLIC_*` and Supabase keys are set. Middleware runs on the Edge runtime by default.\n- **GitHub Actions**: Create a workflow that triggers on deployment or push to main/production branch; connects to the production Supabase instance; runs pending migrations via Supabase CLI; uses GitHub Secrets for sensitive credentials; handles errors with clear feedback. Document in README how to set up and configure the workflow and secrets.\n\n---\n\n## 11. General\n\n- **Error handling**: Include proper error handling for authentication and database operations; avoid silent failures.\n- **Comments**: Add comments in code where logic or intent is non-obvious.\n- **Naming**: Use clear, consistent names for routes, components, hooks, and functions; document in README when choices affect how others use the starter.\n\n## 12. Submission Checklist\n\n- Remove `node_modules` before submitting. Zip the project folder; do not delete the `supabase/` directory (migrations and schemas must remain).\n- Ensure the setup script is included and executable.\n- Verify README is comprehensive and clear.\n"},"lastSynced":"2026-03-08T02:11:58.159Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing rapid Next.js and Supabase integration for modern web app development with authentication.","zh":"非常适合需要快速Next.js和Supabase集成的全栈开发代理，用于现代Web应用开发和身份验证。","ja":"Next.jsとSupabaseの迅速な統合を必要とするフルスタックエージェントに最適で、モダンなWebアプリケーションの開発と認証を行う。","ko":"Next.js와 Supabase의 빠른 통합이 필요한 풀스택 에이전트에게 적합하며, 현대적인 웹 애플리케이션 개발과 인증에 사용됩니다.","es":"Perfecto para Agentes de Full Stack que necesitan una integración rápida de Next.js y Supabase para el desarrollo de aplicaciones web modernas con autenticación.","fr":"Parfait pour les agents Full Stack ayant besoin d''une intégration rapide de Next.js et Supabase pour le développement d''applications web modernes avec authentification.","de":"Perfekt für Full-Stack-Agenten, die eine schnelle Integration von Next.js und Supabase für die Entwicklung moderner Webanwendungen mit Authentifizierung benötigen.","pt":"Perfeito para Agentes Full Stack que necessitam de integração rápida do Next.js e Supabase para desenvolvimento de aplicativos web modernos com autenticação.","ru":"Идеально подходит для агентов Full Stack, которым требуется быстрая интеграция Next.js и Supabase для разработки современных веб-приложений с аутентификацией.","ar":"مثالي للوكلاء كامل الحزمة الذين يحتاجون إلى دمج سريع من Next.js و Supabase من أجل تطوير تطبيقات الويب الحديثة مع المصادقة."},"recommendation":{"en":"Empowers agents to build well-documented and easy-to-set-up web applications using the latest Next.js and Supabase, following Next.js 13+ App Router conventions for streamlined development and authentication.","zh":"赋予代理构建文档齐全且易于设置的Web应用程序的能力，使用最新的Next.js和Supabase，遵循Next.js 13+ App Router约定，实现流畅的开发和身份验证。","ja":"エージェントに最新のNext.jsとSupabaseを使用して、文書化されていて設定が容易なWebアプリケーションを構築する能力を与え、Next.js 13+ App Routerの規約に従って開発と認証をストリームライン化する。","ko":"에이전트가 최신 Next.js와 Supabase를 사용하여 잘 문서화된 웹 애플리케이션을 쉽게 설정하여 빌드할 수 있는 능력을 부여하며, Next.js 13+ App Router 규약에 따라 개발과 인증을 간소화합니다.","es":"Habilita a los agentes a construir aplicaciones web bien documentadas y fáciles de configurar utilizando las últimas versiones de Next.js y Supabase, siguiendo las convenciones del enrutador de aplicaciones de Next.js 13+ para un desarrollo y autenticación optimizados.","fr":"Permet aux agents de créer des applications web bien documentées et faciles à configurer en utilisant les dernières versions de Next.js et Supabase, en suivant les conventions du routeur d''applications Next.js 13+ pour un développement et une authentification rationalisés.","de":"Ermächtigt Agenten, gut dokumentierte und leicht einzurichtende Webanwendungen mit den neuesten Versionen von Next.js und Supabase zu erstellen, indem sie die Konventionen des Next.js 13+ App-Routers für optimiertes Entwicklung und Authentifizierung befolgen.","pt":"Habilita os agentes a construir aplicações web bem documentadas e fáceis de configurar usando o último Next.js e Supabase, seguindo as convenções do Next.js 13+ App Router para desenvolvimento e autenticação simplificados.","ru":"Наделяет агентов возможностью создавать хорошо документированные и легко настраиваемые веб-приложения, используя последние Next.js и Supabase, в соответствии с конвенциями Next.js 13+ App Router для упрощенного развития и аутентификации.","ar":"يمنح الوكلاء القدرة على بناء تطبيقات الويب الموثقة جيدًا وسهلة الإعداد باستخدام Next.js و Supabase الأحدث ، متبعةً اتفاقيات Next.js 13+ App Router من أجل تطوير ومصادقة مبسطين."},"useCases":{"en":["Bootstrapping modern web apps with built-in authentication","Generating well-structured Next.js projects with Supabase integration","Streamlining development with pre-configured App Router and authentication features"],"zh":["使用内置身份验证快速构建现代Web应用程序","生成结构良好的Next.js项目并集成Supabase","使用预配置的App Router和身份验证功能简化开发"],"ja":["内蔵認証を使用してモダンなWebアプリケーションを迅速に構築する","Next.jsプロジェクトを構造化してSupabaseと統合する","事前設定されたApp Routerと認証機能を使用して開発を簡素化する"],"ko":["내장 인증을 사용하여 현대적인 웹 애플리케이션을 빠르게 구축하는 것","Next.js 프로젝트를 잘 구조화하여 Supabase와 통합하는 것","사전 구성된 App Router 및 인증 기능을 사용하여 개발을 간소화하는 것"],"es":["Inicialización de aplicaciones web modernas con autenticación integrada","Generación de proyectos Next.js bien estructurados con integración de Supabase","Optimización del desarrollo con características de enrutador de aplicaciones y autenticación preconfiguradas"],"fr":["Initialisation d''applications web modernes avec authentification intégrée","Génération de projets Next.js bien structurés avec intégration de Supabase","Optimisation du développement avec des fonctionnalités de routeur d''applications et d''authentification préconfigurées"],"de":["Initialisierung moderner Webanwendungen mit integrierter Authentifizierung","Generierung gut strukturierter Next.js-Projekte mit Supabase-Integration","Optimierung der Entwicklung mit vorab konfigurierten App-Router- und Authentifizierungsfunktionen"],"pt":["Inicialização de aplicativos web modernos com autenticação incorporada","Geração de projetos Next.js bem estruturados com integração Supabase","Otimização do desenvolvimento com recursos de App Router e autenticação pré-configurados"],"ru":["Запуск современных веб-приложений с встроенной аутентификацией","Генерация хорошо структурированных проектов Next.js с интеграцией Supabase","Упрощение разработки с помощью предварительно настроенных функций App Router и аутентификации"],"ar":["تشغيل تطبيقات الويب الحديثة مع المصادقة المدمجة","توليد مشاريع Next.js هيكلية جيدة مع دمج Supabase","تبسيط التطوير باستخدام ميزات App Router والمصادقة مسبقًا التعيين"]},"limitations":{"en":["Requires Next.js 13+ for App Router compatibility","Specifically designed for Supabase as the backend service"],"zh":["需要Next.js 13+才能与App Router兼容","专门为Supabase作为后端服务而设计"],"ja":["App Routerとの互換性を確保するためにNext.js 13+が必要","Supabaseをバックエンドサービスとして使用するように特別に設計"],"ko":["App Router와의 호환성을 보장하기 위해 Next.js 13+가 필요함","Supabase를 백엔드 서비스로 사용하도록 특별히 설계됨"],"es":["Requiere Next.js 13+ para la compatibilidad del enrutador de aplicaciones","Diseñado específicamente para Supabase como servicio de backend"],"fr":["Nécessite Next.js 13+ pour la compatibilité du routeur d''applications","Conçu spécifiquement pour Supabase en tant que service de backend"],"de":["Benötigt Next.js 13+ für die Kompatibilität des App-Routers","Speziell für Supabase als Backend-Service konzipiert"],"pt":["Exige Next.js 13+ para compatibilidade com App Router","Especificamente projetado para Supabase como serviço de backend"],"ru":["Требует Next.js 13+ для совместимости с App Router","Специально разработан для Supabase в качестве сервиса бэкенда"],"ar":["يتطلب Next.js 13+ لتوافق مع App Router","صمّم خصيصًا لـ Supabase كخدمة خلفية"]},"version":4},"contentHash":"186bd8d7f200369aad117c71fe99434dd4e2eead43efe73ac808947cd7c9335a","qualityScore":45}');
