INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('natalialewis/CS4610-Supabase-NextJS-Starter-App/nextjs-supabase-starter', 'nextjs-supabase-starter', 'natalialewis', 'CS4610-Supabase-NextJS-Starter-App', 'community', 'nextjs-supabase-starter natalialewis CS4610-Supabase-NextJS-Starter-App community The nextjs-supabase-starter skill provides a foundation for building modern web apps with authentication using Next.js and Supabase. It benefits developers looking for a well-documented and easy-to-set-up starter app. Next.js + Supabase Starter 应用是一个现代化的 Web 应用模板，包含身份验证和最新的 Next.js 13+ App Router 约定 Next.js + Supabase スターター アプリは、認証と最新の Next.js 13+ App Router 規約を含むモダンな Web アプリ テンプレートです Next.js + Supabase 스타터 앱은 인증과 최신 Next.js 13+ App Router 규칙을 포함하는 현대적인 웹 애플리케이션 템플릿입니다 La aplicación de inicio de Next.js y Supabase ofrece una base sólida para aplicaciones web modernas con autenticación L''application de démarrage Next.js et Supabase fournit une base solide pour les applications web modernes avec authentification Die Next.js- und Supabase-Starter-App bietet eine solide Basis für moderne Webanwendungen mit Authentifizierung O nextjs-supabase-starter é uma ferramenta para criar aplicações web modernas com autenticação nextjs-supabase-starter - это инструмент для создания современных веб-приложений с аутентификацией nextjs-supabase-starter هي أداة لإنشاء تطبيقات ويب حديثة مع مصادقة how to use nextjs-supabase-starter nextjs-supabase-starter setup guide nextjs-supabase-starter vs nextjs-prisma-starter nextjs-supabase-starter install what is nextjs-supabase-starter nextjs-supabase-starter alternative nextjs-supabase-starter tutorial nextjs-supabase-starter documentation nextjs-supabase-starter example Next.js Supabase starter 应用 现代化 Web 应用 身份验证 App Router AIエージェント 设置指南 Uses the latest Next.js version with App Router conventions Follows Next.js 13+ App Router conventions for routing Utilizes the `app/` directory for App Router implementation Includes essential features for modern web apps with authentication Requires clear and consistent naming for routes, components, and hooks Must be well-documented and easy to set up nextjs-supabase-starter is a starter app that combines Next.js with Supabase for building modern web applications with authentication, following Next.js 13+ App Router conventions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('armanisadeghi/ai-matrx-admin/modern-web-design-expert', 'community', 'armanisadeghi', 'ai-matrx-admin', 'armanisadeghi/ai-matrx-admin', 'modern-web-design-expert', 0, 0, 45, '2026-03-08T01:57:15.589Z', '2026-03-08T02:12:00.626Z', '11a620fee8ced807bb403e5dd5fcd75de3a6e0d8605b32a7cceec63c34e876d0', '{"id":"armanisadeghi/ai-matrx-admin/modern-web-design-expert","name":"modern-web-design-expert","description":{"en":"The modern-web-design-expert skill extends Next.js best practices, covering project-specific migration and styling architecture. It benefits developers working with Next.js and Tailwind.","zh":"现代网页设计专家技能提供Next.js和Tailwind设计系统的最佳实践指南","ja":"モダンウェブデザインエキスパートスキルは、Next.jsとTailwind設計システムのベストプラクティスガイドを提供する","ko":"모던 웹 디자인 전문가 스킬은 Next.js 및 Tailwind 디자인 시스템의 베스트 프랙티스 가이드를 제공합니다","es":"El experto en diseño web moderno proporciona una guía de configuración para implementar las mejores prácticas de diseño web con Next.js y Tailwind","fr":"L''expert en conception web moderne fournit un guide de configuration pour mettre en œuvre les meilleures pratiques de conception web avec Next.js et Tailwind","de":"Der Experte für modernes Webdesign bietet einen Einrichtungsleitfaden, um die besten Praktiken für Webdesign mit Next.js und Tailwind umzusetzen","pt":"O Modern Web Design Expert é um guia de configuração para projetos Next.js com Tailwind","ru":"ИИ Агент Modern Web Design Expert - это руководство по настройке для проектов Next.js с Tailwind","ar":"خبير تصميم الويب الحديث هو دليل إعداد لمشاريع Next.js مع Tailwind"},"seo":{"title":{"en":"modern-web-design-expert: Next.js Best Practices Setup Gu...","zh":"现代网页设计专家设置指南 - AI工具","ja":"モダンウェブデザインエキスパートの設定ガイド - AIエージェント","ko":"모던 웹 디자인 전문가 설정 가이드 - AI 에이전트","es":"Experto en Diseño Web Moderno: Guía de Configuración","fr":"Expert en Conception Web Moderne: Guide de Mise en Place","de":"Experte für Modernes Webdesign: Einrichtungsleitfaden","pt":"Guia de Configuração do Modern Web Design Expert","ru":"Настройка ИИ Агента Modern Web Design Expert","ar":"دليل إعداد خبير تصميم الويب الحديث"},"description":{"en":"Unlock efficient web design with modern-web-design-expert. Explore Next.js best practices, Tailwind design-system, and component contracts for AI agents.","zh":"了解现代网页设计专家的最佳实践，包括Next.js和Tailwind设计系统的集成","ja":"モダンウェブデザインエキスパートのベストプラクティスを学び、Next.jsとTailwind設計システムの統合を実現する","ko":"모던 웹 디자인 전문가의 베스트 프랙티스를 학습하고 Next.js 및 Tailwind 디자인 시스템의 통합을 달성하세요","es":"Aprende a implementar las mejores prácticas de diseño web moderno con nuestra guía de configuración para expertos en diseño web","fr":"Découvrez comment mettre en œuvre les meilleures pratiques de conception web moderne avec notre guide de configuration pour les experts en conception web","de":"Erfahren Sie, wie Sie die besten Praktiken für modernes Webdesign mit unserem Einrichtungsleitfaden für Webdesign-Experten umsetzen","pt":"Aprenda a configurar o Modern Web Design Expert com as melhores práticas do Next.js e Tailwind","ru":"Узнайте, как настроить ИИ Агента Modern Web Design Expert с лучшими практиками Next.js и Tailwind","ar":"تعلم كيفية إعداد خبير تصميم الويب الحديث مع أفضل الممارسات في Next.js و Tailwind"},"definition":{"en":"modern-web-design-expert is a skill that provides guidance on Next.js best practices, including styling architecture and component contracts, for efficient web design.","zh":"现代网页设计专家是一种AI工具，提供Next.js和Tailwind设计系统的最佳实践指南","ja":"モダンウェブデザインエキスパートは、Next.jsとTailwind設計システムのベストプラクティスガイドを提供するAIエージェントの一種","ko":"모던 웹 디자인 전문가는 Next.js 및 Tailwind 디자인 시스템의 베스트 프랙티스 가이드를 제공하는 AI 에이전트의 일종입니다","es":"Un experto en diseño web moderno es un agente de inteligencia artificial que ayuda a implementar las mejores prácticas de diseño web","fr":"Un expert en conception web moderne est un agent d''intelligence artificielle qui aide à mettre en œuvre les meilleures pratiques de conception web","de":"Ein Experte für modernes Webdesign ist ein KI-Tool, das hilft, die besten Praktiken für Webdesign umzusetzen","pt":"O que é Modern Web Design Expert? Um guia de configuração para projetos Next.js","ru":"Что такое ИИ Агент Modern Web Design Expert? Руководство по настройке для проектов Next.js","ar":"ما هو خبير تصميم الويب الحديث؟ دليل إعداد لمشاريع Next.js"},"features":{"en":["Extends official Next.js best practices guide","Covers project-specific migration state and priorities","Implements Tailwind design-system mandate","References §13 of Next.js guide for styling architecture","Supports dedicated guide for component contracts and accessibility"],"zh":["Next.js最佳实践指南","Tailwind设计系统集成","项目特定迁移状态和优先级","组件合约和无障碍支持","官方Next.js最佳实践指南扩展"],"ja":["Next.jsベストプラクティスガイド","Tailwind設計システムの統合","プロジェクト特有の移行状態と優先順位","コンポーネント契約とアクセシビリティ対応","公式Next.jsベストプラクティスガイドの拡張"],"ko":["Next.js 베스트 프랙티스 가이드","Tailwind 디자인 시스템 통합","프로젝트 특정 마이그레이션 상태 및 우선순위","컴포넌트 계약 및 접근성 지원","공식 Next.js 베스트 프랙티스 가이드 확장"],"es":["Implementación de las mejores prácticas de diseño web con Next.js","Uso de Tailwind para una arquitectura de estilos robusta","Migración de proyectos a la última versión de Next.js","Mejora de la accesibilidad y el cumplimiento de los estándares web","Optimización del rendimiento y la velocidad de carga de la página"],"fr":["Mise en œuvre des meilleures pratiques de conception web avec Next.js","Utilisation de Tailwind pour une architecture de styles robuste","Migration de projets vers la dernière version de Next.js","Amélioration de l''accessibilité et du respect des normes web","Optimisation des performances et de la vitesse de chargement de la page"],"de":["Umsetzung der besten Praktiken für Webdesign mit Next.js","Verwendung von Tailwind für eine robuste Stilarchitektur","Migration von Projekten auf die neueste Version von Next.js","Verbesserung der Barrierefreiheit und der Einhaltung von Webstandards","Optimierung der Leistung und Ladezeit der Seite"],"pt":["Integração com Next.js","Suporte a Tailwind","Melhores práticas de estilização","Arquitetura de componentes","Acessibilidade e contratos de componentes"],"ru":["Интеграция с Next.js","Поддержка Tailwind","Лучшие практики стилизации","Архитектура компонентов","Доступность и контракты компонентов"],"ar":["التكامل مع Next.js","دعم Tailwind","أفضل الممارسات لتصميم الواجهة","هندسة المكونات","إمكانية الوصول وعقود المكونات"]},"keywords":{"en":["how to use modern-web-design-expert","modern-web-design-expert vs Next.js","modern-web-design-expert setup guide","what is modern-web-design-expert","modern-web-design-expert alternative","modern-web-design-expert install","Next.js best practices","Tailwind design-system","component contracts"],"zh":["现代网页设计","Next.js最佳实践","Tailwind设计系统","AI工具","网页设计专家","项目迁移","组件合约","无障碍支持"],"ja":["モダンウェブデザイン","Next.jsベストプラクティス","Tailwind設計システム","AIエージェント","ウェブデザインエキスパート","プロジェクト移行","コンポーネント契約","アクセシビリティ対応"],"ko":["모던 웹 디자인","Next.js 베스트 프랙티스","Tailwind 디자인 시스템","AI 에이전트","웹 디자인 전문가","프로젝트 마이그레이션","컴포넌트 계약","접근성 지원"],"es":["diseño web moderno","Next.js","Tailwind","mejores prácticas de diseño web","migración de proyectos","accesibilidad web","optimización de rendimiento","herramientas de inteligencia artificial para diseño web"],"fr":["conception web moderne","Next.js","Tailwind","meilleures pratiques de conception web","migration de projets","accessibilité web","optimisation des performances","outils d''intelligence artificielle pour la conception web"],"de":["modernes Webdesign","Next.js","Tailwind","beste Praktiken für Webdesign","Migration von Projekten","Barrierefreiheit im Web","Leistungsoptimierung","KI-Tools für Webdesign"],"pt":["modern web design expert","nextjs best practices","tailwind design system","estilização de componentes","acessibilidade em nextjs","guias de configuração nextjs"],"ru":["ИИ Агент modern web design expert","лучшие практики nextjs","система дизайна tailwind","стилизация компонентов","доступность в nextjs","руководства по настройке nextjs"],"ar":["خبير تصميم الويب الحديث","أفضل الممارسات في nextjs","نظام تصميم tailwind","تصميم مكونات","إمكانية الوصول في nextjs","دلائل إعداد nextjs"]}},"owner":"armanisadeghi","repo":"ai-matrx-admin","repoPath":"armanisadeghi/ai-matrx-admin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.589Z","topics":[],"category":"community","skillMd":{"name":"modern-web-design-expert","description":"Project-specific web design patterns for AI Matrx Admin. Extends the global modern-web-design-expert skill with project state, migration priorities, and local conventions. Use when working on UI components, styles, or responsive layouts in this project.","bodyPreview":"# Modern Web Design Expert — AI Matrx Admin\n\n> **Official guide:** `~/.arman/rules/nextjs-best-practices/nextjs-guide.md` — §13 (Styling Architecture) covers the Tailwind design-system mandate. The old §15 (Component Contracts & Accessibility) was removed and will get a dedicated guide. This skill covers project-specific migration state and priorities.\n\nThis skill extends the **official Next.js best practices guide**. Read that first for best practices. This document covers:\n\n1. What AI Matrx Ad","body":"# Modern Web Design Expert — AI Matrx Admin\n\n> **Official guide:** `~/.arman/rules/nextjs-best-practices/nextjs-guide.md` — §13 (Styling Architecture) covers the Tailwind design-system mandate. The old §15 (Component Contracts & Accessibility) was removed and will get a dedicated guide. This skill covers project-specific migration state and priorities.\n\nThis skill extends the **official Next.js best practices guide**. Read that first for best practices. This document covers:\n\n1. What AI Matrx Admin already does correctly\n2. What needs migration to best practices\n3. Project-specific conventions\n\n> **📱 For mobile-specific guidelines:** See `.cursor/skills/ios-mobile-first/SKILL.md`\n> \n> The ios-mobile-first skill covers viewport units, safe areas, touch targets, responsive patterns, and iOS-native UX. Use that skill for all mobile layout and interaction work.\n\n---\n\n## Project Context\n\n**Type:** Admin dashboard / B2B tool  \n**Responsive Strategy:** Desktop-first, mobile-responsive  \n**Stack:** Next.js 16 + React 19 + Tailwind CSS 4.1 + shadcn/ui + Framer Motion\n\n---\n\n## ✅ Already Aligned with Best Practices\n\n| Pattern | Status | Location |\n|---------|--------|----------|\n| Tailwind v4 with `@theme inline` | ✅ Correct | `app/globals.css` |\n| Design tokens (`--primary`, `--secondary`) | ✅ Correct | `app/globals.css` |\n| Dark mode via `.dark` class | ✅ Correct | `@custom-variant dark` |\n| `h-dvh`, `min-h-dvh`, `max-h-dvh` | ✅ Correct | Custom utilities in globals |\n| Safe area insets (`pb-safe`, `env()`) | ✅ Correct | Custom utilities in globals |\n| Lucide React icons exclusively | ✅ Correct | Project rule enforced |\n| 16px+ input font size | ✅ Correct | `1.0625rem` in base styles |\n| `next-themes` for dark mode | ✅ Correct | Installed and configured |\n\n---\n\n## 🔄 Migration Required — New Code Must Use Best Practices\n\n### 1. Typography: Fixed Tokens → Fluid `clamp()`\n\n**Current (Legacy):**\n```css\n/* Fixed font size tokens in globals.css */\n--font-size-2xs: 0.6rem;\n--font-size-xs: 0.8rem;\n--font-size-sm: 0.85rem;\n/* ... etc */\n```\n\n**Best Practice:**\n```css\n/* Fluid typography with clamp() */\nh1 { font-size: clamp(2rem, 1.5rem + 2vw, 3.5rem); }\nh2 { font-size: clamp(1.5rem, 1.25rem + 1.5vw, 2.5rem); }\nbody { font-size: clamp(1rem, 0.95rem + 0.25vw, 1.125rem); }\n```\n\n**Action:**\n- **New code:** Use `clamp()` for all typography via Tailwind arbitrary values\n- **Migration priority:** Medium — can migrate incrementally per component\n- **Example:** `text-[clamp(1rem,0.9rem+0.5vw,1.25rem)]`\n\n---\n\n### 2. Animations: Framer Motion Heavy → CSS-First\n\n**Current (Legacy):**\n- Heavy use of Framer Motion (`motion` package) for all animations\n- Animation presets in `componentConfig.ts` files\n- `AnimatePresence` for entrance/exit animations\n\n**Best Practice:**\n- CSS `@starting-style` for entrance animations\n- CSS `transition` for hover/focus effects\n- Framer Motion only for gesture-based or complex orchestration\n\n**Action:**\n- **New code:** Use CSS `@starting-style` for entrance animations\n- **Migration priority:** Low — existing Framer Motion works fine, optimize new code\n- **When to use Framer Motion:** Drag gestures, physics-based springs, staggered lists with complex timing\n\n---\n\n### 3. Container Queries: Minimal → Expand Usage\n\n**Current:**\n- Only 2 files use `@container`:\n  - `app/entities/forms/EntityFormStandard.tsx`\n  - `app/(authenticated)/demo/component-demo/container-queries/page.tsx`\n\n**Best Practice:**\n- All reusable components should use container queries\n- Cards, profile components, widgets should respond to container, not viewport\n\n**Action:**\n- **New code:** Use `@container` for all reusable components\n- **Migration priority:** Medium — improves component reusability\n- **Pattern:** `<div className=\"@container\"><div className=\"@md:flex-row\">...</div></div>`\n\n---\n\n### 4. Component Wrappers: Raw shadcn/ui → Custom Wrappers\n\n**Current:**\n- Mix of raw shadcn/ui components and some custom wrappers\n- Custom wrappers exist (e.g., `FloatingSheet`) but not systematic\n\n**Best Practice:**\n- Every shadcn/ui primitive should have a project wrapper\n- Wrappers enforce consistency and include common logic\n\n**Action:**\n- **New code:** Create custom wrappers before using any new shadcn/ui component\n- **Migration priority:** High — improves consistency across app\n- **Location:** `components/ui/app-*.tsx` (e.g., `app-dialog.tsx`, `app-sheet.tsx`)\n\n**Audit needed:** Check `components/ui/` for which primitives need wrappers.\n\n---\n\n### 5. Entrance Animations: JS-Triggered → `@starting-style`\n\n**Current:**\n- Many components use JS/Framer Motion to trigger entrance animations\n- Class toggling or `AnimatePresence` for fade-ins\n\n**Best Practice:**\n```tsx\n<div className=\"\n  opacity-100 translate-y-0\n  transition-all duration-300\n  [@starting-style]:opacity-0 \n  [@starting-style]:translate-y-4\n\">\n```\n\n**Action:**\n- **New code:** Use `@starting-style` for all entrance animations\n- **Migration priority:** Low — existing animations work, optimize new code\n\n---\n\n## 📍 Project-Specific Conventions\n\n### Header Height\n\n```css\n--header-height: 2.5rem; /* 40px - unified for mobile and desktop */\n```\n\n**Full-height pattern:**\n```tsx\n<div className=\"h-[calc(100dvh-var(--header-height))] flex flex-col overflow-hidden\">\n```\n\n### Textured Backgrounds\n\nThis project uses subtle texture overlays:\n\n```tsx\n<div className=\"bg-textured\">      {/* Main page backgrounds */}\n<div className=\"bg-card\">          {/* Card backgrounds with card-texture */}\n```\n\n### Scrollbar Styling\n\nCustom thin scrollbars are defined globally:\n\n```css\n--scrollbar-track: /* defined per theme */\n--scrollbar-thumb: /* defined per theme */\n```\n\nUse `.scrollbar-hide` or `.scrollbar-thin` utilities.\n\n### Animation Presets (Framer Motion)\n\nWhen Framer Motion is appropriate, use existing presets:\n\n- Location: `components/matrx/Entity/prewired-components/quick-reference/componentConfig.ts`\n- Presets: `none`, `subtle`, `smooth`, `energetic`, `playful`\n\n### Layout Components\n\n- `ResponsiveLayout`: Switches between desktop/mobile layouts at 1024px\n- `AdaptiveLayout`: Multi-panel layout with canvas support\n- `FloatingSheet`: Multi-position sheet component (right, left, top, bottom, center)\n\n---\n\n## 📁 Key Files Reference\n\n| Purpose | Location |\n|---------|----------|\n| Design tokens & utilities | `app/globals.css` |\n| Base card component | `components/ui/card.tsx` |\n| Sheet component | `components/official/FloatingSheet.tsx` |\n| Responsive layout | `components/layout/new-layout/ResponsiveLayout.tsx` |\n| Mobile detection hook | `hooks/use-mobile.tsx` |\n| Animation presets | `components/matrx/Entity/prewired-components/quick-reference/componentConfig.ts` |\n\n---\n\n## 🚨 Migration Priorities Summary\n\n| Item | Priority | Approach |\n|------|----------|----------|\n| Custom component wrappers | **High** | Create wrappers before using new shadcn/ui components |\n| Fluid typography | **Medium** | Use `clamp()` in new code, migrate existing incrementally |\n| Container queries | **Medium** | Use `@container` in new reusable components |\n| CSS entrance animations | **Low** | Use `@starting-style` in new code |\n| Framer Motion reduction | **Low** | Keep existing, use CSS for new simple animations |\n\n---\n\n## Quick Reference: New Code Standards\n\nWhen writing new UI code in this project:\n\n```tsx\n// ✅ DO: Fluid typography\n<h1 className=\"text-[clamp(2rem,1.5rem+2vw,3.5rem)]\">\n\n// ✅ DO: Container queries for reusable components\n<div className=\"@container\">\n  <div className=\"flex flex-col @md:flex-row\">\n\n// ✅ DO: CSS entrance animations\n<div className=\"[@starting-style]:opacity-0 [@starting-style]:translate-y-4 transition-all\">\n\n// ✅ DO: Custom wrapper components\nimport { AppDialog } from \"@/components/ui/app-dialog\";\n\n// ❌ DON''T: Fixed font sizes with breakpoints\n<h1 className=\"text-2xl md:text-3xl lg:text-4xl\">\n\n// ❌ DON''T: Raw shadcn/ui without wrapper\nimport { Dialog } from \"@/components/ui/dialog\"; // Use AppDialog instead\n\n// ❌ DON''T: Framer Motion for simple entrance animations\n<motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}> // Use @starting-style\n```\n"},"lastSynced":"2026-03-08T02:12:00.626Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced Next.js and Tailwind CSS styling architecture expertise.","zh":"非常适合需要高级 Next.js 和 Tailwind CSS 样式架构专业知识的前端代理。","ja":"Next.js と Tailwind CSS の高度なスタイリング アーキテクチャの専門知識が必要なフロントエンド エージェントに最適です。","ko":"고급 Next.js와 Tailwind CSS 스타일링 아키텍처 전문 지식이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes de frontend que necesitan experiencia avanzada en arquitectura de estilo Next.js y Tailwind CSS.","fr":"Parfait pour les agents de frontend qui ont besoin d''une expertise avancée en architecture de style Next.js et Tailwind CSS.","de":"Perfekt für Frontend-Agents, die Expertenwissen in Next.js- und Tailwind-CSS-Stilarchitektur benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de expertise avançada em arquitetura de estilo Next.js e Tailwind CSS.","ru":"Идеально для агентов Frontend, которым необходимы продвинутые знания архитектуры стиля Next.js и Tailwind CSS.","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى خبرة متقدمة في بنية النمط Next.js و Tailwind CSS."},"recommendation":{"en":"Empowers agents to extend Next.js best practices, covering project-specific migration and styling architecture using Tailwind CSS, enabling seamless integration with modern web design principles and efficient management of component contracts and accessibility.","zh":"赋予代理扩展 Next.js 最佳实践的能力，涵盖特定项目的迁移和使用 Tailwind CSS 的样式架构，实现与现代 Web 设计原则的无缝集成，并高效管理组件契约和可访问性。","ja":"Next.js のベストプラクティスを拡張するエージェントの能力を提供し、特定のプロジェクトの移行と Tailwind CSS を使用したスタイリング アーキテクチャをカバーし、モダンな Web 設計原則とのシームレスな統合とコンポーネント契約およびアクセシビリティの効率的な管理を可能にします。","ko":"Next.js의 최선의实践을 확장할 수 있는 에이전트의 능력을 제공하여, 특정 프로젝트의 마이그레이션과 Tailwind CSS를 사용한 스타일링 아키텍처를 다루며, 현대적인 웹 디자인 원칙과 컴포넌트 계약 및 접근성의 효율적인 관리를 가능하게 하는 무결한 통합을 제공합니다.","es":"Habilita a los agentes a ampliar las mejores prácticas de Next.js, cubriendo la migración y la arquitectura de estilo específicas del proyecto utilizando Tailwind CSS, lo que permite una integración sin problemas con los principios de diseño web modernos y una gestión eficiente de los contratos de componentes y la accesibilidad.","fr":"Permet aux agents d''étendre les meilleures pratiques de Next.js, en couvrant la migration et l''architecture de style spécifiques au projet en utilisant Tailwind CSS, permettant ainsi une intégration transparente avec les principes de conception web modernes et une gestion efficace des contrats de composants et de l''accessibilité.","de":"Ermöglicht es Agenten, die besten Praktiken von Next.js zu erweitern, indem es die projektspezifische Migration und Stilarchitektur unter Verwendung von Tailwind CSS abdeckt, was eine nahtlose Integration mit modernen Webdesign-Prinzipien und eine effiziente Verwaltung von Komponentenverträgen und Zugänglichkeit ermöglicht.","pt":"Habilita os agentes a estender as melhores práticas do Next.js, cobrindo a migração e a arquitetura de estilo específicas do projeto usando Tailwind CSS, permitindo uma integração perfeita com os princípios de design web modernos e um gerenciamento eficiente de contratos de componentes e acessibilidade.","ru":"Наделяет агентов возможностью расширить лучшие практики Next.js, покрывая миграцию и архитектуру стиля, специфичную для проекта, используя Tailwind CSS, что позволяет обеспечить бесшовную интеграцию с современными принципами веб-дизайна и эффективное управление контрактами компонентов и доступностью.","ar":"تمكين الوكلاء من扩展 أفضل الممارسات ل Next.js، وغلاف هجرة مشروع معماري نمط محدد باستخدام Tailwind CSS، وتمكين التكامل السلس مع مبادئ تصميم الويب الحديثة وإدارة كفاءة عقود المكونات والوصول."},"useCases":{"en":["Migrating legacy projects to Next.js with optimized styling","Implementing Tailwind CSS design-system mandates for consistent UI","Debugging accessibility issues in Next.js applications"],"zh":["将遗留项目迁移到 Next.js 并优化样式","实施 Tailwind CSS 设计系统指令以实现一致的 UI","调试 Next.js 应用程序中的可访问性问题"],"ja":["Next.js へのレガシープロジェクトの移行を最適化されたスタイリングで実行する","一貫した UI を実現するための Tailwind CSS デザインシステムのマンドを実施する","Next.js アプリケーションのアクセシビリティの問題をデバッグする"],"ko":["최적화된 스타일링으로 레거시 프로젝트를 Next.js로 마이그레이션하는 것","일관된 UI를 구현하기 위한 Tailwind CSS 디자인 시스템 지시를 구현하는 것","Next.js 애플리케이션의 접근성 문제를 디버깅하는 것"],"es":["Migrar proyectos heredados a Next.js con estilo optimizado","Implementar mandatos de diseño de sistema Tailwind CSS para una UI coherente","Depurar problemas de accesibilidad en aplicaciones Next.js"],"fr":["Migrer des projets hérités vers Next.js avec un style optimisé","Mettre en œuvre des mandats de conception de système Tailwind CSS pour une IU cohérente","Déboguer les problèmes d''accessibilité dans les applications Next.js"],"de":["Legacy-Projekte mit optimiertem Stil auf Next.js migrieren","Tailwind-CSS-Designsystem-Vorgaben für eine konsistente Benutzeroberfläche implementieren","Zugänglichkeitsprobleme in Next.js-Anwendungen debuggen"],"pt":["Migrar projetos legados para Next.js com estilização otimizada","Implementar mandatos de design-system do Tailwind CSS para UI consistente","Depurar problemas de acessibilidade em aplicações Next.js"],"ru":["Мигрировать устаревшие проекты в Next.js с оптимизированной стилизацией","Реализовывать директивы дизайн-системы Tailwind CSS для последовательного UI","Отлаживать проблемы доступности в приложениях Next.js"],"ar":["هجرة مشاريع تراثية إلى Next.js مع تحسين التنسيق","تنفيذ أوامر نظام التصميم من Tailwind CSS لويف معماري متسق","تصحيح أخطاء في مشاكل الوصول في تطبيقات Next.js"]},"limitations":{"en":["Requires knowledge of Next.js and Tailwind CSS","Limited to projects using Next.js and Tailwind CSS"],"zh":["需要 Next.js 和 Tailwind CSS 的知识","仅限于使用 Next.js 和 Tailwind CSS 的项目"],"ja":["Next.js と Tailwind CSS の知識が必要","Next.js と Tailwind CSS を使用するプロジェクトに限定される"],"ko":["Next.js와 Tailwind CSS에 대한 지식이 필요함","Next.js와 Tailwind CSS를 사용하는 프로젝트에만 제한됨"],"es":["Requiere conocimiento de Next.js y Tailwind CSS","Limitado a proyectos que utilizan Next.js y Tailwind CSS"],"fr":["Nécessite des connaissances en Next.js et Tailwind CSS","Limité aux projets utilisant Next.js et Tailwind CSS"],"de":["Benötigt Kenntnisse von Next.js und Tailwind CSS","Begrenzt auf Projekte, die Next.js und Tailwind CSS verwenden"],"pt":["Requer conhecimento de Next.js e Tailwind CSS","Limitado a projetos que utilizam Next.js e Tailwind CSS"],"ru":["Требует знаний Next.js и Tailwind CSS","Ограничен проектами, использующими Next.js и Tailwind CSS"],"ar":["يتطلب معرفة Next.js و Tailwind CSS","محدود بمشاريع تستخدم Next.js و Tailwind CSS"]},"version":4},"contentHash":"11a620fee8ced807bb403e5dd5fcd75de3a6e0d8605b32a7cceec63c34e876d0","qualityScore":45}');
