INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('armanisadeghi/ai-matrx-admin/modern-web-design-expert', 'modern-web-design-expert', 'armanisadeghi', 'ai-matrx-admin', 'community', 'modern-web-design-expert armanisadeghi ai-matrx-admin community The modern-web-design-expert skill extends Next.js best practices, covering project-specific migration and styling architecture. It benefits developers working with Next.js and Tailwind. 现代网页设计专家技能提供Next.js和Tailwind设计系统的最佳实践指南 モダンウェブデザインエキスパートスキルは、Next.jsとTailwind設計システムのベストプラクティスガイドを提供する 모던 웹 디자인 전문가 스킬은 Next.js 및 Tailwind 디자인 시스템의 베스트 프랙티스 가이드를 제공합니다 El experto en diseño web moderno proporciona una guía de configuración para implementar las mejores prácticas de diseño web con Next.js y Tailwind L''expert en conception web moderne fournit un guide de configuration pour mettre en œuvre les meilleures pratiques de conception web avec Next.js et Tailwind Der Experte für modernes Webdesign bietet einen Einrichtungsleitfaden, um die besten Praktiken für Webdesign mit Next.js und Tailwind umzusetzen O Modern Web Design Expert é um guia de configuração para projetos Next.js com Tailwind ИИ Агент Modern Web Design Expert - это руководство по настройке для проектов Next.js с Tailwind خبير تصميم الويب الحديث هو دليل إعداد لمشاريع Next.js مع Tailwind how to use modern-web-design-expert modern-web-design-expert vs Next.js modern-web-design-expert setup guide what is modern-web-design-expert modern-web-design-expert alternative modern-web-design-expert install Next.js best practices Tailwind design-system component contracts 现代网页设计 Next.js最佳实践 Tailwind设计系统 AI工具 网页设计专家 项目迁移 组件合约 无障碍支持 Extends official Next.js best practices guide Covers project-specific migration state and priorities Implements Tailwind design-system mandate References §13 of Next.js guide for styling architecture Supports dedicated guide for component contracts and accessibility modern-web-design-expert is a skill that provides guidance on Next.js best practices, including styling architecture and component contracts, for efficient web design.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kousaku-maron/astro-cloudflare-example/better-auth-best-practices', 'community', 'kousaku-maron', 'astro-cloudflare-example', 'kousaku-maron/astro-cloudflare-example', 'better-auth-best-practices', 0, 0, 45, '2026-03-08T01:57:15.599Z', '2026-03-08T02:12:33.565Z', 'd67a75a83202355fe76e2db21775cce12e4948189c7b51106989e824bb1da43c', '{"id":"kousaku-maron/astro-cloudflare-example/better-auth-best-practices","name":"better-auth-best-practices","description":{"en":"better-auth-best-practices is a TypeScript-first auth framework supporting multiple authentication methods. It benefits developers by providing a framework-agnostic solution for secure authentication.","zh":"Better Auth 是一个 TypeScript 第一、框架无关的认证框架，支持电子邮件/密码、OAuth、魔术链接、密钥等认证方式","ja":"Better Auth は、TypeScript 最初のフレームワーク非依存の認証フレームワークで、メール/パスワード、OAuth、魔術リンク、パスキーなどの認証方法をサポートします","ko":"Better Auth는 TypeScript 첫 번째 프레임워크 비의존 인증 프레임워크로, 이메일/암호, OAuth, 매직 링크, 패스키 등 인증 방식을 지원합니다","es":"Better Auth es un framework de autenticación de TypeScript que admite autenticación por correo electrónico/contraseña, OAuth, enlaces mágicos y más","fr":"Better Auth est un framework d''authentification TypeScript qui prend en charge l''authentification par e-mail/mot de passe, OAuth, liens magiques et plus","de":"Better Auth ist ein Authentifizierungsframework von TypeScript, das die Authentifizierung per E-Mail/Paswort, OAuth, Magische Links und mehr unterstützt","pt":"Better Auth é uma estrutura de autenticação TypeScript-first e framework-agnostic que suporta email/senha, OAuth, links mágicos, passkeys e mais via plugins.","ru":"Better Auth — это фреймворк-агностичная аутентификационная платформа, поддерживающая электронную почту/пароль, OAuth, магические ссылки, парольные ключи и многое другое через плагины.","ar":"Better Auth هو إطار أمان TypeScript-first و framework-agnostic يدعم البريد الإلكتروني / كلمة المرور، OAuth، الروابط السحرية، مفاتيح المرور وغيرها من خلال الإضافات."},"seo":{"title":{"en":"better-auth-best-practices: Authentication Setup Guide | ...","zh":"Better Auth 最佳实践设置指南","ja":"Better Auth ベストプラクティス設定ガイド - AIエージェント","ko":"Better Auth 최적 설정 가이드 - AI 도구","es":"Guía de configuración de Better Auth: Mejores prácticas d...","fr":"Guide de configuration de Better Auth : Meilleures pratiq...","de":"Better Auth-Konfigurationsleitfaden: Best Practices für A...","pt":"Melhores Práticas de Autenticação com Better Auth: Guia d...","ru":"Лучшие практики аутентификации с Better Auth: Руководство...","ar":"أفضل الممارسات لأمان أفضل مع Better Auth: دليل الإعداد لل..."},"description":{"en":"Unlock secure authentication with better-auth-best-practices. Learn how to integrate email/password, OAuth, and more with our expert guide. Get started now!","zh":"了解 Better Auth 的最佳实践，包括环境变量、加密和插件配置，实现安全高效的认证系统","ja":"Better Auth のベストプラクティスを学び、環境変数、暗号化、プラグイン設定をマスターして、セキュアで効率的な認証システムを構築しましょう - AIエージェント","ko":"Better Auth의 최적 설정을 통해 환경 변수, 암호화, 플러그인 구성 등 보안 높은 인증 시스템을 구축하는 방법을 알아보세요 - AI 도구","es":"Aprende a configurar Better Auth con nuestras mejores prácticas de autenticación para una integración segura y eficiente","fr":"Découvrez comment configurer Better Auth avec nos meilleures pratiques d''authentification pour une intégration sécurisée et efficace","de":"Erfahren Sie, wie Sie Better Auth mit unseren Best Practices für Authentifizierung konfigurieren, um eine sichere und effiziente Integration zu gewährleisten","pt":"Aprenda a configurar a autenticação com Better Auth, uma estrutura de autenticação TypeScript-first e framework-agnostic. Consulte nosso guia para obter os m...","ru":"Узнайте, как настроить аутентификацию с Better Auth, TypeScript-first и фреймворк-агностичной аутентификационной платформой. Читайте наше руководство для ИИ ...","ar":"تعلم كيفية تكوين أمان أفضل مع Better Auth، إطار أمان TypeScript-first و framework-agnostic. استشر دليلنا للحصول على أفضل النتائج للآي إجينتس."},"definition":{"en":"better-auth-best-practices is a TypeScript-first, framework-agnostic auth framework supporting email/password, OAuth, magic links, passkeys, and more via plugins.","zh":"Better Auth 是一个认证框架，提供安全高效的认证解决方案","ja":"Better Auth は、セキュアで効率的な認証ソリューションを提供する認証フレームワークです","ko":"Better Auth는 보안 높은 인증 솔루션을 제공하는 인증 프레임워크입니다","es":"Better Auth es un framework de autenticación que proporciona una integración segura y eficiente para aplicaciones web","fr":"Better Auth est un framework d''authentification qui propose une intégration sécurisée et efficace pour les applications web","de":"Better Auth ist ein Authentifizierungsframework, das eine sichere und effiziente Integration für Webanwendungen bietet","pt":"Better Auth é uma estrutura de autenticação que fornece recursos de autenticação seguros e escaláveis para aplicações web.","ru":"Better Auth — это аутентификационная платформа, обеспечивающая безопасные и масштабируемые функции аутентификации для веб-приложений.","ar":"Better Auth هو إطار أمان يوفر ميزات أمان وتأكيد هويّة مُتقدّمة ومُوسّعة لاتّصال التّطبيقات الويب."},"features":{"en":["Supports email/password authentication","Provides OAuth integration via plugins","Enables magic links and passkeys for secure authentication","Requires environment variables such as BETTER_AUTH_SECRET and BETTER_AUTH_URL","Utilizes OpenSSL for generating encryption secrets","Offers a quick reference guide for easy setup"],"zh":["支持电子邮件/密码、OAuth、魔术链接、密钥等认证方式","环境变量配置，包括 BETTER_AUTH_SECRET 和 BETTER_AUTH_URL","插件架构，支持扩展和自定义认证逻辑","TypeScript 第一开发，确保代码质量和可维护性","框架无关，支持多种开发框架和库"],"ja":["メール/パスワード、OAuth、魔術リンク、パスキーなどの認証方法をサポート","環境変数設定、BETTER_AUTH_SECRET と BETTER_AUTH_URL を含む","プラグインアーキテクチャ、認証ロジックの拡張とカスタマイズをサポート","TypeScript 最初の開発、コード品質とメンテナンス性を確保","フレームワーク非依存、多種の開発フレームワークとライブラリをサポート"],"ko":["이메일/암호, OAuth, 매직 링크, 패스키 등 인증 방식을 지원","환경 변수 설정, BETTER_AUTH_SECRET 및 BETTER_AUTH_URL 포함","플러그인 아키텍처, 인증 로직 확장 및 커스터마이징 지원","TypeScript 첫 번째 개발, 코드 품질 및 유지 보수성을 보장","프레임워크 비의존, 다양한 개발 프레임워크 및 라이브러리 지원"],"es":["Soporte para autenticación por correo electrónico/contraseña","Compatibilidad con OAuth y enlaces mágicos","Uso de plugins para ampliar la funcionalidad","Requerimiento de variable de entorno BETTER_AUTH_SECRET para cifrado","Requerimiento de variable de entorno BETTER_AUTH_URL para la URL base"],"fr":["Prise en charge de l''authentification par e-mail/mot de passe","Compatibilité avec OAuth et les liens magiques","Utilisation de plugins pour étendre la fonctionnalité","Exigence de la variable d''environnement BETTER_AUTH_SECRET pour le chiffrement","Exigence de la variable d''environnement BETTER_AUTH_URL pour l''URL de base"],"de":["Unterstützung für Authentifizierung per E-Mail/Paswort","Kompatibilität mit OAuth und Magischen Links","Verwendung von Plugins, um die Funktionalität zu erweitern","Anforderung der Umgebungsvariable BETTER_AUTH_SECRET für Verschlüsselung","Anforderung der Umgebungsvariable BETTER_AUTH_URL für die Basis-URL"],"pt":["Suporte a email/senha, OAuth, links mágicos e passkeys","Estrutura TypeScript-first e framework-agnostic","Plugins para extensão de funcionalidades","Suporte a variáveis de ambiente para configuração","Recursos de criptografia para segurança"],"ru":["Поддержка электронной почты/пароля, OAuth, магических ссылок и парольных ключей","Фреймворк-агностичная платформа с поддержкой TypeScript","Плагины для расширения функциональности","Поддержка переменных окружения для конфигурации","Возможности шифрования для обеспечения безопасности"],"ar":["دعم البريد الإلكتروني / كلمة المرور، OAuth، الروابط السحرية، مفاتيح المرور","إطار أمان TypeScript-first و framework-agnostic","الإضافات لتوسيع الوظائف","دعم متغيرات البيئة لضبط التكوين","ميزات التشفير لتأمين البيانات"]},"keywords":{"en":["how to use better-auth-best-practices","better-auth-best-practices setup guide","better-auth-best-practices alternative","better-auth-best-practices vs auth0","better-auth-best-practices install","what is better-auth-best-practices","better-auth-best-practices tutorial","better-auth-best-practices documentation","better-auth-best-practices examples"],"zh":["Better Auth","认证框架","TypeScript","OAuth","魔术链接","密钥","环境变量","插件架构","AIエージェント","认证解决方案"],"ja":["Better Auth","認証フレームワーク","TypeScript","OAuth","魔術リンク","パスキー","環境変数","プラグインアーキテクチャ","AIエージェント","認証ソリューション"],"ko":["Better Auth","인증 프레임워크","TypeScript","OAuth","매직 링크","패스키","환경 변수","플러그인 아키텍처","AI 도구","인증 솔루션"],"es":["autenticación de TypeScript","mejores prácticas de autenticación","integración de Better Auth","configuración de Better Auth","seguridad de aplicaciones web","autenticación por correo electrónico/contraseña","OAuth","enlaces mágicos"],"fr":["authentification TypeScript","meilleures pratiques d''authentification","intégration de Better Auth","configuration de Better Auth","sécurité des applications web","authentification par e-mail/mot de passe","OAuth","liens magiques"],"de":["Authentifizierung von TypeScript","Best Practices für Authentifizierung","Integration von Better Auth","Konfiguration von Better Auth","Sicherheit von Webanwendungen","Authentifizierung per E-Mail/Paswort","OAuth","Magische Links"],"pt":["autenticação melhor","guias de configuração de autenticação","melhores práticas de autenticação","recursos de autenticação seguros","estruturas de autenticação escaláveis","plugins de autenticação","variáveis de ambiente de autenticação"],"ru":["лучшие практики аутентификации","руководство по настройке аутентификации","безопасные функции аутентификации","масштабируемые аутентификационные платформы","плагины аутентификации","переменные окружения для аутентификации","ИИ Агенты для аутентификации"],"ar":["أفضل الممارسات لأمان أفضل","دلائل الإعداد لأمان أفضل","ميزات أمان وتأكيد هويّة مُتقدّمة","منصات تأكيد هويّة مُوسّعة","إضافات تأكيد هويّة","متغيرات البيئة لأمان أفضل","الآي إجينتس لأمان أفضل"]}},"owner":"kousaku-maron","repo":"astro-cloudflare-example","repoPath":"kousaku-maron/astro-cloudflare-example","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.599Z","topics":[],"category":"community","skillMd":{"name":"better-auth-best-practices","description":"Skill for integrating Better Auth - the comprehensive TypeScript authentication framework.","bodyPreview":"# Better Auth Integration Guide\n\n**Always consult [better-auth.com/docs](https://better-auth.com/docs) for code examples and latest API.**\n\nBetter Auth is a TypeScript-first, framework-agnostic auth framework supporting email/password, OAuth, magic links, passkeys, and more via plugins.\n\n---\n\n## Quick Reference\n\n### Environment Variables\n- `BETTER_AUTH_SECRET` - Encryption secret (min 32 chars). Generate: `openssl rand -base64 32`\n- `BETTER_AUTH_URL` - Base URL (e.g., `https://example.com`)\n\nOnl","body":"# Better Auth Integration Guide\n\n**Always consult [better-auth.com/docs](https://better-auth.com/docs) for code examples and latest API.**\n\nBetter Auth is a TypeScript-first, framework-agnostic auth framework supporting email/password, OAuth, magic links, passkeys, and more via plugins.\n\n---\n\n## Quick Reference\n\n### Environment Variables\n- `BETTER_AUTH_SECRET` - Encryption secret (min 32 chars). Generate: `openssl rand -base64 32`\n- `BETTER_AUTH_URL` - Base URL (e.g., `https://example.com`)\n\nOnly define `baseURL`/`secret` in config if env vars are NOT set.\n\n### File Location\nCLI looks for `auth.ts` in: `./`, `./lib`, `./utils`, or under `./src`. Use `--config` for custom path.\n\n### CLI Commands\n- `npx @better-auth/cli@latest migrate` - Apply schema (built-in adapter)\n- `npx @better-auth/cli@latest generate` - Generate schema for Prisma/Drizzle\n- `npx @better-auth/cli mcp --cursor` - Add MCP to AI tools\n\n**Re-run after adding/changing plugins.**\n\n---\n\n## Core Config Options\n\n| Option | Notes |\n|--------|-------|\n| `appName` | Optional display name |\n| `baseURL` | Only if `BETTER_AUTH_URL` not set |\n| `basePath` | Default `/api/auth`. Set `/` for root. |\n| `secret` | Only if `BETTER_AUTH_SECRET` not set |\n| `database` | Required for most features. See adapters docs. |\n| `secondaryStorage` | Redis/KV for sessions & rate limits |\n| `emailAndPassword` | `{ enabled: true }` to activate |\n| `socialProviders` | `{ google: { clientId, clientSecret }, ... }` |\n| `plugins` | Array of plugins |\n| `trustedOrigins` | CSRF whitelist |\n\n---\n\n## Database\n\n**Direct connections:** Pass `pg.Pool`, `mysql2` pool, `better-sqlite3`, or `bun:sqlite` instance.\n\n**ORM adapters:** Import from `better-auth/adapters/drizzle`, `better-auth/adapters/prisma`, `better-auth/adapters/mongodb`.\n\n**Critical:** Better Auth uses adapter model names, NOT underlying table names. If Prisma model is `User` mapping to table `users`, use `modelName: \"user\"` (Prisma reference), not `\"users\"`.\n\n---\n\n## Session Management\n\n**Storage priority:**\n1. If `secondaryStorage` defined → sessions go there (not DB)\n2. Set `session.storeSessionInDatabase: true` to also persist to DB\n3. No database + `cookieCache` → fully stateless mode\n\n**Cookie cache strategies:**\n- `compact` (default) - Base64url + HMAC. Smallest.\n- `jwt` - Standard JWT. Readable but signed.\n- `jwe` - Encrypted. Maximum security.\n\n**Key options:** `session.expiresIn` (default 7 days), `session.updateAge` (refresh interval), `session.cookieCache.maxAge`, `session.cookieCache.version` (change to invalidate all sessions).\n\n---\n\n## User & Account Config\n\n**User:** `user.modelName`, `user.fields` (column mapping), `user.additionalFields`, `user.changeEmail.enabled` (disabled by default), `user.deleteUser.enabled` (disabled by default).\n\n**Account:** `account.modelName`, `account.accountLinking.enabled`, `account.storeAccountCookie` (for stateless OAuth).\n\n**Required for registration:** `email` and `name` fields.\n\n---\n\n## Email Flows\n\n- `emailVerification.sendVerificationEmail` - Must be defined for verification to work\n- `emailVerification.sendOnSignUp` / `sendOnSignIn` - Auto-send triggers\n- `emailAndPassword.sendResetPassword` - Password reset email handler\n\n---\n\n## Security\n\n**In `advanced`:**\n- `useSecureCookies` - Force HTTPS cookies\n- `disableCSRFCheck` - ⚠️ Security risk\n- `disableOriginCheck` - ⚠️ Security risk  \n- `crossSubDomainCookies.enabled` - Share cookies across subdomains\n- `ipAddress.ipAddressHeaders` - Custom IP headers for proxies\n- `database.generateId` - Custom ID generation or `\"serial\"`/`\"uuid\"`/`false`\n\n**Rate limiting:** `rateLimit.enabled`, `rateLimit.window`, `rateLimit.max`, `rateLimit.storage` (\"memory\" | \"database\" | \"secondary-storage\").\n\n---\n\n## Hooks\n\n**Endpoint hooks:** `hooks.before` / `hooks.after` - Array of `{ matcher, handler }`. Use `createAuthMiddleware`. Access `ctx.path`, `ctx.context.returned` (after), `ctx.context.session`.\n\n**Database hooks:** `databaseHooks.user.create.before/after`, same for `session`, `account`. Useful for adding default values or post-creation actions.\n\n**Hook context (`ctx.context`):** `session`, `secret`, `authCookies`, `password.hash()`/`verify()`, `adapter`, `internalAdapter`, `generateId()`, `tables`, `baseURL`.\n\n---\n\n## Plugins\n\n**Import from dedicated paths for tree-shaking:**\n```\nimport { twoFactor } from \"better-auth/plugins/two-factor\"\n```\nNOT `from \"better-auth/plugins\"`.\n\n**Popular plugins:** `twoFactor`, `organization`, `passkey`, `magicLink`, `emailOtp`, `username`, `phoneNumber`, `admin`, `apiKey`, `bearer`, `jwt`, `multiSession`, `sso`, `oauthProvider`, `oidcProvider`, `openAPI`, `genericOAuth`.\n\nClient plugins go in `createAuthClient({ plugins: [...] })`.\n\n---\n\n## Client\n\nImport from: `better-auth/client` (vanilla), `better-auth/react`, `better-auth/vue`, `better-auth/svelte`, `better-auth/solid`.\n\nKey methods: `signUp.email()`, `signIn.email()`, `signIn.social()`, `signOut()`, `useSession()`, `getSession()`, `revokeSession()`, `revokeSessions()`.\n\n---\n\n## Type Safety\n\nInfer types: `typeof auth.$Infer.Session`, `typeof auth.$Infer.Session.user`.\n\nFor separate client/server projects: `createAuthClient<typeof auth>()`.\n\n---\n\n## Common Gotchas\n\n1. **Model vs table name** - Config uses ORM model name, not DB table name\n2. **Plugin schema** - Re-run CLI after adding plugins\n3. **Secondary storage** - Sessions go there by default, not DB\n4. **Cookie cache** - Custom session fields NOT cached, always re-fetched\n5. **Stateless mode** - No DB = session in cookie only, logout on cache expiry\n6. **Change email flow** - Sends to current email first, then new email\n\n---\n\n## Resources\n\n- [Docs](https://better-auth.com/docs)\n- [Options Reference](https://better-auth.com/docs/reference/options)\n- [LLMs.txt](https://better-auth.com/llms.txt)\n- [GitHub](https://github.com/better-auth/better-auth)\n- [Init Options Source](https://github.com/better-auth/better-auth/blob/main/packages/core/src/types/init-options.ts)"},"lastSynced":"2026-03-08T02:12:33.565Z","agentAnalysis":{"suitability":{"en":"Perfect for Security-focused Agents needing framework-agnostic authentication solutions with support for multiple methods like email/password, OAuth, and passkeys.","zh":"非常适合需要框架无关的身份验证解决方案的安全专注代理，支持多种方法，如电子邮件/密码、OAuth 和密钥。","ja":"セキュリティに焦点を当てたエージェントが、フレームワーク非依存の認証ソリューションを必要とする場合に最適です。電子メール/パスワード、OAuth、パスキーなどの複数の方法をサポートします。","ko":"보안에 중점을 둔 에이전트에게 적합한 프레임워크 비의존적인 인증 솔루션을 제공하며, 이메일/비밀번호, OAuth, 패스키와 같은 여러 방법을 지원합니다.","es":"Perfecto para agentes de seguridad que necesitan soluciones de autenticación agnósticas al marco de trabajo con soporte para múltiples métodos como correo electrónico/contraseña, OAuth y passkeys.","fr":"Parfait pour les agents axés sur la sécurité qui ont besoin de solutions d''authentification indépendantes du framework avec une prise en charge de plusieurs méthodes comme e-mail/mot de passe, OAuth et passkeys.","de":"Perfekt für sicherheitsorientierte Agenten, die framework-agnostische Authentifizierungslösungen mit Unterstützung für mehrere Methoden wie E-Mail/Kennwort, OAuth und Passkeys benötigen.","pt":"Perfeito para Agentes focados em Segurança que necessitam de soluções de autenticação independentes de framework com suporte a vários métodos como email/senha, OAuth e passkeys.","ru":"Идеально для агентов, ориентированных на безопасность, которым необходимы решения аутентификации, независимые от фреймворка, с поддержкой нескольких методов, таких как email/пароль, OAuth и ключи.","ar":"مثالي للوكلاء المتأثرين بالأمان الذين يحتاجون إلى حلول التحقق من الهوية غير معتمدة على الإطار مع دعم العديد من الطرق مثل البريد الإلكتروني / كلمة المرور و OAuth والمفاتيح."},"recommendation":{"en":"Empowers agents to implement secure authentication using TypeScript-first auth framework, supporting plugins for various authentication methods, and providing a framework-agnostic solution via environment variables like BETTER_AUTH_SECRET and BETTER_AUTH_URL.","zh":"启用代理使用基于TypeScript的身份验证框架实现安全的身份验证，支持各种身份验证方法的插件，并通过环境变量（如BETTER_AUTH_SECRET和BETTER_AUTH_URL）提供框架无关的解决方案。","ja":"TypeScriptを使用した認証フレームワークを使用して、エージェントが安全な認証を実装できるようにします。さまざまな認証方法のプラグインをサポートし、環境変数（BETTER_AUTH_SECRETやBETTER_AUTH_URLなど）を使用してフレームワーク非依存のソリューションを提供します。","ko":"에이전트가 안전한 인증을 구현할 수 있도록 TypeScript를 기반으로 하는 인증 프레임워크를 사용합니다. 다양한 인증 방법의 플러그인을 지원하며, 환경 변수(BETTER_AUTH_SECRET 및 BETTER_AUTH_URL 등)를 통해 프레임워크 비의존적인 솔루션을 제공합니다.","es":"Habilita a los agentes a implementar una autenticación segura utilizando un framework de autenticación de TypeScript, que admite plugins para varios métodos de autenticación y proporciona una solución agnóstica al marco de trabajo a través de variables de entorno como BETTER_AUTH_SECRET y BETTER_AUTH_URL.","fr":"Permet aux agents de mettre en œuvre une authentification sécurisée en utilisant un framework d''authentification basé sur TypeScript, prenant en charge des plugins pour diverses méthodes d''authentification et fournissant une solution indépendante du framework via des variables d''environnement comme BETTER_AUTH_SECRET et BETTER_AUTH_URL.","de":"Ermächtigt Agenten, eine sichere Authentifizierung mithilfe eines TypeScript-Authentifizierungsframeworks umzusetzen, das Plugins für verschiedene Authentifizierungsmethoden unterstützt und eine framework-agnostische Lösung über Umgebungsvariablen wie BETTER_AUTH_SECRET und BETTER_AUTH_URL bereitstellt.","pt":"Habilita os agentes a implementar autenticação segura usando o framework de autenticação TypeScript-first, suportando plugins para vários métodos de autenticação e fornecendo uma solução independente de framework por meio de variáveis de ambiente como BETTER_AUTH_SECRET e BETTER_AUTH_URL.","ru":"Наделяет агентов возможностью реализовать безопасную аутентификацию с помощью фреймворка аутентификации TypeScript-first, поддерживающего плагины для различных методов аутентификации и предоставляющего решение, независимое от фреймворка, посредством переменных среды, таких как BETTER_AUTH_SECRET и BETTER_AUTH_URL.","ar":"يمنح الوكلاء القدرة على تنفيذ التحقق من الهوية الآمن باستخدام إطار التحقق من الهوية الأولي من النوع TypeScript، يدعم الإضافات لمختلف طرق التحقق من الهوية ويوفر حلًا مستقلًا عن الإطار من خلال متغيرات البيئة مثل BETTER_AUTH_SECRET و BETTER_AUTH_URL."},"useCases":{"en":["Implementing email/password authentication with encryption","Configuring OAuth for social media login integration","Generating magic links for passwordless login experiences"],"zh":["使用加密实现电子邮件/密码身份验证","配置OAuth以实现社交媒体登录集成","生成魔术链接以实现无密码登录体验"],"ja":["暗号化を使用した電子メール/パスワード認証の実装","OAuthの構成によるソーシャルメディアログイン統合","パスワードレスログイン体験のためのマジックリンクの生成"],"ko":["암호화를 사용한 이메일/비밀번호 인증 구현","OAuth를 구성하여 소셜 미디어 로그인 통합","패스워드 없는 로그인 경험을 위한 마법 링크 생성"],"es":["Implementar la autenticación por correo electrónico/contraseña con cifrado","Configurar OAuth para la integración de inicio de sesión en las redes sociales","Generar enlaces mágicos para experiencias de inicio de sesión sin contraseña"],"fr":["Mettre en œuvre l''authentification par e-mail/mot de passe avec chiffrement","Configurer OAuth pour l''intégration de connexion aux réseaux sociaux","Générer des liens magiques pour des expériences de connexion sans mot de passe"],"de":["Implementierung der E-Mail/Kennwort-Authentifizierung mit Verschlüsselung","Konfiguration von OAuth für die Integration von Social-Media-Login","Generierung von Magischen Links für passwortlose Login-Erfahrungen"],"pt":["Implementação de autenticação email/senha com criptografia","Configuração do OAuth para integração de login de mídia social","Geração de links mágicos para experiências de login sem senha"],"ru":["Реализация аутентификации email/пароль с шифрованием","Настройка OAuth для интеграции социальных сетей","Генерация магических ссылок для опыта входа без пароля"],"ar":["تنفيذ التحقق من الهوية البريد الإلكتروني / كلمة المرور مع التشفير","تكوين OAuth لدمج تسجيل الدخول إلى وسائل الإعلام الاجتماعية","генерация روابط سحرية لتجارب تسجيل الدخول بدون كلمة مرور"]},"limitations":{"en":["Requires TypeScript compatibility","Needs BETTER_AUTH_SECRET and BETTER_AUTH_URL environment variables setup"],"zh":["需要TypeScript兼容性","需要设置BETTER_AUTH_SECRET和BETTER_AUTH_URL环境变量"],"ja":["TypeScriptの互換性が必要","BETTER_AUTH_SECRETとBETTER_AUTH_URL環境変数の設定が必要"],"ko":["TypeScript 호환성이 필요함","BETTER_AUTH_SECRET 및 BETTER_AUTH_URL 환경 변수 설정이 필요"],"es":["Requiere compatibilidad con TypeScript","Necesita la configuración de las variables de entorno BETTER_AUTH_SECRET y BETTER_AUTH_URL"],"fr":["Nécessite la compatibilité avec TypeScript","Nécessite la configuration des variables d''environnement BETTER_AUTH_SECRET et BETTER_AUTH_URL"],"de":["Benötigt TypeScript-Kompatibilität","Benötigt die Einrichtung der Umgebungsvariablen BETTER_AUTH_SECRET und BETTER_AUTH_URL"],"pt":["Exige compatibilidade com TypeScript","Necessita de configuração das variáveis de ambiente BETTER_AUTH_SECRET e BETTER_AUTH_URL"],"ru":["Требует совместимости с TypeScript","Требует настройки переменных среды BETTER_AUTH_SECRET и BETTER_AUTH_URL"],"ar":["يتطلب توافقًا مع TypeScript","يحتاج إلى إعداد متغيرات البيئة BETTER_AUTH_SECRET و BETTER_AUTH_URL"]},"version":4},"contentHash":"d67a75a83202355fe76e2db21775cce12e4948189c7b51106989e824bb1da43c","qualityScore":45}');
