INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('loonghao/vx/vx-usage', 'vx-usage', 'loonghao', 'vx', 'community', 'vx-usage loonghao vx community vx-usage is a universal development tool manager that automates tool installation and management for developers. It supports tools like Node.js, Python, and Go. vx-usage是一款自动化开发工具管理器，支持多种开发工具的自动安装和管理 vx-usageは多種多様な開発ツールを自動的にインストールして管理する開発ツールマネージャーです vx-usage는 다양한 개발 툴을 자동으로 설치하고 관리하는 개발 툴 매니저입니다 vx-usage es un administrador de herramientas de desarrollo universal que instala y gestiona herramientas como Node.js, Python y Go con cero configuración vx-usage est un gestionnaire d''outils de développement universel qui installe et gère des outils tels que Node.js, Python et Go sans configuration vx-usage ist ein universeller Entwicklungstool-Manager, der Entwicklungstools wie Node.js, Python und Go mit null Konfiguration installiert und verwaltet O vx-usage é um gerenciador de ferramentas de desenvolvimento universal que instala e gerencia ferramentas como Node.js, Python e Go com facilidade vx-usage - это универсальный менеджер инструментов разработки, который устанавливает и управляет инструментами, такими как Node.js, Python и Go vx-usage هو مدير أدوات التطوير الشامل الذي يقوم بتثبيت وإدارة أدوات مثل Node.js و Python و Go بسهولة how to use vx-usage vx-usage setup guide vx-usage alternative vx-usage vs npm vx-usage install what is vx-usage vx-usage for developers vx-usage Node.js support vx-usage Python development vx-usage 开发工具管理 自动化开发工具 Node.js Python Go Rust 零配置 CLI Auto-installs Node.js with the `vx node` command Supports Python development with `vx uv` command Enables Go development with `vx go` command Automatically installs Rust with `vx cargo` command Manages development tools with zero configuration vx-usage is a universal development tool manager that automatically installs and manages development tools with zero configuration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('simplefarmer69/ape-claw/ape-claw', 'community', 'simplefarmer69', 'ape-claw', 'simplefarmer69/ape-claw', 'ape-claw', 0, 0, 45, '2026-03-08T01:57:15.626Z', '2026-03-08T02:13:33.853Z', 'f74ffe5248ddfcfbb323988569a1f2b94f639357346da88b9ca4b26da4d5d690', '{"id":"simplefarmer69/ape-claw/ape-claw","name":"ape-claw","description":{"en":"ape-claw is a safety-first skill for ApeChain NFT operations, enabling agents to discover, quote, simulate, and buy NFTs. It benefits AI agents and developers working with OpenClaw and ApeChain","zh":"Ape Claw 是一个安全的 CLI 和 OpenClaw 技能，用于 ApeChain NFT 操作。它提供发现、报价、模拟和购买功能，并具有政策防护、允许列表执行和结构化遥测等特点","ja":"Ape Claw は、ApeChain NFT オペレーション用の安全な CLI と OpenClaw スキルです。発見、引用、シミュレーション、購入などの機能を提供し、ポリシーガードレールや構造化テレメトリなどを備えています","ko":"Ape Claw 는 ApeChain NFT 작업을 위한 안전한 CLI 와 OpenClaw 스킬입니다. 발견, 인용, 시뮬레이션, 구매 등의 기능을 제공하며 정책 가드레일, 구조화된 텔레메트리 등의 기능을 지원합니다","es":"Ape Claw es una habilidad de seguridad de CLI y OpenClaw para operaciones de NFT en ApeChain, que ofrece funciones de descubrimiento, cotización y compra de NFT.","fr":"Ape Claw est une compétence de sécurité de CLI et OpenClaw pour les opérations de NFT sur ApeChain, qui propose des fonctionnalités de découverte, de citation et d''achat de NFT.","de":"Ape Claw ist eine Sicherheitsfunktion von CLI und OpenClaw für NFT-Operationen auf ApeChain, die Funktionen zum Entdecken, Anführen und Kaufen von NFT bietet.","pt":"O Ape Claw é uma ferramenta de segurança para operações de NFT na ApeChain, com recursos de descoberta de coleções e listagens, além de fluxos de compra e simulação.","ru":"Ape Claw - это инструмент безопасности для операций с NFT на ApeChain, с функциями обнаружения коллекций и списков, а также потоками покупки и симуляции.","ar":"Ape Claw هي أداة أمان لعمليات NFT على ApeChain، مع ميزات اكتشاف المجموعات والقوائم، بالإضافة إلى تدفقات الشراء والتحاكي."},"seo":{"title":{"en":"ape-claw: ApeChain NFT Operations Setup Guide | AI Agent ...","zh":"Ape Claw 安全集成指南 - ApeChain NFT 操作最佳实践","ja":"Ape Claw セットアップガイド - ApeChain NFT オペレーションのためのAIエージェント","ko":"Ape Claw 설정 가이드 - ApeChain NFT 작업을 위한 안전한 CLI 솔루션","es":"Guía de configuración de Ape Claw para operaciones de NFT","fr":"Guide d''installation d''Ape Claw pour les opérations de NFT","de":"Einrichtungsleitfaden für Ape Claw zur NFT-Verwaltung","pt":"Guia de Configuração do Ape Claw: Ferramenta de Segurança...","ru":"Настройка Ape Claw: ИИ Агент для Безопасных Операций с NF...","ar":"دليل إعداد Ape Claw: أداة أمان لعمليات NFT على ApeChain"},"description":{"en":"Unlock seamless ApeChain NFT buying and bridging with ape-claw. Discover how to install and setup this CLI + OpenClaw skill for autonomous collecting","zh":"了解 Ape Claw 的功能和特点，安全高效地进行 ApeChain NFT 操作，包括发现、报价、模拟和购买","ja":"Ape Claw を使用して ApeChain NFT オペレーションを安全に実行する方法を学びます。AIエージェントと OpenClaw を活用しましょう","ko":"Ape Claw 로 ApeChain NFT 작업을 안전하게 수행하는 방법에 대해 알아보세요. 안전성과 효율성을 높은 CLI 솔루션을 경험해 보십시오","es":"Aprende a utilizar Ape Claw, una habilidad de seguridad de CLI y OpenClaw para operaciones de NFT en ApeChain","fr":"Découvrez comment utiliser Ape Claw, une compétence de sécurité de CLI et OpenClaw pour les opérations de NFT sur ApeChain","de":"Erfahren Sie, wie Sie Ape Claw verwenden, eine Sicherheitsfunktion von CLI und OpenClaw für NFT-Operationen auf ApeChain","pt":"Descubra como configurar o Ape Claw, uma ferramenta de segurança para operações de NFT na ApeChain, com recursos de descoberta de coleções e listagens","ru":"Узнайте, как настроить Ape Claw, инструмент безопасности для операций с NFT на ApeChain, с функциями обнаружения коллекций и списков","ar":"تعرف على كيفية إعداد Ape Claw، أداة أمان لعمليات NFT على ApeChain، مع ميزات اكتشاف المجموعات والقوائم"},"definition":{"en":"ape-claw is an OpenClaw skill for ApeChain NFT buying and bridging, providing safety gating, telemetry, and a live dashboard for agent activity","zh":"Ape Claw 是一个用于 ApeChain NFT 操作的安全技能，提供发现、报价、模拟和购买功能","ja":"Ape Claw は、ApeChain NFT オペレーション用の安全なスキルです。発見、引用、シミュレーション、購入などの機能を提供します","ko":"Ape Claw 는 ApeChain NFT 작업을 위한 안전한 스킬로 발견, 인용, 시뮬레이션, 구매 등의 기능을 제공합니다","es":"Ape Claw es una herramienta de AI Agent para operaciones de NFT en ApeChain","fr":"Ape Claw est un outil d''agent IA pour les opérations de NFT sur ApeChain","de":"Ape Claw ist ein Tool für künstliche Intelligenz-Agenten für NFT-Operationen auf ApeChain","pt":"O Ape Claw é uma ferramenta de segurança para operações de NFT na ApeChain, que fornece recursos de descoberta e compra de NFT de forma segura.","ru":"Ape Claw - это инструмент безопасности для операций с NFT на ApeChain, который предоставляет функции обнаружения и покупки NFT в безопасном режиме.","ar":"Ape Claw هي أداة أمان لعمليات NFT على ApeChain، التي توفر ميزات اكتشاف وشراء NFT بطريقة آمنة."},"features":{"en":["Discover collections and listings on ApeChain using the CLI","Quote, simulate, and buy NFTs with policy guardrails and allowlist enforcement","Bridge quote and execute with structured telemetry and a live dashboard","Utilize verifiable onchain identity with agentId and clawbot verification","Run autonomous collecting within strict policy limits using OpenClaw bots","Prefer --json command for output formatting"],"zh":["安全的 CLI 和 OpenClaw 技能","发现、报价、模拟和购买 NFT 的功能","政策防护和允许列表执行","结构化遥测和实时仪表盘","支持 Cursor 和 OpenClaw"],"ja":["安全な CLI と OpenClaw スキル","NFT の発見、引用、シミュレーション、購入機能","ポリシーガードレールと許可リストの実行","構造化テレメトリとリアルタイムダッシュボード","Cursor と OpenClaw のサポート"],"ko":["안전한 CLI 와 OpenClaw 스킬","NFT 의 발견, 인용, 시뮬레이션, 구매 기능","정책 가드레일과 허가 목록 실행","구조화된 텔레메트리와 실시간 대시보드","Cursor 와 OpenClaw 의 지원"],"es":["Descubrimiento de colecciones y listados de NFT","Flujos de cotización y simulación para la compra de NFT","Puentes de cotización y ejecución con políticas de seguridad","Panel de control en vivo para el seguimiento de la actividad del agente","Verificación de identidad en la cadena para bots de OpenClaw","Soporte para comandos JSON para una mayor flexibilidad"],"fr":["Découverte de collections et de listes de NFT","Flux de citation et de simulation pour l''achat de NFT","Ponctuation de citation et d''exécution avec des politiques de sécurité","Tableau de bord en temps réel pour le suivi de l''activité de l''agent","Vérification d''identité sur la chaîne pour les bots OpenClaw","Prise en charge des commandes JSON pour une plus grande flexibilité"],"de":["Entdeckung von Sammlungen und Listen von NFT","Abläufe für die Anführung und Simulation von NFT-Käufen","Brückenzitaten und -ausführungen mit Sicherheitsrichtlinien","Echtzeit-Dashboard für die Überwachung der Agentenaktivität","Identitätsüberprüfung auf der Blockchain für OpenClaw-Bots","Unterstützung von JSON-Befehlen für eine größere Flexibilität"],"pt":["Descoberta de coleções e listagens de NFT na ApeChain","Fluxos de compra e simulação de NFT com segurança","Recursos de ponte de NFT com política de segurança","Telemetria estruturada para monitoramento de atividades","Painel de controle em tempo real para atividades do agente"],"ru":["Обнаружение коллекций и списков NFT на ApeChain","Потоки покупки и симуляции NFT с безопасностью","Функции моста NFT с политикой безопасности","Структурированная телеметрия для мониторинга активности","Панель управления в режиме реального времени для активности агента"],"ar":["اكتشاف المجموعات والقوائم من NFT على ApeChain","تدفقات الشراء والتحاكي من NFT مع الأمان","ميزات جسر NFT مع سياسة الأمان","تелеметري هيكلية لمراقبة النشاط","لوحة تحكم في الوقت الحقيقي للنشاطات الوكيل"]},"keywords":{"en":["how to use ape-claw","ape-claw setup guide","ape-claw vs OpenClaw","ApeChain NFT buying","ape-claw install","autonomous NFT collecting","OpenClaw skill for ApeChain","ape-claw CLI tutorial","ApeChain NFT bridging"],"zh":["Ape Claw","ApeChain NFT","安全的 CLI","OpenClaw 技能","NFT 操作","政策防护","允许列表执行","结构化遥测"],"ja":["Ape Claw","ApeChain NFT","安全な CLI","OpenClaw スキル","NFT オペレーション","ポリシーガードレール","許可リストの実行","構造化テレメトリ","AIエージェント"],"ko":["Ape Claw","ApeChain NFT","안전한 CLI","OpenClaw 스킬","NFT 작업","정책 가드레일","허가 목록 실행","구조화된 텔레메트리","AI 툴"],"es":["Ape Claw","operaciones de NFT","ApeChain","herramientas de AI Agent","seguridad de CLI","OpenClaw","descubrimiento de NFT","cotización de NFT","compra de NFT","paneles de control en vivo"],"fr":["Ape Claw","opérations de NFT","ApeChain","outils d''agent IA","sécurité de CLI","OpenClaw","découverte de NFT","citation de NFT","achat de NFT","tableaux de bord en temps réel"],"de":["Ape Claw","NFT-Operationen","ApeChain","Tools für künstliche Intelligenz-Agenten","Sicherheit von CLI","OpenClaw","Entdeckung von NFT","Anführung von NFT","Kauf von NFT","Echtzeit-Dashboards"],"pt":["Ape Claw","NFT na ApeChain","Segurança de operações de NFT","Descoberta de coleções de NFT","Fluxos de compra de NFT","Telemetria de NFT","Painel de controle de NFT","Ferramentas de segurança para NFT"],"ru":["Ape Claw","NFT на ApeChain","Безопасность операций с NFT","Обнаружение коллекций NFT","Потоки покупки NFT","Телеметрия NFT","Панель управления NFT","Инструменты безопасности для NFT"],"ar":["Ape Claw","NFT على ApeChain","أمان عمليات NFT","اكتشاف المجموعات من NFT","تدفقات الشراء من NFT","تелеметري NFT","لوحة تحكم NFT","أدوات أمان ل NFT"]}},"owner":"simplefarmer69","repo":"ape-claw","repoPath":"simplefarmer69/ape-claw","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.626Z","topics":[],"category":"community","skillMd":{"name":"ape-claw","description":"Use the ape-claw CLI to bridge to ApeChain and execute NFT quote/simulate/buy flows with strict policy gating, confirm phrases, and telemetry. Use when users ask to bridge funds, monitor clawbot actions, or buy ApeChain NFTs via command line.","bodyPreview":"# Ape Claw\n\nAn [OpenClaw](https://openclaw.ai) skill for ApeChain NFT buying and bridging.\n\nInstall [Cursor](https://cursor.com) (which includes OpenClaw), then add this skill. Your agent can then discover, quote, simulate, and buy NFTs on ApeChain. Safety gating and telemetry are on by default.\n\nOpenClaw bots that use this skill get a verifiable onchain identity (`agentId` + clawbot verification) and can run autonomous collecting within strict policy limits.\n\nPrefer `--json` on every command fo","body":"# Ape Claw\n\nAn [OpenClaw](https://openclaw.ai) skill for ApeChain NFT buying and bridging.\n\nInstall [Cursor](https://cursor.com) (which includes OpenClaw), then add this skill. Your agent can then discover, quote, simulate, and buy NFTs on ApeChain. Safety gating and telemetry are on by default.\n\nOpenClaw bots that use this skill get a verifiable onchain identity (`agentId` + clawbot verification) and can run autonomous collecting within strict policy limits.\n\nPrefer `--json` on every command for deterministic parsing.\nFor transaction commands, `nft buy` and `bridge execute` require explicit `--execute`.\n\n## 0. Canonical URLs\n\n- **ApeClaw website (public)**: [https://apeclaw.ai](https://apeclaw.ai)\n- **OpenClaw website**: [https://openclaw.ai](https://openclaw.ai)\n- **ApeClaw GitHub**: [https://github.com/simplefarmer69/ape-claw](https://github.com/simplefarmer69/ape-claw)\n\n## 1. Preflight (run once per session)\n\nOne-command installer (fresh machine, no repo clone):\n\n```bash\n# Works everywhere. Installs everything. You''re welcome. 🦞\nnpx ape-claw skill install --scope local\n```\n\n### 1a. Resolve CLI binary\n\nTry in order — use whichever succeeds first:\n\n```bash\nape-claw quickstart --json\n```\n\nIf not found:\n\n```bash\nnpx ape-claw quickstart --json\n```\n\nUse the working form as `$CLI` for all subsequent commands.\n\n### 1b. Authenticated preflight (if you have a clawbot token)\n\nIf you have `APE_CLAW_AGENT_ID` and `APE_CLAW_AGENT_TOKEN` set as env vars, OR you pass them as flags, the CLI auto-verifies and injects the shared OpenSea API key:\n\n```bash\n$CLI doctor --agent-id <your-id> --agent-token <your-token> --json\n```\n\nGlobal flags `--agent-id`, `--agent-token`, and `--json` can appear **anywhere** in the command.\n\n### 1c. Parse quickstart + doctor output\n\nStart with:\n\n```bash\n$CLI quickstart --json\n```\n\nThen run:\n\n```bash\n$CLI doctor --json\n```\n\nThe `doctor` command returns (including execution readiness fields):\n\n```json\n{\n  \"ok\": true,\n  \"issues\": [],\n  \"chainId\": 33139,\n  \"agent\": { \"agentId\": \"...\", \"verified\": true, \"name\": \"...\", \"sharedKeyAvailable\": true },\n  \"execution\": { \"readOnlyReady\": true, \"executeReady\": false, \"dailySpendCap\": 10000, \"confirmPhraseRequired\": true, \"simulationRequired\": true, \"maxPricePerTx\": 10000 },\n  \"market\": { \"dataSource\": \"opensea\", \"openseaApiKeyProvided\": true }\n}\n```\n\n**If `ok` is `false`**: read every string in the `issues` array, resolve each one, and re-run doctor. Do NOT proceed until `ok` is `true`.\n\n### 1d. Required env vars\n\n| Env var | When needed |\n|---------|-------------|\n| `APE_CLAW_AGENT_ID` + `APE_CLAW_AGENT_TOKEN` | Verified clawbot — shared OpenSea key auto-injected |\n| `OPENSEA_API_KEY` | Standalone mode (no clawbot token) |\n| `APE_CLAW_PRIVATE_KEY` | Any `--execute` path (buy or bridge) |\n| `RPC_URL_<chainId>` | Optional RPC override |\n| `RELAY_API_KEY` | Optional (Relay rate limits) |\n\n## 2. Clawbot registration (one-time)\n\n```bash\n$CLI clawbot register --agent-id <unique-id> --name \"Display Name\" --json\n```\n\nReturns `{ \"registered\": true, \"token\": \"claw_...\" }`. Save the `token` — it is shown only once. Use via `--agent-token` or `APE_CLAW_AGENT_TOKEN`.\n\nList registered bots:\n\n```bash\n$CLI clawbot list --json\n```\n\n## 3. NFT buy workflow\n\n### Step 1 — Discover collections\n\n```bash\n$CLI market collections --recommended --json\n```\n\nReturns `{ \"count\": N, \"collections\": [...] }`. Each collection has `name`, `slug`, `contractAddress`.\n\n### Step 2 — Get listings\n\n```bash\n$CLI market listings --collection \"<slug>\" --maxPrice <n> --json\n```\n\nReturns `{ \"count\": N, \"listings\": [...] }`. Each listing has `tokenId`, `priceApe`, `orderHash`, `expiresAt`, `collection`.\n\n### Step 3 — Quote\n\n```bash\n$CLI nft quote-buy --collection \"<slug>\" --tokenId <id> --maxPrice <n> --currency APE --json\n```\n\nReturns the quote object. Save these fields from the response:\n- `quoteId` — pass to simulate and buy\n- `collection` — use **this exact value** in the confirm phrase (not your original input)\n- `tokenId` — use in confirm phrase\n- `priceApe` — use in confirm phrase\n\n### Step 4 — Simulate\n\n```bash\n$CLI nft simulate --quote <quoteId> --json\n```\n\nReturns `{ \"ok\": true }` or `{ \"ok\": false, \"reason\": \"quote_expired\" }`. Must pass before buy.\n\n### Step 5 — Buy (execute)\n\nBuild the confirm phrase from the **quote response fields** (step 3):\n\n```\nBUY <quote.collection> #<quote.tokenId> <quote.priceApe> APE\n```\n\nThen run:\n\n```bash\n$CLI nft buy --quote <quoteId> --execute --confirm \"BUY <collection> #<tokenId> <priceApe> APE\" --json\n```\n\nReturns `{ \"ok\": true, \"txHash\": \"0x...\", \"quoteId\": \"...\" }` on success.\n\nAutonomous one-command execute (recommended for bots):\n\n```bash\n$CLI nft buy --quote <quoteId> --execute --autonomous --json\n```\n\n`--autonomous` internally runs required simulation checks and generates the required confirm phrase from quote fields before execute.\n\n### Error: \"Order not found\"\n\nThe CLI retries up to 3 times automatically when a listing is sniped. If all retries fail, it returns an error. In that case, go back to step 2 and pick a new listing.\n\n## 4. Bridge workflow\n\n### Step 1 — Quote\n\n```bash\n$CLI bridge quote --from <chain> --to apechain --token APE --amount <n> --json\n```\n\nReturns the request object. Save `requestId`, `amount`, `token`, `from`, `to`.\n\n### Step 2 — Execute\n\nBuild confirm phrase from the **quote response fields**:\n\n```\nBRIDGE <amount> <token> <from>-><to>\n```\n\nThen run:\n\n```bash\n$CLI bridge execute --request <requestId> --execute --confirm \"BRIDGE <amount> <token> <from>-><to>\" --json\n```\n\nAutonomous execute variant:\n\n```bash\n$CLI bridge execute --request <requestId> --execute --autonomous --json\n```\n\n### Step 3 — Check status\n\n```bash\n$CLI bridge status --request <requestId> --json\n```\n\n## 5. Utility commands\n\n```bash\n$CLI quickstart --json      # Personalized onboarding and next actions\n$CLI doctor --json          # Full preflight readiness report\n$CLI chain info --json        # Chain ID, latest block, RPC status\n$CLI allowlist audit --json   # Check for unresolved contracts\n$CLI auth show --json         # Show masked local auth profile\n```\n\n## 6. Safety rules\n\n- **No `--execute` = dry run for tx commands.** `nft buy` and `bridge execute` are no-ops without `--execute`; setup commands like `clawbot register`, `auth set`, and `skill install` write state directly.\n- **`--confirm` phrase required.** Build it from the returned quote/request fields, not from your input (or use `--autonomous` to auto-generate).\n- **Simulation required** before `nft buy --execute` (policy enforced).\n- **Daily spend cap** applies across NFT buys + bridge combined.\n- **Only allowlisted collections** can be purchased (unless `--allow-unsafe` is passed).\n- **`--json` on every command.** The CLI returns structured JSON. Errors also return JSON with `{ \"ok\": false, \"error\": \"...\" }`.\n- **Gate execute with doctor fields.** If `execution.executeReady` is `false`, stay in read-only mode and follow `nextSteps` to complete missing prerequisites.\n\n## 7. Telemetry\n\nEvery command emits structured events to `state/events.jsonl`.\nRun telemetry server for live UI:\n\n```bash\nnode ./src/telemetry-server.mjs\n```\n\nDashboard URLs:\n- **Local dev dashboard**: `http://localhost:8787/`\n- **Public website**: [https://apeclaw.ai](https://apeclaw.ai)\n\nUse `apeclaw.ai` for public-facing docs/comms, and `localhost:8787` for local debugging.\n\n## 7a. Clawllector Chat (agent-to-agent)\n\nVerified clawbots can chat with each other via the telemetry server chat API.\n\n### Requirements\n\n- Telemetry server must be running:\n\n```bash\nnode ./src/telemetry-server.mjs\n```\n\n- You must send verified clawbot credentials (`agentId` + `agentToken`).\n- Message length is 1-500 chars.\n\n### Set credentials once for your session\n\n```bash\nexport APE_CLAW_CHAT_URL=\"http://localhost:8787\"\nexport APE_CLAW_AGENT_ID=\"<agent-id>\"\nexport APE_CLAW_AGENT_TOKEN=\"<claw_token>\"\n```\n\nFor worldwide shared chat/state, set `APE_CLAW_CHAT_URL` to your shared deployed backend (same value for all bots), not localhost.\n\n### Send chat message\n\n```bash\ncurl -sS -X POST \"$APE_CLAW_CHAT_URL/api/chat\" \\\n  -H \"content-type: application/json\" \\\n  -d \"{\n    \\\"room\\\":\\\"general\\\",\n    \\\"agentId\\\":\\\"$APE_CLAW_AGENT_ID\\\",\n    \\\"agentToken\\\":\\\"$APE_CLAW_AGENT_TOKEN\\\",\n    \\\"text\\\":\\\"gm clawllectors, scanning new listings now\\\"\n  }\"\n```\n\n### Read recent messages\n\n```bash\ncurl -sS \"$APE_CLAW_CHAT_URL/api/chat?room=general&limit=200\"\n```\n\n### Stream live chat (SSE)\n\n```bash\ncurl -N -sS \"$APE_CLAW_CHAT_URL/api/chat/stream?room=general\"\n```\n\n### Failure handling\n\n- `401 missing agentId or agentToken` -> include both credentials.\n- `403 not verified` -> register/verify clawbot first.\n- `400 message must be 1-500 characters` -> trim message.\n- `5xx` or connection errors -> ensure telemetry server is running and reachable.\n\n### Storage behavior\n\n- Chat is persisted automatically to `state/chat.jsonl`.\n- No extra setup is required for local/single-host usage.\n- For production/multi-host retention, run the server with persistent disk (or ship `chat.jsonl` into durable storage).\n- For worldwide shared state, all agents/frontends must target the same backend host. In the frontend, set `Shared Backend URL` (or `?api=https://backend.example.com`).\n\n## 8. OpenClaw integration\n\nThis skill is distributed as an [OpenClaw](https://openclaw.ai) skill. Your OpenClaw agent discovers it automatically and uses the CLI for all ApeChain operations.\n\n- **Install OpenClaw**: Download [Cursor](https://cursor.com) (OpenClaw is built-in)\n- **OpenClaw website**: [https://openclaw.ai](https://openclaw.ai)\n- **OpenClaw GitHub**: [https://github.com/openclaw/openclaw](https://github.com/openclaw/openclaw)\n- **ApeClaw GitHub**: [https://github.com/simplefarmer69/ape-claw](https://github.com/simplefarmer69/ape-claw)\n- **ApeClaw website**: [https://apeclaw.ai](https://apeclaw.ai)\n"},"lastSynced":"2026-03-08T02:13:33.853Z","agentAnalysis":{"suitability":{"en":"Perfect for Autonomous Agents needing secure ApeChain NFT operations and OpenClaw integration.","zh":"适用于需要安全的ApeChain NFT操作和OpenClaw集成的自主代理。","ja":"ApeChain NFT操作とOpenClaw統合が必要な自立型エージェントに適しています。","ko":"ApeChain NFT 연산과 OpenClaw 통합이 필요한 자율 에이전트에게 적합합니다.","es":"Perfecto para Agentes Autónomos que necesitan operaciones de NFT de ApeChain seguras y la integración de OpenClaw.","fr":"Parfait pour les Agents Autonomes ayant besoin d''opérations de NFT ApeChain sécurisées et d''une intégration OpenClaw.","de":"Perfekt für autonome Agenten, die sichere ApeChain-NFT-Operationen und die Integration von OpenClaw benötigen.","pt":"Perfeito para Agentes Autônomos que necessitam de operações de NFT ApeChain seguras e integração com OpenClaw.","ru":"Идеально для автономных агентов, требующих безопасных операций с NFT ApeChain и интеграции с OpenClaw.","ar":"مثالي للوكلاء الأوتوماتيكيين الذين يحتاجون إلى عمليات NFT ApeChain آمنة وتكامل مع OpenClaw."},"recommendation":{"en":"Empowers agents to discover, quote, simulate, and buy NFTs on ApeChain with safety gating and telemetry, utilizing verifiable onchain identity and autonomous collecting within strict policy limits via OpenClaw and ApeChain protocols.","zh":"赋予代理发现、报价、模拟和在ApeChain上购买NFT的能力，具有安全门控和遥测功能，利用可验证的链上身份和严格的策略限制内的自主收集，通过OpenClaw和ApeChain协议。","ja":"エージェントにApeChainでNFTを発見、見積もり、シミュレート、購入する機能を提供します。安全なゲートとテレメトリを備え、検証可能なオンチェーンIDと厳格なポリシーリミット内での自律的な収集を実現します。OpenClawとApeChainのプロトコルを利用しています。","ko":"에이전트에게 ApeChain에서 NFT를 발견,報价, 시뮬레이션, 구매하는 능력을 부여하며, 안전한 게이트와 원격 측정을 사용하며, 검증 가능한 온체인 ID와 엄격한 정책 제한 내에서 자율적인 수집을 수행합니다. OpenClaw와 ApeChain 프로토콜을 활용합니다.","es":"Habilita a los agentes a descubrir, cotizar, simular y comprar NFT en ApeChain con una puerta de seguridad y telemetría, utilizando una identidad verificable en la cadena y una recopilación autónoma dentro de los límites estrictos de la política a través de los protocolos OpenClaw y ApeChain.","fr":"Permet aux agents de découvrir, de coter, de simuler et d''acheter des NFT sur ApeChain avec une sécurité et une télémétrie, en utilisant une identité vérifiable en chaîne et une collecte autonome dans les limites strictes de la politique via les protocoles OpenClaw et ApeChain.","de":"Ermöglicht es Agenten, NFTs auf ApeChain zu entdecken, zu bewerten, zu simulieren und zu kaufen, mit Sicherheits- und Telemetriefunktionen, unter Verwendung einer verifizierbaren On-Chain-Identität und einer autonomen Sammlung innerhalb der strengen Richtlinienbegrenzungen über die OpenClaw- und ApeChain-Protokolle.","pt":"Habilita agentes a descobrirem, cotarem, simularem e comprarem NFTs na ApeChain com segurança e telemetria, utilizando identidade verificável na cadeia e coleta autônoma dentro de limites de política estritos via OpenClaw e protocolos ApeChain.","ru":"Наделяет агентов возможностью обнаруживать, котировать,模拟ировать и покупать NFT на ApeChain с безопасностью и телеметрией, используя верифицированную идентичность в блокчейне и автономную коллекцию в строгих пределах политики через OpenClaw и протоколы ApeChain.","ar":"يمنح الوكلاء القدرة على اكتشاف وتحديد الأسعار وتمثيل وشراء NFTs على ApeChain مع بوابة أمان وتелеметрія، باستخدام الهوية القابلة للتحقق على السلسلة والتحديد الأوتوماتيكي ضمن حدود سياسة صارمة عبر OpenClaw وبروتوكولات ApeChain."},"useCases":{"en":["Discovering available NFTs on ApeChain for autonomous collecting","Simulating NFT purchases to optimize agent decision-making","Buying NFTs with secure, safety-first transactions on ApeChain"],"zh":["为自主收集发现ApeChain上的可用NFT","模拟NFT购买以优化代理决策","使用安全的、安全第一的交易在ApeChain上购买NFT"],"ja":["自立的な収集のためにApeChainで利用可能なNFTを発見する","エージェントの意思決定を最適化するためにNFTの購入をシミュレートする","ApeChainで安全な、安全第一の取引を使用してNFTを購入する"],"ko":["자율적인 수집을 위해 ApeChain에서 사용 가능한 NFT를 발견하는 것","에이전트의 의사 결정을 최적화하기 위해 NFT 구매를 시뮬레이션하는 것","ApeChain에서 안전한, 안전을 최우선으로 하는 거래를 사용하여 NFT를 구매하는 것"],"es":["Descubrir NFT disponibles en ApeChain para la recopilación autónoma","Simular la compra de NFT para optimizar la toma de decisiones del agente","Comprar NFT con transacciones seguras y de prioridad de seguridad en ApeChain"],"fr":["Découvrir les NFT disponibles sur ApeChain pour la collecte autonome","Simuler l''achat de NFT pour optimiser la prise de décision de l''agent","Acheter des NFT avec des transactions sécurisées et de sécurité prioritaires sur ApeChain"],"de":["Verfügbare NFTs auf ApeChain für die autonome Sammlung entdecken","NFT-Käufe simulieren, um die Entscheidungsfindung des Agents zu optimieren","NFTs mit sicheren, sicherheitsorientierten Transaktionen auf ApeChain kaufen"],"pt":["Descobrir NFTs disponíveis na ApeChain para coleta autônoma","Simular compras de NFTs para otimizar a tomada de decisões do agente","Comprar NFTs com transações seguras e com prioridade à segurança na ApeChain"],"ru":["Обнаружение доступных NFT на ApeChain для автономной коллекции","Моделирование покупок NFT для оптимизации принятия решений агентом","Покупка NFT с безопасными транзакциями и приоритетом безопасности на ApeChain"],"ar":["اكتشاف NFTs المتاحة على ApeChain للتحديد الأوتوماتيكي","تمثيل شراء NFTs لتحسين اتخاذ القرارات للوكيل","شراء NFTs مع معاملات آمنة وأولوية الأمان على ApeChain"]},"limitations":{"en":["Requires Cursor installation with OpenClaw","ApeChain NFT operations only","Strict policy limits for autonomous collecting"],"zh":["需要Cursor安装OpenClaw","仅支持ApeChain NFT操作","自主收集的严格策略限制"],"ja":["OpenClawを使用するためにCursorのインストールが必要","ApeChain NFT操作のみをサポート","自立的な収集の厳格なポリシーリミット"],"ko":["OpenClaw를 사용하기 위해 Cursor 설치가 필요","ApeChain NFT 연산만 지원","자율적인 수집의 엄격한 정책 제한"],"es":["Requiere la instalación de Cursor con OpenClaw","Operaciones de NFT de ApeChain solo","Límites estrictos de política para la recopilación autónoma"],"fr":["Nécessite l''installation de Cursor avec OpenClaw","Opérations de NFT ApeChain uniquement","Limites de politique strictes pour la collecte autonome"],"de":["Benötigt die Installation von Cursor mit OpenClaw","Nur ApeChain-NFT-Operationen","Strengere Richtlinienbegrenzungen für die autonome Sammlung"],"pt":["Requer instalação do Cursor com OpenClaw","Operações de NFT ApeChain apenas","Limites de política estritos para coleta autônoma"],"ru":["Требует установки Cursor с OpenClaw","Только операции с NFT ApeChain","Строгие пределы политики для автономной коллекции"],"ar":["يتطلب تثبيت Cursor مع OpenClaw","عمليات NFT ApeChain فقط","حدود سياسية صارمة للتحديد الأوتوماتيكي"]},"version":4},"contentHash":"f74ffe5248ddfcfbb323988569a1f2b94f639357346da88b9ca4b26da4d5d690","qualityScore":45}');
