INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('simplefarmer69/ape-claw/ape-claw', 'ape-claw', 'simplefarmer69', 'ape-claw', 'community', 'ape-claw simplefarmer69 ape-claw community ape-claw is a safety-first skill for ApeChain NFT operations, enabling agents to discover, quote, simulate, and buy NFTs. It benefits AI agents and developers working with OpenClaw and ApeChain Ape Claw 是一个安全的 CLI 和 OpenClaw 技能，用于 ApeChain NFT 操作。它提供发现、报价、模拟和购买功能，并具有政策防护、允许列表执行和结构化遥测等特点 Ape Claw は、ApeChain NFT オペレーション用の安全な CLI と OpenClaw スキルです。発見、引用、シミュレーション、購入などの機能を提供し、ポリシーガードレールや構造化テレメトリなどを備えています Ape Claw 는 ApeChain NFT 작업을 위한 안전한 CLI 와 OpenClaw 스킬입니다. 발견, 인용, 시뮬레이션, 구매 등의 기능을 제공하며 정책 가드레일, 구조화된 텔레메트리 등의 기능을 지원합니다 Ape Claw es una habilidad de seguridad de CLI y OpenClaw para operaciones de NFT en ApeChain, que ofrece funciones de descubrimiento, cotización y compra de NFT. Ape Claw est une compétence de sécurité de CLI et OpenClaw pour les opérations de NFT sur ApeChain, qui propose des fonctionnalités de découverte, de citation et d''achat de NFT. Ape Claw ist eine Sicherheitsfunktion von CLI und OpenClaw für NFT-Operationen auf ApeChain, die Funktionen zum Entdecken, Anführen und Kaufen von NFT bietet. O Ape Claw é uma ferramenta de segurança para operações de NFT na ApeChain, com recursos de descoberta de coleções e listagens, além de fluxos de compra e simulação. Ape Claw - это инструмент безопасности для операций с NFT на ApeChain, с функциями обнаружения коллекций и списков, а также потоками покупки и симуляции. Ape Claw هي أداة أمان لعمليات NFT على ApeChain، مع ميزات اكتشاف المجموعات والقوائم، بالإضافة إلى تدفقات الشراء والتحاكي. how to use ape-claw ape-claw setup guide ape-claw vs OpenClaw ApeChain NFT buying ape-claw install autonomous NFT collecting OpenClaw skill for ApeChain ape-claw CLI tutorial ApeChain NFT bridging Ape Claw ApeChain NFT 安全的 CLI OpenClaw 技能 NFT 操作 政策防护 允许列表执行 结构化遥测 Discover collections and listings on ApeChain using the CLI Quote, simulate, and buy NFTs with policy guardrails and allowlist enforcement Bridge quote and execute with structured telemetry and a live dashboard Utilize verifiable onchain identity with agentId and clawbot verification Run autonomous collecting within strict policy limits using OpenClaw bots Prefer --json command for output formatting ape-claw is an OpenClaw skill for ApeChain NFT buying and bridging, providing safety gating, telemetry, and a live dashboard for agent activity');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danshapiro/kilroy/investigating-kilroy-runs', 'community', 'danshapiro', 'kilroy', 'danshapiro/kilroy', 'investigating-kilroy-runs', 0, 0, 45, '2026-03-08T01:57:15.634Z', '2026-03-08T02:13:36.984Z', 'a8d14848303f84eb2e93236dd2c44482bdf715c00d3eb4f99445ac57dfba9ad7', '{"id":"danshapiro/kilroy/investigating-kilroy-runs","name":"investigating-kilroy-runs","description":{"en":"investigating-kilroy-runs helps developers diagnose Kilroy runs by resolving run roots and providing a precise diagnosis. It benefits developers working with Kilroy attractor runs.","zh":"Investigating Kilroy Runs 技术允许您快速诊断问题，使用 --logs-root 路径和 RUN_ROOT 目录来提高效率","ja":"Investigating Kilroy Runs 技術は、--logs-root パスと RUN_ROOT ディレクトリを使用して問題を迅速に診断することを可能にします - AIエージェント","ko":"Investigating Kilroy Runs 기능을 사용하면 --logs-root 경로와 RUN_ROOT 디렉토리를 통해 문제를 빠르게 진단할 수 있습니다","es":"Investigating Kilroy Runs es una habilidad que permite diagnosticar y solucionar problemas de ejecución de forma precisa. Utiliza comandos como --logs-root para localizar el directorio de ejecución.","fr":"Investigating Kilroy Runs est une compétence qui permet de diagnostiquer et de résoudre les problèmes d''exécution de manière précise. Elle utilise des commandes comme --logs-root pour localiser le répertoire d''exécution.","de":"Investigating Kilroy Runs ist eine Fähigkeit, die es ermöglicht, Ausführungsprobleme präzise zu diagnostizieren und zu beheben. Sie verwendet Befehle wie --logs-root, um das Ausführungsverzeichnis zu lokalisieren.","pt":"Investigar Kilroy Runs é um processo que envolve resolver o root do run e localizar os registros mais recentes. Este guia fornece uma visão geral técnica de como fazer isso.","ru":"Расследование Kilroy Runs включает в себя определение корня запуска и поиск последних журналов. Это руководство предоставляет технический обзор того, как это сделать с помощью ИИ Агентов","ar":"التحقيق في Kilroy Runs هو عملية تتضمن حل جذور التشغيل وfinding السجلات الأخيرة. هذا الدليل يقدم نظرة عامة تقنية عن كيفية القيام بذلك باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"investigating-kilroy-runs: Diagnostic Workflow Setup Guid...","zh":"Investigating Kilroy Runs 快速故障诊断指南","ja":"Investigating Kilroy Runs のセットアップガイド - AIエージェント","ko":"Investigating Kilroy Runs 문제 해결을 위한 최고의 실践","es":"Guía de Configuración para Investigar Kilroy Runs con AI ...","fr":"Guide de Configuration pour Investiguer les Kilroy Runs a...","de":"Einrichtungsleitfaden für die Untersuchung von Kilroy-Läu...","pt":"Guia de Configuração para Investigar Kilroy Runs","ru":"Настройка ИИ Агентов для расследования Kilroy Runs","ar":"دليل إعداد التحقيق في Kilroy Runs باستخدام أدوات الذكاء ا..."},"description":{"en":"Learn how to inspect Kilroy runs quickly with our diagnostic workflow. Get started with investigating-kilroy-runs and resolve run roots with confidence.","zh":"学习如何快速诊断 Kilroy Runs 问题，了解如何使用 --logs-root 路径和 RUN_ROOT 目录","ja":"Kilroy Runs の問題を迅速に診断する方法を学び、--logs-root パスと RUN_ROOT ディレクトリの使用法を理解しましょう - AIエージェント","ko":"Kilroy Runs 문제를 빠르게 진단하고 해결하는 방법을 알아보세요. --logs-root 경로와 RUN_ROOT 디렉토리 사용법을 포함합니다","es":"Aprende a diagnosticar y solucionar problemas en Kilroy Runs con nuestra guía paso a paso sobre cómo utilizar el comando --logs-root y localizar el directori...","fr":"Découvrez comment diagnostiquer et résoudre les problèmes de Kilroy Runs avec notre guide étape par étape sur l''utilisation de la commande --logs-root et la ...","de":"Erfahren Sie, wie Sie Probleme bei Kilroy-Läufen diagnostizieren und beheben können, mit unserer Schritt-für-Schritt-Anleitung zur Verwendung des Befehls --l...","pt":"Aprenda a diagnosticar problemas nos runs do Kilroy com este guia passo a passo sobre como resolver o root do run e localizar os registros mais recentes","ru":"Узнайте, как диагностировать проблемы в запусках Kilroy с помощью этого пошагового руководства по настройке ИИ Агентов и поиску последних журналов","ar":"تعرف على كيفية تشخيص مشاكل تشغيل Kilroy باستخدام هذا الدليل المنهجي حول إعداد أدوات الذكاء الاصطناعي وfinding السجلات الأخيرة"},"definition":{"en":"investigating-kilroy-runs is a diagnostic workflow that inspects Kilroy runs to produce a precise diagnosis by resolving run roots.","zh":"Investigating Kilroy Runs 是一种用于快速诊断 Kilroy Runs 问题的技术","ja":"Investigating Kilroy Runs は、Kilroy Runs の問題を迅速に診断するための技術です - AIエージェント","ko":"Investigating Kilroy Runs 는 Kilroy Runs 문제를 빠르게 진단하는 기술입니다","es":"Investigating Kilroy Runs es una habilidad de AI Agent que permite diagnosticar problemas de ejecución en Kilroy","fr":"Investigating Kilroy Runs est une compétence d''Outil IA qui permet de diagnostiquer les problèmes d''exécution dans Kilroy","de":"Investigating Kilroy Runs ist eine Fähigkeit von KI-Tool, die es ermöglicht, Ausführungsprobleme in Kilroy zu diagnostizieren","pt":"Investigating Kilroy Runs é uma técnica de diagnóstico que envolve a resolução do root do run e a localização dos registros mais recentes","ru":"Расследование Kilroy Runs - это метод диагностики, который включает в себя определение корня запуска и поиск последних журналов с помощью ИИ Агентов","ar":"التحقيق في Kilroy Runs هو تقنية تشخيصية تتضمن حل جذور التشغيل وfinding السجلات الأخيرة باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Resolves run root with highest confidence using an explicit --logs-root path","Infers run root when no path is provided by locating the newest run under ~/.local/state/kilroy/attractor/runs","Treats the located directory as RUN_ROOT for consistent later commands","Utilizes the find command to locate the newest run","Supports bash scripting for automated diagnosis","Provides a precise diagnosis by resolving run roots"],"zh":["使用 --logs-root 路径来提高诊断效率","自动检测 RUN_ROOT 目录","支持快速问题诊断","集成 find 命令来查找最新的运行","使用环境变量来简化配置","支持 CLI 命令来执行诊断"],"ja":["--logs-root パスを使用して診断の効率を高める","RUN_ROOT ディレクトリを自動で検出","迅速な問題診断をサポート","find コマンドを使用して最新の実行を検索","環境変数を使用して設定を簡素化","CLI コマンドを使用して診断を実行 - AIエージェント"],"ko":["--logs-root 경로를 사용하여 진단 효율을 높임","RUN_ROOT 디렉토리를 자동으로检测","빠른 문제 진단을 지원","find 명령을 사용하여 최신 실행을 찾음","환경 변수를 사용하여 구성 단순화","CLI 명령을 사용하여 진단을 수행"],"es":["Utiliza el comando --logs-root para localizar el directorio de ejecución","Localiza el directorio de ejecución más reciente en ~/.local/state/kilroy/attractor/runs","Permite diagnosticar problemas de ejecución de forma precisa","Utiliza la variable de entorno RUN_ROOT para mantener la coherencia en los comandos","Soporta la inferencia del directorio de ejecución cuando no se proporciona un camino explícito"],"fr":["Utilise la commande --logs-root pour localiser le répertoire d''exécution","Localise le répertoire d''exécution le plus récent dans ~/.local/state/kilroy/attractor/runs","Permet de diagnostiquer les problèmes d''exécution de manière précise","Utilise la variable d''environnement RUN_ROOT pour maintenir la cohérence dans les commandes","Prend en charge l''inférence du répertoire d''exécution lorsque aucun chemin explicite n''est fourni"],"de":["Verwendet den Befehl --logs-root, um das Ausführungsverzeichnis zu lokalisieren","Lokalisiert das aktuellste Ausführungsverzeichnis in ~/.local/state/kilroy/attractor/runs","Ermöglicht die präzise Diagnose von Ausführungsproblemen","Verwendet die Umgebungsvariable RUN_ROOT, um die Konsistenz in den Befehlen zu gewährleisten","Unterstützt die Inferenz des Ausführungsverzeichnisses, wenn kein expliziter Pfad angegeben ist"],"pt":["Resolução do root do run com maior confiança","Localização dos registros mais recentes em ~/.local/state/kilroy/attractor/runs","Uso de comandos CLI para encontrar o diretório do run","Tratamento do diretório como RUN_ROOT para comandos subsequentes","Integração com tecnologias de linha de comando para diagnóstico eficaz"],"ru":["Определение корня запуска с наибольшей достоверностью","Поиск последних журналов в ~/.local/state/kilroy/attractor/runs","Использование команд CLI для нахождения директории запуска","Обработка директории как RUN_ROOT для последующих команд","Интеграция с технологиями командной строки для эффективной диагностики с помощью ИИ Агентов"],"ar":["حل جذور التشغيل بأعلى ثقة","finding السجلات الأخيرة في ~/.local/state/kilroy/attractor/runs","استخدام أوامر CLI للعثور على دليل التشغيل","معالجة الدليل كـ RUN_ROOT للأوامر اللاحقة","التكامل مع تقنيات سطر الأوامر لتشخيص فعال باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use investigating-kilroy-runs","investigating-kilroy-runs setup guide","what is investigating-kilroy-runs","investigating-kilroy-runs alternative","investigating-kilroy-runs vs diagnostic tools","investigating-kilroy-runs install","kilroy attractor runs diagnosis","resolving run roots with investigating-kilroy-runs","diagnostic workflow for kilroy runs"],"zh":["Kilroy Runs","快速诊断","--logs-root","RUN_ROOT","CLI","问题诊断","自动检测","环境变量","AI工具","技术指南"],"ja":["Kilroy Runs","迅速な診断","--logs-root","RUN_ROOT","CLI","問題診断","自動検出","環境変数","AIエージェント","テクニカルガイド"],"ko":["Kilroy Runs","빠른 진단","--logs-root","RUN_ROOT","CLI","문제 진단","자동 감지","환경 변수","AI 도구","기술 가이드"],"es":["investigating kilroy runs","ai agent","diagnóstico de problemas de ejecución","comando --logs-root","localización de directorio de ejecución","variable de entorno run_root","inferencia de directorio de ejecución"],"fr":["investigating kilroy runs","outil ia","diagnostic de problèmes d''exécution","commande --logs-root","localisation de répertoire d''exécution","variable d''environnement run_root","inférence de répertoire d''exécution"],"de":["investigating kilroy runs","ki-tool","diagnose von ausführungsproblemen","befehl --logs-root","lokalisierung von ausführungsverzeichnis","umgebungsvariable run_root","inferenz von ausführungsverzeichnis"],"pt":["investigating kilroy runs","diagnóstico de runs","resolução do root do run","localização de registros","CLI","tecnologias de linha de comando","desenvolvimento de software","depuração de código"],"ru":["расследование kilroy runs","диагностика запусков","определение корня запуска","поиск журналов","CLI","технологии командной строки","разработка программного обеспечения","отладка кода","ИИ Агенты"],"ar":["التحقيق في kilroy runs","تشخيص تشغيل","حل جذور التشغيل","finding سجلات","CLI","تقنيات سطر الأوامر","تطوير البرمجيات","تصحيح أخطاء الكود","أدوات الذكاء الاصطناعي"]}},"owner":"danshapiro","repo":"kilroy","repoPath":"danshapiro/kilroy","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.634Z","topics":[],"category":"community","skillMd":{"name":"investigating-kilroy-runs","description":"To diagnose active, stuck, or failed Kilroy Attractor runs, inspect run artifacts (`manifest.json`, `live.json`, `checkpoint.json`, `final.json`, `progress.ndjson`), resolve run IDs/log roots, identify model/provider routing, and isolate failure causes. Includes CXDB operations for launching/probing CXDB, opening the CXDB UI, and querying run context turns. This skill is useful when investigating run status, debugging retries/failures, explaining model usage, or inspecting CXDB-backed event history.","bodyPreview":"# Investigating Kilroy Runs\n\nTo inspect a run quickly and produce a precise diagnosis, follow this workflow.\n\n## Resolve Run Root\n\n1. To resolve run root with highest confidence, start from an explicit `--logs-root` path when provided.\n2. To infer run root when no path is provided, locate the newest run under `~/.local/state/kilroy/attractor/runs`.\n3. To keep later commands consistent, treat that directory as `RUN_ROOT`.\n\n```bash\nRUNS=\"$HOME/.local/state/kilroy/attractor/runs\"\nRUN_ID=\"$(find \"$R","body":"# Investigating Kilroy Runs\n\nTo inspect a run quickly and produce a precise diagnosis, follow this workflow.\n\n## Resolve Run Root\n\n1. To resolve run root with highest confidence, start from an explicit `--logs-root` path when provided.\n2. To infer run root when no path is provided, locate the newest run under `~/.local/state/kilroy/attractor/runs`.\n3. To keep later commands consistent, treat that directory as `RUN_ROOT`.\n\n```bash\nRUNS=\"$HOME/.local/state/kilroy/attractor/runs\"\nRUN_ID=\"$(find \"$RUNS\" -mindepth 1 -maxdepth 1 -type d -printf ''%T@ %f\\n'' | sort -nr | awk ''NR==1 {id=$2} END {print id}'')\"\nRUN_ROOT=\"$RUNS/$RUN_ID\"\necho \"$RUN_ID\"\n```\n\nFor a quick check of the newest run without manually resolving `RUN_ROOT`, use:\n\n```bash\n./kilroy attractor status --latest --json\n```\n\n## CXDB: Launch, UI, and Query\n\nTo get CXDB connection details, start with `manifest.json`, then fall back to `run_config.json` and live artifacts when fields are missing:\n\n```bash\nCXDB_URL=\"$(jq -r ''.cxdb.http_base_url // empty'' \"$RUN_ROOT/manifest.json\")\"\nCONTEXT_ID=\"$(jq -r ''.cxdb.context_id // empty'' \"$RUN_ROOT/manifest.json\")\"\n\nif [ -z \"$CXDB_URL\" ] && [ -f \"$RUN_ROOT/run_config.json\" ]; then\n  CXDB_URL=\"$(jq -r ''.cxdb.http_base_url // empty'' \"$RUN_ROOT/run_config.json\")\"\nfi\nif [ -z \"$CONTEXT_ID\" ] && [ -f \"$RUN_ROOT/live.json\" ]; then\n  CONTEXT_ID=\"$(jq -r ''.context_id // empty'' \"$RUN_ROOT/live.json\")\"\nfi\nif [ -z \"$CONTEXT_ID\" ] && [ -f \"$RUN_ROOT/checkpoint.json\" ]; then\n  CONTEXT_ID=\"$(jq -r ''.context_id // empty'' \"$RUN_ROOT/checkpoint.json\")\"\nfi\n\necho \"cxdb_url=$CXDB_URL context_id=$CONTEXT_ID\"\n```\n\nTo make sure CXDB is available and to print the UI endpoint, run:\n\n```bash\n./scripts/start-cxdb.sh\nUI_LINE=\"$(./scripts/start-cxdb-ui.sh)\"\necho \"$UI_LINE\"   # prints: cxdb_ui=http://...\nCXDB_UI=\"${UI_LINE#cxdb_ui=}\"\n```\n\nUse the endpoint printed by `start-cxdb-ui.sh` (`cxdb_ui=...`) as the source of truth. To open the UI in a browser when needed, run:\n\n```bash\nKILROY_CXDB_OPEN_UI=1 ./scripts/start-cxdb-ui.sh\n```\n\nTo follow run events directly from CXDB:\n\n```bash\n./kilroy attractor status --logs-root \"$RUN_ROOT\" --follow --cxdb\n./kilroy attractor status --logs-root \"$RUN_ROOT\" --follow --cxdb --raw\n```\n\nTo run direct HTTP queries for ad-hoc debugging, use:\n\n```bash\n# Health endpoint may be /healthz even when /health returns 404.\ncurl -fsS \"$CXDB_URL/health\" || curl -fsS \"$CXDB_URL/healthz\"\ncurl -fsS \"$CXDB_URL/v1/contexts\"\ncurl -fsS \"$CXDB_URL/v1/contexts/$CONTEXT_ID\"\ncurl -fsS \"$CXDB_URL/v1/contexts/$CONTEXT_ID/turns?limit=20\"\ncurl -fsS \"$CXDB_URL/v1/contexts/$CONTEXT_ID/turns?view=typed&limit=20\"\n```\n\n## Read Canonical Files\n\nTo build a reliable picture of run state:\n\nAlways inspect `graph.dot` first so status is interpreted in graph context.\n\nPreflight-only runs (`--preflight` / `--test-run`) are expected to write `preflight_report.json` and skip execution artifacts (`manifest.json`, `checkpoint.json`, `final.json`, `worktree/`).\n\n1. `manifest.json`: run identity, graph name, repo, worktree, `started_at`.\n2. `live.json`: most recent event.\n3. `checkpoint.json`: last completed node and failure context.\n4. `final.json`: if present, run is finished (`success` or `fail`).\n5. `progress.ndjson`: full event timeline.\n\n```bash\nsed -n ''1,200p'' \"$RUN_ROOT/graph.dot\"\nsed -n ''1,200p'' \"$RUN_ROOT/manifest.json\"\nsed -n ''1,200p'' \"$RUN_ROOT/live.json\"\n[ -f \"$RUN_ROOT/checkpoint.json\" ] && sed -n ''1,200p'' \"$RUN_ROOT/checkpoint.json\"\n[ -f \"$RUN_ROOT/final.json\" ] && sed -n ''1,200p'' \"$RUN_ROOT/final.json\"\ntail -n 80 \"$RUN_ROOT/progress.ndjson\"\n```\n\n## Determine Current State\n\nTo classify run state:\n\n- Running: `final.json` missing and `live.json`/`progress.ndjson` still changing.\n- Finished: `final.json` present.\n- Likely stalled: no `progress.ndjson` updates for longer than configured stall timeout.\n- `attractor status` can show terminal `fail` while `progress.ndjson` still advances in overlap conditions; timestamp comparison resolves this ambiguity.\n\nTo quickly validate terminal state vs liveness, use:\n\n```bash\nls -la \"$RUN_ROOT/final.json\"\ntail -n 1 \"$RUN_ROOT/progress.ndjson\"\n```\n\n## Discover Event Schema First\n\nTo avoid filtering for non-existent event keys, discover the active event schema before building event-specific queries:\n\n```bash\njq -r ''.event? // empty'' \"$RUN_ROOT/progress.ndjson\" | sort | uniq -c | sort -nr\n```\n\nTo inspect fields for a specific event type, run:\n\n```bash\njq -c ''select(.event==\"stage_attempt_end\")'' \"$RUN_ROOT/progress.ndjson\" | head -n 5\n```\n\n## Noise-to-Signal Query Patterns (Observed)\n\nThese patterns come from real investigation mistakes where the first query produced noisy output and the replacement query produced useful signal.\n\n1. Raw tail was dominated by heartbeats.\n\n```bash\n# noisy\ntail -n 80 \"$RUN_ROOT/progress.ndjson\"\n\n# higher-signal\njq -rc ''select(.event!=\"branch_heartbeat\") | {ts,event,node_id,status,branch_key,branch_event,branch_status,branch_failure_reason}'' \\\n  \"$RUN_ROOT/progress.ndjson\" | tail -n 80\n```\n\n2. Event frequency counts gave little \"what is happening now\" signal.\n\n```bash\n# broad but low immediate diagnostic value\njq -r ''.event? // empty'' \"$RUN_ROOT/progress.ndjson\" | sort | uniq -c | sort -nr\n\n# better for current state\njq -rc ''select(.event!=\"branch_heartbeat\") | {ts,event,node_id,status,branch_key,branch_event,branch_status,branch_failure_reason}'' \\\n  \"$RUN_ROOT/progress.ndjson\" | tail -n 40\n```\n\n3. Broad history scans mixed unrelated commits into run analysis.\n\n```bash\n# noisy across repo history\ngit rev-list HEAD | head -n 200\n\n# scoped to this run''s commits\ngit log --oneline --grep \"$RUN_ID\" -n 80\n```\n\n4. Full commit stats pulled in `target/` and artifact churn.\n\n```bash\n# noisy if commit touched build outputs\ngit show --stat <commit>\n\n# source-focused\ngit show --stat <commit> -- demo/rogue/rogue-wasm/src\n```\n\n5. Progress checks can fail on pipe/SIGPIPE mechanics instead of run state.\n\n```bash\n# brittle in strict pipefail shells\nset -euo pipefail\njq -rc ''select(.event!=\"branch_heartbeat\")'' \"$RUN_ROOT/progress.ndjson\" | head -n 20\n\n# safer wrapper for quick probes\nset -euo pipefail\njq -rc ''select(.event!=\"branch_heartbeat\")'' \"$RUN_ROOT/progress.ndjson\" | head -n 20 || true\n```\n\n6. \"Is code still improving?\" was unclear without a last-meaningful-change anchor.\n\n```bash\n# activity-only view\ngit log --oneline --grep \"$RUN_ID\" -n 30\n\n# source progress since last meaningful implementation commit\ngit diff --stat <last_meaningful_commit>..HEAD -- demo/rogue/rogue-wasm/src\n```\n\n## Resolve Terminal-vs-Live Conflicts\n\nTo handle cases where `final.json` exists but `progress.ndjson` still changes:\n\n1. If `final.json` exists and `progress.ndjson` is newer, this is a possible overlapping-resume state rather than immediate data corruption.\n2. Compare file mtimes and latest event timestamps.\n3. Confirm whether a `run`/`resume` process is currently active.\n\n```bash\nstat -c ''%n %y'' \"$RUN_ROOT/final.json\" \"$RUN_ROOT/live.json\" \"$RUN_ROOT/progress.ndjson\" 2>/dev/null\ntail -n 5 \"$RUN_ROOT/progress.ndjson\"\n```\n\n## Check Process Liveness\n\nTo determine whether the run is truly active at the OS level:\n\n```bash\npgrep -af ''kilroy attractor (run|resume)''\n[ -f \"$RUN_ROOT/run.pid\" ] && cat \"$RUN_ROOT/run.pid\"\n[ -f \"$RUN_ROOT/run.pid\" ] && ps -fp \"$(cat \"$RUN_ROOT/run.pid\")\"\nps -ef | rg -i ''kilroy attractor (run|resume)'' | rg -v rg\n```\n\nIf a `resume` process is already active for the same `--logs-root`, launching another `resume` is a possible source of mixed terminal/live state.\n\nA live PID with unchanged tail events across repeated checks is a possible stale/hung process, not active run progress.\n\n```bash\nE1=\"$(tail -n 1 \"$RUN_ROOT/progress.ndjson\")\"\nsleep 3\nE2=\"$(tail -n 1 \"$RUN_ROOT/progress.ndjson\")\"\n[ \"$E1\" = \"$E2\" ] && echo \"no new events\" || echo \"events advancing\"\n```\n\n## Relaunch Hygiene (Single Owner)\n\nWhen relaunching, quiescing duplicate `resume` processes first and launching one detached `resume` reduces the chance of `stopped by signal terminated` outcomes.\n\n```bash\nps -ef | rg -i \"kilroy attractor resume --logs-root $RUN_ROOT\" | rg -v rg\n# If duplicates exist, stop extras before launching a single detached resume.\nsetsid -f bash -lc \"cd /path/to/repo && ./kilroy attractor resume --logs-root ''$RUN_ROOT'' >> ''$RUN_ROOT/resume.out'' 2>&1\"\n```\n\n## Debug Parallel Fan-In Stalls\n\nTo diagnose fan-in waits, inspect branch-local progress under `parallel/<join-node>/`:\n\n```bash\nfind \"$RUN_ROOT/parallel\" -maxdepth 3 -type f -name ''progress.ndjson'' | sort\n```\n\nTo inspect branch outcomes and status-contract behavior:\n\n```bash\nrg -n ''status_contract|stage_attempt_end|stage_retry_blocked|deterministic_failure_cycle_check|subgraph_deterministic_failure_cycle_check'' \\\n  \"$RUN_ROOT\"/parallel/*/*/progress.ndjson\n```\n\nTo interpret heartbeat-only behavior:\n\n- If events are mostly `branch_heartbeat` and `branch_idle_ms` rises monotonically, the branch is likely waiting/stalled rather than converging.\n- If `branch_progress` continues with new `stage_attempt_*` events, the branch is still making progress.\n\n```bash\ntail -n 200 \"$RUN_ROOT/progress.ndjson\" | rg ''branch_heartbeat|branch_progress|branch_idle_ms''\n```\n\n## Check Loop and Cycle Guardrails\n\nTo distinguish policy stops from compute hangs, inspect guardrail events directly:\n\n```bash\nrg -n ''stuck_cycle_breaker|deterministic_failure_cycle_breaker|stage_retry_blocked|deterministic_failure_cycle_check'' \\\n  \"$RUN_ROOT/progress.ndjson\"\n```\n\nInterpretation guidance:\n\n- `stuck_cycle_breaker` with `visit_count`/`visit_limit` indicates a configured loop-visit stop.\n- `*_cycle_breaker` indicates repeated deterministic failures reached the configured signature limit.\n\n## Identify Models and Providers\n\nTo identify models/providers accurately, combine static and runtime evidence:\n\n1. Static routing from graph `model_stylesheet` and node classes.\n2. Runtime events from `progress.ndjson` (`llm_retry`, `llm_call_*`, provider/model fields).\n3. Provider availability from `run_config.json`.\n\n```bash\nrg -n ''model_stylesheet|llm_model|llm_provider|class='' \"$RUN_ROOT/graph.dot\"\nrg -n ''\"event\":\"llm_|\"provider\":\"|\"model\":\"'' \"$RUN_ROOT/progress.ndjson\"\nsed -n ''1,220p'' \"$RUN_ROOT/run_config.json\"\n```\n\n## Triage Common Failures\n\n- To diagnose `missing status.json`, check whether the codergen node emitted the required status signal.\n- To diagnose `llm retry` with `429`/rate-limit, check for provider quota or backoff pressure.\n- To diagnose `deterministic_failure_cycle_check`, check for repeated deterministic failure at the same node.\n- To diagnose toolchain/setup errors, inspect `setup_command_*` events and stage `stderr.log`.\n\n```bash\nrg -n ''missing status.json|llm_retry|deterministic_failure_cycle_check|setup_command_|failure_reason'' \"$RUN_ROOT/progress.ndjson\"\n```\n\n## Postmortem Capture (Overlap/Termination)\n\nCapture `final.json` timestamp, latest `progress.ndjson` timestamp, active `resume` PIDs/PPIDs, and termination events (`stopped by signal terminated`, `subgraph_canceled_exit`, `stage_attempt_end`).\n\n```bash\nstat -c ''%y %n'' \"$RUN_ROOT/final.json\" \"$RUN_ROOT/live.json\" \"$RUN_ROOT/progress.ndjson\" 2>/dev/null\nps -ef | rg -i \"kilroy attractor resume --logs-root $RUN_ROOT\" | rg -v rg\nrg -n ''stopped by signal terminated|subgraph_canceled_exit|stage_attempt_end'' \"$RUN_ROOT/progress.ndjson\" | tail -n 80\n```\n\n## Report Format\n\nTo present findings clearly, report in this order:\n\n1. `run_id`, `run_root`, started time.\n2. Current node/state and whether run is still active.\n3. Models/providers configured and observed.\n4. Top failure signals with exact file references.\n5. One next action (continue waiting, resume, or fix specific failure cause).\n"},"lastSynced":"2026-03-08T02:13:36.984Z","agentAnalysis":{"suitability":{"en":"Perfect for Debugging Agents needing precise Kilroy run diagnostics and run root resolution capabilities.","zh":"非常适合需要精确Kilroy运行诊断和运行根解析能力的调试代理。","ja":"デバッグエージェントがKilroyの実行診断と実行ルート解決能力を必要とする場合に最適です。","ko":"정확한 Kilroy 실행 진단 및 실행 루트 해결 기능이 필요한 디버깅 에이전트에 적합합니다.","es":"Perfecto para Agentes de Depuración que necesitan diagnósticos precisos de ejecución de Kilroy y capacidades de resolución de raíz de ejecución.","fr":"Parfait pour les Agents de Débogage nécessitant des diagnostics d''exécution Kilroy précis et des capacités de résolution de racine d''exécution.","de":"Perfekt für Debugging-Agents, die präzise Kilroy-Laufdiagnosen und Laufwurzelauflösungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Depuração que necessitam de diagnósticos precisos de execução do Kilroy e capacidades de resolução de raiz de execução.","ru":"Идеально подходит для агентов отладки, которым требуются точные диагностические данные запуска Kilroy и возможности разрешения корневой директории запуска.","ar":"مثالي للوكلاء الذين يحتاجون إلى تشخيصات دقيقة لتشغيل Kilroy وقدرات حل جذور التشغيل."},"recommendation":{"en":"Empowers agents to diagnose Kilroy runs by resolving run roots and providing precise diagnoses, utilizing `--logs-root` paths and inspecting directories like `~/.local/state/kilroy/attractor/runs` for the newest run.","zh":"赋予代理诊断Kilroy运行的能力，通过解析运行根并提供精确的诊断，利用 `--logs-root` 路径并检查目录，如 `~/.local/state/kilroy/attractor/runs`，以获取最新的运行记录。","ja":"エージェントがKilroyの実行を診断する能力を与え、実行ルートを解決し、精密な診断を提供することで、`--logs-root` パスを利用し、`~/.local/state/kilroy/attractor/runs` のようなディレクトリを検査して最新の実行を取得します。","ko":"에이전트가 Kilroy 실행을 진단할 수 있는 능력을 부여하여 실행 루트를 해결하고 정확한 진단을 제공하며, `--logs-root` 경로를 사용하여 `~/.local/state/kilroy/attractor/runs`와 같은 디렉토리를 검사하여 최신 실행을 가져옵니다.","es":"Permite a los agentes diagnosticar ejecuciones de Kilroy resolviendo raíces de ejecución y proporcionando diagnósticos precisos, utilizando rutas `--logs-root` y inspeccionando directorios como `~/.local/state/kilroy/attractor/runs` para la ejecución más reciente.","fr":"Permet aux agents de diagnostiquer les exécutions Kilroy en résolvant les racines d''exécution et en fournissant des diagnostics précis, en utilisant des chemins `--logs-root` et en inspectant des répertoires comme `~/.local/state/kilroy/attractor/runs` pour l''exécution la plus récente.","de":"Ermöglicht es den Agenten, Kilroy-Läufe zu diagnostizieren, indem sie Laufwurzeln auflösen und präzise Diagnosen liefern, indem sie `--logs-root`-Pfade verwenden und Verzeichnisse wie `~/.local/state/kilroy/attractor/runs` für den neuesten Lauf untersuchen.","pt":"Habilita os agentes a diagnosticar execuções do Kilroy, resolvendo raízes de execução e fornecendo diagnósticos precisos, utilizando caminhos `--logs-root` e inspecionando diretórios como `~/.local/state/kilroy/attractor/runs` para a execução mais recente.","ru":"Позволяет агентам диагностировать запуски Kilroy, разрешая корневые директории запуска и предоставляя точные диагнозы, используя пути `--logs-root` и осматривая директории типа `~/.local/state/kilroy/attractor/runs` для последнего запуска.","ar":"يمكن للوكلاء تشخيص تشغيل Kilroy من خلال حل جذور التشغيل وتقديم تشخيصات دقيقة، واستخدام مسارات `--logs-root` وتفتيش الدلائل مثل `~/.local/state/kilroy/attractor/runs` لأحدث تشغيل."},"useCases":{"en":["Resolving run roots with highest confidence","Inferring run roots from default directories","Producing precise diagnoses for Kilroy attractor runs"],"zh":["以最高的置信度解析运行根","从默认目录推断运行根","为Kilroy吸引器运行生成精确的诊断"],"ja":["最高の信頼性で実行ルートを解決する","デフォルトディレクトリから実行ルートを推論する","Kilroyアトラクターの実行に対して精密な診断を生成する"],"ko":["가장 높은 신뢰도로 실행 루트를 해결하는 것","기본 디렉토리에서 실행 루트를 추론하는 것","Kilroy 매개변수 실행에 대해 정확한 진단을 생성하는 것"],"es":["Resolución de raíces de ejecución con la mayor confianza","Inferencia de raíces de ejecución desde directorios predeterminados","Producción de diagnósticos precisos para ejecuciones de atractores Kilroy"],"fr":["Résolution des racines d''exécution avec la confiance la plus élevée","Inférence des racines d''exécution à partir de répertoires par défaut","Production de diagnostics précis pour les exécutions d''attracteurs Kilroy"],"de":["Auflösung von Laufwurzeln mit höchster Zuverlässigkeit","Ableitung von Laufwurzeln aus Standardverzeichnissen","Erzeugung präziser Diagnosen für Kilroy-Attraktor-Läufe"],"pt":["Resolver raízes de execução com maior confiança","Inferir raízes de execução a partir de diretórios padrão","Produzir diagnósticos precisos para execuções do atractor do Kilroy"],"ru":["Разрешение корневых директорий запуска с наивысшей уверенностью","Выявление корневых директорий запуска из директорий по умолчанию","Получение точных диагнозов для запусков атректора Kilroy"],"ar":["حل جذور التشغيل بأعلى ثقة","استنتاج جذور التشغيل من الدلائل الافتراضية","إنتاج تشخيصات دقيقة لتشغيلات جذب Kilroy"]},"limitations":{"en":["Requires access to Kilroy attractor run logs and directories","Dependent on specific directory structures like `~/.local/state/kilroy/attractor/runs`"],"zh":["需要访问Kilroy吸引器运行日志和目录","依赖于特定的目录结构，如 `~/.local/state/kilroy/attractor/runs`"],"ja":["Kilroyアトラクターの実行ログとディレクトリへのアクセスが必要","特定のディレクトリ構造、例えば `~/.local/state/kilroy/attractor/runs` に依存する"],"ko":["Kilroy 매개변수 실행 로그 및 디렉토리에 대한 액세스가 필요함","예를 들어 `~/.local/state/kilroy/attractor/runs`와 같은 특정 디렉토리 구조에 의존"],"es":["Requiere acceso a registros y directorios de ejecución de atractores Kilroy","Dependiente de estructuras de directorios específicas como `~/.local/state/kilroy/attractor/runs`"],"fr":["Nécessite l''accès aux journaux et répertoires d''exécution d''attracteurs Kilroy","Dépend de structures de répertoire spécifiques comme `~/.local/state/kilroy/attractor/runs`"],"de":["Erfordert Zugriff auf Protokolle und Verzeichnisse von Kilroy-Attraktor-Läufen","Abhängig von bestimmten Verzeichnisstrukturen wie `~/.local/state/kilroy/attractor/runs`"],"pt":["Requer acesso a logs e diretórios de execução do atractor do Kilroy","Dependente de estruturas de diretório específicas como `~/.local/state/kilroy/attractor/runs`"],"ru":["Требует доступа к журналам и директориям запуска атректора Kilroy","Зависит от конкретных структур директорий типа `~/.local/state/kilroy/attractor/runs`"],"ar":["يتطلب الوصول إلى سجلات ودلائل تشغيل جذب Kilroy","يعتمد على هياكل دلائل محددة مثل `~/.local/state/kilroy/attractor/runs`"]},"version":4},"contentHash":"a8d14848303f84eb2e93236dd2c44482bdf715c00d3eb4f99445ac57dfba9ad7","qualityScore":45}');
