INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danshapiro/kilroy/investigating-kilroy-runs', 'investigating-kilroy-runs', 'danshapiro', 'kilroy', 'community', 'investigating-kilroy-runs danshapiro kilroy community investigating-kilroy-runs helps developers diagnose Kilroy runs by resolving run roots and providing a precise diagnosis. It benefits developers working with Kilroy attractor runs. Investigating Kilroy Runs 技术允许您快速诊断问题，使用 --logs-root 路径和 RUN_ROOT 目录来提高效率 Investigating Kilroy Runs 技術は、--logs-root パスと RUN_ROOT ディレクトリを使用して問題を迅速に診断することを可能にします - AIエージェント Investigating Kilroy Runs 기능을 사용하면 --logs-root 경로와 RUN_ROOT 디렉토리를 통해 문제를 빠르게 진단할 수 있습니다 Investigating Kilroy Runs es una habilidad que permite diagnosticar y solucionar problemas de ejecución de forma precisa. Utiliza comandos como --logs-root para localizar el directorio de ejecución. Investigating Kilroy Runs est une compétence qui permet de diagnostiquer et de résoudre les problèmes d''exécution de manière précise. Elle utilise des commandes comme --logs-root pour localiser le répertoire d''exécution. Investigating Kilroy Runs ist eine Fähigkeit, die es ermöglicht, Ausführungsprobleme präzise zu diagnostizieren und zu beheben. Sie verwendet Befehle wie --logs-root, um das Ausführungsverzeichnis zu lokalisieren. Investigar Kilroy Runs é um processo que envolve resolver o root do run e localizar os registros mais recentes. Este guia fornece uma visão geral técnica de como fazer isso. Расследование Kilroy Runs включает в себя определение корня запуска и поиск последних журналов. Это руководство предоставляет технический обзор того, как это сделать с помощью ИИ Агентов التحقيق في Kilroy Runs هو عملية تتضمن حل جذور التشغيل وfinding السجلات الأخيرة. هذا الدليل يقدم نظرة عامة تقنية عن كيفية القيام بذلك باستخدام أدوات الذكاء الاصطناعي how to use investigating-kilroy-runs investigating-kilroy-runs setup guide what is investigating-kilroy-runs investigating-kilroy-runs alternative investigating-kilroy-runs vs diagnostic tools investigating-kilroy-runs install kilroy attractor runs diagnosis resolving run roots with investigating-kilroy-runs diagnostic workflow for kilroy runs Kilroy Runs 快速诊断 --logs-root RUN_ROOT CLI 问题诊断 自动检测 环境变量 AI工具 技术指南 Resolves run root with highest confidence using an explicit --logs-root path Infers run root when no path is provided by locating the newest run under ~/.local/state/kilroy/attractor/runs Treats the located directory as RUN_ROOT for consistent later commands Utilizes the find command to locate the newest run Supports bash scripting for automated diagnosis Provides a precise diagnosis by resolving run roots investigating-kilroy-runs is a diagnostic workflow that inspects Kilroy runs to produce a precise diagnosis by resolving run roots.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('drbobber/superdiscount-deals/email', 'community', 'drbobber', 'superdiscount-deals', 'drbobber/superdiscount-deals', 'email', 0, 0, 45, '2026-03-08T01:57:15.647Z', '2026-03-08T02:13:49.302Z', '6b821d8a0f26e09781bc369db2f6607dd77f923c84ef298ee5b1f487294de88f', '{"id":"drbobber/superdiscount-deals/email","name":"email","description":{"en":"The email skill enables AI agents to automate and manage email tasks, benefiting developers and users who need to streamline their email workflows. It supports Gmail, Outlook, and IMAP/SMTP protocols.","zh":"AI邮箱管理工具提供发送和读取电子邮件、搜索消息和组织标签/文件夹等功能","ja":"AIエージェントによるメール自動化ツールは、メールの送信と読み取り、メッセージの検索とラベル/フォルダの組織化を提供","ko":"이메일 관리 도구는 이메일 보내기 및 받기, 메시지 검색 및 레이블/폴더 구성 등 기능을 제공","es":"Nuestra herramienta de correo electrónico con AI Agent permite enviar, leer y organizar correos electrónicos de manera eficiente. Compatible con Gmail, Outlook e IMAP/SMTP","fr":"Notre outil d''email avec l''agent AI permet d''envoyer, de lire et d''organiser les emails de manière efficace. Compatible avec Gmail, Outlook et IMAP/SMTP","de":"Unser E-Mail-Tool mit AI-Agent ermöglicht das effiziente Senden, Lesen und Organisieren von E-Mails. Kompatibel mit Gmail, Outlook und IMAP/SMTP","pt":"O skill de email permite a automação e gestão de emails, com recursos como envio, leitura e organização de emails.","ru":"Сkill электронной почты позволяет автоматизировать и управлять электронными письмами, с функциями seperti отправка, чтение и организация электронных писем.","ar":"مهارة البريد الإلكتروني تمكن من أتمتة البريد الإلكتروني والتحكم به، مع ميزات مثل إرسال وقراءة وتحريك البريد الإلكتروني."},"seo":{"title":{"en":"Email: Automation and Management Setup Guide | AI Agent S...","zh":"AI邮箱管理工具：发送和读取电子邮件","ja":"AIエージェントによるメール自動化ガイド","ko":"이메일 관리 도구: 이메일 보내기 및 받기","es":"Guía de configuración de correo electrónic