INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jacky-wong9273/rclaw/gh-issues', 'gh-issues', 'jacky-wong9273', 'rclaw', 'community', 'gh-issues jacky-wong9273 rclaw community The gh-issues skill auto-fixes GitHub issues using parallel sub-agents and the GitHub REST API. It benefits developers by automating issue resolution. gh-issues是一种使用curl和GitHub REST API自动修复GitHub问题的AI工具，支持任何操作系统和平台 gh-issuesは、curlとGitHub REST APIを使用してGitHub Issuesを自動修復するAIエージェントです。 cualquier OSとプラットフォームに対応しています gh-issues는 curl과 GitHub REST API를 사용하여 GitHub 이슈를 자동으로 수정하는 AI 도구입니다. 모든 운영 체제와 플랫폼에서 작동합니다 gh-issues es una habilidad que utiliza la API de REST de GitHub y curl para autoreparar problemas de GitHub de manera eficiente. Sigue los 6 fases para configurarla correctamente gh-issues est une compétence qui utilise l''API REST de GitHub et curl pour auto-résoudre les problèmes GitHub de manière efficace. Suivez les 6 phases pour la configurer correctement gh-issues ist eine Fähigkeit, die die GitHub-REST-API und curl verwendet, um GitHub-Probleme automatisch und effizient zu beheben. Befolgen Sie die 6 Phasen, um sie richtig zu konfigurieren O gh-issues é uma habilidade que automatiza a resolução de issues do GitHub com sub-agentes paralelos e a API REST do GitHub. ИИ Агенты: gh-issues - это навык, который автоматизирует исправление проблем на GitHub с помощью параллельных суб-агентов и REST API GitHub. وكلاء الذكاء الاصطناعي: gh-issues هو مهارة تautomatiza إصلاح الأخطاء على GitHub باستخدام وكلاء فرعيين متوازيين وواجهة برمجة تطبيقات GitHub how to use gh-issues gh-issues setup guide gh-issues alternative gh-issues vs github cli auto-fix github issues github rest api tutorial curl github api github issue management gh-issues GitHub问题自动修复 AI工具 curl GitHub REST API 自动修复流程 并行子代理 GH_TOKEN环境变量 Uses curl for API calls with Bearer token authentication Utilizes the GitHub REST API for issue management Follows a 6-phase process for issue resolution Supports parallel sub-agents for efficient issue fixing Does not require gh CLI dependency Injects GH_TOKEN env var for secure API calls gh-issues is a skill that utilizes curl and the GitHub REST API to auto-fix GitHub issues, following a 6-phase process without gh CLI dependency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bitwize-music-studio/claude-ai-music-skills/configure', 'community', 'bitwize-music-studio', 'claude-ai-music-skills', 'bitwize-music-studio/claude-ai-music-skills', 'configure', 0, 0, 45, '2026-03-08T01:57:15.660Z', '2026-03-08T02:14:05.509Z', '61ee61fada86acae4e11c70b8404dfb91d01e3eebf978fb20aea9027f4ab403e', '{"id":"bitwize-music-studio/claude-ai-music-skills/configure","name":"configure","description":{"en":"The Configure skill facilitates an interactive setup for Suno''s music production workflow, enabling users to manage their config.yaml file efficiently. It benefits music producers and developers working with AI music production tools.","zh":"配置Suno AI音乐生产工作流，管理配置文件并优化音乐制作过程","ja":"Suno AI音楽制作ワークフローを設定し、設定ファイルを管理して音楽制作プロセスを最適化します","ko":"Suno AI 음악 제작 워크플로우를 설정하고 구성 파일을 관리하여 음악 제작 프로세스를 최적화합니다","es":"La configuración de herramientas de música con AI permite a los usuarios personalizar su flujo de trabajo de producción musical con Suno","fr":"La configuration des outils de musique avec l''IA permet aux utilisateurs de personnaliser leur flux de travail de production musicale avec Suno","de":"Die Konfiguration von Musiktools mit KI ermöglicht es Benutzern, ihren Musikproduktionsworkflow mit Suno anzupassen","pt":"O agente de configuração permite aos usuários gerenciar seu arquivo de configuração YAML para produzir música com o Suno","ru":"Агент настройки позволяет пользователям управлять своим файлом конфигурации YAML для музыкального производства с помощью Suno","ar":"الوكيل الإعداد يسمح للمستخدمين بإدارة ملفاتهم YAML لتكوين لإنتاج الموسيقى مع Suno"},"seo":{"title":{"en":"Configure: Interactive Setup Guide for AI Music Productio...","zh":"配置设置指南 - Suno AI音乐生产工作流","ja":"設定ガイド - Suno AI音楽制作ワークフロー","ko":"설정 가이드 - Suno AI 음악 제작 워크플로","es":"Configuración de herramientas de música con AI: Guía de c...","fr":"Configurer les outils de musique avec l''IA: Meilleures pr...","de":"Konfigurieren von Musiktools mit KI: Einrichtungsanleitung","pt":"Guia de Configuração do Agente de Música AI","ru":"Настройка ИИ Агента для Музыкального Производства","ar":"دليل إعداد الوكيل الموسيقي الإصطناعي"},"description":{"en":"Discover how to streamline your music production workflow with Configure, a skill that simplifies setup and management of your config.yaml file - get started...","zh":"了解如何配置Suno AI音乐生产工作流，包括设置、编辑和验证配置文件","ja":"Suno AI音楽制作ワークフローの設定方法について学びます。設定、編集、検証など","ko":"Suno AI 음악 제작 워크플로우를 설정하는 방법에 대해 알아보세요. 설정, 편집, 검증 등","es":"Aprende a configurar herramientas de música con AI para mejorar tu flujo de trabajo de producción musical con Suno","fr":"Découvrez comment configurer les outils de musique avec l''IA pour améliorer votre flux de travail de production musicale avec Suno","de":"Erfahren Sie, wie Sie Musiktools mit KI konfigurieren, um Ihren Musikproduktionsworkflow mit Suno zu optimieren","pt":"Aprenda a configurar o agente de música AI para produzir música com o Suno, incluindo templates e ferramentas","ru":"Узнайте, как настроить ИИ агент для музыкального производства с помощью Suno, включая шаблоны и инструменты","ar":"تعلم كيفية إعداد الوكيل الموسيقي الإصطناعي لإنشاء الموسيقى مع Suno، بما في ذلك القوالب والأدوات"},"definition":{"en":"Configure is a skill that assists in setting up and managing the ~/.bitwize-music/config.yaml configuration file for AI music production workflows.","zh":"配置是Suno AI音乐生产工作流中的一个技能，用于设置和管理配置文件","ja":"設定は、Suno AI音楽制作ワークフローのスキルであり、設定ファイルの設定と管理に使用されます","ko":"설정은 Suno AI 음악 제작 워크플로우의 기능으로 구성 파일을 설정하고 관리하는 데 사용됩니다","es":"La configuración de herramientas de música con AI se refiere al proceso de personalización de la configuración de ~/.bitwize-music/config.yaml","fr":"La configuration des outils de musique avec l''IA fait référence au processus de personnalisation de la configuration de ~/.bitwize-music/config.yaml","de":"Die Konfiguration von Musiktools mit KI bezeichnet den Prozess der Anpassung der Konfiguration von ~/.bitwize-music/config.yaml","pt":"O que é um agente de configuração? É um recurso que ajuda a gerenciar arquivos de configuração YAML","ru":"Что такое агент настройки? Это функция, которая помогает управлять файлами конфигурации YAML","ar":"ما هو وكيل الإعداد؟ هو ميزة تساعد في إدارة ملفات YAML للتكوين"},"features":{"en":["Interactive first-time setup via the `setup` command","Edits specific settings using the `edit` command","Displays current configuration with the `show` command","Validates config for issues using the `validate` command","Resets config to default state with the `reset` command"],"zh":["支持交互式首次设置","提供编辑和显示当前配置的功能","可以验证配置文件以检查问题","支持删除配置文件并重新开始","使用~/.bitwize-music/config.yaml配置文件","支持/configure和/configure s命令"],"ja":["インタラクティブな初期設定をサポート","編集と現在の設定の表示機能を提供","設定ファイルを検証して問題をチェック","設定ファイルを削除して再開することをサポート","~/.bitwize-music/config.yaml設定ファイルを使用","/configureと/configure sコマンドをサポート"],"ko":["대화형 초기 설정을 지원","편집 및 현재 구성 표시 기능을 제공","구성 파일을 검증하여 문제를 확인","구성 파일을 삭제하고 다시 시작하는 것을 지원","~/.bitwize-music/config.yaml 구성 파일을 사용","/configure 및 /configure s 명령어를 지원"],"es":["Configuración interactiva para principiantes","Edición de configuración específica con el comando `/configure edit`","Visualización de la configuración actual con el comando `/configure show`","Validación de la configuración para detectar problemas","Reinicialización de la configuración con el comando `/configure reset`"],"fr":["Configuration interactive pour les débutants","Édition de la configuration spécifique avec la commande `/configure edit`","Affichage de la configuration actuelle avec la commande `/configure show`","Validation de la configuration pour détecter les problèmes","Réinitialisation de la configuration avec la commande `/configure reset`"],"de":["Interaktive Konfiguration für Anfänger","Bearbeitung von spezifischen Konfigurationseinstellungen mit dem Befehl `/configure edit`","Anzeige der aktuellen Konfiguration mit dem Befehl `/configure show`","Überprüfung der Konfiguration auf Probleme","Zurücksetzen der Konfiguration mit dem Befehl `/configure reset`"],"pt":["Suporte a configuração interativa","Edição de configurações específicas","Exibição da configuração atual","Validação de configuração para problemas","Reinicialização da configuração"],"ru":["Поддержка интерактивной настройки","Редактирование конкретных настроек","Отображение текущей конфигурации","Проверка конфигурации на наличие проблем","Сброс конфигурации"],"ar":["دعم الإعداد التفاعلي","تحرير الإعدادات المحددة","عرض الإعداد الحالي","التحقق من الإعدادات لمعرفة المشاكل","إعادة ضبط الإعداد"]},"keywords":{"en":["how to use configure","configure setup guide","configure alternative","configure vs music production software","configure install","what is configure","configure music production workflow","configure config.yaml management"],"zh":["Suno AI音乐生产工作流","配置设置","音乐制作过程","AI音乐工具","配置文件管理","交互式设置","配置验证","AIエージェント配置"],"ja":["Suno AI音楽制作ワークフロー","設定方法","音楽制作プロセス","AI音楽ツール","設定ファイル管理","インタラクティブな設定","設定検証","AIエージェント設定"],"ko":["Suno AI 음악 제작 워크플로","설정 가이드","음악 제작 프로세스","AI 음악 도구","구성 파일 관리","대화형 설정","구성 검증","AI 에이전트 설정"],"es":["configuración de herramientas de música con AI","Suno música","producción musical con AI","config.yaml","comandos de configuración","herramientas de música con IA"],"fr":["configuration des outils de musique avec l''IA","Suno musique","production musicale avec l''IA","config.yaml","commandes de configuration","outils de musique avec IA"],"de":["Konfiguration von Musiktools mit KI","Suno Musik","Musikproduktion mit KI","config.yaml","Konfigurationsbefehle","Musiktools mit KI"],"pt":["agente de música AI","configuração de música","produção de música","Suno","YAML","configuração interativa","edição de configuração"],"ru":["ИИ агент для музыки","настройка музыки","музыкальное производство","Suno","YAML","интерактивная настройка","редактирование конфигурации"],"ar":["وكيل موسيقي إصطناعي","إعداد الموسيقى","إنتاج الموسيقى","Suno","YAML","إعداد تفاعلي","تحرير الإعداد"]}},"owner":"bitwize-music-studio","repo":"claude-ai-music-skills","repoPath":"bitwize-music-studio/claude-ai-music-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.660Z","topics":[],"category":"community","skillMd":{"name":"configure","description":"Sets up or edits the plugin configuration file interactively. Use on first-time setup, when config is missing, or when the user wants to change settings.","bodyPreview":"## Your Task\n\n**Input**: $ARGUMENTS\n\nRoute based on argument:\n- `setup` or no argument → Interactive first-time setup\n- `edit` → Edit specific settings\n- `show` → Display current configuration\n- `validate` → Check config for issues\n- `reset` → Delete config and start fresh\n\n---\n\n# Plugin Configuration Skill\n\nYou help users set up and manage their `~/.bitwize-music/config.yaml` configuration.\n\n## Config Location\n\n```\n~/.bitwize-music/config.yaml\n```\n\n## Commands\n\n### `/configure` or `/configure s","body":"## Your Task\n\n**Input**: $ARGUMENTS\n\nRoute based on argument:\n- `setup` or no argument → Interactive first-time setup\n- `edit` → Edit specific settings\n- `show` → Display current configuration\n- `validate` → Check config for issues\n- `reset` → Delete config and start fresh\n\n---\n\n# Plugin Configuration Skill\n\nYou help users set up and manage their `~/.bitwize-music/config.yaml` configuration.\n\n## Config Location\n\n```\n~/.bitwize-music/config.yaml\n```\n\n## Commands\n\n### `/configure` or `/configure setup`\n\nInteractive first-time setup. Guide user through creating their config.\n\n**Steps:**\n\n1. Check if `~/.bitwize-music/config.yaml` exists\n2. If exists, ask if they want to overwrite or edit instead\n3. If creating new:\n   - Create `~/.bitwize-music/` directory if needed\n   - Ask for each required setting interactively\n   - Write the config file\n   - Validate the result\n\n**Required settings to ask:**\n1. `artist.name` - \"What''s your artist/project name?\"\n2. `paths.content_root` - \"Where should albums and projects be stored? (e.g., ~/music-projects)\"\n3. `paths.audio_root` - \"Where should mastered audio files go? (e.g., ~/music-projects/audio)\"\n4. `paths.documents_root` - \"Where should research documents/PDFs go? (e.g., ~/music-projects/documents)\"\n\n**Optional settings:**\n5. `artist.genres` - \"What are your primary genres? (comma-separated, or skip)\"\n6. `urls.soundcloud` - \"SoundCloud profile URL? (or skip)\"\n\n**Step 5: Overrides Directory (Optional)**\n\nAsk:\n> You can optionally provide a path to a directory containing override files.\n> This is where you can customize workflows and skills without plugin update conflicts.\n>\n> Override files you can create:\n>   - CLAUDE.md (custom workflow instructions)\n>   - pronunciation-guide.md (artist names, character names)\n>   - explicit-words.md (custom explicit word list)\n>\n> Default: ~/music-projects/overrides\n>\n> Enter path (or press Enter to use default):\n\nIf user provides path:\n- Add to config: `paths.overrides: \"[user-path]\"`\n\nIf user presses Enter (accepts default):\n- Add to config: `paths.overrides: \"~/music-projects/overrides\"`\n- Tell user: \"Note: Directory doesn''t need to exist yet. Create override files when you want to customize.\"\n\n**Step 6: Album Ideas File (Optional)**\n\nAsk:\n> You can optionally provide a path to a file for tracking album ideas.\n> This is managed by the /bitwize-music:album-ideas skill for brainstorming and planning.\n>\n> Default: ~/music-projects/IDEAS.md\n>\n> Enter path (or press Enter to use default):\n\nIf user provides path:\n- Add to config: `paths.ideas_file: \"[user-path]\"`\n\nIf user presses Enter (accepts default):\n- Add to config: `paths.ideas_file: \"~/music-projects/IDEAS.md\"`\n- Tell user: \"Note: File doesn''t need to exist yet. The album-ideas skill creates it when first used.\"\n\n**Example interaction:**\n```\nLet''s set up your bitwize-music configuration.\n\nWhat''s your artist/project name?\n> Neon Circuits\n\nWhere should albums and projects be stored?\n(This is where your album folders, lyrics, and research will live)\n> ~/music-projects\n\nWhere should mastered audio files go?\n> ~/music-projects/audio\n\nWhere should research documents/PDFs go?\n> ~/music-projects/documents\n\nWhat are your primary genres? (comma-separated, or press Enter to skip)\n> electronic, synthwave\n\nSoundCloud profile URL? (or press Enter to skip)\n> https://soundcloud.com/neon-circuits\n\nOverrides directory path? (press Enter for default: ~/music-projects/overrides)\n> [Enter]\n\nAlbum ideas file path? (press Enter for default: ~/music-projects/IDEAS.md)\n> [Enter]\n\nCreating config at ~/.bitwize-music/config.yaml...\n\n✓ Configuration saved!\n\nYour settings:\n  Artist: Neon Circuits\n  Content: ~/music-projects\n  Audio: ~/music-projects/audio\n  Documents: ~/music-projects/documents\n  Genres: electronic, synthwave\n  SoundCloud: https://soundcloud.com/neon-circuits\n  Overrides: ~/music-projects/overrides (will be used if created)\n  Ideas File: ~/music-projects/IDEAS.md (will be created when first used)\n\nYou''re ready to start creating albums!\n```\n\n### `/configure edit`\n\nEdit specific settings without recreating the whole config.\n\n**Steps:**\n1. Read existing config\n2. Show current values\n3. Ask what they want to change\n4. Update just that setting\n5. Validate and save\n\n**Example:**\n```\nCurrent configuration:\n\n  artist.name: Neon Circuits\n  paths.content_root: ~/music-projects\n  paths.audio_root: ~/music-projects/audio\n  paths.documents_root: ~/music-projects/documents\n  artist.genres: [electronic, synthwave]\n  urls.soundcloud: https://soundcloud.com/neon-circuits\n\nWhat would you like to change?\n```\n\n### `/configure show`\n\nDisplay the current configuration in a readable format.\n\n**Steps:**\n1. Read `~/.bitwize-music/config.yaml`\n2. Display all settings in a formatted table\n3. Note any missing required settings\n\n**Example output:**\n```\nbitwize-music Configuration\nLocation: ~/.bitwize-music/config.yaml\n\n┌─────────────────────┬────────────────────────────────────┐\n│ Setting             │ Value                              │\n├─────────────────────┼────────────────────────────────────┤\n│ artist.name         │ Neon Circuits                      │\n│ artist.genres       │ electronic, synthwave              │\n│ paths.content_root  │ ~/music-projects                   │\n│ paths.audio_root    │ ~/music-projects/audio             │\n│ paths.documents_root│ ~/music-projects/documents         │\n│ paths.overrides     │ ~/music-projects/overrides         │\n│ paths.ideas_file    │ ~/music-projects/IDEAS.md          │\n│ urls.soundcloud     │ https://soundcloud.com/neon-circuits│\n│ generation.service  │ suno                               │\n└─────────────────────┴────────────────────────────────────┘\n\n✓ All required settings present\n```\n\n### `/configure validate`\n\nCheck the config for issues.\n\n**Checks:**\n1. Config file exists\n2. All required fields present\n3. Paths are valid (directories exist or can be created)\n4. No syntax errors in YAML\n\n**Example output:**\n```\nValidating ~/.bitwize-music/config.yaml...\n\n✓ Config file exists\n✓ artist.name: Neon Circuits\n✓ paths.content_root: ~/music-projects (exists)\n✓ paths.audio_root: ~/music-projects/audio (exists)\n✓ paths.documents_root: ~/music-projects/documents (will be created)\n✓ paths.overrides: ~/music-projects/overrides (will be used if created)\n✓ paths.ideas_file: ~/music-projects/IDEAS.md (will be created when first used)\n✓ generation.service: suno\n\nAll checks passed!\n```\n\nOr with issues:\n```\nValidating ~/.bitwize-music/config.yaml...\n\n✓ Config file exists\n✓ artist.name: Neon Circuits\n✗ paths.content_root: not set (required)\n✓ paths.audio_root: ~/music-projects/audio\n✗ paths.documents_root: /invalid/path (directory doesn''t exist)\n\n2 issues found. Run /configure edit to fix.\n```\n\n### `/configure reset`\n\nDelete config and optionally start fresh.\n\n**Steps:**\n1. Confirm user really wants to reset\n2. Back up existing config to `config.yaml.bak`\n3. Delete `~/.bitwize-music/config.yaml`\n4. Ask if they want to run setup now\n\n**Example:**\n```\n⚠️  This will delete your configuration at ~/.bitwize-music/config.yaml\n\nCurrent config will be backed up to config.yaml.bak\n\nAre you sure you want to reset? (yes/no)\n```\n\nIf yes:\n```\n✓ Backed up to ~/.bitwize-music/config.yaml.bak\n✓ Deleted ~/.bitwize-music/config.yaml\n\nConfig has been reset.\n\nWould you like to set up a new config now? (yes/no)\n```\n\n---\n\n## Config Template\n\nWhen creating a new config, use this structure:\n\n```yaml\n# bitwize-music Plugin Configuration\n# Generated by /configure\n\nartist:\n  name: \"{artist_name}\"\n  genres:\n    - \"{genre1}\"\n    - \"{genre2}\"\n\npaths:\n  content_root: \"{content_root}\"\n  audio_root: \"{audio_root}\"\n  documents_root: \"{documents_root}\"\n  overrides: \"{overrides}\"\n  ideas_file: \"{ideas_file}\"\n\nurls:\n  soundcloud: \"{soundcloud_url}\"\n\ngeneration:\n  service: suno\n```\n\n---\n\n## Edge Cases\n\n### Config exists but is invalid YAML\n- Back up the existing file: `config.yaml.bak`\n- Offer to create fresh config\n\n### Directory doesn''t exist\n- Offer to create it: \"Directory ~/music-projects doesn''t exist. Create it?\"\n\n### User provides relative path\n- Expand to absolute: `./projects` → `/Users/name/projects`\n- Or use `~` prefix: `~/projects`\n\n---\n\n## Remember\n\n- **Preserve exact casing** - If user says \"bitwize\", write \"bitwize\" not \"Bitwize\"\n- Always expand `~` in paths for display\n- Create directories if they don''t exist (with permission)\n- Back up existing config before overwriting\n- Validate after any changes\n- Be friendly and explain what each setting does\n"},"lastSynced":"2026-03-08T02:14:05.509Z","agentAnalysis":{"suitability":{"en":"Perfect for Music Production Agents needing efficient configuration management for AI music production workflows.","zh":"非常适合需要高效配置管理的音乐制作代理人，用于AI音乐制作工作流程。","ja":"AI音楽制作ワークフローにおいて効率的な設定管理が必要な音楽制作エージェントに最適です。","ko":"AI 음악 제작 워크플로우에 효율적인 구성 관리가 필요한 음악 제작 에이전트에게 완벽합니다.","es":"Perfecto para agentes de producción de música que necesitan una gestión de configuración eficiente para flujos de trabajo de producción de música de inteligencia artificial.","fr":"Parfait pour les agents de production musicale qui ont besoin d''une gestion de configuration efficace pour les flux de travail de production musicale d''intelligence artificielle.","de":"Perfekt für Musikproduktionsagenten, die eine effiziente Konfigurationsverwaltung für KI-Musikproduktions-Workflows benötigen.","pt":"Perfeito para Agentes de Produção de Música que necessitam de gerenciamento de configuração eficiente para fluxos de trabalho de produção de música de IA.","ru":"Идеально для агентов музыкальной продукции, которым необходим эффективный менеджмент конфигурации для рабочих процессов музыкальной продукции ИИ.","ar":"مثالي لعمليات إنتاج الموسيقى التي تحتاج إلى إدارة التهيئة الفعالة لتدفقات عمل إنتاج الموسيقى بالذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to manage config.yaml files, facilitating interactive setup and editing of music production settings using YAML file formats and supporting protocols like file system access.","zh":"赋予代理人管理config.yaml文件的能力，通过YAML文件格式和支持的协议，如文件系统访问，实现交互式设置和编辑音乐制作设置。","ja":"エージェントにconfig.yamlファイルを管理する能力を与え、YAMLファイル形式やファイルシステムアクセスなどのサポートプロトコルを使用して、音楽制作設定のインタラクティブな設定と編集を容易にします。","ko":"에이전트에게 config.yaml 파일을 관리할 수 있는 능력을 부여하여 YAML 파일 형식 및 파일 시스템 액세스와 같은 지원 프로토콜을 사용하여 음악 제작 설정의 상호 작용 설정 및 편집을 용이하게 합니다.","es":"Habilita a los agentes a gestionar archivos config.yaml, facilitando la configuración y edición interactiva de la configuración de la producción de música utilizando formatos de archivo YAML y protocolos de soporte como el acceso al sistema de archivos.","fr":"Permet aux agents de gérer les fichiers config.yaml, facilitant la configuration et l''édition interactive des paramètres de production musicale en utilisant des formats de fichiers YAML et des protocoles de support tels que l''accès au système de fichiers.","de":"Ermächtigt Agenten, Konfigurationsdateien (config.yaml) zu verwalten, wodurch die interaktive Einrichtung und Bearbeitung von Musikproduktions-Einstellungen mithilfe von YAML-Dateiformaten und unterstützenden Protokollen wie Dateisystemzugriff erleichtert wird.","pt":"Habilita agentes a gerenciar arquivos config.yaml, facilitando a configuração interativa e edição de configurações de produção de música usando formatos de arquivo YAML e protocolos de suporte como acesso ao sistema de arquivos.","ru":"Наделяет агентов возможностью управлять файлами config.yaml, облегчая интерактивную настройку и редактирование настроек музыкальной продукции с использованием форматов файлов YAML и поддерживающих протоколов, таких как доступ к файловой системе.","ar":"يمكّن الوكلاء من إدارة ملفات config.yaml، ويتيسر إعداد التهيئة التفاعلية وتحرير إعدادات إنتاج الموسيقى باستخدام تنسيقات ملف YAML والبروتوكولات المدعومة مثل وصول نظام الملفات."},"useCases":{"en":["Setting up music production workflows","Editing specific settings in config.yaml","Validating config files for issues"],"zh":["设置音乐制作工作流程","编辑config.yaml中的特定设置","验证配置文件中的问题"],"ja":["音楽制作ワークフローの設定","config.yaml内の特定の設定の編集","設定ファイルの問題の検証"],"ko":["음악 제작 워크플로우 설정","config.yaml의 특정 설정 편집","구성 파일의 문제 검증"],"es":["Configuración de flujos de trabajo de producción de música","Edición de ajustes específicos en config.yaml","Validación de archivos de configuración para problemas"],"fr":["Configuration de flux de travail de production musicale","Édition de paramètres spécifiques dans config.yaml","Validation de fichiers de configuration pour les problèmes"],"de":["Einrichtung von Musikproduktions-Workflows","Bearbeitung spezifischer Einstellungen in config.yaml","Validierung von Konfigurationsdateien auf Probleme"],"pt":["Configuração de fluxos de trabalho de produção de música","Edição de configurações específicas em config.yaml","Validação de arquivos de configuração para problemas"],"ru":["Настройка рабочих процессов музыкальной продукции","Редактирование конкретных настроек в config.yaml","Проверка файлов конфигурации на наличие проблем"],"ar":["تهيئة تدفقات عمل إنتاج الموسيقى","تحرير إعدادات محددة في config.yaml","التحقق من صحة ملفات التهيئة للقضايا"]},"limitations":{"en":["Requires access to ~/.bitwize-music/config.yaml file","Dependent on YAML file format"],"zh":["需要访问~/.bitwize-music/config.yaml文件","依赖于YAML文件格式"],"ja":["~/.bitwize-music/config.yamlファイルへのアクセスが必要","YAMLファイル形式に依存している"],"ko":["~/.bitwize-music/config.yaml 파일에 액세스해야 함","YAML 파일 형식에 의존"],"es":["Requiere acceso al archivo ~/.bitwize-music/config.yaml","Dependiente del formato de archivo YAML"],"fr":["Nécessite un accès au fichier ~/.bitwize-music/config.yaml","Dépendant du format de fichier YAML"],"de":["Erfordert Zugriff auf die Datei ~/.bitwize-music/config.yaml","Abhängig vom YAML-Dateiformat"],"pt":["Exige acesso ao arquivo ~/.bitwize-music/config.yaml","Dependente do formato de arquivo YAML"],"ru":["Требует доступа к файлу ~/.bitwize-music/config.yaml","Зависит от формата файла YAML"],"ar":["يتطلب الوصول إلى ملف ~/.bitwize-music/config.yaml","يعتمد على تنسيق ملف YAML"]},"version":4},"contentHash":"61ee61fada86acae4e11c70b8404dfb91d01e3eebf978fb20aea9027f4ab403e","qualityScore":45}');
