INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rdjakovic/todo2/testing-tauri-apps', 'testing-tauri-apps', 'rdjakovic', 'todo2', 'community', 'testing-tauri-apps rdjakovic todo2 community The testing-tauri-apps skill enables developers to test Tauri applications using unit testing with mocks and end-to-end testing with WebDriver, supporting CI integration. 本技能介绍了 Tauri v2 应用程序的测试策略，包括单元测试、端到端测试和 CI 集成 このスキルでは、Tauri v2 アプリケーションのテスト戦略について説明します。ユニットテスト、エンドツーエンドテスト、CI 統合が含まれます 이 스킬은 Tauri v2 애플리케이션의 테스트 전략을 소개합니다. 유닛 테스트, 엔드 투 엔드 테스트, CI 통합이 포함됩니다 El skill testing-tauri-apps cubre estrategias de testing para aplicaciones Tauri v2, incluyendo testing de unidad y extremo a extremo. Le skill testing-tauri-apps couvre les stratégies de testing pour les applications Tauri v2, notamment les tests unitaires et de bout en bout. Das Skill testing-tauri-apps deckt Teststrategien für Tauri-v2-Anwendungen ab, einschließlich Einheits- und End-to-End-Testing. O skill de testes de aplicativos Tauri cobre estratégias de teste unitário e de ponta a ponta para aplicativos Tauri v2 Навык тестирования приложений Tauri охватывает стратегии юнит-тестирования и тестирования от начала до конца для приложений Tauri v2 مهارة اختبار تطبيقات Tauri تغطي استراتيجيات الاختبار الوحدوي واختبار النهاية إلى النهاية لتطبيقات Tauri v2 how to test Tauri apps testing-tauri-apps setup guide Tauri v2 testing strategies WebDriver protocol for Tauri CI integration for Tauri testing testing-tauri-apps vs Jest install testing-tauri-apps what is testing-tauri-apps testing-tauri-apps alternative Tauri app testing best practices Tauri 应用程序测试 Tauri v2 测试 单元测试 端到端测试 CI 集成 WebDriver Tauri API 模拟 Supports unit/integration testing with mock runtime using @tauri-apps/api/mocks Enables end-to-end testing with WebDriver protocol for browser automation Allows CI integration for seamless testing Uses @tauri-apps/api/mocks module to simulate Tauri APIs Covers testing approaches overview for Tauri v2 applications testing-tauri-apps is a skill that covers testing strategies for Tauri v2 applications, including unit and end-to-end testing methodologies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('charl-kruger/charl/wrangler', 'community', 'charl-kruger', 'charl', 'charl-kruger/charl', 'wrangler', 6, 2, 45, '2026-02-03T12:23:27Z', '2026-03-06T06:53:16.321Z', '0221396d5c3bc0a2995f32dcb107fc0be4d7f897546bd1379b9bbc1699eec1b8', '{"id":"charl-kruger/charl/wrangler","name":"wrangler","description":{"en":"The Wrangler skill enables developers to deploy, develop, and manage Cloudflare Workers and associated resources. It provides a command-line interface for efficient workflow management.","zh":"Wrangler 是一种命令行工具，用于部署、开发和管理 Cloudflare Workers。它支持 JSON 配置和兼容性日期设置","ja":"Wrangler は、Cloudflare Workers を開発および管理するための CLI ツールです。JSON 構成と互換性日設定をサポートしています","ko":"Wrangler는 클라우드플레어 워커를 배포, 개발 및 관리하는 명령줄 도구입니다. JSON 구성 및 호환성 날짜 설정을 지원합니다","es":"Wrangler es una herramienta de línea de comandos para deployar y gestionar Workers de Cloudflare","fr":"Wrangler est un outil en ligne de commande pour déployer et gérer les Workers Cloudflare","de":"Wrangler ist ein Kommandozeilen-Tool zum Bereitstellen und Verwalten von Cloudflare-Workern","pt":"O Wrangler é uma ferramenta de linha de comando para desenvolver e gerenciar Cloudflare Workers. Veja como configurá-lo e usá-lo.","ru":"Wrangler - это инструмент командной строки для разработки и управления Cloudflare Workers. Узнайте, как настроить и использовать его с помощью ИИ Агентов.","ar":"Wrangler هو أداة سطر أوامر لتطوير و إدارة Cloudflare Workers. تعلم كيفية إعدادها و استخدامها مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Wrangler: Cloudflare Workers Setup Guide | AI Agent Skill","zh":"Wrangler Setup Guide: Cloudflare Workers 部署与管理","ja":"Wrangler のベストプラクティス: AIエージェントによる Cloudflare Workers の開発","ko":"Wrangler 설치 가이드: 클라우드플레어 워커 개발 및 관리","es":"Guía de configuración de Wrangler para Cloudflare Workers","fr":"Guide de démarrage de Wrangler pour les Workers Cloudflare","de":"Wrangler-Setup-Leitfaden für Cloudflare-Entwickler","pt":"Guia de Configuração do Wrangler: Desenvolvimento de Clou...","ru":"Настройка Wrangler: Разработка и управление Cloudflare Wo...","ar":"دليل إعداد Wrangler: تطوير و إدارة Cloudflare Workers باس..."},"description":{"en":"Discover how to deploy, develop, and manage Cloudflare Workers with Wrangler CLI. Get started with our expert setup guide and unlock its full potential.","zh":"学习如何使用 Wrangler CLI部署、开发和管理 Cloudflare Workers，包括 JSON 配置和兼容性日期设置","ja":"Wrangler の使い方を学習し、Cloudflare Workers の開発と管理を最適化する方法を発見しましょう","ko":"Wrangler CLI를 사용하여 클라우드플레어 워커를 배포, 개발 및 관리하는 방법을 알아보세요","es":"Aprende a instalar y configurar Wrangler para deployar y gestionar Workers de Cloudflare con facilidad","fr":"Découvrez comment installer et configurer Wrangler pour déployer et gérer les Workers Cloudflare avec facilité","de":"Erfahren Sie, wie Sie Wrangler installieren und konfigurieren, um Cloudflare-Worker bereitzustellen und zu verwalten","pt":"Aprenda a configurar o Wrangler para desenvolver e gerenciar Cloudflare Workers. Veja as melhores práticas e dicas para começar.","ru":"Узнайте, как настроить Wrangler для разработки и управления Cloudflare Workers. Просмотрите лучшие практики и советы для начала работы с ИИ Агентами.","ar":"تعلم كيفية إعداد Wrangler لتطوير و إدارة Cloudflare Workers. استكشف أفضل الممارسات و النصائح للبدء في استخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"Wrangler is a CLI tool for deploying, developing, and managing Cloudflare Workers and related resources, utilizing JSON config and compatibility dates.","zh":"Wrangler 是一种用于部署、开发和管理 Cloudflare Workers 的命令行工具","ja":"Wrangler は、Cloudflare Workers の開発および管理に使用される CLI ツールです","ko":"Wrangler는 클라우드플레어 워커를 배포, 개발 및 관리하는 명령줄 도구입니다","es":"Wrangler es una herramienta de CLI para Cloudflare Workers","fr":"Wrangler est un outil de ligne de commande pour les Workers Cloudflare","de":"Wrangler ist ein Kommandozeilen-Tool für Cloudflare-Worker","pt":"Wrangler é uma ferramenta de linha de comando para desenvolver e gerenciar Cloudflare Workers e recursos associados.","ru":"Wrangler - это инструмент командной строки для разработки, развертывания и управления Cloudflare Workers и связанными ресурсами с помощью ИИ Агентов.","ar":"Wrangler هو أداة سطر أوامر لتطوير و نشر و إدارة Cloudflare Workers و الموارد المرتبطة بها باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Verifies Wrangler installation using the `wrangler --version` command","Installs Wrangler using `npm install -D wrangler@latest`","Supports JSON config via `wrangler.jsonc` files","Requires setting a recent `compatibility_date` for optimal performance","Enables management of Cloudflare Workers and associated resources"],"zh":["支持 JSON 配置","兼容性日期设置","Cloudflare Workers 的部署和管理","支持 wrangler.jsonc 配置文件","兼容性日期设置检查"],"ja":["JSON 構成のサポート","互換性日設定","Cloudflare Workers のデプロイと管理","wrangler.jsonc 構成ファイルのサポート","互換性日設定のチェック"],"ko":["JSON 구성 지원","호환성 날짜 설정","클라우드플레어 워커의 배포 및 관리","wrangler.jsonc 구성 파일 지원","호환성 날짜 설정 확인"],"es":["Instalación y configuración de Wrangler","Uso de wrangler.jsonc para la configuración","Configuración de la fecha de compatibilidad","Deploy de Workers de Cloudflare","Gestión de recursos asociados"],"fr":["Installation et configuration de Wrangler","Utilisation de wrangler.jsonc pour la configuration","Configuration de la date de compatibilité","Déploiement de Workers Cloudflare","Gestion des ressources associées"],"de":["Installation und Konfiguration von Wrangler","Verwendung von wrangler.jsonc für die Konfiguration","Konfiguration des Kompatibilitätsdatums","Bereitstellung von Cloudflare-Workern","Verwaltung von zugehörigen Ressourcen"],"pt":["Instalação do Wrangler via npm","Uso do arquivo wrangler.jsonc para configuração","Definição da data de compatibilidade para recursos mais recentes","Verificação da versão do Wrangler","Desenvolvimento e gerenciamento de Cloudflare Workers"],"ru":["Установка Wrangler через npm","Использование файла wrangler.jsonc для конфигурации","Определение даты совместимости для новых функций","Проверка версии Wrangler","Разработка и управление Cloudflare Workers с помощью ИИ Агентов"],"ar":["تثبيت Wrangler عبر npm","استخدام ملف wrangler.jsonc للتهيئة","تحديد تاريخ التوافق لاستخدام الميزات الحديثة","فحص إصدار Wrangler","تطوير و إدارة Cloudflare Workers باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use wrangler","wrangler setup guide","cloudflare workers tutorial","wrangler vs serverless","wrangler install","wrangler json config","what is wrangler","wrangler compatibility dates","wrangler alternative"],"zh":["Wrangler","Cloudflare Workers","JSON 配置","兼容性日期设置","命令行工具","AIエージェント","云计算"],"ja":["Wrangler","Cloudflare Workers","JSON 構成","互換性日設定","CLI ツール","AIエージェント","クラウドコンピューティング"],"ko":["Wrangler","클라우드플레어 워커","JSON 구성","호환성 날짜 설정","명령줄 도구","AI 에이전트","클라우드 컴퓨팅"],"es":["Wrangler Cloudflare","Workers de Cloudflare","CLI para Cloudflare","Instalación de Wrangler","Configuración de Wrangler","Desarrollo de Workers","Gestión de Workers","Cloudflare Workers tutorial"],"fr":["Wrangler Cloudflare","Workers Cloudflare","CLI pour Cloudflare","Installation de Wrangler","Configuration de Wrangler","Développement de Workers","Gestion de Workers","Tutoriel Cloudflare Workers"],"de":["Wrangler Cloudflare","Cloudflare-Worker","CLI für Cloudflare","Installation von Wrangler","Konfiguration von Wrangler","Entwicklung von Workern","Verwaltung von Workern","Cloudflare-Worker-Tutorial"],"pt":["Wrangler","Cloudflare Workers","desenvolvimento web","ferramenta de linha de comando","npm","wrangler.jsonc","compatibilidade","recursos de desenvolvimento"],"ru":["Wrangler","Cloudflare Workers","разработка веб-приложений","инструмент командной строки","npm","wrangler.jsonc","совместимость","функции разработки","ИИ Агенты"],"ar":["Wrangler","Cloudflare Workers","تطوير الويب","أداة سطر الأوامر","npm","wrangler.jsonc","التوافق","ميزات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"charl-kruger","repo":"charl","repoPath":"charl-kruger/charl","stars":6,"forks":2,"updatedAt":"2026-02-03T12:23:27Z","topics":[],"category":"community","skillMd":{"name":"wrangler","description":"Cloudflare Workers CLI for deploying, developing, and managing Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines, and Secrets Store. Load before running wrangler commands to ensure correct syntax and best practices.","bodyPreview":"# Wrangler CLI\n\nDeploy, develop, and manage Cloudflare Workers and associated resources.\n\n## FIRST: Verify Wrangler Installation\n\n```bash\nwrangler --version  # Requires v4.x+\n```\n\nIf not installed:\n\n```bash\nnpm install -D wrangler@latest\n```\n\n## Key Guidelines\n\n- **Use `wrangler.jsonc`**: Prefer JSON config over TOML. Newer features are JSON-only.\n- **Set `compatibility_date`**: Use a recent date (within 30 days). Check https://developers.cloudflare.com/workers/configuration/compatibility-dates/","body":"# Wrangler CLI\n\nDeploy, develop, and manage Cloudflare Workers and associated resources.\n\n## FIRST: Verify Wrangler Installation\n\n```bash\nwrangler --version  # Requires v4.x+\n```\n\nIf not installed:\n\n```bash\nnpm install -D wrangler@latest\n```\n\n## Key Guidelines\n\n- **Use `wrangler.jsonc`**: Prefer JSON config over TOML. Newer features are JSON-only.\n- **Set `compatibility_date`**: Use a recent date (within 30 days). Check https://developers.cloudflare.com/workers/configuration/compatibility-dates/\n- **Generate types after config changes**: Run `wrangler types` to update TypeScript bindings.\n- **Local dev defaults to local storage**: Bindings use local simulation unless `remote: true`.\n- **Validate config before deploy**: Run `wrangler check` to catch errors early.\n- **Use environments for staging/prod**: Define `env.staging` and `env.production` in config.\n\n## Quick Start: New Worker\n\n```bash\n# Initialize new project\nnpx wrangler init my-worker\n\n# Or with a framework\nnpx create-cloudflare@latest my-app\n```\n\n## Quick Reference: Core Commands\n\n| Task                      | Command                     |\n| ------------------------- | --------------------------- |\n| Start local dev server    | `wrangler dev`              |\n| Deploy to Cloudflare      | `wrangler deploy`           |\n| Deploy dry run            | `wrangler deploy --dry-run` |\n| Generate TypeScript types | `wrangler types`            |\n| Validate configuration    | `wrangler check`            |\n| View live logs            | `wrangler tail`             |\n| Delete Worker             | `wrangler delete`           |\n| Auth status               | `wrangler whoami`           |\n\n---\n\n## Configuration (wrangler.jsonc)\n\n### Minimal Config\n\n```jsonc\n{\n  \"$schema\": \"./node_modules/wrangler/config-schema.json\",\n  \"name\": \"my-worker\",\n  \"main\": \"src/index.ts\",\n  \"compatibility_date\": \"2026-01-01\"\n}\n```\n\n### Full Config with Bindings\n\n```jsonc\n{\n  \"$schema\": \"./node_modules/wrangler/config-schema.json\",\n  \"name\": \"my-worker\",\n  \"main\": \"src/index.ts\",\n  \"compatibility_date\": \"2026-01-01\",\n  \"compatibility_flags\": [\"nodejs_compat_v2\"],\n\n  // Environment variables\n  \"vars\": {\n    \"ENVIRONMENT\": \"production\"\n  },\n\n  // KV Namespace\n  \"kv_namespaces\": [{ \"binding\": \"KV\", \"id\": \"<KV_NAMESPACE_ID>\" }],\n\n  // R2 Bucket\n  \"r2_buckets\": [{ \"binding\": \"BUCKET\", \"bucket_name\": \"my-bucket\" }],\n\n  // D1 Database\n  \"d1_databases\": [\n    { \"binding\": \"DB\", \"database_name\": \"my-db\", \"database_id\": \"<DB_ID>\" }\n  ],\n\n  // Workers AI (always remote)\n  \"ai\": { \"binding\": \"AI\" },\n\n  // Vectorize\n  \"vectorize\": [{ \"binding\": \"VECTOR_INDEX\", \"index_name\": \"my-index\" }],\n\n  // Hyperdrive\n  \"hyperdrive\": [{ \"binding\": \"HYPERDRIVE\", \"id\": \"<HYPERDRIVE_ID>\" }],\n\n  // Durable Objects\n  \"durable_objects\": {\n    \"bindings\": [{ \"name\": \"COUNTER\", \"class_name\": \"Counter\" }]\n  },\n\n  // Cron triggers\n  \"triggers\": {\n    \"crons\": [\"0 * * * *\"]\n  },\n\n  // Environments\n  \"env\": {\n    \"staging\": {\n      \"name\": \"my-worker-staging\",\n      \"vars\": { \"ENVIRONMENT\": \"staging\" }\n    }\n  }\n}\n```\n\n### Generate Types from Config\n\n```bash\n# Generate worker-configuration.d.ts\nwrangler types\n\n# Custom output path\nwrangler types ./src/env.d.ts\n\n# Check types are up to date (CI)\nwrangler types --check\n```\n\n---\n\n## Local Development\n\n### Start Dev Server\n\n```bash\n# Local mode (default) - uses local storage simulation\nwrangler dev\n\n# With specific environment\nwrangler dev --env staging\n\n# Force local-only (disable remote bindings)\nwrangler dev --local\n\n# Remote mode - runs on Cloudflare edge (legacy)\nwrangler dev --remote\n\n# Custom port\nwrangler dev --port 8787\n\n# Live reload for HTML changes\nwrangler dev --live-reload\n\n# Test scheduled/cron handlers\nwrangler dev --test-scheduled\n# Then visit: http://localhost:8787/__scheduled\n```\n\n### Remote Bindings for Local Dev\n\nUse `remote: true` in binding config to connect to real resources while running locally:\n\n```jsonc\n{\n  \"r2_buckets\": [\n    { \"binding\": \"BUCKET\", \"bucket_name\": \"my-bucket\", \"remote\": true }\n  ],\n  \"ai\": { \"binding\": \"AI\", \"remote\": true },\n  \"vectorize\": [\n    { \"binding\": \"INDEX\", \"index_name\": \"my-index\", \"remote\": true }\n  ]\n}\n```\n\n**Recommended remote bindings**: AI (required), Vectorize, Browser Rendering, mTLS, Images.\n\n### Local Secrets\n\nCreate `.dev.vars` for local development secrets:\n\n```\nAPI_KEY=local-dev-key\nDATABASE_URL=postgres://localhost:5432/dev\n```\n\n---\n\n## Deployment\n\n### Deploy Worker\n\n```bash\n# Deploy to production\nwrangler deploy\n\n# Deploy specific environment\nwrangler deploy --env staging\n\n# Dry run (validate without deploying)\nwrangler deploy --dry-run\n\n# Keep dashboard-set variables\nwrangler deploy --keep-vars\n\n# Minify code\nwrangler deploy --minify\n```\n\n### Manage Secrets\n\n```bash\n# Set secret interactively\nwrangler secret put API_KEY\n\n# Set from stdin\necho \"secret-value\" | wrangler secret put API_KEY\n\n# List secrets\nwrangler secret list\n\n# Delete secret\nwrangler secret delete API_KEY\n\n# Bulk secrets from JSON file\nwrangler secret bulk secrets.json\n```\n\n### Versions and Rollback\n\n```bash\n# List recent versions\nwrangler versions list\n\n# View specific version\nwrangler versions view <VERSION_ID>\n\n# Rollback to previous version\nwrangler rollback\n\n# Rollback to specific version\nwrangler rollback <VERSION_ID>\n```\n\n---\n\n## KV (Key-Value Store)\n\n### Manage Namespaces\n\n```bash\n# Create namespace\nwrangler kv namespace create MY_KV\n\n# List namespaces\nwrangler kv namespace list\n\n# Delete namespace\nwrangler kv namespace delete --namespace-id <ID>\n```\n\n### Manage Keys\n\n```bash\n# Put value\nwrangler kv key put --namespace-id <ID> \"key\" \"value\"\n\n# Put with expiration (seconds)\nwrangler kv key put --namespace-id <ID> \"key\" \"value\" --expiration-ttl 3600\n\n# Get value\nwrangler kv key get --namespace-id <ID> \"key\"\n\n# List keys\nwrangler kv key list --namespace-id <ID>\n\n# Delete key\nwrangler kv key delete --namespace-id <ID> \"key\"\n\n# Bulk put from JSON\nwrangler kv bulk put --namespace-id <ID> data.json\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"kv_namespaces\": [{ \"binding\": \"CACHE\", \"id\": \"<NAMESPACE_ID>\" }]\n}\n```\n\n---\n\n## R2 (Object Storage)\n\n### Manage Buckets\n\n```bash\n# Create bucket\nwrangler r2 bucket create my-bucket\n\n# Create with location hint\nwrangler r2 bucket create my-bucket --location wnam\n\n# List buckets\nwrangler r2 bucket list\n\n# Get bucket info\nwrangler r2 bucket info my-bucket\n\n# Delete bucket\nwrangler r2 bucket delete my-bucket\n```\n\n### Manage Objects\n\n```bash\n# Upload object\nwrangler r2 object put my-bucket/path/file.txt --file ./local-file.txt\n\n# Download object\nwrangler r2 object get my-bucket/path/file.txt\n\n# Delete object\nwrangler r2 object delete my-bucket/path/file.txt\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"r2_buckets\": [{ \"binding\": \"ASSETS\", \"bucket_name\": \"my-bucket\" }]\n}\n```\n\n---\n\n## D1 (SQL Database)\n\n### Manage Databases\n\n```bash\n# Create database\nwrangler d1 create my-database\n\n# Create with location\nwrangler d1 create my-database --location wnam\n\n# List databases\nwrangler d1 list\n\n# Get database info\nwrangler d1 info my-database\n\n# Delete database\nwrangler d1 delete my-database\n```\n\n### Execute SQL\n\n```bash\n# Execute SQL command (remote)\nwrangler d1 execute my-database --remote --command \"SELECT * FROM users\"\n\n# Execute SQL file (remote)\nwrangler d1 execute my-database --remote --file ./schema.sql\n\n# Execute locally\nwrangler d1 execute my-database --local --command \"SELECT * FROM users\"\n```\n\n### Migrations\n\n```bash\n# Create migration\nwrangler d1 migrations create my-database create_users_table\n\n# List pending migrations\nwrangler d1 migrations list my-database --local\n\n# Apply migrations locally\nwrangler d1 migrations apply my-database --local\n\n# Apply migrations to remote\nwrangler d1 migrations apply my-database --remote\n```\n\n### Export/Backup\n\n```bash\n# Export schema and data\nwrangler d1 export my-database --remote --output backup.sql\n\n# Export schema only\nwrangler d1 export my-database --remote --output schema.sql --no-data\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"d1_databases\": [\n    {\n      \"binding\": \"DB\",\n      \"database_name\": \"my-database\",\n      \"database_id\": \"<DATABASE_ID>\",\n      \"migrations_dir\": \"./migrations\"\n    }\n  ]\n}\n```\n\n---\n\n## Vectorize (Vector Database)\n\n### Manage Indexes\n\n```bash\n# Create index with dimensions\nwrangler vectorize create my-index --dimensions 768 --metric cosine\n\n# Create with preset (auto-configures dimensions/metric)\nwrangler vectorize create my-index --preset @cf/baai/bge-base-en-v1.5\n\n# List indexes\nwrangler vectorize list\n\n# Get index info\nwrangler vectorize get my-index\n\n# Delete index\nwrangler vectorize delete my-index\n```\n\n### Manage Vectors\n\n```bash\n# Insert vectors from NDJSON file\nwrangler vectorize insert my-index --file vectors.ndjson\n\n# Query vectors\nwrangler vectorize query my-index --vector \"[0.1, 0.2, ...]\" --top-k 10\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"vectorize\": [{ \"binding\": \"SEARCH_INDEX\", \"index_name\": \"my-index\" }]\n}\n```\n\n---\n\n## Hyperdrive (Database Accelerator)\n\n### Manage Configs\n\n```bash\n# Create config\nwrangler hyperdrive create my-hyperdrive \\\n  --connection-string \"postgres://user:pass@host:5432/database\"\n\n# List configs\nwrangler hyperdrive list\n\n# Get config details\nwrangler hyperdrive get <HYPERDRIVE_ID>\n\n# Update config\nwrangler hyperdrive update <HYPERDRIVE_ID> --origin-password \"new-password\"\n\n# Delete config\nwrangler hyperdrive delete <HYPERDRIVE_ID>\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"compatibility_flags\": [\"nodejs_compat_v2\"],\n  \"hyperdrive\": [{ \"binding\": \"HYPERDRIVE\", \"id\": \"<HYPERDRIVE_ID>\" }]\n}\n```\n\n---\n\n## Workers AI\n\n### List Models\n\n```bash\n# List available models\nwrangler ai models\n\n# List finetunes\nwrangler ai finetune list\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"ai\": { \"binding\": \"AI\" }\n}\n```\n\n**Note**: Workers AI always runs remotely and incurs usage charges even in local dev.\n\n---\n\n## Queues\n\n### Manage Queues\n\n```bash\n# Create queue\nwrangler queues create my-queue\n\n# List queues\nwrangler queues list\n\n# Delete queue\nwrangler queues delete my-queue\n\n# Add consumer to queue\nwrangler queues consumer add my-queue my-worker\n\n# Remove consumer\nwrangler queues consumer remove my-queue my-worker\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"queues\": {\n    \"producers\": [{ \"binding\": \"MY_QUEUE\", \"queue\": \"my-queue\" }],\n    \"consumers\": [\n      {\n        \"queue\": \"my-queue\",\n        \"max_batch_size\": 10,\n        \"max_batch_timeout\": 30\n      }\n    ]\n  }\n}\n```\n\n---\n\n## Containers\n\n### Build and Push Images\n\n```bash\n# Build container image\nwrangler containers build -t my-app:latest .\n\n# Build and push in one command\nwrangler containers build -t my-app:latest . --push\n\n# Push existing image to Cloudflare registry\nwrangler containers push my-app:latest\n```\n\n### Manage Containers\n\n```bash\n# List containers\nwrangler containers list\n\n# Get container info\nwrangler containers info <CONTAINER_ID>\n\n# Delete container\nwrangler containers delete <CONTAINER_ID>\n```\n\n### Manage Images\n\n```bash\n# List images in registry\nwrangler containers images list\n\n# Delete image\nwrangler containers images delete my-app:latest\n```\n\n### Manage External Registries\n\n```bash\n# List configured registries\nwrangler containers registries list\n\n# Configure external registry (e.g., ECR)\nwrangler containers registries configure <DOMAIN> \\\n  --public-credential <AWS_ACCESS_KEY_ID>\n\n# Delete registry configuration\nwrangler containers registries delete <DOMAIN>\n```\n\n---\n\n## Workflows\n\n### Manage Workflows\n\n```bash\n# List workflows\nwrangler workflows list\n\n# Describe workflow\nwrangler workflows describe my-workflow\n\n# Trigger workflow instance\nwrangler workflows trigger my-workflow\n\n# Trigger with parameters\nwrangler workflows trigger my-workflow --params ''{\"key\": \"value\"}''\n\n# Delete workflow\nwrangler workflows delete my-workflow\n```\n\n### Manage Workflow Instances\n\n```bash\n# List instances\nwrangler workflows instances list my-workflow\n\n# Describe instance\nwrangler workflows instances describe my-workflow <INSTANCE_ID>\n\n# Terminate instance\nwrangler workflows instances terminate my-workflow <INSTANCE_ID>\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"workflows\": [\n    {\n      \"binding\": \"MY_WORKFLOW\",\n      \"name\": \"my-workflow\",\n      \"class_name\": \"MyWorkflow\"\n    }\n  ]\n}\n```\n\n---\n\n## Pipelines\n\n### Manage Pipelines\n\n```bash\n# Create pipeline\nwrangler pipelines create my-pipeline --r2 my-bucket\n\n# List pipelines\nwrangler pipelines list\n\n# Show pipeline details\nwrangler pipelines show my-pipeline\n\n# Update pipeline\nwrangler pipelines update my-pipeline --batch-max-mb 100\n\n# Delete pipeline\nwrangler pipelines delete my-pipeline\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"pipelines\": [{ \"binding\": \"MY_PIPELINE\", \"pipeline\": \"my-pipeline\" }]\n}\n```\n\n---\n\n## Secrets Store\n\n### Manage Stores\n\n```bash\n# Create store\nwrangler secrets-store store create my-store\n\n# List stores\nwrangler secrets-store store list\n\n# Delete store\nwrangler secrets-store store delete <STORE_ID>\n```\n\n### Manage Secrets in Store\n\n```bash\n# Add secret to store\nwrangler secrets-store secret put <STORE_ID> my-secret\n\n# List secrets in store\nwrangler secrets-store secret list <STORE_ID>\n\n# Get secret\nwrangler secrets-store secret get <STORE_ID> my-secret\n\n# Delete secret from store\nwrangler secrets-store secret delete <STORE_ID> my-secret\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"secrets_store_secrets\": [\n    {\n      \"binding\": \"MY_SECRET\",\n      \"store_id\": \"<STORE_ID>\",\n      \"secret_name\": \"my-secret\"\n    }\n  ]\n}\n```\n\n---\n\n## Pages (Frontend Deployment)\n\n```bash\n# Create Pages project\nwrangler pages project create my-site\n\n# Deploy directory to Pages\nwrangler pages deploy ./dist\n\n# Deploy with specific branch\nwrangler pages deploy ./dist --branch main\n\n# List deployments\nwrangler pages deployment list --project-name my-site\n```\n\n---\n\n## Observability\n\n### Tail Logs\n\n```bash\n# Stream live logs\nwrangler tail\n\n# Tail specific Worker\nwrangler tail my-worker\n\n# Filter by status\nwrangler tail --status error\n\n# Filter by search term\nwrangler tail --search \"error\"\n\n# JSON output\nwrangler tail --format json\n```\n\n### Config Logging\n\n```jsonc\n{\n  \"observability\": {\n    \"enabled\": true,\n    \"head_sampling_rate\": 1\n  }\n}\n```\n\n---\n\n## Testing\n\n### Local Testing with Vitest\n\n```bash\nnpm install -D @cloudflare/vitest-pool-workers vitest\n```\n\n`vitest.config.ts`:\n\n```typescript\nimport { defineWorkersConfig } from \"@cloudflare/vitest-pool-workers/config\";\n\nexport default defineWorkersConfig({\n  test: {\n    poolOptions: {\n      workers: {\n        wrangler: { configPath: \"./wrangler.jsonc\" }\n      }\n    }\n  }\n});\n```\n\n### Test Scheduled Events\n\n```bash\n# Enable in dev\nwrangler dev --test-scheduled\n\n# Trigger via HTTP\ncurl http://localhost:8787/__scheduled\n```\n\n---\n\n## Troubleshooting\n\n### Common Issues\n\n| Issue                           | Solution                                   |\n| ------------------------------- | ------------------------------------------ |\n| `command not found: wrangler`   | Install: `npm install -D wrangler`         |\n| Auth errors                     | Run `wrangler login`                       |\n| Config validation errors        | Run `wrangler check`                       |\n| Type errors after config change | Run `wrangler types`                       |\n| Local storage not persisting    | Check `.wrangler/state` directory          |\n| Binding undefined in Worker     | Verify binding name matches config exactly |\n\n### Debug Commands\n\n```bash\n# Check auth status\nwrangler whoami\n\n# Validate config\nwrangler check\n\n# View config schema\nwrangler docs configuration\n```\n\n---\n\n## Best Practices\n\n1. **Version control `wrangler.jsonc`**: Treat as source of truth for Worker config.\n2. **Use automatic provisioning**: Omit resource IDs for auto-creation on deploy.\n3. **Run `wrangler types` in CI**: Add to build step to catch binding mismatches.\n4. **Use environments**: Separate staging/production with `env.staging`, `env.production`.\n5. **Set `compatibility_date`**: Update quarterly to get new runtime features.\n6. **Use `.dev.vars` for local secrets**: Never commit secrets to config.\n7. **Test locally first**: `wrangler dev` with local bindings before deploying.\n8. **Use `--dry-run` before major deploys**: Validate changes without deployment.\n"},"lastSynced":"2026-03-06T06:53:16.321Z","agentAnalysis":{"suitability":{"en":"Ideal for Cloudflare-focused AI Agents needing efficient Cloudflare Workers management and deployment capabilities.","zh":"适用于需要高效的 Cloudflare Workers 管理和部署能力的 Cloudflare 集中 AI 代理。","ja":"Cloudflare Workers の効率的な管理とデプロイ機能が必要な Cloudflare フォーカス AI エージェントに適しています。","ko":"Cloudflare Workers 관리 및 배포 기능을 효율적으로 필요한 Cloudflare 중심 AI 에이전트에 적합합니다.","es":"Ideal para agentes de inteligencia artificial de Cloudflare que necesitan capacidades de gestión y despliegue de Cloudflare Workers eficientes.","fr":"Idéal pour les agents d''intelligence artificielle de Cloudflare nécessitant des capacités de gestion et de déploiement de Cloudflare Workers efficaces.","de":"Ideal für Cloudflare-fokussierte KI-Agents, die effiziente Cloudflare Workers-Verwaltungs- und Bereitstellungsfähigkeiten benötigen.","pt":"Ideal para Agentes de IA com foco na Cloudflare que necessitam de capacidades de gerenciamento e implantação eficientes de Cloudflare Workers.","ru":"Идеально для агентов ИИ, ориентированных на Cloudflare, которым необходимы эффективные возможности управления и развертывания Cloudflare Workers.","ar":"مثالي لعميل الذكاء الاصطناعي ذي التركيز على Cloudflare الذي يحتاج إلى إمكانيات إدارة وتشغيل Cloudflare Workers بكفاءة."},"recommendation":{"en":"Empowers agents to deploy, develop, and manage Cloudflare Workers and associated resources using a command-line interface, with features like JSON configuration and compatibility date setting, leveraging wrangler.jsonc and compatibility_dates from https://developers.cloudflare.com/workers/configuration/compatibility-dates/","zh":"赋予代理部署、开发和管理 Cloudflare Workers 及相关资源的能力，使用命令行界面，具有 JSON 配置和兼容性日期设置等功能，利用 wrangler.jsonc 和兼容性日期来自 https://developers.cloudflare.com/workers/configuration/compatibility-dates/","ja":"Cloudflare Workers と関連リソースをコマンドラインインターフェイスを使用してデプロイ、開発、管理する能力をエージェントに与え、JSON 構成や互換性日付の設定などの機能を提供し、wrangler.jsonc と互換性日付を https://developers.cloudflare.com/workers/configuration/compatibility-dates/ から利用します。","ko":"에이전트에게 Cloudflare Workers 및 관련 리소스를 명령줄 인터페이스를 사용하여 배포, 개발 및 관리할 수 있는 능력을 부여하고, JSON 구성 및 호환성 날짜 설정 등의 기능을 제공하며, wrangler.jsonc 및 호환성 날짜를 https://developers.cloudflare.com/workers/configuration/compatibility-dates/ 에서 활용합니다.","es":"Habilita a los agentes a implementar, desarrollar y gestionar Cloudflare Workers y recursos asociados utilizando una interfaz de línea de comandos, con características como configuración JSON y establecimiento de fechas de compatibilidad, aprovechando wrangler.jsonc y compatibility_dates desde https://developers.cloudflare.com/workers/configuration/compatibility-dates/","fr":"Permet aux agents de déployer, de développer et de gérer Cloudflare Workers et ressources associées en utilisant une interface en ligne de commande, avec des fonctionnalités comme la configuration JSON et la définition de dates de compatibilité, en exploitant wrangler.jsonc et compatibility_dates depuis https://developers.cloudflare.com/workers/configuration/compatibility-dates/","de":"Ermächtigt Agents, Cloudflare Workers und zugehörige Ressourcen mithilfe einer Kommandozeilen-Schnittstelle zu bereitstellen, entwickeln und verwalten, mit Funktionen wie JSON-Konfiguration und Festlegung von Kompatibilitätsdatum, unter Nutzung von wrangler.jsonc und compatibility_dates von https://developers.cloudflare.com/workers/configuration/compatibility-dates/","pt":"Habilita os agentes a implantar, desenvolver e gerenciar Cloudflare Workers e recursos associados usando uma interface de linha de comando, com recursos como configuração JSON e definição de data de compatibilidade, aproveitando wrangler.jsonc e compatibility_dates de https://developers.cloudflare.com/workers/configuration/compatibility-dates/","ru":"Наделяет агентов возможностью развертывать, разрабатывать и управлять Cloudflare Workers и связанными с ними ресурсами, используя командную строку интерфейса, с функциями, такими как конфигурация JSON и настройка даты совместимости, используя wrangler.jsonc и compatibility_dates с https://developers.cloudflare.com/workers/configuration/compatibility-dates/","ar":"تمكّن الوكلاء من نشر وتطوير وإدارة Cloudflare Workers والموارد المرتبطة بها باستخدام واجهة سطر الأوامر، مع ميزات مثل تكوين JSON وضبط تاريخ التوافق، باستخدام wrangler.jsonc وcompatibility_dates من https://developers.cloudflare.com/workers/configuration/compatibility-dates/"},"useCases":{"en":["Deploying Cloudflare Workers using the Wrangler CLI","Managing Cloudflare Workers configurations with wrangler.jsonc","Setting compatibility dates for Cloudflare Workers"],"zh":["使用 Wrangler CLI 部署 Cloudflare Workers","使用 wrangler.jsonc 管理 Cloudflare Workers 配置","为 Cloudflare Workers 设置兼容性日期"],"ja":["Wrangler CLI を使用して Cloudflare Workers をデプロイする","wrangler.jsonc を使用して Cloudflare Workers 構成を管理する","Cloudflare Workers に互換性日付を設定する"],"ko":["Wrangler CLI를 사용하여 Cloudflare Workers를 배포하는 것","wrangler.jsonc를 사용하여 Cloudflare Workers 구성 관리","Cloudflare Workers에 호환성 날짜를 설정"],"es":["Implementación de Cloudflare Workers con el CLI de Wrangler","Gestión de configuraciones de Cloudflare Workers con wrangler.jsonc","Establecimiento de fechas de compatibilidad para Cloudflare Workers"],"fr":["Déploiement de Cloudflare Workers à l''aide du CLI de Wrangler","Gestion des configurations de Cloudflare Workers avec wrangler.jsonc","Définition des dates de compatibilité pour Cloudflare Workers"],"de":["Bereitstellung von Cloudflare Workers mit dem Wrangler-CLI","Verwaltung von Cloudflare Workers-Konfigurationen mit wrangler.jsonc","Festlegung von Kompatibilitätsdaten für Cloudflare Workers"],"pt":["Implantação de Cloudflare Workers usando o Wrangler CLI","Gerenciamento de configurações de Cloudflare Workers com wrangler.jsonc","Definição de datas de compatibilidade para Cloudflare Workers"],"ru":["Развертывание Cloudflare Workers с помощью Wrangler CLI","Управление конфигурациями Cloudflare Workers с помощью wrangler.jsonc","Настройка дат совместимости для Cloudflare Workers"],"ar":["نشر Cloudflare Workers باستخدام Wrangler CLI","إدارة تكوينات Cloudflare Workers مع wrangler.jsonc","ضبط تواريخ التوافق ل Cloudflare Workers"]},"limitations":{"en":["Requires Wrangler installation (npm install -D wrangler@latest)","Wrangler version 4.x+ required","JSON configuration preferred over TOML"],"zh":["需要安装 Wrangler (npm install -D wrangler@latest)","需要 Wrangler 版本 4.x+","更喜欢 JSON 配置而不是 TOML"],"ja":["Wrangler のインストール (npm install -D wrangler@latest) が必要","Wrangler バージョン 4.x+ が必要","TOML よりも JSON 構成を優先"],"ko":["Wrangler 설치(npm install -D wrangler@latest)가 필요함","Wrangler 버전 4.x+ 필요","TOML보다 JSON 구성이 선호됨"],"es":["Requiere instalación de Wrangler (npm install -D wrangler@latest)","Se requiere la versión 4.x+ de Wrangler","Se prefiere la configuración JSON sobre TOML"],"fr":["Nécessite l''installation de Wrangler (npm install -D wrangler@latest)","La version 4.x+ de Wrangler est requise","La configuration JSON est préférée à TOML"],"de":["Erfordert Wrangler-Installation (npm install -D wrangler@latest)","Wrangler-Version 4.x+ erforderlich","JSON-Konfiguration wird bevorzugt gegenüber TOML"],"pt":["Requer instalação do Wrangler (npm install -D wrangler@latest)","Wrangler versão 4.x+ necessária","Configuração JSON preferida em relação à TOML"],"ru":["Требуется установка Wrangler (npm install -D wrangler@latest)","Wrangler версия 4.x+ необходима","Конфигурация JSON предпочтительнее TOML"],"ar":["يتطلب تثبيت Wrangler (npm install -D wrangler@latest)","نسخة Wrangler 4.x+ مطلوبة","التكوين JSON مفضل على TOML"]},"version":4},"contentHash":"0221396d5c3bc0a2995f32dcb107fc0be4d7f897546bd1379b9bbc1699eec1b8","qualityScore":45}');
