INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('UndiFineD/PyAgent/copilot-instructions-blueprint-generator', 'copilot-instructions-blueprint-generator', 'UndiFineD', 'PyAgent', 'community', 'copilot-instructions-blueprint-generator UndiFineD PyAgent community The copilot-instructions-blueprint-generator is a Python agent that automates project setup by generating configuration blueprints based on variables like project type and architecture style, benefiting developers and project managers. copilot-instructions-blueprint-generator 是一个 Python Agent，用于生成配置蓝图，支持多种技术和架构风格 Copilot Instructions Blueprint Generator は、Python プロジェクトの構成ブループリントを生成する AI エージェントで、多様なテクノロジーとアーキテクチャスタイルをサポート copilot-instructions-blueprint-generator는 Python 프로젝트의 구성 청사진을 생성하는 Python 에이전트로서 다양한 기술과 아키텍처 스타일을 지원합니다 El copilot-instructions-blueprint-generator es una herramienta de Python que genera instrucciones para proyectos con diferentes estilos de arquitectura y enfoques de calidad Le copilot-instructions-blueprint-generator est un outil Python qui génère des instructions pour des projets avec différents styles d''architecture et des approches de qualité Der copilot-instructions-blueprint-generator ist ein Python-Tool, das Anweisungen für Projekte mit verschiedenen Architekturstilen und Qualitätsansätzen generiert O Copilot Instructions Blueprint Generator é uma ferramenta de código aberto que ajuda os desenvolvedores a criar projetos personalizados com tecnologias como Python, React e Angular. ИИ Агент Copilot Instructions Blueprint Generator - это инструмент с открытым исходным кодом, который помогает разработчикам создавать индивидуальные проекты с использованием технологий zoals Python, React и Angular. Copilot Instructions Blueprint Generator هو أداة مفتوحة المصدر تساعد المطورين على إنشاء مشاريع مخصصة باستخدام تقنيات مثل Python و React و Angular. how to use copilot-instructions-blueprint-generator copilot-instructions-blueprint-generator alternative copilot-instructions-blueprint-generator setup guide what is copilot-instructions-blueprint-generator copilot-instructions-blueprint-generator vs other project setup tools automating project setup with copilot-instructions-blueprint-generator configuring copilot-instructions-blueprint-generator for optimal results copilot-instructions-blueprint-generator install copilot-instructions-blueprint-generator documentation copilot-instructions-blueprint-generator Python Agent 配置蓝图 技术细节 项目类型 架构风格 质量优先级 文档级别 Supports multiple project types, including .NET, Java, JavaScript, TypeScript, React, Angular, and Python Allows configuration of architectural approaches, such as Layered, Microservices, Monolithic, Domain-Driven, Event-Driven, and Serverless Enables setting of code quality priorities, including Maintainability, Performance, Security, Accessibility, and Testability Generates configuration blueprints based on predefined variables, such as DOCUMENTATION_LEVEL and CODE_QUALITY_FOCUS Supports auto-detection of project type for simplified setup Provides options for mixed architecture styles and multiple project types copilot-instructions-blueprint-generator is a Python-based AI agent that generates project configuration blueprints based on predefined variables such as project type, architecture style, and code quality focus.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stephenhuo-code/sunnyagent/skill-creator', 'community', 'stephenhuo-code', 'sunnyagent', 'stephenhuo-code/sunnyagent', 'skill-creator', 0, 0, 45, '2026-03-07T12:46:33.394Z', '2026-03-07T12:51:33.558Z', 'd57b6e3a44535b9c0ef454dad5c86f5df78185fc80a65c7092885b4b5e10f81b', '{"id":"stephenhuo-code/sunnyagent/skill-creator","name":"skill-creator","description":{"en":"The skill-creator is a specialized AI agent skill that provides developers with guidance for creating modular, self-contained packages. It helps build skills that transform Claude from a general-purpose agent into a specialized one equipped with domain-specific workflows and procedural knowledge.","zh":"Skill Creator 是一个提供创建有效技能的指导的技能，帮助开发者扩展 AI 工具的能力","ja":"スキルクリエーターは、AI エージェントの能力を拡張するための専門知識とワークフローを提供する技能です","ko":"스킬 크리에이터는 개발자가 전문 지식과 워크플로우를 제공하는技能을 생성할 수 있도록 도와주는 기술입니다","es":"Skill Creator es una herramienta que proporciona orientación para crear habilidades efectivas que amplían las capacidades de los Agentes de IA","fr":"Skill Creator est un outil qui fournit des conseils pour créer des compétences efficaces qui étendent les capacités des Outils d''IA","de":"Skill Creator ist ein Tool, das Anleitungen zur Erstellung effektiver Fähigkeiten bietet, um die Fähigkeiten von KI-Agenten zu erweitern","pt":"O Skill Creator é uma habilidade que fornece orientação para a criação de habilidades eficazes, permitindo que os agentes de IA se tornem especializados em domínios ou tarefas específicas.","ru":"Skill Creator — это навык, который предоставляет руководство по созданию эффективных навыков, позволяя ИИ Агентам стать специалистами в конкретных областях или задачах.","ar":"Skill Creator هو مهارة يوفر إرشادات لإنشاء مهارات فعالة، مما يسمح لأدوات الذكاء الاصطناعي بأن تصبح مخصصة في مجالات أو مهام معينة."},"seo":{"title":{"en":"skill-creator: Build Modular AI Agent Skills | Setup Guide","zh":"Skill Creator 设置指南 - 创建高效技能","ja":"スキルクリエーター ベストプラクティス - AIエージェントの能力を拡張","ko":"스킬 크리에이터 설정 가이드 - 전문 지식과 워크플로우 제공","es":"Guía de configuración de Skill Creator para Agentes de IA","fr":"Guide de mise en place de Skill Creator pour les Outils d''IA","de":"Einrichtungsleitfaden für Skill Creator in KI-Agenten","pt":"Guia de Configuração do Skill Creator para Agentes de IA","ru":"Настройка Skill Creator для ИИ Агентов: Руководство","ar":"دليل إعداد Skill Creator لأدوات الذكاء الاصطناعي"},"description":{"en":"Learn how the skill-creator AI agent package provides specialized guidance for developing modular, self-contained skills that extend Claude''s capabilities wi...","zh":"了解 Skill Creator 的技术细节和功能，创建高效的技能并扩展 AI 工具的能力","ja":"スキルクリエーターで AI エージェントの能力を拡張する方法を学ぶ - 専門知識とワークフローを提供","ko":"스킬 크리에이터를 사용하여 전문 지식과 워크플로우를 제공하는 방법을 알아보세요 - 개발자를 위한 가이드","es":"Aprende a crear habilidades efectivas con Skill Creator, la herramienta perfecta para ampliar las capacidades de tus Agentes de IA con flujos de trabajo espe...","fr":"Découvrez comment créer des compétences efficaces avec Skill Creator, l''outil idéal pour étendre les capacités de vos Outils d''IA avec des flux de travail sp...","de":"Erfahren Sie, wie Sie mit Skill Creator effektive Fähigkeiten erstellen und die Fähigkeiten Ihrer KI-Agenten mit spezialisierten Workflows erweitern","pt":"Aprenda a criar habilidades personalizadas com o Skill Creator. Descubra como estender as capacidades dos agentes de IA com workflows especializados.","ru":"Узнайте, как создавать индивидуальные навыки с помощью Skill Creator. Расширьте возможности ИИ Агентов с помощью специализированных рабочих процессов.","ar":"تعلم كيفية إنشاء مهارات مخصصة باستخدام Skill Creator. اكتشف كيفية توسيع قدرات أدوات الذكاء الاصطناعي مع سلاسل عمل مخصصة."},"definition":{"en":"skill-creator is an AI agent skill that provides structured guidance for creating modular skill packages. These packages extend Claude''s capabilities by providing specialized domain knowledge, multi-step workflows, and procedural expertise that the base model cannot possess on its own.","zh":"Skill Creator 是一个用于创建高效技能的技能，提供专门的工作流程和工具","ja":"スキルクリエーターとは、AI エージェントの能力を拡張するための技能です","ko":"스킬 크리에이터는 전문 지식과 워크플로우를 제공하는技能을 생성하는 기술입니다","es":"Skill Creator es una herramienta de creación de habilidades que permite a los desarrolladores crear paquetes modulares y autocontenidos que amplían las capacidades de los Agentes de IA","fr":"Skill Creator est un outil de création de compétences qui permet aux développeurs de créer des packages modulaires et autocontenus qui étendent les capacités des Outils d''IA","de":"Skill Creator ist ein Tool zur Erstellung von Fähigkeiten, das es Entwicklern ermöglicht, modulare und selbstenthaltene Pakete zu erstellen, um die Fähigkeiten von KI-Agenten zu erweitern","pt":"O que é Skill Creator? É uma habilidade que permite criar pacotes modulares e autossuficientes que estendem as capacidades dos agentes de IA.","ru":"Что такое Skill Creator? Это навык, который позволяет создавать модульные и самодостаточные пакеты, расширяющие возможности ИИ Агентов.","ar":"ما هو Skill Creator? هو مهارة يسمح بإنشاء حزم مخصصة ومتكاملة لتوسيع قدرات أدوات الذكاء الاصطناعي."},"features":{"en":["Provides guidance for creating modular, self-contained skill packages","Extends Claude''s capabilities with specialized domain knowledge","Enables development of specialized workflows for AI agents","Transforms general-purpose agents into domain-specific experts","Delivers procedural knowledge that base models cannot possess"],"zh":["提供专门的工作流程","支持多步骤的工作流程","扩展 AI 工具的能力","提供专业知识和工具","支持开发者创建自定义技能"],"ja":["専門のワークフローを提供","複数ステップのワークフローをサポート","AI エージェントの能力を拡張","専門知識とツールを提供","開発者がカスタム スキルを作成することをサポート"],"ko":["전문적인 워크플로우 제공","다단계 워크플로우 지원","AI 도구의 능력 확장","전문 지식과 도구 제공","개발자가 사용자 정의 스킬을 생성하도록 지원"],"es":["Flujos de trabajo especializados","Paquetes modulares y autocontenidos","Ampliación de las capacidades de los Agentes de IA","Orientación para la creación de habilidades efectivas","Integración con tecnologías de vanguardia"],"fr":["Flux de travail spécialisés","Packages modulaires et autocontenus","Élargissement des capacités des Outils d''IA","Guidance pour la création de compétences efficaces","Intégration avec des technologies de pointe"],"de":["Spezialisierte Workflows","Modulare und selbstenthaltene Pakete","Erweiterung der Fähigkeiten von KI-Agenten","Anleitung zur Erstellung effektiver Fähigkeiten","Integration mit SpitzenTechnologien"],"pt":["Fornece orientação para a criação de habilidades eficazes","Permite a criação de workflows especializados","Estende as capacidades dos agentes de IA","Transforma os agentes de IA em especialistas em domínios ou tarefas específicas","Fornece conhecimento procedural que nenhum modelo pode possuir completamente"],"ru":["Предоставляет руководство по созданию эффективных навыков","Позволяет создавать специализированные рабочие процессы","Расширяет возможности ИИ Агентов","Преобразует ИИ Агентов в специалистов в конкретных областях или задачах","Предоставляет процедурные знания, которые ни одна модель не может полностью обладать"],"ar":["يوفر إرشادات لإنشاء مهارات فعالة","يسمح بإنشاء سلاسل عمل مخصصة","يوسع قدرات أدوات الذكاء الاصطناعي","يحول أدوات الذكاء الاصطناعي إلى مخصصة في مجالات أو مهام معينة","يوفر معرفة إجرائية التي لا يمكن أن يمتلكها أي نموذج بشكل كامل"]},"keywords":{"en":["how to use skill-creator","what is skill-creator AI agent","skill-creator vs other AI tools","skill-creator installation guide","skill-creator setup tutorial","creating modular AI skills","Claude skill development","AI agent workflow creation","skill-creator best practices"],"zh":["Skill Creator","AI 工具","创建技能","扩展能力","专门工作流程","开发者指南","AI 技术","技能开发"],"ja":["スキルクリエーター","AI エージェント","スキルを作成","能力を拡張","専門ワークフロー","開発者ガイド","AI 技術","スキル開発"],"ko":["스킬 크리에이터","AI 도구","스킬 생성","능력 확장","전문 워크플로우","개발자 가이드","AI 기술","스킬 개발"],"es":["Skill Creator","Agentes de IA","Herramientas de IA","Desarrollo de habilidades","Flujos de trabajo especializados","Paquetes modulares","Ampliación de capacidades","Creación de habilidades efectivas","Integración con tecnologías de vanguardia"],"fr":["Skill Creator","Outils d''IA","Compétences efficaces","Flux de travail spécialisés","Packages modulaires","Élargissement des capacités","Création de compétences efficaces","Intégration avec des technologies de pointe","Développement de compétences"],"de":["Skill Creator","KI-Agenten","KI-Tools","Fähigkeitsentwicklung","Spezialisierte Workflows","Modulare Pakete","Erweiterung der Fähigkeiten","Erstellung effektiver Fähigkeiten","Integration mit SpitzenTechnologien"],"pt":["Skill Creator","agentes de IA","habilidades personalizadas","workflows especializados","conhecimento procedural","desenvolvimento de habilidades","IA e machine learning","tecnologias de IA","ferramentas de desenvolvimento de IA"],"ru":["Skill Creator","ИИ Агенты","индивидуальные навыки","специализированные рабочие процессы","процедурные знания","разработка навыков","ИИ и машинное обучение","технологии ИИ","инструменты разработки ИИ"],"ar":["Skill Creator","أدوات الذكاء الاصطناعي","مهارات مخصصة","سلاسل عمل مخصصة","معرفة إجرائية","تطوير المهارات","الذكاء الاصطناعي وتعلم الآلة","تقنيات الذكاء الاصطناعي","أدوات تطوير الذكاء الاصطناعي"]}},"owner":"stephenhuo-code","repo":"sunnyagent","repoPath":"stephenhuo-code/sunnyagent","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.394Z","topics":[],"category":"community","skillMd":{"name":"skill-creator","description":"Guide for creating effective skills. This skill should be used when users want to create a new skill (or update an existing skill) that extends Claudes capabilities with specialized knowledge, workflows, or tool integrations.","bodyPreview":"# Skill Creator\n\nThis skill provides guidance for creating effective skills.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi","body":"# Skill Creator\n\nThis skill provides guidance for creating effective skills.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi-step procedures for specific domains\n2. Tool integrations - Instructions for working with specific file formats or APIs\n3. Domain expertise - Company-specific knowledge, schemas, business logic\n4. Bundled resources - Scripts, references, and assets for complex and repetitive tasks\n\n## Core Principles\n\n### Concise is Key\n\nThe context window is a public good. Skills share the context window with everything else Claude needs: system prompt, conversation history, other Skills'' metadata, and the actual user request.\n\n**Default assumption: Claude is already very smart.** Only add context Claude doesn''t already have. Challenge each piece of information: \"Does Claude really need this explanation?\" and \"Does this paragraph justify its token cost?\"\n\nPrefer concise examples over verbose explanations.\n\n### Set Appropriate Degrees of Freedom\n\nMatch the level of specificity to the task''s fragility and variability:\n\n**High freedom (text-based instructions)**: Use when multiple approaches are valid, decisions depend on context, or heuristics guide the approach.\n\n**Medium freedom (pseudocode or scripts with parameters)**: Use when a preferred pattern exists, some variation is acceptable, or configuration affects behavior.\n\n**Low freedom (specific scripts, few parameters)**: Use when operations are fragile and error-prone, consistency is critical, or a specific sequence must be followed.\n\nThink of Claude as exploring a path: a narrow bridge with cliffs needs specific guardrails (low freedom), while an open field allows many routes (high freedom).\n\n### Anatomy of a Skill\n\nEvery skill consists of a required SKILL.md file and optional bundled resources:\n\n```\nskill-name/\n├── SKILL.md (required)\n│   ├── YAML frontmatter metadata (required)\n│   │   ├── name: (required)\n│   │   ├── description: (required)\n│   │   └── compatibility: (optional, rarely needed)\n│   └── Markdown instructions (required)\n└── Bundled Resources (optional)\n    ├── scripts/          - Executable code (Python/Bash/etc.)\n    ├── references/       - Documentation intended to be loaded into context as needed\n    └── assets/           - Files used in output (templates, icons, fonts, etc.)\n```\n\n#### SKILL.md (required)\n\nEvery SKILL.md consists of:\n\n- **Frontmatter** (YAML): Contains `name` and `description` fields (required), plus optional fields like `license`, `metadata`, and `compatibility`. Only `name` and `description` are read by Claude to determine when the skill triggers, so be clear and comprehensive about what the skill is and when it should be used. The `compatibility` field is for noting environment requirements (target product, system packages, etc.) but most skills don''t need it.\n- **Body** (Markdown): Instructions and guidance for using the skill. Only loaded AFTER the skill triggers (if at all).\n\n#### Bundled Resources (optional)\n\n##### Scripts (`scripts/`)\n\nExecutable code (Python/Bash/etc.) for tasks that require deterministic reliability or are repeatedly rewritten.\n\n- **When to include**: When the same code is being rewritten repeatedly or deterministic reliability is needed\n- **Example**: `scripts/rotate_pdf.py` for PDF rotation tasks\n- **Benefits**: Token efficient, deterministic, may be executed without loading into context\n- **Note**: Scripts may still need to be read by Claude for patching or environment-specific adjustments\n\n##### References (`references/`)\n\nDocumentation and reference material intended to be loaded as needed into context to inform Claude''s process and thinking.\n\n- **When to include**: For documentation that Claude should reference while working\n- **Examples**: `references/finance.md` for financial schemas, `references/mnda.md` for company NDA template, `references/policies.md` for company policies, `references/api_docs.md` for API specifications\n- **Use cases**: Database schemas, API documentation, domain knowledge, company policies, detailed workflow guides\n- **Benefits**: Keeps SKILL.md lean, loaded only when Claude determines it''s needed\n- **Best practice**: If files are large (>10k words), include grep search patterns in SKILL.md\n- **Avoid duplication**: Information should live in either SKILL.md or references files, not both. Prefer references files for detailed information unless it''s truly core to the skill—this keeps SKILL.md lean while making information discoverable without hogging the context window. Keep only essential procedural instructions and workflow guidance in SKILL.md; move detailed reference material, schemas, and examples to references files.\n\n##### Assets (`assets/`)\n\nFiles not intended to be loaded into context, but rather used within the output Claude produces.\n\n- **When to include**: When the skill needs files that will be used in the final output\n- **Examples**: `assets/logo.png` for brand assets, `assets/slides.pptx` for PowerPoint templates, `assets/frontend-template/` for HTML/React boilerplate, `assets/font.ttf` for typography\n- **Use cases**: Templates, images, icons, boilerplate code, fonts, sample documents that get copied or modified\n- **Benefits**: Separates output resources from documentation, enables Claude to use files without loading them into context\n\n#### What to Not Include in a Skill\n\nA skill should only contain essential files that directly support its functionality. Do NOT create extraneous documentation or auxiliary files, including:\n\n- README.md\n- INSTALLATION_GUIDE.md\n- QUICK_REFERENCE.md\n- CHANGELOG.md\n- etc.\n\nThe skill should only contain the information needed for an AI agent to do the job at hand. It should not contain auxilary context about the process that went into creating it, setup and testing procedures, user-facing documentation, etc. Creating additional documentation files just adds clutter and confusion.\n\n### Progressive Disclosure Design Principle\n\nSkills use a three-level loading system to manage context efficiently:\n\n1. **Metadata (name + description)** - Always in context (~100 words)\n2. **SKILL.md body** - When skill triggers (<5k words)\n3. **Bundled resources** - As needed by Claude (Unlimited because scripts can be executed without reading into context window)\n\n#### Progressive Disclosure Patterns\n\nKeep SKILL.md body to the essentials and under 500 lines to minimize context bloat. Split content into separate files when approaching this limit. When splitting out content into other files, it is very important to reference them from SKILL.md and describe clearly when to read them, to ensure the reader of the skill knows they exist and when to use them.\n\n**Key principle:** When a skill supports multiple variations, frameworks, or options, keep only the core workflow and selection guidance in SKILL.md. Move variant-specific details (patterns, examples, configuration) into separate reference files.\n\n**Pattern 1: High-level guide with references**\n\n```markdown\n# PDF Processing\n\n## Quick start\n\nExtract text with pdfplumber:\n[code example]\n\n## Advanced features\n\n- **Form filling**: See [FORMS.md](FORMS.md) for complete guide\n- **API reference**: See [REFERENCE.md](REFERENCE.md) for all methods\n- **Examples**: See [EXAMPLES.md](EXAMPLES.md) for common patterns\n```\n\nClaude loads FORMS.md, REFERENCE.md, or EXAMPLES.md only when needed.\n\n**Pattern 2: Domain-specific organization**\n\nFor Skills with multiple domains, organize content by domain to avoid loading irrelevant context:\n\n```\nbigquery-skill/\n├── SKILL.md (overview and navigation)\n└── reference/\n    ├── finance.md (revenue, billing metrics)\n    ├── sales.md (opportunities, pipeline)\n    ├── product.md (API usage, features)\n    └── marketing.md (campaigns, attribution)\n```\n\nWhen a user asks about sales metrics, Claude only reads sales.md.\n\nSimilarly, for skills supporting multiple frameworks or variants, organize by variant:\n\n```\ncloud-deploy/\n├── SKILL.md (workflow + provider selection)\n└── references/\n    ├── aws.md (AWS deployment patterns)\n    ├── gcp.md (GCP deployment patterns)\n    └── azure.md (Azure deployment patterns)\n```\n\nWhen the user chooses AWS, Claude only reads aws.md.\n\n**Pattern 3: Conditional details**\n\nShow basic content, link to advanced content:\n\n```markdown\n# DOCX Processing\n\n## Creating documents\n\nUse docx-js for new documents. See [DOCX-JS.md](DOCX-JS.md).\n\n## Editing documents\n\nFor simple edits, modify the XML directly.\n\n**For tracked changes**: See [REDLINING.md](REDLINING.md)\n**For OOXML details**: See [OOXML.md](OOXML.md)\n```\n\nClaude reads REDLINING.md or OOXML.md only when the user needs those features.\n\n**Important guidelines:**\n\n- **Avoid deeply nested references** - Keep references one level deep from SKILL.md. All reference files should link directly from SKILL.md.\n- **Structure longer reference files** - For files longer than 100 lines, include a table of contents at the top so Claude can see the full scope when previewing.\n\n## Skill Creation Process\n\nSkill creation involves these steps:\n\n1. Understand the skill with concrete examples\n2. Plan reusable skill contents (scripts, references, assets)\n3. Initialize the skill (run init_skill.py)\n4. Edit the skill (implement resources and write SKILL.md)\n5. Package the skill (run package_skill.py)\n6. Iterate based on real usage\n\nFollow these steps in order, skipping only if there is a clear reason why they are not applicable.\n\n### Step 1: Understanding the Skill with Concrete Examples\n\nSkip this step only when the skill''s usage patterns are already clearly understood. It remains valuable even when working with an existing skill.\n\nTo create an effective skill, clearly understand concrete examples of how the skill will be used. This understanding can come from either direct user examples or generated examples that are validated with user feedback.\n\nFor example, when building an image-editor skill, relevant questions include:\n\n- \"What functionality should the image-editor skill support? Editing, rotating, anything else?\"\n- \"Can you give some examples of how this skill would be used?\"\n- \"I can imagine users asking for things like ''Remove the red-eye from this image'' or ''Rotate this image''. Are there other ways you imagine this skill being used?\"\n- \"What would a user say that should trigger this skill?\"\n\nTo avoid overwhelming users, avoid asking too many questions in a single message. Start with the most important questions and follow up as needed for better effectiveness.\n\nConclude this step when there is a clear sense of the functionality the skill should support.\n\n### Step 2: Planning the Reusable Skill Contents\n\nTo turn concrete examples into an effective skill, analyze each example by:\n\n1. Considering how to execute on the example from scratch\n2. Identifying what scripts, references, and assets would be helpful when executing these workflows repeatedly\n\nExample: When building a `pdf-editor` skill to handle queries like \"Help me rotate this PDF,\" the analysis shows:\n\n1. Rotating a PDF requires re-writing the same code each time\n2. A `scripts/rotate_pdf.py` script would be helpful to store in the skill\n\nExample: When designing a `frontend-webapp-builder` skill for queries like \"Build me a todo app\" or \"Build me a dashboard to track my steps,\" the analysis shows:\n\n1. Writing a frontend webapp requires the same boilerplate HTML/React each time\n2. An `assets/hello-world/` template containing the boilerplate HTML/React project files would be helpful to store in the skill\n\nExample: When building a `big-query` skill to handle queries like \"How many users have logged in today?\" the analysis shows:\n\n1. Querying BigQuery requires re-discovering the table schemas and relationships each time\n2. A `references/schema.md` file documenting the table schemas would be helpful to store in the skill\n\nTo establish the skill''s contents, analyze each concrete example to create a list of the reusable resources to include: scripts, references, and assets.\n\n### Step 3: Initializing the Skill\n\nAt this point, it is time to actually create the skill.\n\nSkip this step only if the skill being developed already exists, and iteration or packaging is needed. In this case, continue to the next step.\n\nWhen creating a new skill from scratch, always run the `init_skill.py` script. The script conveniently generates a new template skill directory that automatically includes everything a skill requires, making the skill creation process much more efficient and reliable.\n\nUsage:\n\n```bash\nscripts/init_skill.py <skill-name> --path <output-directory>\n```\n\nThe script:\n\n- Creates the skill directory at the specified path\n- Generates a SKILL.md template with proper frontmatter and TODO placeholders\n- Creates example resource directories: `scripts/`, `references/`, and `assets/`\n- Adds example files in each directory that can be customized or deleted\n\nAfter initialization, customize or remove the generated SKILL.md and example files as needed.\n\n### Step 4: Edit the Skill\n\nWhen editing the (newly-generated or existing) skill, remember that the skill is being created for another instance of Claude to use. Include information that would be beneficial and non-obvious to Claude. Consider what procedural knowledge, domain-specific details, or reusable assets would help another Claude instance execute these tasks more effectively.\n\n#### Learn Proven Design Patterns\n\nConsult these helpful guides based on your skill''s needs:\n\n- **Multi-step processes**: See references/workflows.md for sequential workflows and conditional logic\n- **Specific output formats or quality standards**: See references/output-patterns.md for template and example patterns\n\nThese files contain established best practices for effective skill design.\n\n#### Start with Reusable Skill Contents\n\nTo begin implementation, start with the reusable resources identified above: `scripts/`, `references/`, and `assets/` files. Note that this step may require user input. For example, when implementing a `brand-guidelines` skill, the user may need to provide brand assets or templates to store in `assets/`, or documentation to store in `references/`.\n\nAdded scripts must be tested by actually running them to ensure there are no bugs and that the output matches what is expected. If there are many similar scripts, only a representative sample needs to be tested to ensure confidence that they all work while balancing time to completion.\n\nAny example files and directories not needed for the skill should be deleted. The initialization script creates example files in `scripts/`, `references/`, and `assets/` to demonstrate structure, but most skills won''t need all of them.\n\n#### Update SKILL.md\n\n**Writing Guidelines:** Always use imperative/infinitive form.\n\n##### Frontmatter\n\nWrite the YAML frontmatter with `name` and `description`:\n\n- `name`: The skill name\n- `description`: This is the primary triggering mechanism for your skill, and helps Claude understand when to use the skill.\n  - Include both what the Skill does and specific triggers/contexts for when to use it.\n  - Include all \"when to use\" information here - Not in the body. The body is only loaded after triggering, so \"When to Use This Skill\" sections in the body are not helpful to Claude.\n  - Example description for a `docx` skill: \"Comprehensive document creation, editing, and analysis with support for tracked changes, comments, formatting preservation, and text extraction. Use when Claude needs to work with professional documents (.docx files) for: (1) Creating new documents, (2) Modifying or editing content, (3) Working with tracked changes, (4) Adding comments, or any other document tasks\"\n\nDo not include any other fields in YAML frontmatter.\n\n##### Body\n\nWrite instructions for using the skill and its bundled resources.\n\n### Step 5: Packaging a Skill\n\nOnce development of the skill is complete, it must be packaged into a distributable .skill file that gets shared with the user. The packaging process automatically validates the skill first to ensure it meets all requirements:\n\n```bash\nscripts/package_skill.py <path/to/skill-folder>\n```\n\nOptional output directory specification:\n\n```bash\nscripts/package_skill.py <path/to/skill-folder> ./dist\n```\n\nThe packaging script will:\n\n1. **Validate** the skill automatically, checking:\n\n   - YAML frontmatter format and required fields\n   - Skill naming conventions and directory structure\n   - Description completeness and quality\n   - File organization and resource references\n\n2. **Package** the skill if validation passes, creating a .skill file named after the skill (e.g., `my-skill.skill`) that includes all files and maintains the proper directory structure for distribution. The .skill file is a zip file with a .skill extension.\n\nIf validation fails, the script will report the errors and exit without creating a package. Fix any validation errors and run the packaging command again.\n\n### Step 6: Iterate\n\nAfter testing the skill, users may request improvements. Often this happens right after using the skill, with fresh context of how the skill performed.\n\n**Iteration workflow:**\n\n1. Use the skill on real tasks\n2. Notice struggles or inefficiencies\n3. Identify how SKILL.md or bundled resources should be updated\n4. Implement changes and test again\n"},"lastSynced":"2026-03-07T12:51:33.558Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents seeking to create modular, self-contained packages with domain-specific workflows and procedural knowledge.","zh":"非常适合开发人员代理创建模块化、自包含的软件包，具有特定领域的工作流和程序化知识。","ja":"モジュラー化された自己完結的なパッケージを作成し、ドメイン固有のワークフローと手続き型の知識を備えた開発者エージェントに最適です。","ko":"모듈화된 자기 포함된 패키지를 생성하고 특정 도메인의 워크플로 및 절차적 지식을 갖춘 개발자 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que buscan crear paquetes modulares, autocontenidos con flujos de trabajo y conocimiento procedimental específicos del dominio.","fr":"Parfait pour les Agents de Développeur qui cherchent à créer des packages modulaires, autocontenus avec des flux de travail et des connaissances procédurales spécifiques au domaine.","de":"Perfekt für Entwicklungsagenten, die modulare, selbstenthaltene Pakete mit domänenspezifischen Workflows und prozeduralem Wissen erstellen möchten.","pt":"Perfeito para Agentes de Desenvolvedor que buscam criar pacotes modulares, autocontidos com fluxos de trabalho específicos de domínio e conhecimento procedural.","ru":"Идеально для агентов-разработчиков, стремящихся создавать модульные, самодостаточные пакеты с рабочими процессами, специфичными для области и процедурными знаниями.","ar":"مثالي لعميل المطور الذي يسعى إلى إنشاء حزم متعددة ومستقلة تحتوي على تدفقات عمل محددة في المجال والمعرفة الإجرائية."},"recommendation":{"en":"Empowers agents to transform into specialized entities equipped with procedural knowledge, providing guidance for creating effective skills that extend capabilities through specialized knowledge, workflows, and tools, utilizing modular packages.","zh":"赋予代理转化为具有程序化知识的专用实体的能力，提供创建有效技能的指导，这些技能通过专用知识、工作流和工具来扩展其功能，利用模块化的软件包。","ja":"手続き型の知識を備えた専用エンティティに変化させるためのエージェントをEmpowerし、専用の知識、ワークフロー、およびツールを使用して機能を拡張するための効果的なスキルの作成に関するガイダンスを提供する。","ko":"절차적 지식을 갖춘 전문 엔티티로 변신하기 위한 에이전트를 Empower하고, 전문 지식, 워크플로 및 도구를 사용하여 기능을 확장하기 위한 효과적인 스킬 생성에 대한 가이드를 제공합니다.","es":"Habilita a los agentes a transformarse en entidades especializadas equipadas con conocimiento procedimental, brindando orientación para crear habilidades efectivas que amplían las capacidades a través de conocimiento especializado, flujos de trabajo y herramientas, utilizando paquetes modulares.","fr":"Permet aux agents de se transformer en entités spécialisées équipées de connaissances procédurales, fournissant des conseils pour créer des compétences efficaces qui étendent les capacités à travers des connaissances spécialisées, des flux de travail et des outils, en utilisant des packages modulaires.","de":"Ermächtigt Agenten, sich in spezialisierte Entitäten mit prozeduralem Wissen zu verwandeln, indem sie Anleitungen zur Erstellung effektiver Fähigkeiten bereitstellen, die die Fähigkeiten durch spezialisiertes Wissen, Arbeitsabläufe und Tools erweitern, unter Verwendung modularer Pakete.","pt":"Habilita os agentes a se transformarem em entidades especializadas equipadas com conhecimento procedural, fornecendo orientação para a criação de habilidades eficazes que estendem as capacidades por meio de conhecimento especializado, fluxos de trabalho e ferramentas, utilizando pacotes modulares.","ru":"Наделяет агентов возможностью превратиться в специализированные сущности, оснащенные процедурными знаниями, предоставляя рекомендации по созданию эффективных навыков, которые расширяют возможности посредством специализированных знаний, рабочих процессов и инструментов, используя модульные пакеты.","ar":"تمكّن العميل من التحول إلى كيانات متخصصة مجهزة بمعرفة إجرائية، وتقديم إرشادات لإنشاء مهارات فعالة تمتد القدرات من خلال معرفة متخصصة وعمليات عمل وأدوات، باستخدام حزم متعددة."},"useCases":{"en":["Creating domain-specific skills for Claude","Building procedural knowledge modules","Developing specialized workflows for tasks"],"zh":["为Claude创建特定领域的技能","构建程序化知识模块","为任务开发专用工作流"],"ja":["Claudeのためのドメイン固有のスキルを作成する","手続き型の知識モジュールを構築する","タスクのための専用ワークフローを開発する"],"ko":["Claude를 위한 특정 도메인의 스킬 생성하기","절차적 지식 모듈 구축하기","작업을 위한 전문 워크플로 개발하기"],"es":["Creación de habilidades específicas del dominio para Claude","Creación de módulos de conocimiento procedimental","Desarrollo de flujos de trabajo especializados para tareas"],"fr":["Création de compétences spécifiques au domaine pour Claude","Création de modules de connaissances procédurales","Développement de flux de travail spécialisés pour les tâches"],"de":["Erstellung domänenspezifischer Fähigkeiten für Claude","Erstellung von Modulen mit prozeduralem Wissen","Entwicklung spezialisierter Workflows für Aufgaben"],"pt":["Criação de habilidades específicas de domínio para Claude","Construção de módulos de conhecimento procedural","Desenvolvimento de fluxos de trabalho especializados para tarefas"],"ru":["Создание навыков, специфичных для области, для Claude","Построение модулей процедурных знаний","Разработка специализированных рабочих процессов для задач"],"ar":["إنشاء مهارات محددة في المجال لسكلاود","بناء وحدات معرفة إجرائية","تطوير عمليات عمل متخصصة للمهام"]},"limitations":{"en":["Requires Claude agent framework","Domain-specific knowledge needed for skill creation"],"zh":["需要Claude代理框架","需要特定领域的知识来创建技能"],"ja":["Claudeエージェントフレームワークが必要","スキル作成のためのドメイン固有の知識が必要"],"ko":["Claude 에이전트 프레임워크 필요","스킬 생성을 위한 특정 도메인의 지식 필요"],"es":["Requiere el framework de agente Claude","Se necesita conocimiento específico del dominio para la creación de habilidades"],"fr":["Nécessite le framework d''agent Claude","Des connaissances spécifiques au domaine sont nécessaires pour la création de compétences"],"de":["Benötigt das Claude-Agenten-Framework","Domänenspezifisches Wissen ist erforderlich, um Fähigkeiten zu erstellen"],"pt":["Exige estrutura de agente Claude","Conhecimento específico de domínio necessário para criação de habilidades"],"ru":["Требует框架 агента Claude","Необходимо знание, специфичное для области, для создания навыков"],"ar":["يتطلب إطار عميل كلاود","مطلوب معرفة محددة في المجال لإنشاء المهارات"]},"version":4},"contentHash":"d57b6e3a44535b9c0ef454dad5c86f5df78185fc80a65c7092885b4b5e10f81b","qualityScore":45}');
